    static let beachRoadRaceV1 = SmallCases.make(
        key: "story.beachRoadRace",
        category: .traffic,
        headlines: ["Two Rental Jeeps Race Ocean Road at Dusk Past Surf Fishermen", "Tourist Video Shows Jeeps Side by Side Near Pier"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, racing at 55 miles per hour in a 25 zone on an oceanfront road, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 7:50 p.m. on {DATE}, {D} and another rented jeep accelerated side by side along an oceanfront road toward a fishing pier. Surf fishermen were crossing to the dunes. A deputy clocked {D} at 55 in a 25 zone and stopped both jeeps at 7:56 p.m. {D} says the other jeep pulled alongside and {D.he} did not know the limit.",
        state: [E(.video, 3, "Tourist Phone Video", "Two jeeps side by side past a group with fishing rods, with the nearer jeep passing within feet of the crosswalk."), E(.document, 2, "Radar Log", "55 miles per hour in a posted 25 zone at 7:51 p.m."), E(.document, 2, "Rental Agreement", "{DL} signed a notice of the oceanfront speed limit and the no-racing rule."), E(.statement, 2, "Deputy", "Saw both jeeps accelerate together from the stop sign.")],
        defense: [E(.statement, 1, "Pulled Alongside", "{DL} says the other jeep came up on the left and {D.he} kept pace."), E(.document, 1, "Rental Map", "The rental map does not list the speed limit.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see on the oceanfront road at 7:50 p.m. on {DATE}?", "\"Two rented jeeps accelerating side by side toward the fishing pier from the stop sign. Surf fishermen with rods were crossing to the dunes at the time.\""), .direct("How fast was {DL} going?", "\"I clocked {D} at 55 miles per hour in a posted 25 zone. The radar log shows it at 7:51 p.m. I stopped both jeeps at 7:56.\""), .direct("What does the tourist video show?", "\"Two jeeps side by side passing a group carrying fishing rods, with the nearer jeep coming within feet of the crosswalk.\""), .direct("Where were you when you first noticed the jeeps?", "\"Parked at the stop sign near the pier entrance, finishing a report. I heard engines rev and looked up as two rented jeeps launched together.\""), .direct("What was happening on the road at that hour?", "\"A group of surf fishermen with rods and coolers was crossing to the dunes at the marked crosswalk. The nearer jeep passed within feet of them.\""), .direct("What did you do?", "\"I pulled out with lights and siren, clocked {D} at 55 on radar at 7:51, and stopped both jeeps by 7:56 at the end of the road.\""), .cross("Was the other driver ever identified or charged?", "\"The other driver was not identified or interviewed. I stopped both jeeps, but I have no further report on that person.\""), .cross("Did {DL} know the limit?", "\"{D} signed a rental notice of the speed limit. The rental map doesn't list it, so I can see why {D} might say that.\""), .cross("Was it the other jeep that pulled alongside?", "\"The video shows them moving side by side, but I did not see which one started it. They accelerated together.\""), .cross("Did either driver tell you they did not know the limit?", "\"{D} said {D.he} did not see a sign. The limit is posted at the start of the stretch, but the signs are sun-faded.\""), .cross("You did not see who started the acceleration, did you?", "\"No. I saw both jeeps already side by side when I first looked. I cannot say who pulled alongside first.\"")],
        defenseRole: "Tourist who watched",
        defenseExam: [.direct("What were you doing near the pier?", "\"I was a tourist on the beach, watching people fish. I had a clear view of the road from the dunes.\""), .direct("What did you see?", "\"Two jeeps came along side by side. The one on the left seemed to push ahead, and the other kept even with it.\""), .direct("How close were the fishermen?", "\"They were crossing the road with rods. The nearer jeep passed close to the crosswalk. It looked tight.\""), .direct("How far were you from the road?", "\"About fifty yards up the beach, watching the fishermen set up. I had a clear view of the road and the crosswalk.\""), .direct("What did the jeeps sound like?", "\"Loud engines revving and then two vehicles roaring past almost together. The one on the left seemed to push the pace.\""), .direct("How close did the nearer jeep come to the group?", "\"A few feet from the crosswalk. The fishermen jumped back and one dropped a rod.\""), .cross("Which jeep started it?", "\"I can't say for sure. The one on the left pulled up first, I think, but they ended up neck and neck.\""), .cross("Did the nearer jeep slow down?", "\"Not that I noticed. It kept going until the deputy's lights came on.\""), .cross("Did you film it?", "\"Not myself. Another tourist did. I only saw it with my own eyes.\""), .cross("Could you tell who started the speeding?", "\"Not for certain. They moved at the same time, and I could not say which one started it.\""), .cross("Did you see either driver's face?", "\"No. I only saw shapes behind windshields.\"")],
        theory: ("{D} raced a jeep past fishermen.", "{D} was keeping pace with another jeep."),
        allocution: "\"It was reckless and I'm sorry.\"",
        truths: ("{DL} texted the other driver 'race you to the pier.'", "The other jeep did pull ahead and force the pace."),
        defendant: [.direct("What happened on the oceanfront road?", "\"I was driving a rented jeep when another jeep pulled up on my left. I kept pace without thinking, and we both sped up.\""), .direct("Did you know the speed limit?", "\"No. I didn't see a sign I remember, and the rental map didn't list it. I was a visitor and didn't know the road.\""), .direct("Did you see the people crossing?", "\"Only at the last moment. I lifted my foot as soon as I saw them. I never wanted to put anyone in danger.\""), .direct("How did the other jeep end up beside you?", "\"I was already moving along the oceanfront when it came up on my left. It stayed even with me, and I kept pace without thinking.\""), .direct("What were you thinking about speed?", "\"That I was keeping up with traffic. I did not look at the speedometer, and I assumed the limit was around 45.\""), .direct("What happened when you saw the fishermen?", "\"I saw them at the last second and lifted my foot hard. The jeep slowed, and I stopped soon after when the deputy's lights came on.\""), .cross("You signed a rental notice of the speed limit, didn't you?", "\"I signed a stack of papers at pickup. I didn't read it carefully, and nobody pointed it out.\""), .cross("You were doing 55 in a 25, weren't you?", "\"That's what the radar says. I didn't think I was going that fast, but I won't argue with the number.\""), .cross("You could have slowed down when the other jeep pulled alongside, couldn't you?", "\"Yes. I own that. I got caught up in the moment and kept pace.\""), .cross("You and the other jeep accelerated together. Isn't that racing?", "\"It felt like a mix of both of us speeding up. I did not agree to race anyone.\""), .cross("You texted the other driver before that, didn't you?", "\"We had been messaging about meeting up at the pier. I do not remember the exact words, and It looks bad, I know.\"")],
        openings: ("At 7:50 p.m., two rented jeeps accelerated side by side along an oceanfront road as surf fishermen crossed to the dunes. A deputy clocked {D} at 55 in a 25 zone. The State will show the tourist's video, the radar log, and the signed rental notice.", "The defense will point you to a visitor who did not know the limit, a rental map that never listed it, and a second jeep that pulled alongside and set the pace."),
        closings: ("Two jeeps, 55 miles per hour in a 25 zone, and a crosswalk full of fishermen. {D} signed a notice about the limit and the no-racing rule.", "The other jeep pulled alongside and was never identified. {D} did not know the limit and never meant to race. The State has not proved a willful race."),
        timeline: [(0, "7:50 p.m.: the jeeps accelerate from the stop sign."), (0, "7:51 p.m.: the radar reads 55."), (0, "7:56 p.m.: the deputy stops both jeeps."), (1, "The tourist sends the phone video.")],
        identified: "The deputy stopped {D} at the scene, and the tourist's video shows the jeep.",
        notDone: ["The other jeep's driver was never identified or interviewed.", "The rental company's speed warning was never shown to {DL} at pickup."],
                mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let firePitFeudV1 = SmallCases.make(
        key: "story.firePitFeud",
        category: .publicOrder,
        headlines: ["Car Stereo at 1 a.m. and Shouted Threats Over Parking Space", "Neighbor Warns Parking Dispute Will End Badly"],
        law: "disorderly",
        spec: "Disturbed the peace of {V}, a neighbor, by loud noise and shouted threats at night, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 1 a.m. on {DATE}, {D} sat in a parked car with the stereo blasting and shouted threats at {V}'s window about a parking space. {V} called deputies at 1:10 a.m. Deputies arrived at 1:25 a.m. and found {D} still shouting. {D} says the stereo was on a low setting and {D.he} was only upset.",
        state: [E(.video, 3, "Porch Camera", "{D} shouts at {V}'s window and the stereo is audible across the yard."), E(.document, 2, "Decibel Reading", "A deputy's meter reads 82 decibels at the property line at 1:30 a.m."), E(.statement, 2, "{V}", "Woke up and heard the threat to 'make parking a lot less fun.'"), E(.document, 2, "Parking Complaint", "A written complaint from {V} to the landlord two days earlier.")],
        defense: [E(.statement, 1, "Low Stereo", "{DL} says the stereo was low and only the shouting was real."), E(.document, 1, "Lease Parking Clause", "A clause assigning {D} the space in question.")],
        role: "Neighbor",
        exam: [.direct("What woke you at 1 a.m. on {DATE}?", "\"{D} was sitting in a parked car with the stereo blasting and shouting at my window about a parking space.\""), .direct("What did {DL} say?", "\"A threat to 'make parking a lot less fun.' I heard it clearly. I called deputies at 1:10, and they arrived at 1:25.\""), .direct("What else do the records show?", "\"A deputy's meter read 82 decibels at the property line at 1:30. I had sent a written complaint to the landlord two days before about the space.\""), .direct("What did you hear when you woke?", "\"A car stereo thumping so loudly the walls vibrated, and a voice shouting from the lot. It was about 1 a.m. and I was in bed.\""), .direct("What did you do?", "\"I looked out and saw {D} in the car staring up at my window. I called deputies at 1:10 and they arrived at 1:25.\""), .direct("What was the history over the space?", "\"A parking space that the lease gave to {D} and another that I used. We argued about it, and I sent a written complaint to the landlord two days earlier.\""), .cross("{DL} says the stereo was low, doesn't {D.he}?", "\"The meter says 82 decibels, and it was audible across the yard on my porch camera.\""), .cross("Did other neighbors have music playing?", "\"Possibly. I can't speak for everyone. I know what I heard coming from {D}'s car.\""), .cross("Does the lease give {DL} the space?", "\"There is a clause assigning {D} a space. Whether it's the one in dispute is what we argued about.\""), .cross("Did {D} threaten you physically?", "\"The threat was about parking: 'make parking a lot less fun.' I did not hear a threat of violence.\""), .cross("Was {D} still shouting when deputies arrived?", "\"Yes. {D} was shouting at the window when they pulled up.\"")],
        defenseRole: "Third neighbor",
        defenseExam: [.direct("Do you live in the complex?", "\"Yes. I'm a third neighbor, upstairs from both of them. I heard what went on that night.\""), .direct("What did you hear?", "\"Shouting from the lot. A stereo was on, but there was music from other places too.\""), .direct("How loud was {DL}'s stereo?", "\"Not very. I'd say low to moderate. The shouting was louder than the music.\""), .direct("How far is your apartment from the lot?", "\"Right above both neighbors. I hear everything that happens in the lot when my window is open.\""), .direct("What kind of noise was it that night?", "\"Some bass from a stereo and a loud voice. There was also a party two doors down with music playing.\""), .direct("What was {D} saying?", "\"Something about the parking issue. I could not catch the whole thing.\""), .cross("Could you tell whose music was whose?", "\"Not exactly. I heard a mix. I can't say I isolated {D}'s car.\""), .cross("Did you hear the threat?", "\"I heard shouting. I couldn't make out every word.\""), .cross("Did you call anyone?", "\"No. I thought it would settle down. It didn't, and I regret not calling.\""), .cross("Could you tell whose speakers were loudest?", "\"Not clearly. It was a mix from several places.\""), .cross("Did you see {D} look at {V}'s window?", "\"I saw {D} in the car facing that direction. I do not know what {D} was looking at.\"")],
        theory: ("{D} blasted a stereo and shouted threats.", "{D} was upset over a parking space."),
        allocution: "\"I let things get out of hand.\"",
        truths: ("{DL} had been parking in front of {V}'s space on purpose for a week.", "The stereo was low and a neighbor's music added to the noise."),
        defendant: [.direct("Why were you in the car at 1 a.m.?", "\"I was upset about the parking space and sat in my car to cool off. I was angry and wanted to be heard.\""), .direct("Was the stereo loud?", "\"It was on low. Someone else's music was louder than mine. I was mostly just shouting.\""), .direct("Did you mean to threaten {V}?", "\"No. I said something sharp about the parking, but I didn't mean harm. I was upset.\""), .direct("Why were you sitting in your car at 1 a.m.?", "\"I had come back from a late shift and found someone parked in my space. I sat in the car to calm down and could not.\""), .direct("How loud was your stereo?", "\"Low. I had it on a soft playlist to settle myself. A different car or apartment had louder music.\""), .direct("What did you shout?", "\"That I was tired of being pushed around about parking. I said something dumb about making parking less fun.\""), .cross("The deputy's meter read 82 decibels, didn't it?", "\"I've heard that. I think the meter picked up other noise too. I can't be sure.\""), .cross("You shouted at {V}'s window, didn't you?", "\"Yes. I did. It was late and I'm ashamed. I should have gone to the landlord.\""), .cross("You said you'd make parking a lot less fun, didn't you?", "\"Something like that. It was a stupid thing to say. It was about parking, nothing more.\""), .cross("The meter read 82 decibels. How can that be a low stereo?", "\"It could have been the music from other places, or my voice. I do not think the stereo alone did that.\""), .cross("You shouted at a neighbor's window at 1 a.m. Why?", "\"I was angry and exhausted. I regret that I let it spill over at that hour.\"")],
        openings: ("At 1 a.m., {D} sat in a parked car with the stereo blasting and shouted threats at {V}'s window over a parking space. Deputies measured 82 decibels at the property line. The State will show the porch camera, the reading, and the complaint.", "The defense will present a lease clause giving {D} the space, a low stereo, other neighbors' music, and shouting that was upset, not menacing. Listen closely to the witnesses."),
        closings: ("A blasting stereo, shouting at a window at 1 a.m., a threat about parking, and a meter reading of 82 decibels. {V} could not sleep.", "A parking dispute, a low stereo, and noise from several sources. The State has not proved {D} made a true threat or a noise the law forbids."),
        timeline: [(0, "1:00 a.m.: {D} starts shouting."), (0, "1:10 a.m.: {V} calls deputies."), (0, "1:25 a.m.: deputies arrive."), (1, "Deputies file the report.")],
        identified: "The porch camera identifies {D}.",
        notDone: ["The decibel meter's calibration was never put on the record.", "Other neighbors' music was never accounted for."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let treeHouseClimbV1 = SmallCases.make(
        key: "story.treeHouseClimb",
        category: .publicOrder,
        headlines: ["Man Sleeps in Neighbor's Backyard Shed After No-Trespass Letter", "Deputies Find Neighbor Asleep Among Tools"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a neighbor, after being notified not to, in a backyard shed, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} sent {D} a no-trespass letter after finding {D} in the backyard shed a month earlier. At 10 p.m. on {DATE}, the yard camera shows {D} open the shed and settle in on a pile of tarps. {V} called deputies at 10:20 p.m. and found {D} asleep when they arrived at 10:35 p.m. {D} says {D.he} thought the shed was open to anyone.",
        state: [E(.document, 3, "No-Trespass Letter", "A signed letter a month earlier barring {D} from the property."), E(.video, 3, "Yard Camera", "{D} opens the shed door and goes in at 10 p.m."), E(.statement, 2, "{V}", "Called deputies when the alert came."), E(.document, 2, "Deputy's Report", "Found {D} asleep on tarps at 10:35 p.m.")],
        defense: [E(.statement, 1, "Open Shed", "{DL} says the shed door was open and {D.he} thought no one minded."), E(.document, 1, "Photo of Latch", "A photo of a broken latch on the shed.")],
        role: "Neighbor",
        exam: [.direct("What did you do after finding {D} in your backyard shed a month earlier?", "\"I sent {D} a signed no-trespass letter, barring {D} from the property. I wanted it in writing so there would be no confusion.\""), .direct("What did your yard camera show at 10 p.m. on that date?", "\"{D} opening the shed door and going in, then settling on a pile of tarps. The alert came to my phone.\""), .direct("What happened next?", "\"I called deputies at 10:20, and they arrived at 10:35 and found {D} asleep on the tarps inside the shed.\""), .direct("How did you first learn someone was in your shed?", "\"A month earlier I found {D} asleep on tarps. I told {D} to leave and had a no-trespass letter delivered a few days later.\""), .direct("What alert came on the night of {DATE}?", "\"My yard camera sent a motion notice at about 10 p.m. I watched the video and saw {D} open the shed door and go in.\""), .direct("How did the night end?", "\"I called deputies at 10:20. They arrived at 10:35, found {D} asleep, and woke {D} up. {D} was taken out and given a citation.\""), .cross("{D} says {D.he} thought the shed was open to anyone, doesn't {D.he}?", "\"That is what {D} says. But {D} had my letter, and the shed is on my property.\""), .cross("Was the latch on that shed broken?", "\"I have heard it was for weeks. I do not use the shed often, and I did not check it.\""), .cross("Did {D} damage anything in the shed?", "\"No. {D} only slept there. Nothing was broken or taken that I could find.\""), .cross("Had you fixed the latch?", "\"No. It was broken. I had not thought it was worth repairing since I rarely use the shed.\""), .cross("Was anything missing or damaged?", "\"No. Everything was in place. {D} only slept on the tarps.\"")],
        defenseRole: "Neighbor on the other side",
        defenseExam: [.direct("Was the latch on the shed broken?", "\"For weeks, yes. It hung loose, and anyone could pull the door open without any key or tool.\""), .direct("Does {V} use the shed much?", "\"Rarely. It sits mostly unused, with old tarps and tools. I almost never see {V} go in or out of it.\""), .direct("Did you ever warn {D} about the shed?", "\"I heard that {V} warned {D} once. I did not hear the conversation, only that it happened.\""), .direct("How long have you lived next to {V}?", "\"Seven years. I see the yard all the time from my own.\""), .direct("What is the shed used for?", "\"Old tools and tarps. {V} rarely goes in, and I have not seen it in use for months.\""), .direct("What did you notice about the latch?", "\"It had been hanging by one screw for weeks. A tug would open the door.\""), .cross("Did you see {D} go into the shed that night?", "\"No. I did not see {D} go in. I was inside my own house that evening.\""), .cross("Did you know {D} had received a written no-trespass letter?", "\"I heard about it afterward. I did not know about it at the time.\""), .cross("Does a broken latch make it fine to sleep in someone's shed?", "\"No. It does not. I would not say that. I only describe how the shed looked.\""), .cross("Did {V} ever tell you to keep an eye on the yard?", "\"After the first incident, yes. I told {V} I would watch for anyone.\""), .cross("Did you see anyone near the shed that night?", "\"No. I was inside and did not see {D} go in.\"")],
        theory: ("{D} entered the shed after a written ban.", "{D} thought the shed was open."),
        allocution: "\"It was childish, and I know it.\"",
        truths: ("{DL} had slept there twice before.", "The latch was broken and the shed looked unused."),
        defendant: [.direct("Why did you go into the shed?", "\"I needed a place to sleep. The latch was broken, the shed looked unused, and I thought no one would mind.\""), .direct("Had you slept there before?", "\"Twice before, on other cold nights. Nobody had stopped me, so I thought it was all right.\""), .direct("Did you receive the no-trespass letter?", "\"Yes, I got it. I did not take it as final. I thought it was about the yard, not the shed.\""), .direct("What was your situation that week?", "\"I was between places and sleeping where I could. The weather had turned cold, and I needed shelter.\""), .direct("How did you know the shed was available?", "\"The door hung open the first time I walked by, and the latch was broken. It seemed like an unused building.\""), .direct("What did you do when deputies arrived?", "\"I woke up confused, apologized, and gathered my things. I did not argue.\""), .cross("The letter barred you from the property, didn't it?", "\"It did. I knew that. But I was desperate for a place to sleep, and I made a poor choice.\""), .cross("You opened the door and went in on camera at 10 p.m., didn't you?", "\"Yes. I did. I did not try to hide, and I did not damage anything.\""), .cross("You slept on {V}'s tarps. Isn't that trespassing?", "\"Yes, I suppose it is. I feel awful about it. I will find somewhere else.\""), .cross("You had read the letter. Why go back?", "\"I did not take it as a final word. I was desperate and cold and made a poor choice.\""), .cross("Isn't it true you had slept there twice before?", "\"Yes. Nobody stopped me before, and I thought it was fine.\"")],
        openings: ("{V} sent {D} a signed no-trespass letter after finding {D} in the backyard shed. A month later, at 10 p.m., the yard camera shows {D} open the shed and settle on a pile of tarps.", "The defense evidence will establish that the shed latch had been broken for weeks, that the shed looked unused, and that {D} was only looking for a place to sleep."),
        closings: ("A signed letter barring {D}, a camera showing {D} open the shed, and deputies finding {D} asleep inside. {D} knew exactly what the letter said.", "A broken latch, an unused shed, and a person with nowhere else to go. {D} took nothing and damaged nothing, and this was desperation, not a crime of malice."),
        timeline: [(-30, "{V} gives {D} the no-trespass letter."), (0, "10 p.m.: {D} enters the shed."), (0, "10:35 p.m.: deputies find {D} asleep."), (1, "{V} sends the yard video.")],
        identified: "The yard camera identifies {D}.",
        notDone: ["The shed's latch was never inspected.", "The no-trespass letter was never hand-delivered."],
        mood: .sympathetic,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

