        state: [E(.video, 3, "Lot Camera", "{D} loads three cases into a hatchback at 9:14 p.m. and drives away."), E(.document, 2, "Inventory Count", "Three cases missing from the cooler aisle."), E(.document, 2, "Sales Log", "No sale was rung up between 9:05 and 9:20 p.m."), E(.statement, 2, "Clerk", "Was in the stockroom and came out to an empty aisle.")],
        defense: [E(.statement, 1, "Waved Through", "{DL} says an employee waved {D.him} out the side door."), E(.document, 1, "Staff Schedule", "Two clerks were on the schedule that night.")],
        role: "Convenience store clerk",
        exam: [.direct("What happened at your store at 9:10 p.m. on {DATE}?", "\"I was in the stockroom when {D} came in and carried three cases of energy drinks to a hatchback in the lot. When I came out, the aisle was empty.\""), .direct("What does the lot camera show?", "\"{D} loading three cases into the hatchback at 9:14 and driving away. The camera caught the plate.\""), .direct("What do your records show?", "\"Three cases missing from the cooler aisle, and no sale rung up between 9:05 and 9:20.\""), .direct("Where were you when the incident began?", "\"In the stockroom unpacking a delivery at about 9:10. I came out a few minutes later to an empty cooler aisle.\""), .direct("What did you do when you saw the cases were gone?", "\"I checked the register log, saw no sale, and called the manager. We reviewed the lot camera and found {D} loading the hatchback at 9:14.\""), .direct("How much were the cases worth?", "\"About $90 each, so roughly $270. The cooler aisle count showed three cases missing from the energy drink display.\""), .cross("{DL} says an employee waved {D.him} out the side door, doesn't {D.he}?", "\"I was in the stockroom, so I can't say what another employee did.\""), .cross("Was another clerk working that night?", "\"Yes. Two clerks were on the schedule. The other was at the other register.\""), .cross("Is there a camera on the side door?", "\"No. The side door isn't covered. I have only the lot camera.\""), .cross("Did you talk to the other clerk about letting anyone out the side door?", "\"Not that night. The other clerk was at the front register, and I did not see who left through the side.\""), .cross("Is the side door normally used by customers?", "\"Not usually. It is for deliveries, but sometimes staff open it for carts or large purchases.\"")],
        defenseRole: "Second clerk",
        defenseExam: [.direct("Were you working on {DATE}?", "\"Yes. I was the second clerk, at the other register that evening.\""), .direct("Did you wave customers out the side door?", "\"Sometimes, when the front was crowded. I did that night, I believe, for several customers.\""), .direct("Did you wave {DL} out?", "\"I may have. I wave a lot of people through. I don't remember {D} specifically.\""), .direct("What were you doing at 9 p.m. that night?", "\"Working the front register. It was a busy evening, and I was ringing up a steady line of customers.\""), .direct("How do you use the side door?", "\"If the front is jammed, I open the side so customers can walk straight to the lot. I do it with big carts.\""), .direct("What do you recall about {D}?", "\"I recall a person carrying cases to the side. I may have held the door, but I do not remember checking whether {D} paid.\""), .cross("Did you tell anyone they could take cases without paying?", "\"No. Never. I only waved people toward the exit after they paid.\""), .cross("Did {DL} pay at your register?", "\"I don't recall that. I can't say whether {D} paid.\""), .cross("Were you interviewed right away?", "\"No. It was a couple of weeks before anyone asked me. My memory is hazier now.\""), .cross("Did you ask whether {D} had paid?", "\"No. I assumed they had paid at the other register.\""), .cross("Were you told to check?", "\"The manager said never to wave anyone out without a receipt. I got careless.\"")],
        theory: ("{D} took three cases and drove off.", "{D} thought an employee waved {D.him} out."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} sold the cases at a flea market the next day.", "The second clerk did wave customers out the side door that evening and may have waved {DL} through."),
        defendant: [.direct("What did you do in the store that night?", "\"I picked up three cases of energy drinks. An employee waved me toward the side door, and I thought it was fine to take them out.\""), .direct("Did you pay?", "\"No. I thought the employee was letting me go through. I should have asked at the register.\""), .direct("Did you plan to steal?", "\"No. I thought I had been allowed. I wouldn't have loaded the car in plain view of a camera if I thought it was theft.\""), .direct("What did you buy at the store?", "\"I stopped for a drink and walked to the cooler aisle. Three cases of energy drinks were stacked on a dolly and I picked them up.\""), .direct("What can you tell us about the employee who waved you out?", "\"A person in a store shirt at the side door nodded and held it open. I thought they were letting me carry the cases out to pay at the car.\""), .direct("What did you do in the lot?", "\"Loaded the cases into the hatchback. I figured someone would come out for payment, and when no one did I drove away.\""), .cross("No sale was rung up, was there?", "\"No. I didn't go to the register. I took the cases and left.\""), .cross("The clerk who was waving can't be named, can {V.he}?", "\"I can describe the person, but I don't know the name. It was a quick wave.\""), .cross("You drove away right after, didn't you?", "\"Yes. I wasn't hiding. I thought it was a normal pickup.\""), .cross("Why didn't you stop at the register?", "\"Because I thought the employee at the door had handled it. I should have checked.\""), .cross("If it was a legitimate sale, why not hand over a card or receipt?", "\"Nobody asked. I assumed there was a deal and did not think about proof.\"")],
        openings: ("At 9:10 p.m., {D} carried three cases of energy drinks to a hatchback while the clerk was in the stockroom and drove off without paying. The lot camera caught the plate. The State will show the video, the inventory count, and the sales log.", "The defense evidence includes a side door where employees wave customers through, a second clerk who cannot rule out waving {D}, and a driver who loaded the car openly."),
        closings: ("Three cases carried out, no sale rung up, and a plate on camera. {D} left without paying, and the stockroom clerk came back to an empty aisle.", "An employee may have waved {D} through the side door, and no camera covers it. The State has not proved {D} meant to steal."),
        timeline: [(0, "9:10 p.m.: {D} enters the store."), (0, "9:14 p.m.: {D} loads the cases."), (0, "9:20 p.m.: the clerk finds the aisle empty."), (1, "The store sends the lot video to the Sheriff's Office.")],
        identified: "The lot camera and the plate identify {D}.",
        notDone: ["The side door was never covered by a camera.", "The clerk at the other register was not interviewed for two weeks."],
                mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let registerTwentiesV1 = SmallCases.make(
        key: "story.registerTwenties",
        category: .property,
        headlines: ["Parking Booth Attendant Takes Cash From Daily Drawer Over Three Weeks", "Ticket Counts and Cash Do Not Match for One Attendant's Shifts"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a parking operator, valued at $640, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A parking lot operator audited booth collections on {DATE} after noticing three weeks of low totals. On {D}'s shifts the cash collected was an average of $35 below the ticket count, while on other attendants' shifts the numbers matched. The shortages totaled $640. The ticket counter and the cash drawer both showed {D}'s login. {D} says the ticket counter jams.",
        state: [E(.document, 3, "Audit Spreadsheet", "Cash below ticket counts on {D}'s shifts only, totaling $640."), E(.digital, 3, "Ticket Counter Log", "Counts recorded under {D}'s login on each shift."), E(.document, 2, "Drawer Counts", "Drawers counted at shift end with {D}'s initials."), E(.statement, 2, "Operator Manager", "Found no counter errors on other attendants' shifts.")],
        defense: [E(.statement, 1, "Counter Jams", "{DL} says the ticket counter jams and miscounts."), E(.document, 1, "Maintenance Ticket", "A service ticket for the counter on {DL}'s booth.")],
        role: "Parking operator manager",
        exam: [.direct("What did your audit of the booth collections show?", "\"Cash below the ticket count on {D}'s shifts only, averaging $35 per shift, for a total of $640 over three weeks.\""), .direct("How did the other attendants' shifts compare?", "\"On every other attendant's shift, the cash and ticket counts matched. I found no counter errors on those shifts.\""), .direct("Whose login was on the ticket counter and the drawer?", "\"{D}'s login on both. The drawers were counted at shift end with {D}'s initials on the sheet.\""), .direct("What first made you audit the booth collections?", "\"Three weeks of low daily totals. The ticket counts were normal, but the cash deposit fell short, and I could not find a pattern at first.\""), .direct("How did you narrow it to one attendant?", "\"I matched shortages with shifts. Only {D}'s shifts were short, an average of $35 each, and all other attendants balanced.\""), .direct("What did you review next?", "\"The ticket counter log, the drawer count sheets, and booth camera footage. Counts were under {D}'s login, and drawer sheets carried {D}'s initials.\""), .cross("{D} says the ticket counter jams, doesn't {D.he}?", "\"Yes. It jammed twice this month, and the log was off on those days. That is fair.\""), .cross("Did those jams account for $640?", "\"No. Two jams would not produce a steady $35 shortfall on shift after shift.\""), .cross("Did anyone see {D} take cash from the drawer?", "\"No. No one saw it. I have the numbers and the logins, nothing more.\""), .cross("Does the counter ever malfunction?", "\"Yes. A maintenance ticket exists for {D}'s booth. It jammed twice, and the log was off on those days.\""), .cross("How do you know the jams did not account for it?", "\"Two jams cannot produce a steady shortfall across three weeks. The shortages were small and repeated.\"")],
        defenseRole: "Other attendant",
        defenseExam: [.direct("Does the ticket counter at your booth jam?", "\"Twice this month. It stuck and miscounted, and I had to reset it by hand each time.\""), .direct("Do you ever cover {D}'s booth?", "\"Sometimes, when {D} takes a break or is out. I handle the cash and counter during those stretches.\""), .direct("Did your own shifts match the ticket counts?", "\"Yes. Mine always matched. But I did not have jams on my shifts, so I cannot speak to the days {D} had them.\""), .direct("How long have you worked as an attendant?", "\"Five years. I work the booth next to {D}'s on most days.\""), .direct("What problems have you seen with the ticket counter?", "\"It jams on busy days. The numbers freeze, and you have to reset it by hand.\""), .direct("How does the count work at shift end?", "\"We read the ticket counter, count the drawer, and compare. If they do not match, we write the difference.\""), .cross("Do you share a drawer with {D}?", "\"No. Each attendant has a separate drawer. I never touch {D}'s drawer, and {D} does not touch mine.\""), .cross("Did you ever see {D} short on cash at the end of a shift?", "\"I did not look at {D}'s count. I counted my own and went home.\""), .cross("Did the jams happen on the days of the large shortfalls?", "\"I do not know. I only know they jammed twice. I cannot tie the dates to the audit.\""), .cross("Did your counter jam on your shifts?", "\"Rarely. It happened mostly on {D}'s booth, which is the older one.\""), .cross("Do you know whether {D} was short?", "\"Only what the audit says. I do not see {D}'s count.\"")],
        theory: ("{D} took cash from the parking booth.", "The ticket counter miscounted."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} paid several bills in cash that month.", "The counter did jam twice and the log was off."),
        defendant: [.direct("Did you take cash from the booth?", "\"No, I did not take any cash from the drawer. I counted it at the end of each shift and put my initials on it.\""), .direct("Why do the counts come up short on your shifts?", "\"The ticket counter jams. When it jams, it can record too many tickets, and the cash looks short.\""), .direct("How do you answer the audit spreadsheet?", "\"I think it reflects the counter errors. I do not control the counter, and I reported the jams to the manager.\""), .direct("How long have you worked as an attendant?", "\"Four years. I take cash, give change, and keep the count at the end of each shift.\""), .direct("What did you notice about the ticket counter?", "\"It stuck often, and I had to reset it by hand. When it stuck, it sometimes counted extra tickets.\""), .direct("Why did you pay several bills in cash that month?", "\"I had been saving from side work and paid a few bills at once to catch up. It was my own money.\""), .cross("Only your shifts were short, weren't they?", "\"So the audit says. I do not know why. I can only tell you I did not take anything.\""), .cross("You paid several bills in cash that month, didn't you?", "\"Yes. I had been saving cash, and I paid some bills at once. It was my own money.\""), .cross("$640 over three weeks is an average of $35 a shift. How does a jam produce a steady number like that?", "\"I do not know. I am not an expert on the counter. I only know what I did.\""), .cross("Only your shifts were short. Who else could it be?", "\"I do not know. I count my drawer at the end, and I turn it in. I did not take anything.\""), .cross("You never reported the jams to your manager, did you?", "\"I told another attendant. I should have written a report.\"")],
        openings: ("A parking operator audited booth collections after three weeks of low totals. Cash fell about $35 below the ticket count on {D}'s shifts only, totaling $640, and the counter and drawer both show {D}'s login.", "The defense will present evidence that the ticket counter jammed twice that month, throwing off the log, and that no one saw {D} take any cash."),
        closings: ("Three weeks, $640 short, and only on {D}'s shifts. The other attendants' numbers matched, and every record carries {D}'s login and initials.", "A ticket counter that jammed and a log that was off. The State has a pattern of numbers, but it must prove {D} took the cash, and a jammed counter raises real doubt."),
        timeline: [(-21, "The shortages begin."), (0, "The operator audits booth collections."), (2, "The manager pulls the counter logs."), (5, "The operator reports $640 missing.")],
        identified: "The login and the drawer initials identify {D}.",
        notDone: ["The counter's service ticket was never reviewed.", "The booth's drawer was never counted by a second person."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let groomerCageV1 = SmallCases.make(
        key: "story.groomerCage",
        category: .violent,
        headlines: ["Dog Left in Hot Car Outside Pet Store for Ninety Minutes", "Passerby Calls Deputies, Who Break Window to Reach Panting Dog"],
        law: "animalCruelty",
        spec: "Intentionally deprived an animal of necessary care by leaving it in a closed vehicle in extreme heat, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "On {DATE}, with the temperature at 92 degrees, {D} left a dog in a parked car outside a pet store at 12:30 p.m. and went shopping. At 1:55 p.m. a passerby saw the dog panting and called deputies, who broke a window. The dog's temperature was 106. {D} says the windows were cracked and {D.he} was gone only twenty minutes.",
        state: [E(.video, 3, "Store Camera", "{D} walks into the store at 12:30 p.m. and does not leave until 2:05 p.m."), E(.document, 3, "Veterinary Note", "Heat stroke with a body temperature of 106; the dog recovered after treatment."), E(.document, 2, "Weather Record", "92 degrees at 1:55 p.m. with direct sun on the lot."), E(.statement, 2, "Deputy", "Found the windows cracked an inch and the dog panting.")],
        defense: [E(.statement, 1, "Twenty Minutes", "{DL} says {D.he} was gone only twenty minutes and the windows were cracked."), E(.document, 1, "Cashier Receipt", "A receipt dated 12:50 p.m.")],
        role: "Passerby",
        exam: [.direct("What did you see at the pet store on {DATE}?", "\"It was 92 degrees. At 1:55 p.m. I saw a dog panting in a parked car in the direct sun. I called deputies.\""), .direct("What did deputies do?", "\"They broke a window. They found the windows cracked about an inch and the dog panting hard.\""), .direct("What condition was the dog in?", "\"Heat stroke, with a body temperature of 106, according to the veterinary note. The dog recovered after treatment.\""), .direct("What caught your attention at the car?", "\"A dog in the back seat panting hard with its tongue out. It was about 1:55 p.m., and the sun was on the car all day.\""), .direct("What did you do?", "\"I looked for the owner, then called deputies. A deputy broke a window and pulled the dog out and poured water over it.\""), .direct("How did the dog look?", "\"Lethargic and drooling, barely able to stand. The vet later said its body temperature was 106.\""), .cross("{DL} says {D.he} was gone only twenty minutes, doesn't {D.he}?", "\"The store camera shows {D} walk in at 12:30 and not leave until 2:05.\""), .cross("Were the windows cracked?", "\"Yes, about an inch. That's what the deputy found. It wasn't enough in that heat, in my view.\""), .cross("Did you see {DL} leave the car?", "\"No. I came by at 1:55 and saw only the dog. I don't know when {D} went in.\""), .cross("Did you check whether the dog had water?", "\"No water was in the car as far as I could see. A deputy later found only a blanket.\""), .cross("How long had the car been there?", "\"I do not know. I arrived at 1:55 and saw only the dog.\"")],
        defenseRole: "Pet store cashier",
        defenseExam: [.direct("Were you working at the pet store?", "\"Yes. I'm a cashier. I rang up {D} that day.\""), .direct("When did you ring {DL} up?", "\"At 12:50 p.m. I recall because the line was long and {D} said {D.he} would be quick.\""), .direct("Did {DL} seem concerned about the dog?", "\"A little. {D} mentioned the dog was in the car and said {D.he} wouldn't be long.\""), .direct("What was the store like at 12:50?", "\"Busy, with a line out to the aisle. It took about fifteen minutes to ring up each customer.\""), .direct("What did {D} say at the register?", "\"That the dog was in the car and {D} would be quick. {D} paid and said thanks.\""), .direct("Did you see {D} leave?", "\"I do not recall. I had other customers, and {D} may have stayed to browse.\""), .cross("Did {DL} leave after paying?", "\"I don't know. I had other customers. I can't say when {D} left the store.\""), .cross("Did you check the car?", "\"No. I didn't think about it. I know I should have.\""), .cross("How long did the line take?", "\"I'd say fifteen or twenty minutes at that hour. I didn't log it.\""), .cross("Did you suggest checking on the dog?", "\"No. I did not. In hindsight I should have asked.\""), .cross("How can you be sure of the time?", "\"The receipt is stamped 12:50. I remember because {D} was in a hurry.\"")],
        theory: ("{D} left a dog in a hot car.", "The windows were cracked and the stop was short."),
        allocution: "\"I'm not proud of it, Your Honor.\"",
        truths: ("The cashier says the checkout line was long and {DL} said {D.he} would be quick.", "The cashier says the checkout line was long and {DL} said {D.he} would be quick."),
        defendant: [.direct("Why was the dog in the car?", "\"I was running a quick errand. I cracked the windows and went in. I thought it would only be twenty minutes.\""), .direct("How long were you actually in the store?", "\"The line was long, and I kept getting delayed. I lost track of time. I didn't realize it was that long.\""), .direct("Looking back, how do you feel about the dog?", "\"Terrible. I love that dog. I'd never knowingly put it in danger. I misjudged the heat and the time.\""), .direct("What was your plan that afternoon?", "\"A quick stop to pick up dog food and a toy. I left the windows cracked and went inside.\""), .direct("What delayed you?", "\"A long checkout line and then a conversation with the cashier about the dog's diet. I lost track of time.\""), .direct("How did you feel when you came out?", "\"Panicked. The deputy was already at the car, and the dog looked awful. I rode with the dog to the vet.\""), .cross("The store camera shows you inside until 2:05, doesn't it?", "\"If that's what the camera says, then it's right. I didn't look at the clock.\""), .cross("It was 92 degrees, wasn't it?", "\"Yes. I knew it was hot. I thought cracked windows would be enough.\""), .cross("The receipt is dated 12:50, isn't it?", "\"Yes. I paid at 12:50 and then kept browsing. I should have gone straight back.\""), .cross("You knew it was 92 degrees. Why leave the dog at all?", "\"I thought a short trip with cracked windows would be okay. I misjudged how hot it would get.\""), .cross("The camera shows you inside for ninety minutes. Is that a quick errand?", "\"No. I lost track browsing after I paid. I should have gone out to check on the dog.\"")],
        openings: ("On a 92-degree day, a dog was left in a parked car outside a pet store from 12:30. By 1:55 it was panting, and the dog's temperature was 106. The store camera shows {D} inside until 2:05. The State will show the video and the veterinary note.", "The defense will present windows that were cracked, a long checkout line, and an owner who meant to be quick and lost track of time."),
        closings: ("Ninety-two degrees, direct sun, windows cracked an inch, and ninety minutes inside the store. A dog with a body temperature of 106 is the cost of that choice.", "{D} meant to be gone twenty minutes and cracked the windows, but a long checkout line and a lost sense of time turned a quick stop into a mistake. The State has not proved a knowing disregard of the dog's safety."),
        timeline: [(0, "12:30 p.m.: {D} leaves the dog in the car."), (0, "1:55 p.m.: the passerby calls deputies."), (0, "2:05 p.m.: {D} comes out of the store."), (1, "The veterinarian reports the dog's recovery.")],
        identified: "The store camera and the car plate identify {D}.",
        notDone: ["The store's line count was never recorded.", "The car's interior temperature log was never requested."],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let drumKitVanV1 = SmallCases.make(
        key: "story.drumKitVan",
        category: .property,
        headlines: ["School Band Booster Trailer Loses PA Speakers and Mixer Over Weekend", "Pawn Ticket Ties Stolen Sound Equipment to Bus Driver"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a school band booster club, valued at $2,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A school band booster club kept a trailer of sound equipment parked behind the school on {DATE}. On Monday the padlock was cut and a mixer, two speakers and a set of microphones worth $2,200 were gone. A pawn shop took in matching equipment from {D}, a school bus driver, on Tuesday. {D} says the equipment was a gift from a former band director.",
        state: [E(.document, 3, "Pawn Ticket", "A pawn ticket signed by {D} for a mixer, two speakers and microphones."), E(.physical, 3, "Serial Numbers", "The mixer's serial number matches the booster club's purchase receipt."), E(.document, 2, "Inventory", "The club's list of equipment kept in the trailer."), E(.video, 2, "Pawn Shop Camera", "{D} at the counter on Tuesday afternoon.")],
        defense: [E(.statement, 1, "Gift", "{DL} says a former band director gave the equipment to {D.him}."), E(.document, 1, "Director's Retirement Card", "A card thanking {DL} for driving the band bus.")],
        role: "Booster club president",
        exam: [.direct("What did the booster club keep behind the school on {DATE}?", "\"A trailer of sound equipment. On Monday the padlock was cut and a mixer, two speakers, and a set of microphones worth $2,200 were gone.\""), .direct("How did {DL} come up?", "\"A pawn shop took in matching equipment from {D}, a school bus driver, on Tuesday. The pawn ticket is signed by {D}.\""), .direct("How do you know it is the club's?", "\"The mixer's serial number matches our purchase receipt. We also have an inventory of what was kept in the trailer.\""), .direct("What did you do when the club's equipment went missing?", "\"On Monday I found the padlock cut and the trailer empty of the mixer, speakers, and mics. I called deputies and sent a photo of the club inventory.\""), .direct("How did you tie the gear to {D}?", "\"A pawn shop took in matching equipment on Tuesday from {D}, and the mixer's serial number matched our purchase receipt.\""), .direct("What was the value of what was taken?", "\"About $2,200. It was bought with fundraiser money from parents, and the band lost its sound system for the season.\""), .cross("{DL} says a former band director gave the equipment, doesn't {D.he}?", "\"I don't know of any gift. Nothing was written down, and I'd have needed to approve it.\""), .cross("Does {DL} have a connection to the school?", "\"Yes, {D} drives a school bus. That doesn't mean {D} had a right to the trailer's equipment.\""), .cross("Did you see {DL} cut the lock?", "\"No. I found the lock cut Monday. I only know the pawn ticket and the camera at the shop.\""), .cross("Who had keys to the trailer or the lot?", "\"A few people. The padlock was cut, so I cannot say who opened it. The school's back lot gate has a code.\""), .cross("Did a former director ever give away club gear?", "\"I am not aware of it. The director could have given away personal equipment, but nothing was recorded for the club's items.\"")],
        defenseRole: "Former band director",
        defenseExam: [.direct("Were you the band director?", "\"Yes, for many years. I retired recently. I know {D} from the band bus.\""), .direct("Did you give {DL} equipment?", "\"I gave {D} some audio gear once, as a thank-you for driving. I can't say exactly what.\""), .direct("How was it given?", "\"Casually. I handed it over when I cleaned out my office. I didn't write anything down.\""), .direct("How long did you direct the band?", "\"Twenty-two years. I retired last spring and cleaned out my office in the weeks after.\""), .direct("What did you give {D}?", "\"A speaker and some microphones from my own supply as a thank-you for driving the band bus.\""), .direct("How did you hand it over?", "\"In the hall outside my office. I put a box in {D}'s hands and said keep it.\""), .cross("Was any of it the booster club's?", "\"I wouldn't have known. The gear I gave was mine, as far as I knew.\""), .cross("Did you tell the club?", "\"No. I didn't think I needed to. I regret not writing it down.\""), .cross("Did you give {D} a mixer and two speakers?", "\"I do not remember the full list. I gave a few items, and I may not recall all of them.\""), .cross("Was any of it the club's?", "\"I would not have known. I thought it was mine, but I cannot swear to that.\""), .cross("You never told the club you gave away any equipment, did you?", "\"No, I did not. I gave away what I considered mine and never thought about the club's inventory, and I should have.\"")],
        theory: ("{D} took the equipment and pawned it.", "The equipment was a gift."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} has a key to the school's back lot.", "The former director did give {DL} a speaker and a few microphones."),
        defendant: [.direct("Where did the equipment you pawned come from?", "\"A former band director gave it to me. I was thanked for driving the band bus, and I was told to keep the gear.\""), .direct("Why did you pawn it?", "\"I needed some money, and I didn't need sound equipment. I used my own name and ID.\""), .direct("Did you cut the padlock?", "\"No. I never touched that trailer. I was home when it was taken.\""), .direct("How do you know the former band director?", "\"I have driven the band bus for several years, and the director often gave me small thanks. This time it was audio gear.\""), .direct("What exactly did you receive?", "\"A mixer, two speakers, and microphones in a box. The director said I could have them if I wanted.\""), .direct("Why did you take the gear to the pawn shop?", "\"I was short on money and had no use for it. I pawned the gear the next day and signed my own name.\""), .cross("The mixer's serial number matches the club's receipt, doesn't it?", "\"That's what you say. The director gave it to me. I didn't check serial numbers.\""), .cross("Nothing about the gift was written down, was there?", "\"No. It was a verbal gift. I know that makes it hard to prove.\""), .cross("You pawned it the day after the lock was cut, didn't you?", "\"Yes. I didn't know it was stolen. If I had, I wouldn't have walked into a shop with a camera.\""), .cross("You pawned the gear the day after the trailer was cut. Isn't that suspicious?", "\"The timing looks bad. I did not know it was the club's. I signed with my real name because I had nothing to hide.\""), .cross("Did you know the mixer had a serial number matching the club's receipt?", "\"No. I never looked at it. I only found out when deputies showed me.\"")],
        openings: ("A booster club's sound equipment trailer had its padlock cut, and $2,200 in gear vanished. A pawn shop took matching equipment from {D}, a school bus driver, the next day, and the mixer's serial number matches the club's receipt. The State will show the ticket and the receipt.", "Jurors will also see a former band director who gave {D} gear as a thank-you, a pawn ticket signed in {D}'s own name, and no one who saw {D} cut the lock."),
        closings: ("A cut padlock Monday, a pawn ticket signed by {D} on Tuesday, and a serial number that matches the club's receipt. The equipment was the club's.", "A gift never written down, a pawn ticket in {D}'s real name, and no witness to the lock. The State has not proved {D} knew the equipment was stolen."),
