        state: [E(.video, 3, "Curb Camera", "{D} strikes {V} at 10:50 a.m. beside the trucks."), E(.document, 2, "Medical Note", "A bloody nose and a bruised cheek."), E(.document, 2, "Reservation Sheet", "The park manager's list assigns the spot to {V} that day."), E(.statement, 2, "Park Manager", "Saw {D} block {V}'s truck and the punch that followed.")],
        defense: [E(.statement, 1, "Pushed First", "{DL} says {V} pushed {D.him} first."), E(.statement, 1, "Open Spot", "{DL} says the spot was open when {D.he} arrived.")],
        role: "Park manager",
        exam: [.direct("What did the reservation sheet show for the spot that day?", "\"The park manager's list assigns the spot to {V}, a food truck operator. {V} had reserved it with me.\""), .direct("How did you manage the spots that day?", "\"I use a sheet that assigns each food truck a curb spot. {V} had reserved that spot the week before, and I set out a cone.\""), .direct("What did you see at 10:30 when {D} arrived?", "\"{D} pulled in behind {V}'s truck and blocked it. I walked over and said the spot was reserved.\""), .direct("What happened at 10:50?", "\"{D} and {V} argued over the spot, and {D} struck {V} in the face. {V} staggered back with a bloody nose.\""), .direct("What did you do when you saw {D} pull in behind {V}'s truck?", "\"I walked over and told {D} the spot was reserved. {D} said no one had told {D.him} and stayed where the truck was.\""), .direct("How did you learn about the confrontation at 10:50?", "\"I heard shouting from my office and looked out the window. By the time I got to the curb, {V} was holding a hand to {V.his} face.\""), .cross("{D} says {V} pushed first, doesn't {D.he}?", "\"I did not see a push. I saw the punch. I cannot say what happened before I looked.\""), .cross("Did {D} arrive before {V}?", "\"I understand {D} arrived about ten minutes earlier. But {V} held the reservation.\""), .cross("Did anyone move a cone before {D} parked?", "\"I do not know who moved it. I only know the spot was reserved for {V}.\""), .cross("Did {D} say the spot was open when arriving?", "\"Yes. {D} said the spot looked empty. The cone had been moved, but I do not know by whom.\""), .cross("Did you see {V} touch {D}?", "\"I saw {V} step close and put a hand toward {D}'s chest. I did not see a hard push.\"")],
        defenseRole: "Park manager's assistant",
        defenseExam: [.direct("Who had the reservation for the spot that day?", "\"{V} did. The list said so, and I helped the manager prepare it that morning.\""), .direct("Did {V} push {D} first?", "\"I did not see it. I only noticed the two of them arguing, and then the punch.\""), .direct("Did {D} arrive before {V} that morning?", "\"Earlier, by about ten minutes. {D} pulled into the curb area while the spot looked open.\""), .direct("What is your role at the park?", "\"I am the manager's assistant. I help set cones and check in food trucks each morning.\""), .direct("What did you see at 10:30?", "\"{D} pulled in behind {V}'s truck and blocked it. {V} was setting up and came over.\""), .direct("Where were you when {D} struck {V}?", "\"In the doorway of the office, about fifty feet away. I saw the punch but not the first moment of the argument.\""), .cross("Who moved the cone that marked the reserved space?", "\"I do not know. I did not see anyone move it, and I did not ask.\""), .cross("Was the spot marked clearly as reserved?", "\"With a cone, yes. But a cone can be moved, and that is where the confusion started.\""), .cross("Did you see {D} throw the punch?", "\"Yes. I saw it from the manager's door. It happened fast.\""), .cross("Did you hear what they said?", "\"Raised voices, but not clear words.\""), .cross("Who put the cone out?", "\"I did. It was on the curb that morning. I did not see who moved it.\"")],
        theory: ("{D} punched {V} over a reserved spot.", "{V} pushed first."),
