        truths: ("{DL} had moved {V}'s cone before parking.", "{V} did put a hand on {DL}'s chest."),
        defendant: [.direct("Did you hit {V}?", "\"Yes, I did. {V} put a hand on my chest during an argument over the spot, and I swung.\""), .direct("Why did you park in that spot?", "\"I arrived first and the spot looked open. I did not know it was reserved, and I moved a cone out of the way.\""), .direct("Did you block {V}'s truck?", "\"Yes, I pulled in behind {V}. I was not trying to block anyone. I was parking.\""), .direct("How long have you run a food truck?", "\"Three years. I work lunch crowds at office parks and depend on good curb spots.\""), .direct("What did you do when you arrived at the curb?", "\"I saw an empty stretch with a cone. I moved the cone and parked behind another truck, thinking the spot was free.\""), .direct("What happened when {V} came over?", "\"{V} said the spot was reserved. We argued, and {V} put a hand on my chest. I swung out of anger.\""), .cross("The park manager's list assigns that spot to {V}, doesn't it?", "\"It does. I did not see the list. I only saw an empty curb and a cone.\""), .cross("You moved {V}'s cone before parking, didn't you?", "\"Yes. I thought it was in the way. I should have asked.\""), .cross("{V} had a bloody nose. Do you regret the punch?", "\"Yes. I am sorry. I should have walked away.\""), .cross("You moved the cone. Isn't a cone a sign the spot is taken?", "\"It is. I thought it was left behind. I should have asked the manager first.\""), .cross("You struck {V} in the face. Was that necessary?", "\"No. I could have stepped back. I am sorry for it.\"")],
        openings: ("Two food truck operators arrived at the same office park curb. {V} held the reservation, {D} pulled in behind and blocked {V}'s truck, and at 10:50 {D} struck {V} in the face, causing a bloody nose.", "The defense case is that {D} arrived first, moved a cone not knowing the spot was reserved, and swung only after {V} put a hand on {D}'s chest."),
        closings: ("A reserved spot, a moved cone, a blocked truck, and a punch on camera that left {V} with a bloody nose. {D} chose to hit instead of talk.", "A confusing cone, a hand on the chest, and a single punch that {D} regrets. The State must prove {D} was not provoked, and {V} did push first."),
        timeline: [(0, "10:30 a.m.: the trucks arrive."), (0, "10:40 a.m.: {D} blocks {V}'s truck."), (0, "10:50 a.m.: the punch."), (1, "The manager sends the curb camera video.")],
        identified: "The curb camera identifies {D}.",
        notDone: ["The reservation sheet's timing was never checked.", "The cone's placement was never photographed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let bikeLockCutterV1 = SmallCases.make(
        key: "story.bikeLockCutter",
        category: .property,
        headlines: ["Cargo Bike Locked at Transit Station Cut Free and Ridden Away", "Owner's Tracker Leads Deputies to Back Porch"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a commuter, valued at $520, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} locked a cargo bike to a rack at a transit station at 7:30 a.m. on {DATE}. By 5 p.m., the lock was cut and the bike was gone. A tracker tag in the bike's frame pinged from {D}'s back porch the next morning. {D} says {D.he} bought the bike from a stranger at a flea market.",
        state: [E(.digital, 3, "Tracker Pings", "The tag in the frame shows the bike at {D}'s address from 11 p.m. that night."), E(.video, 2, "Station Camera", "A person in a gray jacket cuts the lock at 2:10 p.m. and rides off."), E(.physical, 2, "Cut Lock", "A hardened lock cut with bolt cutters and left on the ground."), E(.document, 2, "Purchase Receipt", "{V} bought the bike new for $520 with the serial number printed.")],
        defense: [E(.statement, 1, "Flea Market", "{DL} says the bike was bought for $80 from a stranger at a flea market."), E(.document, 1, "Flea Market Map", "A map of the market's Sunday vendors.")],
        role: "Campus officer",
        exam: [.direct("What did {V} report on {DATE}?", "\"{V} locked a cargo bike at a transit station at 7:30 a.m. By 5 p.m. the lock was cut and the bike was gone.\""), .direct("What does the station camera show?", "\"A person in a gray jacket cutting the lock at 2:10 p.m. and riding off. The cut lock was left on the ground.\""), .direct("How did you trace the bike?", "\"A tracker tag in the frame pinged from {D}'s address starting at 11 p.m. that night. The bike's serial number is on {V}'s receipt for $520.\""), .direct("How did {V} report the theft?", "\"{V} came to the campus office at about 5 p.m. after finding only a cut lock on the rack. {V} had the purchase receipt with the serial number.\""), .direct("What did the tracker show?", "\"A small tag in the frame pinged from {D}'s address starting at 11 p.m. that night. The next morning it was still on the back porch.\""), .direct("What did you find when you went to the address?", "\"A cargo bike on the back porch matching the serial number. {D} answered the door and said the bike was bought at a flea market.\""), .cross("{DL} says the bike was bought at a flea market, doesn't {D.he}?", "\"I couldn't find any vendor. I can't confirm the purchase.\""), .cross("Can you see the person's face on the camera?", "\"No. The person wears a gray jacket and a hood. I can't identify anyone.\""), .cross("Were bolt cutters recovered from {DL}?", "\"I don't have that documented. I can say the lock was cut with bolt cutters.\""), .cross("Did you look at the flea market that {D} named?", "\"We looked at a Sunday vendor map and spoke to organizers. We could not identify a vendor who sold bikes.\""), .cross("Did anyone see {D} at the station?", "\"No. The camera shows a person in a gray jacket, and no face. We have no eyewitness.\"")],
        defenseRole: "Neighbor of the defendant",
        defenseExam: [.direct("Do you live next to {DL}?", "\"Yes. I see {D}'s back porch from my yard.\""), .direct("Did you see a bike?", "\"Yes. A cargo bike appeared on the porch one morning. I assumed {D} had bought it.\""), .direct("Did {DL} talk about it?", "\"{D} said it was a bargain from the flea market. That's how {D} described it.\""), .direct("How long have you been {D}'s neighbor?", "\"Six years. My yard backs onto {D}'s, and I can see the porch from my kitchen window.\""), .direct("When did you first notice the bike?", "\"The morning after the theft. I saw it leaning against the porch rail while I was watering plants.\""), .direct("What did {D} say about it?", "\"That it was a good deal from a flea market. {D} sounded proud and did not seem nervous.\""), .cross("Did you see where it came from?", "\"No. I only saw it on the porch. I can't say where it was before.\""), .cross("What time did you see it?", "\"The next morning. I don't know when it arrived.\""), .cross("Do you know {DL}'s tools?", "\"I know {D} has some. I don't know about bolt cutters.\""), .cross("Did you see {D} bring it home?", "\"No. I was asleep. I only saw it in the morning.\""), .cross("Does {D} own tools that could cut a lock?", "\"{D} has a workshop with tools. I have seen bolt cutters in the garage, but I do not know what they were used for.\"")],
        theory: ("{D} cut a lock and kept the bike.", "{D} bought a bike without knowing."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} owns bolt cutters that match the cut on the lock.", "The seller approached {DL} with the story that it was an estate sale item."),
        defendant: [.direct("How did you get the cargo bike?", "\"From a stranger at a flea market. I paid $80. I didn't know it was stolen.\""), .direct("Why did you pay so little?", "\"It was a bargain. The seller said it was from an estate sale. I didn't ask many questions.\""), .direct("Did you cut a lock at the station?", "\"No. I wasn't at the station that day. I have never taken a bike.\""), .direct("Describe the flea market for the jury.", "\"I went on a Sunday looking for tools. A seller had a cargo bike propped up and said it came from an estate sale and that it had to go that day.\""), .direct("What did you do with the bike?", "\"Paid $80 in cash and wheeled it home. I put it on my back porch and planned to clean it up and ride it.\""), .direct("How did you react when deputies arrived?", "\"I was shocked. I showed them the bike and told them where I had bought it. I did not hide anything.\""), .cross("The tracker puts the bike at your address, doesn't it?", "\"Yes. I took it home. I didn't know it had a tracker.\""), .cross("$80 for a $520 bike is cheap, isn't it?", "\"Yes. I thought I got lucky. I see now it was too good to be true.\""), .cross("You can't name the seller, can you?", "\"No. I paid cash and didn't get a name. I know that sounds like a story.\""), .cross("You own bolt cutters. Could you have cut the lock?", "\"I own tools like many people. I did not cut any lock, and I was not at the station that day.\""), .cross("A $520 bike for $80 from a stranger. Didn't that make you wonder?", "\"It did a little. I told myself I was lucky, and I never pushed the seller for details.\"")],
        openings: ("A cargo bike worth $520 was cut from a transit station rack, and a tracker tag in its frame pinged from {D}'s address that night. A person in a gray jacket is seen cutting the lock. The State will show the tracker, the camera, and the cut lock.", "The defense will point you to an $80 purchase from a stranger, a neighbor who saw the bike appear openly on {D}'s porch, and a camera that cannot identify anyone."),
        closings: ("A lock cut at 2:10 p.m., a bike gone, and a tracker that led straight to {D}'s back porch hours later. The bike was in {D}'s possession.", "{D} bought a bike for $80 from a stranger and left it in plain view. The State has not proved {D} cut the lock or knew the bike was stolen."),
        timeline: [(0, "7:30 a.m.: {V} locks the bike."), (0, "2:10 p.m.: the lock is cut."), (0, "11 p.m.: the tracker pings from {D}'s porch."), (1, "{V} sends the tracker data to campus police.")],
        identified: "A tracker in the frame placed the bike at {D}'s home.",
        notDone: ["No flea market vendor was ever identified.", "The bolt cutters were never compared with the cut on the lock."],
                mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let photoPrintsV1 = SmallCases.make(
        key: "story.photoPrints",
        category: .whiteCollar,
        headlines: ["Wedding Videographer Takes $900 Deposit and Never Delivers Video", "Couple Waits Fourteen Months for Wedding Film"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $900, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} a $900 deposit on {DATE} for a wedding videographer package and signed a contract promising delivery within ninety days. {D} filmed the wedding but never delivered the edited video. Over fourteen months {D} sent four excuses about a computer crash and a lost drive. {V} found two other couples with the same complaint. {D} says the computer failed and the files were lost.",
        state: [E(.document, 3, "Contract", "A signed package for $900 promising delivery within ninety days."), E(.digital, 3, "Messages", "Four excuses over fourteen months and no video."), E(.statement, 2, "Other Couples", "Two couples paid deposits and received nothing."), E(.document, 2, "Deposit Receipt", "$900 received by {D} on {DATE}.")],
        defense: [E(.statement, 1, "Computer Crash", "{DL} says a computer crash destroyed the files."), E(.document, 1, "Repair Receipt", "A repair shop receipt for a computer that would not start.")],
        role: "Newlywed",
        exam: [.direct("What did you pay {D} for?", "\"A $900 deposit for a wedding videographer package. We signed a contract promising delivery within ninety days.\""), .direct("What happened after the wedding?", "\"{D} filmed it but never delivered the edited video. Over fourteen months I got four excuses about a computer crash and a lost drive.\""), .direct("What did you learn about other clients?", "\"Two other couples had the same complaint. They paid deposits and received nothing.\""), .direct("What did the contract promise?", "\"A full day of wedding video, an edited film, and delivery within ninety days of the wedding. We paid a $900 deposit when we signed.\""), .direct("What did {D} say as the months went by?", "\"Four different excuses over fourteen months: a computer crash, a lost drive, a long backlog, and a family emergency. Each message promised the video was coming.\""), .direct("What did you do when you found other couples with the same problem?", "\"We compared messages and contracts. Two other couples had also paid deposits and received nothing, so we went to deputies together.\""), .cross("{D} says the computer failed, doesn't {D.he}?", "\"Yes. A computer crash is possible. But the memory cards were never lost, which {D} did not tell me.\""), .cross("Did you receive any video at all?", "\"No. I never got a video. Another client got a rough edit after eight months.\""), .cross("Did {D} offer a refund?", "\"No. {D} never offered a refund of the $900.\""), .cross("Did you ever see any footage?", "\"No. We saw nothing. We asked for even a short clip and were told the files were being fixed.\""), .cross("Did you ask for your money back?", "\"Yes, several times near the end. {D} said it would be handled later and never refunded anything.\"")],
        defenseRole: "Other client",
        defenseExam: [.direct("Did {D} deliver your video?", "\"Eventually, after eight months. It came as a rough edit, not the polished version we were promised.\""), .direct("What reason did {D} give for the delay?", "\"A computer crash. {D} said the editing computer died and that the work had to be redone from the start.\""), .direct("Were you refunded any of your money?", "\"No. I never asked for a refund, because I did get a video in the end, though late.\""), .direct("What did you hire {D} for?", "\"Our wedding video. We paid a deposit and a final balance, and the film came after a long wait.\""), .direct("How long did it take to get the video?", "\"About eight months, well past the ninety days in the contract. We sent several reminders.\""), .direct("What was the final product like?", "\"A rough edit with some great moments and some rough cuts. It was not polished, but we were glad to have it.\""), .cross("Did you get the video you paid for?", "\"Yes, a rough edit. It was not what the package promised, but it was something.\""), .cross("Were you aware that others got nothing?", "\"I heard that later. I felt lucky to have gotten anything at all.\""), .cross("Did you wait longer than ninety days?", "\"Yes, about eight months. It was frustrating.\""), .cross("Did {D} offer any reason for the delay?", "\"A computer crash. {D} said files had been damaged and had to be rebuilt.\""), .cross("Would you recommend {D} to others?", "\"Not now. I got lucky, and I know other couples did not.\"")],
        theory: ("{D} took deposits and never delivered.", "A computer crash destroyed the files."),
        allocution: "\"It was wrong from the start, and I knew it.\"",
        truths: ("{DL} had sold ten more packages while the files sat unedited.", "The computer did crash, but the memory cards were never lost."),
        defendant: [.direct("Did you intend to deliver the videos?", "\"Yes. I filmed the wedding and planned to edit it. I did not mean to leave anyone with nothing.\""), .direct("Why was the video not delivered?", "\"My computer crashed and I lost work. I kept trying to fix it, and I sent updates when I could.\""), .direct("Did you sell other packages while the files sat unedited?", "\"Yes. I sold more. I should not have, and I let the work pile up.\""), .direct("How did you build your videography business?", "\"I started shooting events on weekends and grew to a few packages a month. I did the filming, editing, and delivery myself.\""), .direct("What happened with your computer?", "\"It would not start one night. A repair shop said the drive was dead. I thought I had lost the files, though I still had the memory cards.\""), .direct("Why did you keep selling packages during that time?", "\"I was behind and trying to catch up. I took on more work to cover costs and let delays pile up.\""), .cross("Four excuses over fourteen months. Isn't that a lot?", "\"It is. I was overwhelmed and ashamed, and I kept putting it off.\""), .cross("The memory cards were never lost, were they?", "\"No. They were not. The computer crashed, but the cards were safe. I did not tell {V.him}.\""), .cross("You took $900 and gave nothing. Will you refund it?", "\"I would like to. I do not have it all right now, but I want to make it right.\""), .cross("The memory cards were never lost. Why not edit from them?", "\"I wish I had. I was overwhelmed and kept putting it off, and then I was ashamed to contact people.\""), .cross("You took deposits from new couples while old ones waited. Isn't that dishonest?", "\"It was irresponsible. I did not mean to cheat anyone, but I let it spiral.\"")],
        openings: ("{V} paid {D} a $900 deposit for a wedding videographer package with a contract promising delivery in ninety days. {D} filmed the wedding but never delivered, sending four excuses over fourteen months.", "Jurors will hear that the computer did crash, that {D} delivered a rough edit to another client, and that {D} never meant to cheat anyone."),
        closings: ("A signed contract, $900 paid, a wedding filmed, and no video after fourteen months. {D} kept selling new packages while old ones sat unedited.", "A real computer crash and a photographer who fell behind. The State must prove {D} meant to take the deposit and give nothing, and poor management is not fraud."),
        timeline: [(0, "{V} pays the $900 deposit."), (30, "{D} films the wedding."), (120, "The delivery date passes."), (420, "{V} reports the contract to the Sheriff's Office.")],
        identified: "The contract and deposit receipt name {D}.",
        notDone: ["The repair shop's records were never subpoenaed.", "The memory cards were never examined for the footage."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let swingChainsV1 = SmallCases.make(
        key: "story.swingChains",
        category: .property,
        headlines: ["Basketball Nets Cut and Hoops Bent at Town Court Overnight", "Court Camera Shows Two Teens With Saw and Bar"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a town, basketball nets and hoops, causing damage of $420, on {DATE}.",
        ages: 18...60,
