        state: [E(.video, 3, "Street Camera", "{D} snaps mirrors off eight parked cars between 3:02 and 3:06 a.m."), E(.physical, 3, "Recovered Mirrors", "Six mirrors found in a hedge two houses from {D}'s home."), E(.document, 2, "Repair Estimate", "$320 for {V}'s mirror."), E(.statement, 2, "{V}", "The mirror was fine the evening before.")],
        defense: [E(.statement, 1, "Already Loose", "{DL} says the mirrors were already loose and fell off when touched."), E(.document, 1, "Car Inspection Note", "A note that older mirrors on the street sat loose.")],
        role: "Car owner",
        exam: [.direct("What happened to your car?", "\"My side mirror was snapped off. It was fine the evening before, and it cost $320 to replace.\""), .direct("What was recovered?", "\"Six mirrors found in a hedge two houses from {D}'s home. {V}'s was one of the eight.\""), .direct("When did you last see your mirror intact?", "\"The evening before at about nine, when I parked. I checked the car and the mirror was solid and folded in normally.\""), .direct("How did you learn what happened?", "\"At 7 a.m. I found my mirror gone and the housing hanging by a wire. Neighbors were standing outside with their own damage.\""), .direct("What does the camera show?", "\"{D} walking down the street from 3:02 to 3:06 a.m., grabbing one mirror after another and snapping it off. There are eight cars in that stretch.\""), .direct("What did you do after you learned eight cars had been hit?", "\"I took photos of the stump where my mirror had been, called the sheriff's office, and got a repair estimate for $320 before lunch.\""), .cross("{D} says the mirrors were already loose, doesn't {D.he}?", "\"Yes. Mine was not loose. It was solid when I parked.\""), .cross("Do older mirrors come loose?", "\"Sometimes, yes. A neighbor said the neighbor's mirror fell off in the spring.\""), .cross("Did anyone see {D} touch a mirror?", "\"Only the camera. No person saw it that I know of.\""), .cross("Did anyone see {D} do it?", "\"Only the camera. No neighbor was awake or outside at that hour.\""), .cross("Have you had mirror trouble before?", "\"Never. My car is only three years old, and the mirrors are tight.\"")],
        defenseRole: "Neighbor with a loose mirror",
        defenseExam: [.direct("Do older mirrors on parked cars come loose?", "\"Yes. Mine fell off in the spring on its own, with no one near it. Older mirrors do loosen.\""), .direct("Were all eight mirrors on that street loose?", "\"I do not know. I only know about mine. I did not check the others on the street.\""), .direct("Does {D} walk the street at night often?", "\"Most nights. {D} walks to clear {D.his} head. I have seen {D} out there many times.\""), .direct("How long have you lived on that street?", "\"Ten years. Most of us park at the curb, and older cars have a lot of wear.\""), .direct("What happened with your mirror in the spring?", "\"It dropped off on its own when I closed the door. The bracket was cracked and I taped it until I could afford a replacement.\""), .direct("What do you know about the other mirrors?", "\"I heard a couple were loose. I cannot say which ones or how many.\""), .cross("Did you see {D} touch any mirror?", "\"No. I did not see it. I was asleep that night.\""), .cross("Was your mirror loose before it fell?", "\"It was a little wobbly. I had been meaning to tighten it.\""), .cross("Does a loose mirror snap off by a person walking past?", "\"It would not take much. But eight in four minutes is a lot.\""), .cross("Did you see {D} that night?", "\"No. I was in bed.\""), .cross("Was your mirror attached the night before?", "\"It was wobbly but still on. It was not the one on camera.\"")],
        theory: ("{D} broke off eight mirrors.", "The mirrors were already loose."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had been drinking and snapped them off for fun.", "A few mirrors were loose from age."),
        defendant: [.direct("Did you snap off the mirrors?", "\"Some of them were already loose. I touched a few, and they came off in my hand.\""), .direct("Why were you out at 3 a.m.?", "\"I walk at night. I had been drinking, and I did not think much about what I was doing.\""), .direct("What about the mirrors in the hedge?", "\"I picked them up and put them there. I did not know what else to do with them.\""), .direct("What were you doing out at 3 a.m.?", "\"I had been at a friend's place drinking and was walking home. I take that street almost every night.\""), .direct("What happened with the mirrors?", "\"I touched one and it hung loose. I pulled a few more because I was drunk and thought it was funny.\""), .direct("What did you do with the mirrors?", "\"I carried some home and dropped them in a hedge near my house. I did not plan anything.\""), .cross("The camera shows you snapping them off one after another, doesn't it?", "\"It does. I was drunk and messing around. I know it looks bad.\""), .cross("Eight cars in four minutes. Were they all loose?", "\"No. I do not think so. Some I pulled harder.\""), .cross("Will you pay for the mirrors?", "\"Yes. I will pay. I apologize.\""), .cross("Were all eight mirrors loose before you touched them?", "\"No. Some were solid and I yanked them. I was reckless.\""), .cross("Why put the mirrors in a hedge near your own home?", "\"I was drunk and did not think. I wanted them out of my hands.\"")],
        openings: ("At 3 a.m., a street camera shows {D} walking down a line of parked cars and snapping the mirrors off eight of them in four minutes. Six mirrors were found in a hedge near {D}'s home.", "Jurors will hear that older mirrors do come loose, that some of these were already loose, and that {D} meant no harm."),
