        defense: [E(.statement, 1, "On the Phone", "{DL} says {D.he} was talking loudly on a call."), E(.document, 1, "Phone Record", "A call lasting twenty-two minutes that evening.")],
        role: "Theater manager",
        exam: [.direct("What happened outside your theater at 11:10 p.m.?", "\"After a late show, {D} sat on the curb and shouted insults at patrons leaving. It went on from 11:10 to 11:40.\""), .direct("What did you do?", "\"I asked {D} twice to move, and {D} said no both times. Patrons crossed the street to avoid {D}.\""), .direct("What did deputies find?", "\"{D} on the curb at 11:40 p.m., still shouting. The deputy's report says so.\""), .direct("How did you notice {D}?", "\"The late show let out at about 11:10. {D} was sitting on the curb in front of the entrance and calling out at people as they walked past.\""), .direct("What kind of things was {D} saying?", "\"Insults aimed at passers-by, loud enough that patrons slowed and looked back. Several crossed the street to avoid {D}.\""), .direct("What happened after you asked {D} to move?", "\"I asked twice, and {D} said no. I called deputies, who arrived at 11:40, and {D} was still shouting when they got there.\""), .cross("{D} says {D.he} was only talking loudly into a phone, doesn't {D.he}?", "\"At first, yes. I think {D} was on the phone. It changed after that.\""), .cross("Was the street noisy?", "\"Yes. There was loud traffic. I know it could make someone shout.\""), .cross("Did you hear {D} insult a particular patron?", "\"A patron told us so. I heard shouting but not every word.\""), .cross("Could you tell whether {D} was on a call?", "\"At first {D} seemed to be on the phone. Later I did not see the phone, and the shouting continued.\""), .cross("Did {D} touch anyone?", "\"No. {D} stayed on the curb and never moved toward a patron.\"")],
        defenseRole: "Theater usher",
        defenseExam: [.direct("Was {D} talking on a phone?", "\"At first, yes. {D} was on a call and talking loudly to be heard over the street.\""), .direct("Did {D} insult patrons?", "\"Not that I heard. I stood near the door and did not hear any insults, only loud talking.\""), .direct("Was the street noisy that night?", "\"Loud traffic. Buses and cars were going by all the time, so people had to raise their voices.\""), .direct("What do you do at the theater?", "\"I usher, tear tickets, and help patrons leave after shows. I was at the door that night.\""), .direct("What did you see of {D}?", "\"A person on the curb with a phone to an ear, talking loudly. I did not hear specific insults.\""), .direct("How noisy was the street?", "\"Very. Buses and trucks went by, and you had to raise your voice to be heard.\""), .cross("Did {D} keep shouting after the phone call ended?", "\"For a while, yes. {D} kept talking loudly after the call.\""), .cross("Did patrons cross the street to avoid {D}?", "\"Some did. I saw a few people cross.\""), .cross("Was {D} banned from the theater before?", "\"I had heard that.\""), .cross("Did {D} talk to patrons directly?", "\"I did not see that. {D} seemed to be talking into the phone.\""), .cross("Did you hear what the manager said?", "\"I heard the manager ask {D} to move. {D} said something short and stayed.\"")],
        theory: ("{D} shouted at patrons and refused to move.", "{D} was loud on a phone call."),
        allocution: "\"I'm sorry for the trouble I caused.\"",
        truths: ("{DL} had been banned from the theater for similar conduct.", "{DL}'s phone log shows a long call and {DL} was shouting over traffic noise to be heard."),
        defendant: [.direct("Did you shout at patrons?", "\"I was talking loudly on a phone, over traffic noise. I did not mean to insult anyone.\""), .direct("Why did you sit on the curb?", "\"I was tired, and I was on a long call. It was a place to sit.\""), .direct("Did you refuse to move when the manager asked?", "\"Yes. I did not want to cut my call short, and I did not realize it was a problem.\""), .direct("Why were you at the theater?", "\"I was waiting for a ride after a long evening and sat on the curb. I had a long conversation on my phone about a family matter.\""), .direct("Why did you talk so loudly?", "\"Traffic was loud and the connection was poor. I raised my voice to be heard, and I got heated about the subject.\""), .direct("What happened when the manager asked you to move?", "\"I said I would in a minute. I did not want to cut my call off. I know that sounds stubborn.\""), .cross("You were banned from the theater before, weren't you?", "\"Yes. I was. I know that. I should have stayed away.\""), .cross("Patrons crossed the street to avoid you. Why?", "\"I do not know. I was loud. I did not mean to scare anyone.\""), .cross("You kept shouting until deputies arrived, didn't you?", "\"I kept talking, and then I was arrested. I should have lowered my voice.\""), .cross("A patron says you insulted people. Did you?", "\"If I did, it was not at them. I was talking about someone else on the phone.\""), .cross("The call lasted twenty-two minutes. Why keep shouting after patrons left?", "\"The call was still going and I was upset. I was not thinking about the street.\"")],
        openings: ("After a late show, {D} sat on the curb outside a theater and shouted insults at patrons leaving at 11:10 p.m. The manager asked {D} twice to move and was refused, and deputies arrived at 11:40.", "The defense evidence will establish that {D} was on a long phone call, shouting over loud traffic, and never meant to insult anyone."),
        closings: ("Thirty minutes of shouting from the curb, two refusals to move when the manager asked, and patrons crossing the street to avoid {D}. {D} had been banned from the theater before.", "A long phone call, loud traffic, and a person who raised a voice to be heard over buses. The State must prove {D} meant to insult patrons, and loud talking is not a crime."),
