        state: [E(.video, 3, "Neighbor Camera", "A trailer is loaded with two kayaks and a grill at 6:05 a.m. on checkout day."), E(.document, 3, "Inventory Photos", "Photos before the stay show two kayaks and a grill in place."), E(.document, 2, "Rental Agreement", "Lists the kayaks and grill as property of the owner not for removal."), E(.statement, 2, "Owner", "Never offered anything as a gift.")],
        defense: [E(.statement, 1, "Gift for a Review", "{DL} says the owner offered the items for a good review."), E(.document, 1, "Message Thread", "A thread from before the stay mentioning 'extras for good reviews.'")],
        role: "Vacation rental owner",
        exam: [.direct("What did you find missing after the weekend rental?", "\"Two kayaks and a gas grill from the dock and patio. They were worth about $900.\""), .direct("What do your inventory photos show?", "\"Two kayaks and a grill in place before the stay. The rental agreement lists them as my property, not for removal.\""), .direct("What was the rental arrangement?", "\"A three-night weekend stay at my lake house with a written agreement. It listed two kayaks and a gas grill as my property that could not be removed.\""), .direct("When did you discover the loss?", "\"After checkout, I walked the property and found the dock bare and the patio missing its grill. My inventory photos from before the stay showed both items in place.\""), .direct("What did the neighbor's camera show?", "\"At 6:05 a.m. on checkout day, a trailer backs up and two kayaks and a grill are loaded. The plate belongs to {D}.\""), .direct("What did you do after you found the kayaks and grill gone?", "\"I checked the dock and patio, compared them to my inventory photos, and called the neighbor whose camera faces the driveway.\""), .cross("{D} says you offered them as a gift for a good review, doesn't {D.he}?", "\"I never offered anything as a gift. I did offer a coupon for a review, and that is all.\""), .cross("Why would {D} think they were a gift?", "\"I do not know. I did not say that.\""), .cross("Did {D} load openly?", "\"The camera shows loading at dawn. I cannot say whether it was open or hidden.\""), .cross("Did you ever offer extras for good reviews?", "\"Only a discount coupon on a future stay. I never offered equipment.\""), .cross("Did {D} leave a note or message about the items?", "\"No. {D} left no note and never mentioned them.\"")],
        defenseRole: "Fellow renter",
        defenseExam: [.direct("Did the owner offer extras for reviews?", "\"Yes, a coupon, and maybe more. I remember the owner mentioning perks for good reviews.\""), .direct("Did the owner mention kayaks to you?", "\"Not to me. I do not recall any mention of kayaks or a grill as a gift.\""), .direct("Did {D} load at dawn?", "\"We left early for a hike. Loading before dawn would fit that. I saw the trailer being loaded.\""), .direct("How do you know {D}?", "\"We are friends who rented the house together for the weekend. We split the cost and shared meals.\""), .direct("What did the owner say about extras?", "\"The message thread mentioned extras for good reviews. I do not remember equipment being named.\""), .direct("What did you see on the morning of checkout?", "\"{D} loaded the trailer before we left for a hike. I helped carry a kayak.\""), .cross("Did you see {D} load the kayaks?", "\"Yes, I did. I saw them loaded onto the trailer.\""), .cross("Did you ask the owner about it?", "\"No. I did not. I took {D}'s word.\""), .cross("Did {D} say the owner had given the kayaks?", "\"Yes. {D} said the owner offered them as a thank-you. I took {D} at {D.his} word.\""), .cross("Did you check with the owner?", "\"No. I did not ask. I assumed it was fine.\""), .cross("You were not there when {D} loaded the trailer, were you?", "\"No. I heard about it afterward. I cannot tell you who said what in the owner's messages, only what {D} told me.\"")],
        theory: ("{D} took kayaks and a grill from a rental.", "{D} was offered extras for a review."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} loaded the trailer before dawn so the owner would not notice.", "The thread mentioned a coupon, not equipment."),
        defendant: [.direct("Did you take the kayaks and the grill?", "\"Yes, I took them. The owner offered them as a gift for a good review, and I believed that.\""), .direct("Why did you load before dawn?", "\"We left early for a hike. I loaded the trailer before we went.\""), .direct("What did the owner say?", "\"The owner mentioned a coupon in the thread. I took it to mean more than that, and I may have misread it.\""), .direct("What was your weekend like at the lake house?", "\"We swam, kayaked, and cooked on the grill. The owner had mentioned some extras for a good review, and the kayaks and grill came up in conversation.\""), .direct("What did you understand about the extras?", "\"That the owner would give me something nice if I wrote a strong review. I took that to include the gear I had used.\""), .direct("How did you take the items?", "\"We loaded the trailer in the morning before our hike. I left the review online that afternoon.\""), .cross("The rental agreement says the kayaks and grill are not for removal, doesn't it?", "\"It does. I did not read that part. I should have, yes.\""), .cross("You loaded at 6 a.m. so the owner would not notice, didn't you?", "\"No. I loaded early for a hike. I did not try to avoid anyone.\""), .cross("The thread mentions a coupon, not equipment, doesn't it?", "\"It does. I assumed more. I feel awful about it.\""), .cross("The agreement lists those items as not for removal. Did you read it?", "\"I skimmed it. I should have read it closely and asked the owner for a note.\""), .cross("You never asked the owner in writing whether the kayaks were yours to keep, did you?", "\"No. I took it as a friendly remark and did not follow up. I should have asked before I loaded anything.\"")],
        openings: ("{D} rented a lake house for a weekend, and on checkout day a neighbor's camera shows a trailer loaded with two kayaks and a grill at 6:05 a.m. The plate is {D}'s, and the items were worth $900.", "By the end of this trial, the proof will show that the owner offered perks for a good review and that {D} honestly believed the items were a gift."),
        closings: ("A trailer loaded before dawn, items listed in the agreement as not for removal, and a plate registered to {D}. The owner never offered a gift.", "The owner offered a coupon and perks for reviews, and {D} read it as a gift. The State must prove {D} knew the kayaks and grill were not {D.his} to take."),
