        state: [E(.document, 3, "Sales Contract", "A twelve-month package for $480 signed by {D} on {DATE}."), E(.document, 3, "Default Notice", "A landlord notice dated three weeks before the sale warning of lease termination."), E(.digital, 2, "Social Media Posts", "{D} advertised the same package in posts on the day of the sale and the two weeks after."), E(.statement, 2, "{V}", "Was told the studio had a long lease and was growing.")],
        defense: [E(.statement, 1, "Planned New Space", "{DL} says {D.he} was negotiating for a second location."), E(.document, 1, "Draft Lease", "An unsigned draft lease for a different building dated six weeks later.")],
        role: "Parent",
        exam: [.direct("What did you buy from {DL} on {DATE}?", "\"A twelve-month prepaid class package for my child. It cost $480, and {D} signed the sales contract.\""), .direct("What happened to the studio?", "\"Two months later, the landlord locked it, and {D} stopped answering my calls.\""), .direct("What did you learn about {DL}'s lease?", "\"A landlord notice dated three weeks before our sale warned of lease termination. I was told the studio had a long lease and was growing.\""), .direct("What did you pay and what was promised?", "\"$480 for a twelve-month prepaid class package for my child. {D} told me the studio had a long lease and was growing.\""), .direct("What happened two months later?", "\"I drove my child to class and found the doors chained with a landlord's notice taped to the glass. {D} stopped answering my calls and messages.\""), .direct("How did you find out the studio had been locked?", "\"I drove there for a Saturday class and found a notice on the door and chains on the handles. My child stood there in a uniform.\""), .cross("{DL} says {D.he} meant to reopen elsewhere, doesn't {D.he}?", "\"A draft lease exists for another building. It was unsigned.\""), .cross("Did {DL} tell you about the notice?", "\"No. Never. I only learned later.\""), .cross("Did you ask for a refund?", "\"Yes. I was never given one. I'm out the $480.\""), .cross("Did you see {D}'s advertisement after the default notice?", "\"Yes. {D} kept posting the package on social media for weeks afterward.\""), .cross("Did {D} ever show you a lease for a new space?", "\"No. I only heard about a new space later.\"")],
        defenseRole: "Studio instructor",
        defenseExam: [.direct("Did you teach at the studio?", "\"Yes. I was an instructor. I taught the kids' classes.\""), .direct("Did {DL} talk about a second location?", "\"Yes. {D} said {D.he} was working on a new space. I saw a draft lease.\""), .direct("Was {DL} committed to the studio?", "\"I believed so. {D} put a lot into it. It's the only thing {D} did.\""), .direct("How long did you teach at the studio?", "\"Two years, mostly kids' classes on weekday afternoons.\""), .direct("What did {D} tell you about the studio's future?", "\"That business was picking up and that {D} was working on a bigger space. {D} seemed excited.\""), .direct("How did the closure affect you?", "\"I lost my job and some pay. I had to call parents and tell them classes were over.\""), .cross("Did {DL} tell you about the default notice?", "\"No. I didn't know about it. I only learned when the doors were locked.\""), .cross("Was the lease signed?", "\"Not that I saw. It was a draft. I can't say it was real.\""), .cross("Did you get paid?", "\"Not for the last stretch. I lost wages too.\""), .cross("Did you know about the default notice?", "\"No. I only learned about it after the closure.\""), .cross("Did you see the draft lease for the new place?", "\"Once, a draft on a table. I did not know if it was signed.\"")],
        theory: ("{D} sold classes while the studio faced eviction.", "{D} planned to reopen at a new location."),
        allocution: "\"I should have told the truth the first time.\"",
        truths: ("{DL} sold fourteen other packages after receiving the default notice.", "The draft lease was real and {DL} had a deposit on it."),
        defendant: [.direct("What was your plan for the studio?", "\"To keep it open or move it to a second location. I was negotiating for a new space when the landlord locked the doors.\""), .direct("Did you know about the default notice when you sold the package?", "\"Yes. I knew I was behind. I thought I could work it out, and I believed in the studio.\""), .direct("Did you mean to cheat {V}?", "\"No. I meant to teach the classes. I was trying to keep the studio going and I misjudged.\""), .direct("How long had you run the studio?", "\"Four years. I taught kids and adults and built up a small following. Rent was my biggest cost.\""), .direct("How did the rent problem arise?", "\"Enrollment dropped after a big tenant moved out and I fell behind. The landlord sent a default notice, and I tried to work out a plan.\""), .direct("What was your plan after the notice?", "\"To find a new space and keep classes going. I was negotiating a second location and had put down a deposit.\""), .cross("The notice came three weeks before the sale, didn't it?", "\"Yes. I should have told parents. I was afraid they'd leave.\""), .cross("You advertised the package after the notice, didn't you?", "\"Yes. I kept advertising. I thought I'd fix it.\""), .cross("You stopped answering {V}'s calls, didn't you?", "\"Yes. I was embarrassed. I should have answered.\""), .cross("You sold packages after you knew you might lose the lease. Why not tell parents?", "\"I was afraid they would leave. I thought I could fix it, and that was wrong.\""), .cross("How many parents lost money?", "\"Around two dozen. I will not pretend otherwise. I let a lot of families down.\"")],
        openings: ("{D} sold {V} a twelve-month prepaid class package for $480 while holding a landlord's default notice dated three weeks earlier. Two months later the studio was locked. The State will show the contract, the notice, and the posts.", "The defense will point you to a studio owner fighting to keep the doors open, an instructor who saw a draft lease for a second location, and no plan to cheat."),
        closings: ("A twelve-month package sold with a default notice in hand, a studio locked two months later, and no refund. {V} was told the lease was long and the studio was growing.", "{D} was negotiating a new space and hoped to keep going. The State has not proved {D} meant to take {V}'s money knowing the studio would close."),
