    static let lunchBenefitsV1 = SmallCases.make(
        key: "story.lunchBenefits",
        category: .whiteCollar,
        headlines: ["Applicant Lists Third Child Who Does Not Exist to Get Summer Meal Benefits", "School Records Show Two Enrolled Children, Application Lists Three"],
        law: "falsePretenses",
        spec: "Obtained property of {V}, a school district, by deception, $420 in summer meal benefits, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} applied for summer meal benefits for three children on {DATE}. The school district's enrollment records show only two children in {D}'s household. The third child's name does not match any record and the benefit card carried $140 per child for the summer. {D} says the third child was a niece staying temporarily.",
        state: [E(.document, 3, "Application", "Three children listed with a signed certification of household members."), E(.document, 3, "Enrollment Records", "Two children enrolled at {D}'s address; none matching the third name."), E(.digital, 2, "Benefit Ledger", "$420 loaded in three equal amounts and spent by the end of July."), E(.statement, 2, "District Clerk", "Found no school or medical record for the third child.")],
        defense: [E(.statement, 1, "Niece Staying", "{DL} says a niece was living in the home that summer."), E(.document, 1, "Bus Pass", "A summer bus pass issued to a child with the niece's surname.")],
        role: "District clerk",
        exam: [.direct("What did {D}'s application for summer meal benefits list?", "\"Three children, with a signed certification of household members. Each child carried $140 on the benefit card for the summer.\""), .direct("What did the enrollment records show?", "\"Only two children enrolled at {D}'s address. The third name does not match any school or medical record I could find.\""), .direct("What happened with the benefit card?", "\"$420 was loaded in three equal amounts and spent by the end of July. That is the benefit tied to the third child.\""), .direct("What does the application ask a parent to certify?", "\"A list of every child in the household, their ages, and a signature stating that the information is true. {D} listed three children.\""), .direct("What did you check against?", "\"Enrollment records for our district. They showed two children at {D}'s address, and none matched the third name.\""), .direct("How was the benefit used?", "\"$420 was loaded onto a card in three equal amounts, and the card was spent by the end of July at grocery stores.\""), .cross("{D} says the third child was a niece staying temporarily, doesn't {D.he}?", "\"Yes. A relative says a niece stayed for two weeks in July. I will agree that is possible.\""), .cross("Would a niece staying two weeks show up in school records?", "\"Not necessarily. A visiting child might not be enrolled, so a missing record is not conclusive.\""), .cross("Did you speak with the niece?", "\"No. I only looked at records. I never spoke with any child or relative.\""), .cross("Did you check whether the third child went to another district?", "\"Yes. We checked neighboring districts and a state database. We found no child by that name.\""), .cross("Is it possible a visiting child would not appear in records?", "\"Yes. A child visiting for a short stay might not have records here.\"")],
        defenseRole: "Relative of the child",
        defenseExam: [.direct("Did a child stay with {D} that summer?", "\"A niece did, for two weeks in July. The child was eight and stayed with {D} while a parent traveled.\""), .direct("Did the niece enroll in school there?", "\"No. The child was only visiting. The child went home at the end of the two weeks and did not enroll anywhere.\""), .direct("Was the niece on the application?", "\"I think so. {D} told me {D.he} listed the children in the home, and the niece was one of them.\""), .direct("How do you know {D}?", "\"We are related. I visit often, and I helped with the niece that summer.\""), .direct("What did you see of the niece in July?", "\"The niece stayed in the spare room and played with the other kids, then went home after two weeks.\""), .direct("What did {D} say about the benefits?", "\"That the niece was part of the household for the meals program. {D} did not seem to think it was a problem.\""), .cross("Did the niece live there all summer?", "\"No. Only two weeks in July. The benefit covered the whole summer, so that part is a problem.\""), .cross("Do you know what name {D} listed for the third child?", "\"No. I did not see the application. I only know about the niece.\""), .cross("Are you related to {D}?", "\"Yes. I am a relative. I know that matters, and I am telling you what I know.\""), .cross("Did you see {D}'s application?", "\"No. I only know what {D} told me.\""), .cross("You do not know the third child's name that was on the application, do you?", "\"No. I only know a niece stayed for a couple of weeks. I did not see the paperwork or hear what name was used.\"")],
        theory: ("{D} listed a child who did not live there.", "{D} listed a niece staying for the summer."),
        allocution: "\"It was wrong from the start, and I knew it.\"",
        truths: ("{DL} made up a name for the third child.", "A niece did stay for two weeks in July."),
        defendant: [.direct("Did you invent a third child on the application?", "\"No. I listed a niece who was staying with me. I thought the child counted as part of the household.\""), .direct("How long did the niece stay?", "\"Two weeks in July. The child was eight. The child was visiting while a parent was away.\""), .direct("Did you spend the benefit for all three children?", "\"Yes. I spent the full amount by the end of July, on food for the children in my home.\""), .direct("Who lives in your household?", "\"Two of my own children and sometimes extended family. I work long hours and rely on school meals in the summer.\""), .direct("Tell us about the niece.", "\"A niece came to stay for two weeks in July while the child's parents moved. The child was eight and ate with us every day.\""), .direct("Why did you apply for three children?", "\"I thought I could include the niece because the child was in my home. I did not know the benefit was only for children who lived there all summer.\""), .cross("The niece was there two weeks, but the benefit ran the whole summer, didn't it?", "\"Yes. I did not think about that. I should have asked.\""), .cross("No school or medical record matches the third name, does it?", "\"The child was visiting. The child had no record here. I should have explained that.\""), .cross("You signed a certification of household members, didn't you?", "\"I did. I believed it was accurate, and I did not read it closely enough.\""), .cross("You signed a form certifying who lived in your home. Did you read it?", "\"I read it quickly. I assumed a child staying with me counted.\""), .cross("The niece stayed only two weeks, but you took benefits for the whole summer. Isn't that wrong?", "\"In hindsight, yes. I should have asked the office about it.\"")],
        openings: ("{D} applied for summer meal benefits for three children, but the district's records show only two children at {D}'s address and no record of the third. The card carried $140 per child, and $420 was spent by the end of July.", "Listen for the defense evidence, which will show that a niece did stay with {D} for two weeks in July and that {D} honestly listed everyone living at the home."),
        closings: ("Three children on a signed certification, two in the records, and $420 spent. {D} signed a statement that the district found it could not verify.", "A niece who really did stay in the home for two weeks. The State must prove {D} invented a child, and a visiting relative is not a made-up name."),
        timeline: [(0, "{D} files the application."), (7, "The district loads the benefits."), (60, "The district checks enrollment."), (75, "The district reports the application.")],
        identified: "The signed application names {D}.",
        notDone: ["The niece's school records were never requested.", "The district never asked {DL} to correct the form."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let propaneShortV1 = SmallCases.make(
        key: "story.propaneShort",
        category: .whiteCollar,
        headlines: ["Ice Delivery Driver Leaves Short Bags With Restaurants and Bills for Full Weight", "Scale Check Shows Twenty-Pound Bags Weigh Twelve"],
        law: "falsePretenses",
        spec: "Obtained property of {V}, a restaurant, by deception, $210, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} delivered forty bags of ice marked as twenty pounds to {V}'s restaurant on {DATE} and billed for full weight. The manager weighed a sample the next day and found the bags averaged twelve pounds. Three other restaurants reported the same shortage. The extra charge to {V} came to $210. {D} says the bags froze and lost weight.",
        state: [E(.document, 3, "Delivery Tickets", "Forty bags billed at twenty pounds each on {D}'s ticket."), E(.physical, 3, "Sample Bags", "Six bags weighed on a calibrated scale at twelve pounds each."), E(.document, 2, "Other Restaurant Complaints", "Three restaurants report similar shortfalls."), E(.statement, 2, "Restaurant Manager", "Weighed the bags the next morning.")],
        defense: [E(.statement, 1, "Frozen Loss", "{DL} says ice loses weight when it freezes together."), E(.document, 1, "Supplier Spec", "A spec sheet that says bags may vary by up to 5 percent.")],
        role: "Restaurant manager",
        exam: [.direct("What did {D} deliver to your restaurant?", "\"Forty bags of ice marked as twenty pounds each, billed at full weight. The delivery ticket says forty bags at twenty pounds.\""), .direct("What did the shortage cost you?", "\"About $210 in extra charges. Three other restaurants reported the same shortage on their deliveries.\""), .direct("What was the delivery?", "\"Forty bags of ice labeled as twenty pounds each, delivered to my kitchen door at about ten the night before. The ticket billed forty bags at full weight.\""), .direct("What did you do the next morning?", "\"I took six bags and weighed them on our calibrated food scale. Each weighed twelve pounds, far short of the label.\""), .direct("What did {D}'s company say?", "\"That ice loses weight when it stacks and freezes together. They offered a small credit but not for the full difference.\""), .direct("How did you weigh the sample bags the next morning?", "\"I laid six bags on our calibrated kitchen scale one at a time. Each one came in at twelve pounds, well below the twenty on the ticket.\""), .cross("{D} says the bags froze and lost weight, doesn't {D.he}?", "\"Yes. A little weight loss is possible when bags are stacked, but not eight pounds a bag.\""), .cross("Did you complain to {D} right away?", "\"I called the next morning. I weighed the bags first, so I had numbers to give.\""), .cross("Did {D}'s company deliver to you regularly?", "\"Weekly. I had never had a shortage like this before.\""), .cross("How much of the shortage could be water loss?", "\"A pound or two is possible. Eight pounds on every bag is not.\""), .cross("Did you check all forty bags?", "\"Only six, chosen from different parts of the stack. They were all the same weight.\"")],
        defenseRole: "Manager at another restaurant",
        defenseExam: [.direct("Do ice bags lose weight from freezing?", "\"A little, when they stack up and press together. Some water squeezes out, and the weight drops slightly.\""), .direct("Were your own ice bags short last week?", "\"Twelve pounds, yes. My bags weighed twelve instead of twenty, the same as the manager's.\""), .direct("Did {D}'s company deliver for you weekly?", "\"Weekly, for over a year. This was the first time I had a weight problem with the bags.\""), .direct("How long have you managed your restaurant?", "\"Eight years. I get ice weekly from {D}'s company, and I check it when it comes.\""), .direct("What did you notice about the bags last week?", "\"They looked small. I weighed some and found twelve pounds each.\""), .direct("Did you complain to {D}?", "\"Yes. I called and said the bags were light. They said they would look into it.\""), .cross("Can freezing take eight pounds out of a twenty-pound bag?", "\"No. Freezing might take a pound or so. Eight is far more than I have ever seen.\""), .cross("Did you complain to {D} about the weight?", "\"Once. I called about my own bags, and I was told it was the freezing.\""), .cross("Do you think {D} short-filled the bags on purpose?", "\"I do not know. I only know my bags were light.\""), .cross("Do you think {D} short-filled them?", "\"I do not know. I only know what I saw.\""), .cross("Has the company had a problem like this before?", "\"Not with me. This was the first time in more than a year.\"")],
        theory: ("{D} shorted ice bags and billed for full weight.", "The bags lost weight from freezing."),
        allocution: "\"I should have told the truth the first time.\"",
        truths: ("{DL} filled the bags short on purpose to stretch the load.", "The ice bags did freeze and lose some weight."),
        defendant: [.direct("Did you short the ice bags on purpose?", "\"No. I did not fill them short on purpose. The bags froze and lost weight between the plant and the restaurants.\""), .direct("How did the bags lose weight?", "\"Stacked ice presses out water as it sits. I believe that is what happened, and I did not weigh each bag.\""), .direct("Do you weigh your bags before delivery?", "\"Not every one. I weigh a sample at the plant, and I believed they were fine.\""), .direct("How does your ice business work?", "\"We fill bags at the plant, load them on a truck, and deliver them to restaurants and stores overnight. I handle the route and billing.\""), .direct("How do you check bag weights?", "\"I weigh a sample at the plant once a day. I did not weigh that morning's batch.\""), .direct("What do you think happened?", "\"The bags sat stacked in the truck overnight. Water drains out of the ice, and the bags lose weight. I did not know it could be that much.\""), .cross("Twelve pounds against twenty is a big gap, isn't it?", "\"It is. I do not know how it got that large. I did not see it at the plant.\""), .cross("Three other restaurants had the same shortage, didn't they?", "\"So I hear. I do not know why. Something went wrong with that load.\""), .cross("You billed every bag at full weight, didn't you?", "\"Yes. I billed what I believed was delivered. I will refund the difference.\""), .cross("Four restaurants had the same shortage. Isn't that a plant problem?", "\"It could be. I do not know why every batch came up short.\""), .cross("You billed full price. Wouldn't an honest seller weigh the bags first?", "\"I should have weighed more bags. I trusted the fill machine.\"")],
        openings: ("{D} delivered forty bags of ice marked as twenty pounds to {V}'s restaurant and billed for full weight. The next morning the manager weighed a sample and found the bags averaged twelve pounds, and three other restaurants reported the same shortage.", "The defense case is that ice bags lose weight when they freeze and stack, and that {D} billed what {D} believed was delivered."),
        closings: ("Forty bags billed at twenty pounds, six sample bags weighed at twelve on a calibrated scale, and three other restaurants hit the same way. That is not freezing, it is short-filling.", "Ice that freezes and loses water weight, and a supplier who billed in good faith. The State must prove {D} shorted the bags on purpose."),
        timeline: [(0, "{D} delivers the ice."), (1, "The manager weighs the bags."), (3, "Other restaurants report shortages."), (5, "{V} reports the shortage to the Sheriff's Office.")],
        identified: "The delivery ticket names {D}.",
        notDone: ["The ice plant's bag weights were never audited.", "The supplier's spec sheet was never compared with the tickets."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let libraryKeyboardV1 = SmallCases.make(
        key: "story.libraryKeyboard",
        category: .property,
        headlines: ["Patron Kicks Book Return Kiosk and Cracks Screen After It Rejects Card", "Library Camera Shows Kick That Broke Self-Service Kiosk"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a public library, causing damage of $690, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 11:10 a.m. on {DATE}, a self-service kiosk at a public library rejected {D}'s card three times. {D} kicked the kiosk base, cracked the touch screen and bent the card reader. A librarian called security at 11:12 a.m. The kiosk cost $690 to repair. {D} says the kiosk was already damaged.",
        state: [E(.video, 3, "Library Camera", "{D} kicks the base of the kiosk at 11:11 a.m. and the screen cracks."), E(.document, 2, "Kiosk Log", "Three card rejections at 11:08, 11:09 and 11:10 a.m."), E(.document, 2, "Repair Invoice", "$690 for a touch screen and card reader."), E(.statement, 2, "Librarian", "Heard the kick and found the screen cracked.")],
        defense: [E(.statement, 1, "Already Damaged", "{DL} says the kiosk was already cracked and wobbly."), E(.document, 1, "Service Log", "A work order for a loose card reader two weeks earlier.")],
        role: "Librarian",
        exam: [.direct("What happened at the library kiosk at 11:10 a.m.?", "\"The self-service kiosk rejected {D}'s card three times at 11:08, 11:09, and 11:10. Then I heard a kick and found the screen cracked.\""), .direct("What does the library camera show?", "\"{D} kicking the base of the kiosk at 11:11, and the touch screen cracks. The card reader was also bent.\""), .direct("What did the repair cost?", "\"$690 for a touch screen and a card reader. The invoice is in our file, and I called security at 11:12.\""), .direct("Where were you when it happened?", "\"At the circulation desk about twenty feet from the kiosk. I heard three error beeps and then a loud thud and looked over.\""), .direct("What did you see?", "\"{D} kicking the base of the kiosk. The screen cracked across the middle, and the card reader hung crooked afterward.\""), .direct("What did you do next?", "\"I called security at 11:12 and asked {D} to step away. {D} was breathing hard and said the machine had eaten the card.\""), .cross("{D} says the kiosk was already damaged, doesn't {D.he}?", "\"Yes. There was a hairline crack in a corner of the screen before. I cannot argue.\""), .cross("Had the kiosk misread cards before?", "\"Often. The card reader was loose, and patrons complained about it.\""), .cross("Was the reader ever repaired?", "\"Not yet. It was on the list, but it had not been fixed before that day.\""), .cross("Did you see a crack before the kick?", "\"There was a hairline in one corner that patrons had mentioned. It was small and did not affect the touch function.\""), .cross("Did the kiosk reject other patrons that morning?", "\"A couple of people complained about the reader. It was on the repair list.\"")],
        defenseRole: "Library aide",
        defenseExam: [.direct("Had the kiosk misread cards before that day?", "\"Often. The reader was loose, and cards failed to read about every third try, according to patrons.\""), .direct("Was the screen cracked before that day?", "\"A hairline in the corner. It was small, and it did not affect use, but it was there.\""), .direct("Did you see the kick?", "\"Yes, I did. {D} kicked the base after the rejection, and the screen cracked after the second kick.\""), .direct("What is your job at the library?", "\"I am an aide. I shelve, help patrons with the kiosk, and report equipment problems.\""), .direct("What problem did the card reader have?", "\"It was loose in its bracket and misread about one in five cards. I put it on the work order list two weeks before.\""), .direct("What did you see of {D}?", "\"{D} swiped repeatedly and got more upset each time. Then {D} kicked the base.\""), .cross("Did {D} kick the kiosk more than once?", "\"Twice. The second kick is the one after the screen cracked.\""), .cross("Was the reader repaired before that day?", "\"Not yet. We had put in a work order, but it had not been done.\""), .cross("Did {D} say anything while kicking?", "\"{D} was upset and said the machine had stolen {D.his} time. I did not hear the exact words.\""), .cross("Did {D} damage the screen with the first kick?", "\"I think so. The crack appeared after the first one.\""), .cross("Did you tell {D} the reader had been acting up?", "\"No. I was across the room. I only came over after the noise.\"")],
        theory: ("{D} kicked the kiosk and broke it.", "The kiosk was already damaged."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} kicked it twice after the screen cracked.", "The card reader was loose and misread cards."),
        defendant: [.direct("Did you kick the kiosk?", "\"Yes, I did. It rejected my card three times, and I lost my temper and kicked the base.\""), .direct("Was the kiosk damaged before you kicked it?", "\"Yes. The screen had a crack in the corner already, and the reader was loose and kept misreading cards.\""), .direct("Why were you so frustrated?", "\"I was in a hurry. I needed the card to work, and the kiosk had failed me three times in a row.\""), .direct("What were you trying to do at the kiosk?", "\"Check out two books before a meeting at noon. I had swiped my card three times and each time it said invalid.\""), .direct("What did you feel at that moment?", "\"Frustrated and late. I kicked the base without thinking, and the screen cracked right away.\""), .direct("What did you do after it cracked?", "\"I may have kicked again, then stopped and stepped back. I told the librarian I would pay for it.\""), .cross("You kicked the kiosk twice after the screen cracked, didn't you?", "\"I may have. I was angry. I did not count how many times.\""), .cross("$690 in damage to a public library. Do you accept responsibility?", "\"I do. I am deeply sorry. I should have asked a librarian for help.\""), .cross("The reader was bent after your kick, wasn't it?", "\"Yes. It was already loose, and my kick bent it more.\""), .cross("Kicking a public machine because it rejects a card. Do you see how that looks?", "\"It looks childish, and it was. I should have walked to the desk.\""), .cross("You say the reader was already loose. Did you check that before kicking?", "\"No. I only knew it was not working. The looseness came up later.\"")],
        openings: ("At 11:10 a.m., a library kiosk rejected {D}'s card three times. {D} kicked the base, cracking the touch screen and bending the card reader, and the repair cost $690.", "Weigh the defense proof, which will show that the kiosk reader was loose and misread cards often, that the screen already had a crack, and that {D} lost a temper once."),
        closings: ("Three rejections, a kick on camera, a cracked screen, and a bent card reader costing $690. Frustration with a machine does not give anyone the right to break it.", "A loose reader that failed cards, a screen already cracked, and one moment of anger. {D} accepts responsibility, and the State asks for too much."),
        timeline: [(0, "11:08 a.m.: the kiosk rejects {D}'s card."), (0, "11:11 a.m.: {D} kicks the kiosk."), (0, "11:12 a.m.: the librarian calls security."), (1, "The library sends its camera video.")],
        identified: "The library camera identifies {D}.",
        notDone: ["The kiosk's work order history was never reviewed.", "The hairline crack was never photographed before the kick."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let mailboxFireworkV1 = SmallCases.make(
        key: "story.mailboxFirework",
        category: .property,
        headlines: ["Bottle Rockets Fired From Yard Burn Neighbor's Patio Umbrella and Grill Cover", "Neighbor's Camera Shows Rockets Landing on Deck"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a patio umbrella and grill cover, causing damage of $240, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At dusk on {DATE}, {D} fired bottle rockets from the next yard over a shared fence. Two landed on {V}'s deck. A patio umbrella and a grill cover caught fire and burned before {V} put them out with a hose. The camera recorded {D} at the fence at 8:50 p.m. The replacements cost $240. {D} says the rockets went the wrong way.",
        state: [E(.video, 3, "Deck Camera", "Two bottle rockets arc over the fence at 8:50 p.m. and land on the deck."), E(.physical, 2, "Burned Items", "A scorched umbrella and a melted grill cover with rocket sticks nearby."), E(.document, 2, "Replacement Receipt", "$240 for a new umbrella and grill cover."), E(.statement, 2, "{V}", "Put the fire out with a hose and called deputies.")],
        defense: [E(.statement, 1, "Wrong Way", "{DL} says the rockets went the wrong way in a gust of wind."), E(.document, 1, "Wind Report", "A reading of gusts to 18 miles per hour that evening.")],
        role: "Neighbor",
        exam: [.direct("What happened on your deck at dusk?", "\"Two bottle rockets arced over the fence at 8:50 p.m. and landed on my deck. A patio umbrella and a grill cover caught fire.\""), .direct("What did you do?", "\"I put the fire out with a hose and called deputies. The burned items had rocket sticks near them.\""), .direct("What does your deck camera show?", "\"The two rockets arcing over the fence from the next yard, where {D} was standing at the fence.\""), .direct("What was your evening like before 8:50?", "\"I was sitting on the deck with a drink while the grill cooled. The sun was down and it was getting breezy.\""), .direct("What did you see and hear?", "\"A whistle and a pop over the fence, then two small rockets landed on my deck. The umbrella and the grill cover started smoking right away.\""), .direct("How did you deal with the fire?", "\"I grabbed the hose and sprayed both until the flames were out. Then I called deputies and showed them the sticks.\""), .cross("{D} says the rockets went the wrong way, doesn't {D.he}?", "\"Yes. It was gusty that evening. I will agree that wind can push rockets.\""), .cross("Had you and {D} argued before?", "\"{D} had complained about the smoke from my grill the week before.\""), .cross("What did the replacements cost?", "\"$240 for a new umbrella and grill cover.\""), .cross("Were the rockets aimed at you?", "\"I cannot say. They came from {D}'s side, and the camera shows them arcing over the fence.\""), .cross("Was it windy?", "\"Yes, gusty. I felt it on the deck. A rocket could easily be pushed sideways.\"")],
        defenseRole: "Neighbor two doors down",
        defenseExam: [.direct("Was it windy that evening?", "\"Gusty, enough to move the flags on our block. I noticed it because my flag was flapping hard.\""), .direct("Where did {D} point the rockets?", "\"Toward the open lot beyond the yards. That is what it looked like to me from my porch.\""), .direct("Did two rockets land on the deck?", "\"Two did. I saw them drift off course and come down on the deck next door.\""), .direct("How close do you live to the yards?", "\"Two doors down. I can see both decks from my front steps.\""), .direct("What was the wind that evening?", "\"Gusty. Our flags snapped back and forth most of the evening.\""), .direct("What did you see {D} do?", "\"Set up some rockets on a stand and light them toward the open lot. Two curved off with a gust.\""), .cross("Did {D} check for neighbors before firing?", "\"I do not know. I did not see {D} look around, but I was not watching closely.\""), .cross("Were the rockets a danger to nearby decks?", "\"They could have been. Wind pushes them. It is not a good idea to fire them near houses.\""), .cross("Did you hear about the grill smoke complaint?", "\"Yes. {D} complained about it. I did not take sides.\""), .cross("Did you see where {D} aimed each one?", "\"Mostly toward the lot. I did not follow each rocket.\""), .cross("Did {D} warn anyone before firing?", "\"I did not see that. The neighbors may not have known.\"")],
        theory: ("{D} fired rockets toward a neighbor's deck.", "{D} fired rockets and the wind pushed them."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had complained about the grill smoke the week before.", "{DL} fired the rockets into the open lot and a gust pushed them."),
        defendant: [.direct("Did you fire the rockets at {V}'s deck?", "\"No. I fired them toward the open lot. A gust pushed two of them over the fence.\""), .direct("What about the grill smoke complaint?", "\"I complained about it a week earlier. It was not a feud. I did not aim anything at {V.him}.\""), .direct("Why were you firing bottle rockets?", "\"It was a holiday weekend and a cheap tradition. I set up a few on a stand and pointed them toward the vacant lot.\""), .direct("What happened when you lit them?", "\"Most went out toward the lot. Two caught a gust and curved back over the fence. I yelled and ran to see where they landed.\""), .direct("What did you do afterward?", "\"I went to {V}'s door and apologized. I offered to pay for the damage.\""), .direct("What did you do when you saw smoke coming from {V}'s deck?", "\"I ran to the fence and yelled that I was sorry and asked if I could help. {V} had a hose out, and I did not want to make it worse.\""), .cross("The camera shows the rockets arcing over the fence, doesn't it?", "\"Yes. The wind pushed them. I did not plan for them to land on the deck.\""), .cross("You complained about {V}'s grill smoke. Isn't that a motive?", "\"It was a small complaint. I would never set fire to a neighbor's things.\""), .cross("Did you check the wind before firing?", "\"I did not. In hindsight, yes. I apologize.\""), .cross("You fired next to a shared fence in a breeze. Isn't that careless?", "\"Yes. I should have checked the wind and used the other end of the yard.\""), .cross("You complained about {V}'s grill smoke the week before. Isn't this payback?", "\"No. I mentioned the smoke once and let it go. I did not aim at the deck.\"")],
        openings: ("At dusk, {D} fired bottle rockets from the next yard over a shared fence. Two landed on {V}'s deck, burning a patio umbrella and a grill cover, and {V} put the fire out with a hose.", "Jurors will hear that it was gusty, that {D} aimed toward an open lot, and that the wind pushed two rockets onto the deck."),
        closings: ("Two bottle rockets over a fence, a burned umbrella and grill cover, and a neighbor who had complained about the grill smoke. {D} fired near homes.", "A gusty evening, rockets aimed at an open lot, and two that drifted. The State must prove {D} fired at the deck on purpose, and wind raises real doubt."),
        timeline: [(0, "8:50 p.m.: the rockets go over the fence."), (0, "8:52 p.m.: the umbrella and cover catch fire."), (0, "9 p.m.: {V} puts the fire out."), (1, "{V} sends the camera video.")],
        identified: "The deck camera identifies {D}.",
