    static let dumpsterDiggerV1 = SmallCases.make(
        key: "story.dumpsterDigger",
        category: .publicOrder,
        headlines: ["Bakery Rear Lot Entered at 4 a.m. After Written Notice", "Delivery Driver Finds Banned Man Taking Trays From Bakery Door"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a bakery, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} was given a written trespass notice by a bakery manager three weeks before {DATE} after being caught taking trays from the back door. At 4 a.m. on {DATE}, a delivery driver found {D} in the fenced rear lot loading stale rolls into a bag. The manager arrived at 4:15 a.m. and called deputies. {D} says the gate was open and the rolls were thrown out.",
        state: [E(.document, 3, "Trespass Notice", "A signed notice from the manager three weeks before."), E(.video, 2, "Rear Lot Camera", "{D} enters the lot at 3:55 a.m. and loads a bag."), E(.statement, 2, "Delivery Driver", "Found {D} in the lot and called the manager."), E(.statement, 2, "Bakery Manager", "Recognized {D} and called deputies.")],
        defense: [E(.statement, 1, "Open Gate", "{DL} says the gate was open and the rolls were thrown out."), E(.document, 1, "Delivery Note", "The trash pickup list says day-old rolls are discarded at 5 a.m.")],
        role: "Bakery manager",
        exam: [.direct("What was the history with {DL}?", "\"Three weeks before {DATE}, I gave {D} a written trespass notice after catching {D} taking trays from the back door.\""), .direct("What happened at 4 a.m. on {DATE}?", "\"A delivery driver found {D} in our fenced rear lot loading stale rolls into a bag. I arrived at 4:15 and called deputies.\""), .direct("What does the lot camera show?", "\"{D} entering the lot at 3:55 a.m. and loading a bag.\""), .direct("How did you deal with {D} the first time?", "\"I caught {D} carrying trays out the back door and gave a written trespass notice that {D} signed. I told {D} to stay off the property.\""), .direct("What did the delivery driver report?", "\"At about 4 a.m. the driver saw {D} loading rolls into a bag in the fenced lot. The driver called me, and I arrived at 4:15.\""), .direct("What do you do with day-old rolls?", "\"We bag them for the trash pickup that comes around 5 a.m. Nothing is given out at night.\""), .cross("{DL} says the gate was open and the rolls were thrown out, doesn't {D.he}?", "\"We do throw out day-old rolls, but not until a 5 a.m. pickup.\""), .cross("Was the gate open?", "\"It may have been, because of a delivery. I can't say it was locked at 3:55.\""), .cross("Did {DL} take anything valuable?", "\"Stale rolls. Day-old. They were headed for the trash.\""), .cross("Were the rolls fresh or stale?", "\"Stale, a day old. They were worth little and headed for the dumpster.\""), .cross("The rolls {DL} took were headed for the dumpster anyway, weren't they?", "\"Some were, yes. But the notice was clear, and the rolls were sitting in the trays on the rack, not in the trash bin.\"")],
        defenseRole: "Delivery driver",
        defenseExam: [.direct("Do you deliver to the bakery?", "\"Yes. I'm a delivery driver. I come early in the morning.\""), .direct("Was the gate open?", "\"It was open when I got there. Deliveries often prop it.\""), .direct("What did you see {DL} doing?", "\"Loading rolls into a bag. They looked stale. I figured it was discards.\""), .direct("How long have you delivered to the bakery?", "\"Five years. I make the early run with bread flour and dairy at about four every morning.\""), .direct("What did you notice about the gate that morning?", "\"It was wide open because the earlier truck had left it that way. We often prop it during deliveries.\""), .direct("What did you see {D} do in the lot?", "\"Standing by the bins and putting rolls into a plastic bag. {D} did not try to hide.\""), .cross("Did you call the manager?", "\"Yes. I knew there was a ban on that person. I thought I should.\""), .cross("Did the delivery note say when rolls are discarded?", "\"Yes. Day-old rolls go out at 5 a.m.\""), .cross("Was {DL} hiding?", "\"Not really. {D} was in plain view. But it was before dawn.\""), .cross("Why did you call the manager?", "\"I knew from the staff that there was a ban on {D}. I wanted to follow the rule.\""), .cross("Did {D} look threatening?", "\"No. {D} looked tired and hungry and kept to the bins.\"")],
        theory: ("{D} returned to the lot after a written ban.", "{D} took discarded rolls from an open gate."),
        allocution: "\"I was angry and I made it everyone else's problem.\"",
        truths: ("{DL} knew the notice was still in effect.", "The gate had been propped open by a delivery."),
        defendant: [.direct("Why were you in the bakery's lot at 4 a.m.?", "\"I was getting food that was being thrown out. The gate was open and the rolls were in the discard area.\""), .direct("Did you know about the trespass notice?", "\"I knew I'd signed one. But I thought it was about the back door, not food in the trash.\""), .direct("What did you take?", "\"A bag of stale rolls. Nothing else. I wasn't trying to steal anything valuable.\""), .direct("What led you to the bakery lot?", "\"I had little money and knew the bakery threw out rolls early each morning. I went at four so I would not bother anyone.\""), .direct("What did you see at the gate?", "\"It stood open and the lot was empty. I walked in and filled a bag with rolls from a bin.\""), .direct("What did the driver do?", "\"The driver saw me, called out, and made a call. I did not run. I stayed until the manager came.\""), .cross("You were told in writing not to be on the property, weren't you?", "\"Yes. Three weeks earlier. I should have stayed away.\""), .cross("It was 4 a.m., wasn't it?", "\"Yes. I went early so no one would see me. I realize how that looks.\""), .cross("The lot is fenced, isn't it?", "\"Yes. But the gate was open. I walked in.\""), .cross("You signed a notice three weeks earlier. Why return?", "\"I thought it was about taking trays, and I was only taking trash. That was a poor reading of it.\""), .cross("If it was only trash, why go in the dark?", "\"So no one would see me and be embarrassed. I realize how it sounds.\"")],
        openings: ("Three weeks after a bakery manager gave {D} a written trespass notice, a delivery driver found {D} in the fenced rear lot at 4 a.m. loading stale rolls into a bag. The manager called deputies. The State will show the notice and the lot camera.", "Jurors will also see an open gate, day-old rolls headed for the trash, and a person who took nothing of value and hid nothing. Listen closely to the witnesses."),
        closings: ("A signed trespass notice, a fenced lot at 4 a.m., and {D} loading a bag. {D} was told to stay away and came anyway.", "An open gate and a bag of stale rolls bound for the trash. The State has not proved {D} meant to trespass rather than take discards."),
        timeline: [(-21, "The manager gives {D} the written notice."), (0, "3:55 a.m.: {D} enters the lot."), (0, "4:15 a.m.: the manager arrives."), (0, "4:30 a.m.: deputies arrive.")],
        identified: "The signed notice and the manager identify {D}.",
        notDone: ["The bakery's discard schedule was never entered into evidence.", "The delivery truck's own camera was never checked for the gate."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let shelterGlassV1 = SmallCases.make(
        key: "story.shelterGlass",
        category: .property,
        headlines: ["Trash Can Hurled Through Bus Shelter Panel at 11 p.m.", "Transit Camera Shows Drunk Passenger Throw Can"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a transit authority, causing damage of $1,150, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 11:05 p.m. on {DATE}, {D} lifted a metal trash can from a bus shelter and hurled it through a glass panel. The transit camera shows {D} arguing with a bus driver who had closed the doors. A shelter panel and a sign frame were broken. The repairs cost $1,150. {D} says the can tipped when {D.he} stumbled.",
        state: [E(.video, 3, "Transit Camera", "{D} lifts the can and throws it through the panel at 11:05 p.m."), E(.physical, 2, "Broken Panel", "Shards of tempered glass and a dent from the can."), E(.document, 2, "Repair Invoice", "$1,150 for a panel and a sign frame."), E(.statement, 2, "Bus Driver", "{D} shouted after the doors closed and then threw the can.")],
        defense: [E(.statement, 1, "Stumbled", "{DL} says {D.he} stumbled and the can tipped into the panel."), E(.document, 1, "Bar Tab", "A tab from a bar two blocks away closed at 10:40 p.m.")],
        role: "Transit supervisor",
        exam: [.direct("What happened at the bus shelter at 11:05 p.m.?", "\"{D} lifted a metal trash can and hurled it through a glass panel. A shelter panel and a sign frame were broken.\""), .direct("What does the transit camera show?", "\"{D} arguing with a bus driver who had closed the doors, then lifting the can and throwing it.\""), .direct("What did the repairs cost?", "\"$1,150 for a panel and a sign frame. The invoice is in our file.\""), .direct("How did the incident come to your attention?", "\"The bus driver radioed at about 11:07 about a shelter panel smashed at a stop. We pulled the camera and saw a person throw a can through it.\""), .direct("What exactly does the video show?", "\"{D} arguing with the driver as the doors closed, then lifting a metal can and heaving it through the glass. The can bounced off once before the panel gave way.\""), .direct("What damage was done?", "\"A tempered glass panel shattered and a sign frame bent. The shelter was closed until the next day.\""), .cross("{D} says the can tipped when {D.he} stumbled, doesn't {D.he}?", "\"Yes. {D} had been drinking and was unsteady. That is possible for a first toss.\""), .cross("How many times was the can thrown?", "\"Twice before the panel broke, I believe. The camera shows more than one throw.\""), .cross("Was anyone hurt?", "\"No. No one was near the shelter at that moment. The driver was in the bus.\""), .cross("Was anyone in the shelter?", "\"No. The shelter was empty. Nobody was hurt.\""), .cross("Did {D} flee?", "\"No. {D} stood by the shelter and waited for deputies.\"")],
        defenseRole: "Bar patron who saw it",
        defenseExam: [.direct("Had {D} been drinking that night?", "\"A few drinks. {D} was unsteady on {D.his} feet when we left the bar together.\""), .direct("Did you see the can thrown?", "\"I saw it fly. It went through the glass with a big crash, and then {D} stood still, looking shocked.\""), .direct("Was {D} next to the can when stumbling?", "\"Right beside it. {D} stumbled into it earlier, and it moved. Then {D} picked it up.\""), .direct("What were you doing near the shelter?", "\"Walking out of a bar two blocks away with some friends. We saw the bus leave and someone yelling.\""), .direct("What did you see of {D}?", "\"{D} stumbling near the can early on. Later {D} picked it up and threw it.\""), .direct("How drunk was {D}?", "\"Unsteady. {D} had a few and swayed when walking.\""), .cross("Did {D} shout at the driver first?", "\"Yes. {D} shouted when the doors closed, and the driver pulled away.\""), .cross("Did you see {D} throw the can twice?", "\"I think so. I saw one for sure. I am not certain about a second.\""), .cross("Were you also drinking?", "\"Yes. I had a couple. I was close enough to see, though.\""), .cross("How far were you when it was thrown?", "\"About forty feet. I saw the arc and heard the glass.\""), .cross("Did {D} try to run?", "\"No. {D} stood and swore, then sat on the curb.\"")],
        theory: ("{D} threw a can through a shelter after a missed bus.", "{D} stumbled into the panel."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} threw the can twice before it broke.", "{DL} had been drinking and did stumble earlier."),
        defendant: [.direct("Did you throw the trash can through the panel?", "\"I lifted it, and I threw it. I had been drinking, and I was angry that the bus left me.\""), .direct("Did the can tip when you stumbled?", "\"It moved when I stumbled into it earlier. Then I picked it up and threw it.\""), .direct("Why were you so angry?", "\"The driver closed the doors in my face. I had been waiting, and I felt ignored.\""), .direct("How did your evening go before the bus?", "\"I had a few drinks at a bar two blocks away. I left at about 10:40 to catch the last bus home.\""), .direct("What happened with the driver?", "\"I ran for the bus and it pulled out as I got to the door. I banged on it and shouted, and the driver ignored me.\""), .direct("What did you do with the can?", "\"I picked it up and threw it. It hit the panel and bounced and then I threw it again.\""), .cross("You threw the can twice before it broke the panel, didn't you?", "\"I think so. The first one did not go through. I was not thinking.\""), .cross("You had been drinking, hadn't you?", "\"Yes. I had a few. That is no excuse.\""), .cross("$1,150 in damage over a missed bus. Will you pay?", "\"I will. I am sorry. It was a stupid thing to do.\""), .cross("You tossed a can through a glass panel over a missed bus. How is that a stumble?", "\"It was not a stumble. I stumbled into the can earlier, then I made a choice.\""), .cross("You were drinking. Do you blame that?", "\"I blame myself. The drinks made me careless, but I threw it.\"")],
        openings: ("At 11:05 p.m., {D} argued with a bus driver who closed the doors, then lifted a metal trash can and hurled it through a glass shelter panel. The transit camera recorded it, and the repairs cost $1,150.", "By the end of this trial, the proof will show that {D} had been drinking, stumbled into the can earlier, and acted in a moment of anger with no plan to destroy anything."),
        closings: ("A closed door, a trash can lifted and thrown through glass, and $1,150 in damage. The camera shows {D} throwing it, more than once.", "A drunken stumble, a moment of anger, and a person who will pay for the damage. The State asks for more than this foolish night deserves."),
        timeline: [(0, "10:40 p.m.: {D} leaves the bar."), (0, "11 p.m.: the bus doors close."), (0, "11:05 p.m.: the panel breaks."), (1, "The transit authority prices the repair.")],
        identified: "The transit camera identifies {D}.",
        notDone: ["The can's weight was never measured against the throw.", "The bus driver's door-closing time was never matched to the camera."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let sealcoatScamV1 = SmallCases.make(
        key: "story.sealcoatScam",
        category: .whiteCollar,
        headlines: ["Roof Coating Crew Takes $1,200 Deposit and Rolls on Thinned Sealer", "Lab Test Shows Roof Coating Was Mostly Water"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $1,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}'s crew told {V} on {DATE} that a premium roof coating would last ten years and took $1,200 in advance. The crew rolled a thin gray coat on the roof in two hours, and by the first rain the coating was peeling in sheets. A lab test of a sample found the product was about 80 percent water. {D} says the supplier sold the crew a bad batch.",
        state: [E(.physical, 3, "Peeled Coating", "Sheets of gray coating lifted from the roof with a thumbnail."), E(.document, 3, "Lab Report", "The sample is about 80 percent water with minimal solids."), E(.document, 2, "Invoice", "$1,200 for a ten-year premium coating, paid in advance."), E(.statement, 2, "{V}", "The crew left in two hours and did not clean up.")],
        defense: [E(.statement, 1, "Bad Batch", "{DL} says the supplier sold the crew a bad batch."), E(.document, 1, "Supplier Invoice", "An invoice for twenty gallons of coating the week before.")],
        role: "Homeowner",
        exam: [.direct("What did {D}'s crew tell you about the roof coating?", "\"That a premium coating would last ten years. They took $1,200 in advance.\""), .direct("What did the crew do?", "\"They rolled a thin gray coat in two hours and left without cleaning up. By the first rain, it was peeling in sheets.\""), .direct("What did the lab test show?", "\"The sample was about 80 percent water with minimal solids. It was not a premium coating.\""), .direct("How did the crew approach you?", "\"They knocked and said my roof was at risk and that a premium coating would protect it for ten years. I signed and paid $1,200 in advance.\""), .direct("What happened when they worked?", "\"Two people rolled a thin gray coat across the roof in about two hours and left. They did not sweep or pick up their drop cloths.\""), .direct("When did you see the problem?", "\"After the first rain. The coating lifted in sheets, and I could peel it with my thumbnail.\""), .cross("{D} says the supplier sold a bad batch, doesn't {D.he}?", "\"Yes. A clerk says the batch may have been off. That is accurate.\""), .cross("Did {D} offer to redo the work?", "\"Not at first. I had to call several times.\""), .cross("Was the roof damaged before the coating?", "\"No. It was in fair condition. I wanted it protected.\""), .cross("Did you have the roof checked before the work?", "\"No. I trusted the crew. I only saw the roof after the first leak.\""), .cross("How did {D} respond when you called?", "\"At first, {D} said it was weather. After I sent photos, {D} blamed the supplier.\"")],
        defenseRole: "Supplier's counter clerk",
        defenseExam: [.direct("Did {D} buy coating from you?", "\"Twenty gallons that week. {D} bought it at the counter and paid in full.\""), .direct("Did you test the batch before selling it?", "\"No. We do not test every batch. We rely on the manufacturer.\""), .direct("Has a batch been off before?", "\"Once last year. It was a small issue, and we fixed it quickly.\""), .direct("What do you do at the supply counter?", "\"I sell coatings, sealants, and tools to contractors. I check inventory and write invoices.\""), .direct("What did {D} order that week?", "\"Twenty gallons of a premium roof coating. {D} paid at the counter and loaded it into a truck.\""), .direct("How do you know if a batch is off?", "\"We rely on the manufacturer. If a batch is suspect, we get a notice and pull it.\""), .cross("Did other crews complain about this batch?", "\"Not yet. No other complaints have come in.\""), .cross("Would a bad batch be 80 percent water?", "\"That would be a very bad batch. It is possible, but it would be unusual.\""), .cross("Could a crew add water to buckets?", "\"Yes. That is possible. A contractor could thin the product.\""), .cross("Did you test the batch?", "\"No. We do not test each batch. We trust the labeling.\""), .cross("Have other crews complained about this batch?", "\"Not yet. {D} is the first one to call.\"")],
        theory: ("{D} sold premium coating and applied thinned sealer.", "A supplier sold the crew a bad batch."),
        allocution: "\"I should have told the truth the first time.\"",
        truths: ("{DL} had thinned the buckets with water to cover more roofs.", "The supplier's batch was off and {DL} did not test it."),
        defendant: [.direct("Did you thin the coating with water?", "\"No. I did not add water. The supplier sold the crew a bad batch, and I did not test it.\""), .direct("Why was the coat so thin?", "\"The product looked normal in the bucket. I do not know why it was so watery.\""), .direct("Did you promise a ten-year coating?", "\"I told {V.him} it was a premium product with a long life. I believed that.\""), .direct("How long have you coated roofs?", "\"Eight years. I run a small crew that does roof sealing and patching for homeowners.\""), .direct("What did you buy for the job?", "\"Twenty gallons of premium coating from the supply store the week before. I split it across several roofs.\""), .direct("What did you do when the homeowner complained?", "\"I looked at photos and tried to schedule a fix. I thought the batch was bad and told the supplier.\""), .cross("The lab says the sample is 80 percent water, doesn't it?", "\"It does. I do not know how. I did not add water.\""), .cross("You covered the roof in two hours. Isn't that fast?", "\"My crew is fast. We rolled it thin, as the product allowed.\""), .cross("You took $1,200 in advance for work that peeled in one rain. Will you redo it?", "\"Yes. I will redo it. I did not mean to cheat anyone.\""), .cross("Your crew finished in two hours. Does a ten-year job take two hours?", "\"We work fast and the roof was small. I told the crew to roll it thin to cover more.\""), .cross("Did you add water to the buckets?", "\"No. I would not do that. The product was as it came from the supplier.\"")],
        openings: ("{D}'s crew told {V} a premium roof coating would last ten years and took $1,200 in advance. They rolled a thin gray coat in two hours, and by the first rain it was peeling, with a lab finding it about 80 percent water.", "The defense will present evidence that the supplier sold the crew a bad batch and that {D} never thinned the product or meant to cheat."),
        closings: ("A promise of ten years, $1,200 up front, and a coating that was 80 percent water and peeled in the first rain. The buckets were thinned, and {V} paid for it.", "A supplier's bad batch, a crew that rolled what it was given, and a contractor who will redo the job. The State must prove {D} thinned the coating on purpose."),
        timeline: [(0, "{V} pays $1,200."), (0, "The crew rolls the coating in two hours."), (7, "The first rain peels the coating."), (20, "The lab reports 80 percent water.")],
        identified: "The invoice names {D}.",
        notDone: ["The supplier's batch number was never traced to other customers.", "The buckets were never opened to see how much water they held."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let boosterRaffleV1 = SmallCases.make(
        key: "story.boosterRaffle",
        category: .whiteCollar,
        headlines: ["Football Concession Cash Never Reaches Booster Club Bank", "Treasurer Keeps $780 After Home Game"],
        law: "embezzlement",
        spec: "Embezzled $780 belonging to {V}, a booster club, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, the booster club treasurer, collected $780 in concession stand cash at a home football game on {DATE} and agreed to deposit it Monday morning. No deposit was made that week. When the club president asked for the bank slip, {D} said the cash had been stolen from a car. No police report was filed until nine days later.",
        state: [E(.document, 3, "Concession Tally", "$780 counted by two volunteers at the end of the game and signed by {D}."), E(.document, 3, "Bank Statement", "No deposit from the game; the last deposit was two weeks earlier."), E(.document, 2, "Police Report", "A theft report filed by {D} nine days after the game."), E(.statement, 2, "Volunteers", "Watched {D} put the cash in a gray zip bag.")],
        defense: [E(.statement, 1, "Stolen From Car", "{DL} says the zip bag was stolen from {D.his} car overnight."), E(.document, 1, "Car Insurance Note", "No claim for the break-in was ever filed.")],
        role: "Booster club president",
        exam: [.direct("What did the concession stand collect on {DATE}?", "\"$780 in cash. Two volunteers counted it at the end of the game, and {D} signed the tally as treasurer.\""), .direct("What was supposed to happen next?", "\"{D} agreed to deposit it Monday morning. The bank statement shows no deposit that week; the last was two weeks earlier.\""), .direct("What did {DL} say?", "\"That the cash had been stolen from a car. A police report was filed nine days after the game, and volunteers saw {D} put the cash in a gray zip bag.\""), .direct("How did the concession stand go that night?", "\"It was a big home game and sales were strong. Two volunteers counted $780 after the game and {D} signed the tally.\""), .direct("What did you watch {D} do with the money?", "\"Put it in a gray zip bag and carry it to the parking lot. {D} said the deposit would go in Monday.\""), .direct("When did you ask for the bank slip?", "\"Midweek, when no deposit showed. {D} said the bag had been stolen from the car overnight.\""), .cross("{DL} says the zip bag was stolen overnight, doesn't {D.he}?", "\"I can't say it didn't happen. I only know there was no report for nine days.\""), .cross("Was an insurance claim filed?", "\"I'm told no. I don't have details about {D}'s car insurance.\""), .cross("Did you ask {DL} for the bank slip right away?", "\"Not right away. I waited a few days. I should have asked on Monday.\""), .cross("Did you see {D} take the money for personal use?", "\"No. I only know it was not deposited and that {D} had the bag.\""), .cross("Was the club's account audited?", "\"Yes. The statement shows no deposit from that game. The last deposit was two weeks earlier.\"")],
        defenseRole: "Neighbor on {DL}'s street",
        defenseExam: [.direct("Do you live on {DL}'s street?", "\"Yes. A few houses down. I know {D}'s car.\""), .direct("Was your street quiet that night?", "\"Mostly. There are break-ins sometimes. I've heard about cars being hit.\""), .direct("Did you see anything that night?", "\"No. I was inside. I can't say I saw anything.\""), .direct("How well do you know {D}'s street?", "\"I have lived there eleven years. I know {D}'s car, driveway, and routine.\""), .direct("What are break-ins like in your area?", "\"Now and then cars get broken into on weekend nights. Neighbors talk about it in the group chat.\""), .direct("What did you hear that weekend?", "\"That a couple of cars on the block were hit. I did not hear about the booster bag.\""), .cross("Did you hear about a break-in that night?", "\"I heard about one later. I'm not sure it was that night.\""), .cross("Did you see {DL}'s car broken into?", "\"No. I never saw that. I only know the street.\""), .cross("Was a police report made that night?", "\"Not that I know of. I never heard of one.\""), .cross("Did you see {D}'s car that night?", "\"No. I was inside the whole evening and went to bed fairly early that night.\""), .cross("Did {D} tell you about the money?", "\"Not until several days later, when {D} mentioned in passing that the bag was gone.\"")],
        theory: ("{D} kept the club's money.", "The bag was stolen from {D}'s car."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} paid a past-due car note that week.", "There was a break-in on {DL}'s street that night."),
        defendant: [.direct("What happened to the cash?", "\"I put it in a gray zip bag and left it in my car overnight. When I went out, the bag was gone.\""), .direct("Why didn't you report it right away?", "\"I was in shock and embarrassed. I thought I'd find it. I waited too long, and I regret that.\""), .direct("Did you take the money?", "\"No. I would never take the booster club's money. It was stolen from my car.\""), .direct("How long have you been treasurer?", "\"Three years. I count cash after games, make deposits, and keep the books. I never had a loss before.\""), .direct("What did you do with the money after the game?", "\"I put it in a zip bag and took it to my car. I meant to take it to the bank first thing Monday.\""), .direct("What happened overnight?", "\"In the morning the bag was gone from the car. There were broken-in cars on my street that night.\""), .cross("You signed the tally for $780, didn't you?", "\"Yes. I did. I was responsible for it.\""), .cross("You didn't deposit it Monday, did you?", "\"No. I didn't have it. I should have said so that morning.\""), .cross("The police report came nine days later, didn't it?", "\"Yes. I know it looks bad. I waited and hoped.\""), .cross("You waited nine days to file a police report. Why?", "\"I was ashamed and hoped it would turn up. I know that delay made things worse.\""), .cross("No insurance claim was filed. Isn't that odd?", "\"I did not think about it. The deductible was higher than the loss I thought I could cover.\"")],
        openings: ("A booster club treasurer, {D}, signed for $780 in concession cash after a game and agreed to deposit it Monday. No deposit was made, and {D} said the cash was stolen from a car, reporting it nine days later. The State will show the tally, the statement, and the report.", "The defense will present a theft from a car on a street where break-ins occur, a treasurer who waited too long to speak up, and no proof {D} kept a dollar."),
        closings: ("$780 signed for, no deposit, a story about a theft, and a report nine days late. The club's money never reached the bank.", "A late report and a stolen bag are not proof of embezzlement. The State has not proved {D} took the club's money."),
        timeline: [(0, "9:30 p.m.: the volunteers count $780."), (2, "Monday: the deposit is not made."), (9, "{D} reports the bag stolen."), (10, "The club president asks the Sheriff's Office to investigate.")],
