    static let closedHotTubV1 = SmallCases.make(
        key: "story.closedHotTub",
        category: .publicOrder,
        headlines: ["Apartment Pool Deck Visitor Stays After Posted Closing and Ignores Manager", "Resident's Guest Climbs Gate to Closed Pool and Refuses to Leave"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, an apartment complex, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "An apartment complex pool closed at 10 p.m. on {DATE}. At 10:50 p.m., {D}, a resident's guest, climbed the gate and swam. The night manager told {D} twice to leave and noted the complex's written notice from the previous summer barring {D} from the pool deck. {D} refused until deputies arrived at 11:30 p.m. {D} says a resident invited {D.him}.",
        state: [E(.video, 3, "Pool Camera", "{D} climbs the gate at 10:50 p.m. and swims until 11:25 p.m."), E(.document, 3, "Written Notice", "A notice signed by {D} the previous summer barring {D.him} from the property."), E(.statement, 2, "Night Manager", "Told {D} twice to leave and was refused."), E(.document, 2, "Gate Log", "No fob entry after 10 p.m. that night.")],
        defense: [E(.statement, 1, "Invited", "{DL} says a resident told {D.him} to use the pool."), E(.document, 1, "Text Message", "A text from a resident at 10:30 p.m. saying 'come on over.'")],
        role: "Night manager",
        exam: [.direct("What happened at the pool on {DATE}?", "\"The pool closed at 10 p.m. At 10:50, {D}, a resident's guest, climbed the gate and swam. The camera shows {D} in the water until 11:25.\""), .direct("What did you do?", "\"I told {D} twice to leave. {D} refused. Deputies arrived at 11:30.\""), .direct("What notice did {DL} have?", "\"A written notice signed by {D} the previous summer barring {D.him} from the property.\""), .direct("How do you control access to the pool?", "\"A gate with a key fob lock. The pool closes at 10 p.m., and the gate log records each fob swipe.\""), .direct("What did the pool camera show at 10:50?", "\"A person climbing over the fence and jumping in. {D} swam for about thirty-five minutes in the dark water.\""), .direct("What did you do?", "\"I went to the pool deck, told {D} twice to get out, and called deputies when {D} refused. They arrived at 11:30.\""), .cross("{DL} says a resident invited {D.him}, doesn't {D.he}?", "\"A resident texted at 10:30. But a resident cannot override a ban.\""), .cross("Did {DL} use a fob to enter?", "\"No. The gate log shows no fob entry after 10 p.m. The camera shows the gate being climbed.\""), .cross("Did you show {DL} the old notice that night?", "\"No. I mentioned it. I didn't have it on me.\""), .cross("Did the resident who texted {D} have authority to invite guests?", "\"Residents can bring guests during open hours, but not after closing.\""), .cross("Was {D} damaging anything?", "\"No. {D} only swam. The issue was the closing time and the ban.\"")],
        defenseRole: "Resident who texted {DL}",
        defenseExam: [.direct("Do you live in the complex?", "\"Yes. I texted {DL} that night.\""), .direct("What did you write?", "\"'Come on over.' I told {D} to use the pool.\""), .direct("Why did you invite {DL}?", "\"We're friends. I thought it would be fine. I didn't think about rules.\""), .direct("How do you know {D}?", "\"We are friends from work. {D} has visited my apartment many times.\""), .direct("Why did you text {D} at 10:30?", "\"I was on the pool deck and wanted company. I wrote 'come on over' without thinking about the closing time.\""), .direct("What did you do when {D} arrived?", "\"I was at the gate but could not let {D} in without a fob. {D} climbed it, and I laughed.\""), .cross("Do you have authority to invite guests after closing?", "\"No. The pool closes at 10. I know that. I shouldn't have.\""), .cross("Did you know about the ban?", "\"No. I didn't know {D} was barred. If I had, I wouldn't have texted.\""), .cross("Did you tell {DL} to climb the gate?", "\"No. I never said that. I assumed {D} had a fob.\""), .cross("Did you tell {D} to climb?", "\"No. I assumed {D} would use a fob or wait outside.\""), .cross("You are not the manager of the complex, are you?", "\"No. I live there, but I do not set pool hours or decide who may be invited. I should have known that before I texted.\"")],
        theory: ("{D} entered after closing and ignored a ban.", "{D} was invited by a resident."),
        allocution: "\"It was childish, and I know it.\"",
        truths: ("{DL} knew of the ban and signed the notice.", "The resident who texted {DL} had no authority to invite {D.him}."),
        defendant: [.direct("Why were you at the pool?", "\"A resident texted me at 10:30 saying 'come on over.' I thought I was invited to swim.\""), .direct("Did you know about the ban?", "\"I'd signed a notice the summer before. I forgot about it that night. I was thinking about the invitation.\""), .direct("How did you end up at the complex?", "\"A resident texted me at 10:30 saying to come on over. I was a few blocks away and walked.\""), .direct("Why did you climb the gate?", "\"I had no fob and the resident did not answer. The text said the pool was fine, so I climbed.\""), .direct("What happened when the manager spoke to you?", "\"I told the manager I was invited. I finished my swim because I thought the invitation covered it.\""), .direct("What did you say to the resident who texted you that night?", "\"I asked if the pool was open and was told to come by. I did not ask whether the resident could invite a guest after closing.\""), .cross("You climbed a locked gate after the pool closed, didn't you?", "\"Yes. I did. I know that was wrong.\""), .cross("You were told twice to leave, weren't you?", "\"Yes. And I didn't go right away. I was embarrassed and stubborn.\""), .cross("You signed a notice barring you, didn't you?", "\"Yes. I signed it. I should have remembered.\""), .cross("You signed a ban last summer. Did you forget?", "\"I signed it, and I did forget when I got the text. That is not a good excuse.\""), .cross("Why not leave the first time the manager asked?", "\"I was stubborn and in the water. I should have gotten out.\"")],
        openings: ("After the apartment pool closed at 10 p.m., {D} climbed the gate at 10:50 and swam until deputies arrived at 11:30, refusing two orders to leave and despite a written ban signed the previous summer. The State will show the camera and the notice.", "Jurors will also see a resident's text saying 'come on over,' a guest who accepted an invitation, and a ban that {D} had forgotten. Listen closely to the witnesses."),
        closings: ("A signed ban, a gate climbed after the pool closed, and two orders to leave ignored until deputies arrived. {D} knew the rules and chose to swim anyway.", "{D} was invited by a resident and had forgotten a ban signed months earlier. The State has not proved that {D} knew the invitation could not override the closing time."),
        timeline: [(-300, "{D} signs a written notice barring {D.him} from the pool."), (0, "10:50 p.m.: {D} climbs the gate."), (0, "11:00 p.m.: the manager tells {D} to leave."), (0, "11:30 p.m.: deputies arrive.")],
        identified: "The pool camera and the old written notice identify {D}.",
        notDone: ["The complex's guest policy was never read to the resident.", "The notice from last summer was never shown to {DL} that night."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let boatLakeDWIV1 = SmallCases.make(
        key: "story.boatLakeDWI",
        category: .traffic,
        headlines: ["Pontoon Boat Runs Without Lights at Night With Operator at .10", "Wildlife Officer Stops Boat Weaving Toward Cove"],
        law: "dwi",
        spec: "Operated a vessel while under the influence of an impairing substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 9:40 p.m. on {DATE}, a wildlife officer on patrol saw a pontoon boat running without navigation lights and weaving toward a crowded cove. {D} was at the helm. The officer stopped the boat, smelled alcohol and ran a breath test at 10 p.m.: .10. {D} says a passenger had been driving and {D.he} had just taken the wheel.",
        state: [E(.document, 3, "Breath Result", "A breath alcohol concentration of .10 at 10 p.m."), E(.video, 2, "Officer's Body Camera", "The officer's light finds {D} at the helm with the motor running."), E(.statement, 2, "Wildlife Officer", "The boat crossed in front of a kayak without lights."), E(.document, 2, "Boat Registration", "Registered to {D}.")],
        defense: [E(.statement, 1, "Just Took the Wheel", "{DL} says a passenger drove most of the way and {D.he} took the wheel as the officer came."), E(.document, 1, "Drink Receipt", "A receipt for six beers at the marina between 6:15 and 9 p.m.")],
        role: "Wildlife officer",
        exam: [.direct("What did you see at 9:40 p.m. on {DATE}?", "\"A pontoon boat running without navigation lights and weaving toward a crowded cove. It crossed in front of a kayak, also unlit.\""), .direct("Who was at the helm?", "\"{D}. My body camera light finds {D} at the helm with the motor running. The boat is registered to {D}.\""), .direct("What did you do?", "\"I stopped the boat, smelled alcohol, and ran a breath test at 10 p.m. The result was .10.\""), .direct("What was the first thing you noticed?", "\"A pontoon boat with no navigation lights, weaving across the lake toward a crowded cove. It crossed in front of a kayak at about 9:40.\""), .direct("How did you approach?", "\"I turned on my blue lights and spotlight and closed on the boat. {D} was at the helm with the motor running.\""), .direct("What did you notice about {D}?", "\"A strong smell of alcohol and slow speech. I asked for a breath test and read the result of .10 at 10 p.m.\""), .cross("{DL} says a passenger drove and {D.he} just took the wheel, doesn't {D.he}?", "\"I only saw the boat as it was weaving. When my light found {D}, {D} was at the helm.\""), .cross("Did you see who drove before you lit the boat?", "\"No. It was dark, and I saw a boat without lights. I can't say who was at the helm earlier.\""), .cross("How much time passed before the breath test?", "\"About twenty minutes from the stop. I can't tell you the number at 9:40.\""), .cross("Did you see anyone else touch the wheel?", "\"No. By the time my light reached the boat, {D} was at the helm.\""), .cross("Were there other passengers?", "\"Yes, two. One seemed sober and the other quiet. I did not test them.\"")],
        defenseRole: "Passenger on the boat",
        defenseExam: [.direct("Were the lights on?", "\"I don't remember them being on. I should have checked.\""), .direct("Were you on the boat?", "\"Yes, all evening. I knew everyone aboard and was part of the group that rented the pontoon.\""), .direct("Who did the driving?", "\"I drove from the marina for a while. Later {D} took the wheel when we neared the cove.\""), .direct("What did you notice about the lights?", "\"I do not remember them on. We never turned them on after sunset.\""), .direct("What did you notice about the boat's course just before the officer's light?", "\"We drifted to the right toward the cove, and the wheel felt loose in {D}'s hands. I assumed {D} was steering for the shore.\""), .direct("How much had everyone on the boat had to drink that night?", "\"Most of us had two or three drinks over a few hours. I would not say any of us was sober enough to judge the others.\""), .cross("Who drove from the marina to the cove?", "\"I did, mostly. But I can't say for every minute.\""), .cross("How much did {DL} drink?", "\"I don't know. {D} had some. I didn't count.\""), .cross("How much had you been drinking?", "\"A couple of beers over the afternoon. I felt clear enough to drive, and I ate food too.\""), .cross("How can you be sure you drove most of the way?", "\"I remember steering and talking with others. I cannot give an exact minute.\""), .cross("You cannot say who held the wheel for the full trip, can you?", "\"No. People moved around, and I was sitting in the back. I saw {D} at the wheel near the cove, but I cannot tell you about the rest.\"")],
        theory: ("{D} piloted a boat while impaired.", "A passenger drove and {D} only took the wheel."),
        allocution: "\"It was reckless and I'm sorry.\"",
        truths: ("{DL} drove the boat from the marina to the cove.", "A passenger did take a turn at the helm earlier."),
        defendant: [.direct("Who was driving the pontoon boat?", "\"A passenger drove most of the way. I took the wheel as the officer's light came on, because the passenger wanted to hand it off.\""), .direct("Had you been drinking?", "\"I'd had beers at the marina between about 6 and 9. I didn't think I was impaired.\""), .direct("Why were the lights off?", "\"I didn't realize they were off. The passenger had been driving, and I didn't check.\""), .direct("What was the day on the lake like?", "\"A long afternoon with friends. We stopped at the marina for food and a few beers before heading toward the cove.\""), .direct("Who drove?", "\"A friend drove for a stretch in the middle. I took the wheel when I saw the blue lights, to move the boat clear.\""), .direct("How many drinks did you have?", "\"Several beers between six and nine. I did not count. I thought I was fine.\""), .cross("You were at the helm when the officer found you, weren't you?", "\"Yes. I took the wheel just before. I know that's the problem.\""), .cross("Six beers were bought at the marina, weren't they?", "\"I had a few. Others shared. I can't say I had all of them.\""), .cross("Your boat is registered to you, isn't it?", "\"Yes. It's mine. I let others drive it at times.\""), .cross("The boat is registered to you. Isn't it your responsibility who drives?", "\"Yes. I let others drive it, and I accept that.\""), .cross("You were at the helm when the officer shined a light. Why should the jury believe someone else drove earlier?", "\"Because it is true. The friend was on the helm before and moved when we saw the lights.\"")],
        openings: ("At 9:40 p.m. a wildlife officer saw a pontoon boat without lights weaving toward a crowded cove, crossing in front of a kayak. {D} was at the helm and blew a .10. The State will show the body camera, the breath result, and the registration.", "The defense evidence includes a passenger who drove most of the way, a handoff just as the officer arrived, and a boat that {D} had just taken over."),
        closings: ("A dark pontoon boat in a crowded cove, {D} at the helm with the motor running, and a .10 on the breath test. The boat is {D}'s.", "The boat was weaving before {D} took the wheel, and a passenger had driven most of the way. The State has not proved {D} was operating it while impaired."),
        timeline: [(0, "6:15 p.m.: the first beer at the marina."), (0, "9:40 p.m.: the officer sees the boat."), (0, "10:00 p.m.: the breath test reads .10."), (1, "The marina sends its receipt.")],
        identified: "The officer found {D} at the helm, and the boat is registered to {D}.",
        notDone: ["The friend said to have driven was never named in the report.", "The officer did not ask who held the helm when the light first appeared."],
                mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let scooterShoveV1 = SmallCases.make(
        key: "story.scooterShove",
        category: .violent,
        headlines: ["Cyclist Shoves Jogger Into Greenway Railing After Near Collision", "Trail Camera Shows Shove at Bridge Entrance"],
        law: "simpleAssault",
        spec: "Assaulted {V} by shoving {V.him} into a railing, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 7:15 a.m. on {DATE}, a cyclist nearly collided with {V}, a jogger, at a greenway bridge entrance. Words were exchanged and {D} shoved {V} into the bridge railing, causing a bruised hip and a scrape. A trail camera recorded the shove at 7:16 a.m. {D} says {V} stepped into the bike lane.",
        state: [E(.video, 3, "Trail Camera", "{D} shoves {V} into the railing at 7:16 a.m."), E(.document, 2, "Medical Note", "A bruised hip and a scrape on the forearm."), E(.statement, 2, "Trail Volunteer", "Saw the near miss and the shove."), E(.physical, 1, "Railing", "A smear of {V}'s jacket fabric on the bridge railing.")],
        defense: [E(.statement, 1, "Bike Lane", "{DL} says {V} stepped into the marked bike lane."), E(.document, 1, "Trail Map", "A map with the bike lane marked on the left side of the bridge.")],
        role: "Trail volunteer",
        exam: [.direct("What did you see on the greenway bridge at 7:15 a.m.?", "\"A cyclist nearly collided with a jogger at the bridge entrance. I saw the near miss and the words that followed.\""), .direct("What happened next?", "\"At 7:16, {D} shoved {V} into the bridge railing. A trail camera recorded it.\""), .direct("What was {V}'s injury?", "\"A bruised hip and a scrape on the forearm. A medical note records both. A smear of fabric from {V}'s jacket was on the railing.\""), .direct("What is your role on the greenway?", "\"I volunteer to monitor trail use and help with signage. I was at the bridge entrance at 7:15 handing out maps.\""), .direct("What did you see of the near miss?", "\"A cyclist coming fast down the grade nearly clipped a jogger who had stepped toward the left side of the bridge. Both stopped and began shouting.\""), .direct("What happened right after the words?", "\"The cyclist shoved the jogger into the railing with both hands. The jogger grabbed a hip and slid to the ground.\""), .cross("{D} says {V} stepped into the bike lane, doesn't {D.he}?", "\"Yes. {V} did drift into the marked bike lane. I agree with that.\""), .cross("Did {V} touch {D}?", "\"I did not see contact before the shove.\""), .cross("Was the near miss {D}'s fault or {V}'s?", "\"It was close. I cannot assign fault. It happened fast.\""), .cross("Did the jogger step into the bike lane?", "\"The jogger drifted left toward the painted lane. Many joggers do that without noticing.\""), .cross("Did you see the jogger touch the cyclist?", "\"No. I saw no contact before the shove.\"")],
        defenseRole: "Cyclist who rides the greenway",
        defenseExam: [.direct("Is the bike lane marked on the greenway bridge?", "\"Yes, on the left side of the bridge. It is painted, and signs show where cyclists should ride.\""), .direct("Do joggers drift into the bike lane?", "\"All the time. They run in whatever space is open, and the lane is often used by both.\""), .direct("Do cyclists usually ring a bell?", "\"Not always. Many do not, and joggers with earbuds do not hear them anyway.\""), .direct("How often do you ride the greenway?", "\"Daily, in the early morning. I use the same route every weekday.\""), .direct("How is the bridge marked?", "\"A painted bike lane runs along the left side with a dashed line. The jogger lane is on the right.\""), .direct("What are common near misses there?", "\"Joggers with earbuds drift left, and cyclists come down the slope fast. It is a known problem.\""), .cross("Did you see the shove?", "\"No. I did not see it. I only know how the bridge works.\""), .cross("Does drifting into a bike lane excuse a shove?", "\"No. It does not. I only say the lane gets crowded.\""), .cross("Do you know {D}?", "\"I ride the greenway too. I know {D} by sight.\""), .cross("Did you see this incident?", "\"No. I came by a few minutes later and heard about it.\""), .cross("Is shoving ever the right response?", "\"No. If a rider is angry, the right thing is to stop and say something.\"")],
        theory: ("{D} shoved a jogger after a near miss.", "{V} stepped into the bike lane."),
        allocution: "\"I'm not proud of it, Your Honor.\"",
        truths: ("{DL} shoved first without any contact from {V}.", "{V} did drift into the marked bike lane."),
        defendant: [.direct("Did you shove {V}?", "\"Yes, I did. {V} stepped into the bike lane right in front of me, and I nearly crashed.\""), .direct("Why did you shove {V.him}?", "\"I was scared and angry. I had almost gone over my handlebars, and I reacted.\""), .direct("Was {V} in the bike lane?", "\"Yes. {V} drifted into the marked lane. I did not have time to stop.\""), .direct("How long have you ridden the greenway?", "\"Six years, most mornings on the way to work. I know the bridge and the usual crowd.\""), .direct("What happened as you approached the bridge?", "\"A jogger stepped into the bike lane right in front of me. I hit the brakes hard and nearly went over the handlebars.\""), .direct("What did you do after you stopped?", "\"I stepped off the bike and shouted. The jogger shouted back, and I pushed hard without thinking.\""), .cross("The camera shows you shoving {V} into the railing, doesn't it?", "\"It does. I did not mean for {V.him} to hit the railing. I apologize.\""), .cross("{V} had a bruised hip and a scrape. Do you accept that?", "\"Yes. I feel bad about it.\""), .cross("Did {V} touch you first?", "\"No. {V} did not touch me. I shoved first.\""), .cross("The jogger never touched you. Why shove?", "\"Because my heart was pounding and I was furious. It was not a good reason.\""), .cross("A bruised hip is not nothing. Do you accept that you hurt someone?", "\"Yes. I hurt a person over a near miss, and I regret it deeply.\"")],
        openings: ("A cyclist nearly collided with {V}, a jogger, at a greenway bridge entrance at 7:15 a.m. A minute later, {D} shoved {V} into the bridge railing, causing a bruised hip and a scrape, and a trail camera recorded it.", "Weigh the defense proof, which will show that {V} drifted into the marked bike lane, that {D} nearly crashed, and that the shove was a frightened reaction."),
        closings: ("A near miss on a bridge, words exchanged, and then a shove into a railing on a trail camera. {V} was bruised and scraped, and {V} had not touched {D}.", "A jogger who drifted into the bike lane, a cyclist who almost crashed, and a reaction in a split second. The State must prove the shove was more than a scared reaction."),
        timeline: [(0, "7:15 a.m.: the near miss."), (0, "7:16 a.m.: {D} shoves {V}."), (0, "7:30 a.m.: a volunteer calls deputies."), (1, "The trail office sends the camera video.")],
        identified: "The trail camera identifies {D}.",
        notDone: ["The bike lane's marking was never photographed.", "The jogger's earbuds were never asked about."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let yogaCubbyV1 = SmallCases.make(
        key: "story.yogaCubby",
        category: .property,
        headlines: ["Laptop Bag Taken From Coffee Shop Table While Owner Ordered", "Laptop Tracker Pings From Bus Station"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a laptop and bag, valued at $1,300, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} left a laptop bag on a coffee shop table at 2:10 p.m. on {DATE} while ordering at the counter. At 2:12 p.m., {D} picked up the bag and walked out. A tracker in the laptop pinged from a bus station an hour later and then from {D}'s apartment. The laptop and bag were worth $1,300. {D} says {D.he} thought it was a friend's bag.",
        state: [E(.video, 3, "Coffee Shop Camera", "{D} lifts the bag and walks out at 2:12 p.m."), E(.digital, 3, "Laptop Tracker", "Pings at a bus station at 3:15 p.m. and at {D}'s address that night."), E(.document, 2, "Purchase Receipt", "The laptop and bag bought for $1,300."), E(.physical, 2, "Recovered Laptop", "The laptop found on a shelf in {D}'s apartment.")],
        defense: [E(.statement, 1, "Friend's Bag", "{DL} says {D.he} thought it was a friend's bag and meant to bring it to the friend."), E(.document, 1, "Text Message", "A text from a friend about meeting at the coffee shop.")],
        role: "Laptop owner",
        exam: [.direct("What did you leave at the coffee shop?", "\"A laptop bag on a table at 2:10 p.m. while I ordered at the counter. The laptop and bag were worth $1,300.\""), .direct("What does the coffee shop camera show?", "\"{D} picking up the bag and walking out at 2:12 p.m.\""), .direct("How was the laptop tracked?", "\"A tracker pinged from a bus station at 3:15 and then from {D}'s address. The laptop was found on a shelf in {D}'s apartment.\""), .direct("What were you doing at the coffee shop?", "\"Working on a report. I put the laptop bag on a table, set my jacket on the chair, and went to the counter to order.\""), .direct("What happened when you came back?", "\"The table was empty. I looked around, checked the restroom, and then asked the barista. The camera showed {D} picking up the bag at 2:12.\""), .direct("What did the tracker show?", "\"A ping at the bus station at 3:15 and another at {D}'s apartment that night. Deputies recovered the laptop from a shelf.\""), .cross("{D} says {D.he} thought it was a friend's bag, doesn't {D.he}?", "\"Yes. A friend was supposed to meet {D} there. I will agree to that.\""), .cross("Did {D} text the friend about it?", "\"I understand so. The text said, 'I think I have your bag.'\""), .cross("Was the charger sold?", "\"I heard the charger was sold and the laptop kept.\""), .cross("Did {D} try to hide the bag?", "\"No. {D} carried it out openly and did not run.\""), .cross("Was anything missing from the bag?", "\"The charger. The laptop was recovered but the charger was not.\"")],
        defenseRole: "Friend meeting {DL}",
        defenseExam: [.direct("Did you plan to meet {D} at the coffee shop?", "\"Yes, at two-fifteen. We had agreed to meet there, and I was running a little late.\""), .direct("Did {D} sound confused?", "\"Yes. {D} sounded confused and said the bag looked like mine. That is what made me think it was an honest mix-up.\""), .direct("How do you know {D}?", "\"We are friends. We planned to meet at the coffee shop that afternoon to hand off a laptop bag.\""), .direct("What did {D} text you?", "\"'I think I have your bag.' I wrote back that it was not my bag, and then the conversation got confusing.\""), .direct("What happened later?", "\"{D} went home with it, and I never saw it. I told {D} to take it back.\""), .direct("What did you tell {D} about where you would be sitting?", "\"I said I would be by the window with a gray bag. I figured {D} would see me, and I never told {D} to pick up anything.\""), .cross("Was your bag at the table?", "\"No. My bag was not there. I had not arrived yet.\""), .cross("Did {D} bring the bag to you?", "\"No. {D} never brought it. I did not see it again.\""), .cross("Did {D} tell you the laptop's location?", "\"No. I did not hear anything about the laptop after that.\""), .cross("Did you tell {D} what color or brand your bag was?", "\"I said a dark bag. I did not give details.\""), .cross("Did you tell {D} to take someone else's bag?", "\"No. I only said I would meet {D} there.\"")],
        theory: ("{D} took a laptop from a table.", "{D} thought it belonged to a friend."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
