        exam: [.direct("What did the university gates flag?", "\"Four hang tags with the same serial number and a faint printer line across the logo, scanned on the same days at two gates.\""), .direct("How did you trace the sales?", "\"Campus police traced them through a group chat. {D}'s account posted 'tags $60, cash only' and arranged meetings at the library.\""), .direct("What else tied {DL}?", "\"A campus print kiosk job under {D}'s student ID the day before the first scan. Twelve printed tags had matching serials.\""), .direct("How do your parking tags work?", "\"Each hang tag has a unique serial number, a holographic strip, and the university logo. The gates scan the code and flag duplicates.\""), .direct("What did the gate logs show?", "\"Four tags with the same serial number scanned at two different gates over several days. The printer line across the logo was visible on the photos.\""), .direct("What did campus police find in the group chat?", "\"A post from {D}'s account that said 'tags $60, cash only' and plans to meet at the library. Twelve students bought tags.\""), .cross("{DL} says the tags were bought from an online seller, doesn't {D.he}?", "\"There's an order page with no seller name. I can't verify the seller.\""), .cross("Did you find a printer or card stock with {DL}?", "\"I don't have that to report. I only have the kiosk record, the chat, and the tags.\""), .cross("Can a kiosk job be someone else's?", "\"It was under {D}'s ID. Someone could have borrowed it, though I have no evidence of that.\""), .cross("Can you prove who made the tags?", "\"No. We have a print kiosk job tied to {D}'s ID and the group chat sales. We do not have a witness to the printing.\""), .cross("Did {D} sell tags openly?", "\"Yes. {D} used a public chat and signed with {D.his} name. {D} did not hide the sales.\"")],
        defenseRole: "Classmate",
        defenseExam: [.direct("Did you buy a tag from {DL}?", "\"Yes. {D} sold me one for $60 at the library. I used it on campus.\""), .direct("What did {DL} say about the tags?", "\"That they were from an online seller. {D} said they were real.\""), .direct("Did the tag work at first?", "\"Yes. It scanned fine at first. Then I got a notice.\""), .direct("How do you know {D}?", "\"We are classmates in a few courses. We study at the library, and I saw {D}'s post about tags.\""), .direct("What happened when you bought a tag?", "\"I paid $60 cash at the library, hung it on my mirror, and it worked for a couple of days.\""), .direct("How did you find out it was fake?", "\"The gate flagged it and I got a notice from campus police. I was upset that I had paid for it.\""), .cross("Did you know it was fake?", "\"No. I thought it was real. I'm angry.\""), .cross("Did {DL} offer a discount?", "\"Not that I recall. It was a standard price.\""), .cross("Did you see {DL} make them?", "\"No. I only saw {D} at the library.\""), .cross("Did {D} tell you the tags were fake?", "\"No. {D} said they came from an online seller and seemed to believe it.\""), .cross("Did you see {D} printing anything?", "\"Never. I only saw {D} talking to classmates.\"")],
        theory: ("{D} printed fake hang tags and sold them.", "{D} bought tags online and resold some."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("A printer and blank card stock were found in {DL}'s dorm room.", "The order page was real and the seller used the same serial for every tag."),
        defendant: [.direct("Where did the tags come from?", "\"An online seller. I paid $30 each for a batch and sold some to classmates for $60. I thought they were legitimate.\""), .direct("Did you print the tags?", "\"No. I used the print kiosk for homework, not for tags. I didn't print them.\""), .direct("Why did you sell them?", "\"Classmates wanted parking. I made some money. I didn't know they were fake.\""), .direct("How did you hear about the tags?", "\"A classmate said an online seller had cheap hang tags. I ordered twelve at $30 each and they arrived in an envelope.\""), .direct("Why did you resell them?", "\"Classmates asked about parking, and I made a small profit. I did not think the tags were fake.\""), .direct("What was your use of the print kiosk?", "\"I printed class assignments and a map. I did not print any tags.\""), .cross("You posted 'tags $60, cash only,' didn't you?", "\"Yes. I did. I wanted a little profit.\""), .cross("Four tags had the same serial number, didn't they?", "\"I didn't look. If I'd noticed, I wouldn't have sold them.\""), .cross("The order page doesn't show a seller name, does it?", "\"No. It was an online store. I don't have more.\""), .cross("Twelve tags with identical serial numbers should have been a red flag. Why not notice?", "\"I did not look at the numbers. They looked like real tags to me.\""), .cross("The order page lists no seller name. How can you prove it exists?", "\"I cannot give a name. I have the page and an envelope, and I know how thin that sounds.\"")],
