        state: [E(.document, 3, "Discharge Form", "A form with an out-of-date logo and a patient number belonging to someone else."), E(.document, 3, "Hospital Records", "No visit by {D} on the three days listed."), E(.statement, 2, "Records Clerk", "The hospital has not used that form in two years."), E(.statement, 2, "Warehouse Supervisor", "Received the form on Monday and called the hospital Tuesday.")],
        defense: [E(.statement, 1, "Hospital Gave It", "{DL} says the hospital gave {D.him} the form at a walk-in visit."), E(.document, 1, "Pharmacy Receipt", "A cold medicine purchase on the second day.")],
        role: "Warehouse supervisor",
        exam: [.direct("What did {DL} give you on {DATE}?", "\"A hospital discharge form, after missing three days of work. I handle attendance for our shift.\""), .direct("What did you do?", "\"I called the hospital the next morning. They said the form's patient number belongs to someone else, and the logo is out of date.\""), .direct("What do the records show?", "\"No visit by {D} on the three days listed. A records clerk says the hospital hasn't used that form in two years.\""), .direct("What did you receive from {D}?", "\"A hospital discharge form on Monday, listing three days of illness and signed with a stamp.\""), .direct("Why did you check it?", "\"The company requires verification for absences over two days. I called the number on the form the next morning.\""), .direct("What did the hospital tell you?", "\"The patient number belongs to someone else, and the logo had been replaced two years earlier. There was no visit by {D} on those days.\""), .cross("{DL} says the hospital gave {D.him} the form, doesn't {D.he}?", "\"I don't know what the hospital hands out. I only know what they told me on the phone.\""), .cross("Was {DL} sick?", "\"I can't say. {D} was out three days. A coworker said {D} had a cold.\""), .cross("Has {DL} given you notes before?", "\"No. This is the first time I recall. {D} has been reliable.\""), .cross("Was {D} otherwise reliable?", "\"Yes. {D} had a good attendance record before this.\""), .cross("Did {D} offer any other proof?", "\"A receipt for cold medicine on the second day. It does not prove a hospital visit.\"")],
        defenseRole: "Coworker",
        defenseExam: [.direct("Do you work with {DL}?", "\"Yes. We work the same shift. I saw {D} before and after the absence.\""), .direct("Did {DL} seem sick?", "\"Before the absence, {D} was coughing and said {D.he} felt terrible.\""), .direct("What did {DL} buy?", "\"Cold medicine. I saw the receipt from the pharmacy on the second day.\""), .direct("How long have you worked with {D}?", "\"Three years on the same shift. We load trucks side by side most days, so I see how {D} works and how {D} looks when feeling ill.\""), .direct("What did {D} look like before the absence?", "\"Coughing and tired for a couple of days. {D} said {D.he} felt feverish and left early on Friday, which is not like {D}.\""), .direct("Did you see {D} buy medicine?", "\"I saw a pharmacy receipt on Monday that {D} had stuck in a shirt pocket. It was for cold medicine and dated the second day of the absence.\""), .cross("Did you see {DL} during the three days?", "\"No. I was at work. I only saw {D} before and after.\""), .cross("Could {DL} have been sick without going to the hospital?", "\"Of course. Many people don't go. I can't say.\""), .cross("Did you see the form?", "\"Never. I only know what {D} told me about it when {D} came back to work, so I cannot describe the paper.\""), .cross("Could {D} have been sick without seeing a doctor?", "\"Yes. Plenty of people stay home with a bad cold and get medicine at the pharmacy instead of going to a hospital or a clinic.\""), .cross("You were not with {D} at home during the three days, were you?", "\"No. I only know what {D} told me and what I saw on the day {D} returned. {D} looked pale and tired.\"")],
        theory: ("{D} gave a forged form to cover time off.", "{D} was sick and used the form the hospital gave."),
