        state: [E(.document, 3, "Written Notice", "A notice signed by {D} three weeks before barring {D.him} from the property."), E(.video, 2, "Lot Camera", "{D}'s car parks beside the fence at 10:05 a.m. and stays."), E(.statement, 2, "Director", "Recognized {D} and called deputies."), E(.document, 2, "Pickup Roster", "{D} is not on the center's pickup list.")],
        defense: [E(.statement, 1, "Waiting for a Relative", "{DL} says a relative was inside and {D.he} was waiting to be called."), E(.document, 1, "Enrollment Note", "A child with {DL}'s surname is enrolled on a different shift.")],
        role: "Day care director",
        exam: [.direct("What notice had {D} received?", "\"A written notice barring {D} from the day care property, signed three weeks before. I gave it to {D} myself.\""), .direct("What did you see on the date in question?", "\"At about 10:05 a.m., {D}'s car parked beside the playground fence during outdoor play, and it stayed for forty minutes.\""), .direct("What did you do?", "\"I recognized {D}, called deputies, and watched until they arrived at 10:45.\""), .direct("Why did you issue the notice?", "\"{D} had arrived unannounced and tried to enter the building to pick up a child who was not on {D}'s authorized list. I wrote a formal notice and {D} signed it.\""), .direct("Where was {D}'s car that morning?", "\"In the lot right beside the playground fence, where children were playing outside. It sat there from about 10:05 on.\""), .direct("How did you respond?", "\"I recognized the car, kept the children together, and called deputies. I watched until they arrived at 10:45.\""), .cross("{D} says {D.he} was waiting for a relative, doesn't {D.he}?", "\"Yes. {D} said that. But {D} is not on the center's pickup list.\""), .cross("Did a staff member tell {D} the notice did not apply during pickup?", "\"I understand one did say that that morning. That was not authorized.\""), .cross("Did {D} approach the children?", "\"No. {D} stayed in the car. No child was approached.\""), .cross("Did {D} get out of the car or speak to a child?", "\"No. {D} stayed in the driver's seat. No child approached the car.\""), .cross("Could a relative have been waiting inside?", "\"A child with {D}'s surname is enrolled on a different shift. That is the only link I know of.\"")],
        defenseRole: "Parent at the day care",
        defenseExam: [.direct("Do relatives wait in the lot sometimes?", "\"Sometimes, for the early pickup. Parents and relatives wait in cars before the doors open.\""), .direct("Is {D} on the roster of approved people?", "\"No. I know that. {D} is not on the list for pickup.\""), .direct("Did the director talk to {D} that morning?", "\"Not that I saw. The director watched from the window and called deputies.\""), .direct("How long have you used the day care?", "\"Two years. I drop off every morning and sometimes wait in the lot for pickup.\""), .direct("What do you see in the lot at that hour?", "\"A few cars with parents or relatives waiting. It is common for people to sit in their cars until a child is released.\""), .direct("What did you see of {D}'s car?", "\"It was parked toward the back, near the fence. I did not see anyone get out.\""), .cross("Did you see {D} approach the fence?", "\"No. I did not. {D} stayed in the car, as far as I could see.\""), .cross("Are you related to {D}?", "\"No. I am another parent. I only saw what I saw.\""), .cross("Did you know {D} was barred from the property?", "\"No. I only learned about the notice afterward, when deputies came.\""), .cross("Did you speak to {D}?", "\"No. I never spoke to {D} that morning.\""), .cross("You cannot say what {D} was told about the notice, can you?", "\"No. I only know that the car sat in the lot for a long time. I was not part of any conversation about the notice.\"")],
        theory: ("{D} stayed on the property after a written ban.", "{D} was waiting for a relative."),
        allocution: "\"I understand why people were afraid. I'm sorry.\"",
        truths: ("{DL} had been told the notice applied to all hours.", "A staff member had told {DL} that morning that the notice did not apply during pickup."),
        defendant: [.direct("Why were you parked by the playground fence?", "\"I was waiting for a relative to be released. I thought I was allowed to wait during pickup.\""), .direct("Did you know the notice applied?", "\"I had been told the notice applied to all hours. But a staff member told me that morning it did not apply during pickup.\""), .direct("Did you approach any child?", "\"No. I stayed in my car the whole forty minutes.\""), .direct("What was your reason for being at the day care?", "\"A relative in the program was due to be released that morning, and I was asked to wait in the lot until called.\""), .direct("What did you understand about the notice?", "\"That I could not enter or pick up without approval. I thought waiting in a car in the lot was different.\""), .direct("What did a staff member tell you that morning?", "\"That the notice did not apply during pickup. I took that to mean I could wait outside.\""), .cross("You signed a notice three weeks earlier barring you, didn't you?", "\"Yes. I did. I read it as covering normal hours, not pickup.\""), .cross("You are not on the pickup list, are you?", "\"No. I am not. I was only going to wait.\""), .cross("The playground fence was ten feet from your car. Why park there?", "\"It was the closest spot to the door. I did not realize how it would look.\""), .cross("You are not on the pickup list. How could you collect anyone?", "\"I was not picking up. I was waiting for a relative who was already on the list.\""), .cross("The staff member who spoke to you that morning was not the director, was it?", "\"Correct, it was a staff member and not the director. I took the staff member's word and did not check with the director.\"")],
        openings: ("A day care director gave {D} a written notice barring {D} from the property. Three weeks later, {D} parked beside the playground fence during outdoor play and stayed forty minutes, until deputies arrived.", "Jurors will hear that a staff member told {D} that morning that the notice did not apply during pickup, and that {D} stayed in the car and approached no child."),
        closings: ("A signed notice, a car beside the playground fence during outdoor play, and forty minutes of waiting. {D} was barred and not on the pickup list.", "A staff member's word that pickup was fine, a person who stayed in the car, and no child approached. The State must prove {D} knowingly entered despite the notice."),
        timeline: [(-21, "{D} signs the notice."), (0, "10:05 a.m.: {D} parks beside the fence."), (0, "10:20 a.m.: the director calls deputies."), (0, "10:45 a.m.: deputies arrive.")],
        identified: "The notice and the director identify {D}.",
        notDone: ["The notice's hours were never specified.", "The enrolled child with {DL}'s surname was never asked about a relation."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let checkoutShoveV1 = SmallCases.make(
        key: "story.checkoutShove",
        category: .violent,
        headlines: ["Pharmacy Line Argument Ends in Shove Into Vitamin Display", "Customer Pushed Into Shelf After Stepping in Front at Pickup Window"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him} into a display, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 5:40 p.m. on {DATE}, {V} stepped in front of {D} at a pharmacy pickup window to ask the pharmacist a question. {D} said the line had been waiting twenty minutes and shoved {V} sideways into a vitamin display. {V} bruised a shoulder and a bottle display fell. The pharmacy camera recorded the shove at 5:43 p.m. {D} says {V} elbowed {D.him} first.",
        state: [E(.video, 3, "Pharmacy Camera", "{D} shoves {V} sideways into the vitamin display at 5:43 p.m."), E(.document, 2, "Medical Note", "A bruised shoulder and a scrape on the forearm treated that evening."), E(.statement, 2, "Pharmacist", "Saw {D} push {V} and called the manager."), E(.physical, 1, "Display Damage", "Two bottles broken and a shelf bent.")],
        defense: [E(.statement, 1, "Elbowed First", "{DL} says {V} stepped in and elbowed {D.him} aside."), E(.statement, 1, "Long Wait", "{DL} says the line had waited twenty minutes.")],
        role: "Pharmacist",
        exam: [.direct("What happened at your pickup window at 5:40 p.m. on {DATE}?", "\"{V} stepped in front of {D} to ask me a question. {D} said the line had waited twenty minutes and shoved {V} sideways into a vitamin display.\""), .direct("What does the pharmacy camera show?", "\"The shove at 5:43. {V} goes sideways into the display.\""), .direct("What was the result?", "\"{V} had a bruised shoulder and a scrape, and two bottles broke. A shelf was bent. I called the manager.\""), .direct("What was the pharmacy like at 5:40?", "\"Busy after work, with a line of about eight people waiting. I was working the pickup window and trying to move through prescriptions.\""), .direct("What did you see between {D} and {V}?", "\"{V} stepped up and asked me a question about a refill. {D} said the line had waited twenty minutes and shoved {V} sideways into the vitamin display.\""), .direct("What did you do?", "\"I called for the manager and checked on {V}. Two bottles had broken and a shelf was bent.\""), .cross("{DL} says {V} elbowed {D.him} first, doesn't {D.he}?", "\"I saw {V} step in. I didn't see an elbow.\""), .cross("Did the line wait a long time?", "\"It was long. People were irritated. That doesn't excuse a shove.\""), .cross("Did {V} step in front of {DL}?", "\"Yes. {V} stepped up to ask me a question. That's what started it.\""), .cross("Did {V} cut in line deliberately?", "\"{V} walked up as if there were no line. I do not know if it was deliberate.\""), .cross("Did you see {V} touch {D}?", "\"I saw {V} brush past. I did not see an elbow.\"")],
        defenseRole: "Customer in the pharmacy line",
        defenseExam: [.direct("Were you in line?", "\"Yes. I was behind {D}. The line had waited a long time.\""), .direct("What did {V} do?", "\"Stepped in front of {D} to talk to the pharmacist. People were annoyed.\""), .direct("Did {V} touch {DL}?", "\"I'm not sure. {V} moved fast and bumped past. I can't say it was an elbow.\""), .direct("Where were you in the line?", "\"Right behind {D}, about two feet back. I had a clear view of the window.\""), .direct("What did you see {V} do?", "\"{V} walked past the line and bumped {D}'s arm as {V} stepped up. {V} did not say excuse me.\""), .direct("What did {D} do next?", "\"{D} pushed {V} hard. {V} went into the vitamin display and bottles fell.\""), .cross("Who touched first?", "\"I think {V}, as {V} stepped in. I can't say for sure.\""), .cross("Did {DL} push hard?", "\"Yes. {V} went into the display. It was a real shove.\""), .cross("Did you see a second shove?", "\"No. I only saw one. I looked away after.\""), .cross("Did {D} push twice?", "\"I only saw one push. I looked away afterward.\""), .cross("Was the push justified?", "\"No. It was too hard. Cutting in was rude, but a shove was too much.\"")],
        theory: ("{D} shoved {V} over a line cut.", "{V} elbowed {D} first."),
        allocution: "\"I hurt someone who didn't deserve it. I'm sorry.\"",
        truths: ("{DL} shoved {V} a second time after the first push.", "{V} did brush {DL}'s arm as {V.he} stepped in."),
        defendant: [.direct("Why did you push {V}?", "\"I'd waited twenty minutes. {V} stepped in front of me and elbowed me aside. I pushed back without thinking.\""), .direct("Did you mean to hurt {V}?", "\"No. I wanted {V} out of my way. I didn't know {V} would hit the display.\""), .direct("How are you coping with what happened?", "\"Embarrassed. I shouldn't have touched anyone. I'm willing to pay for the damage.\""), .direct("How long had you been waiting?", "\"About twenty minutes. I had a sick child at home and needed medicine right away.\""), .direct("What did {V} do?", "\"{V} stepped in front of me as if I were not there and started talking to the pharmacist. Our arms touched.\""), .direct("What did you do?", "\"I put my hands out and pushed {V} aside. I did not think about the display behind.\""), .cross("The camera shows you shoving {V}, doesn't it?", "\"Yes. It does. I'm not denying it.\""), .cross("{V} was left with a bruised shoulder, wasn't {V.he}?", "\"I've heard so. I'm sorry.\""), .cross("You could have asked {V} to wait, couldn't you?", "\"Yes. I should have, yes. I was too angry.\""), .cross("You pushed a stranger because of a spot in line. Why?", "\"I was worried and angry. It was no excuse, and I knew it as soon as I did it.\""), .cross("Did you push {V} more than once?", "\"I may have. I do not remember. I was not in my right mind.\"")],
        openings: ("At a pharmacy pickup window, {V} stepped in front of {D}, who said the line had waited twenty minutes and shoved {V} sideways into a vitamin display. The pharmacy camera recorded it. The State will show the video, the medical note, and the damage.", "Jurors will also see a line that had waited twenty minutes, a person who stepped in and bumped {D}, and a single shove. Listen closely to the witnesses."),
        closings: ("A shove on camera, a bruised shoulder, a scrape, and a broken display. A long line gives no one the right to push.", "{V} stepped in front of {D} after a long wait and brushed past. The State has not proved {D}'s one shove was more than a reaction."),
        timeline: [(0, "5:20 p.m.: {D} joins the pharmacy line."), (0, "5:40 p.m.: {V} steps in front."), (0, "5:43 p.m.: {D} shoves {V}."), (1, "The pharmacy sends its camera video.")],
        identified: "The pharmacy camera and the pharmacist identify {D}.",
        notDone: ["The pharmacy never recorded how long the line had waited.", "No one asked {V} whether {V.he} told {DL} about the pharmacist question first."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let roadConesV1 = SmallCases.make(
        key: "story.roadCones",
        category: .property,
        headlines: ["Highway Crew Loses Nine Barricades and a Flashing Arrow Board Overnight", "Yard Camera Shows Truck Backing to Equipment Rack"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a highway contractor, valued at $1,050, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A highway contractor kept nine barricades and a flashing arrow board in its equipment yard on {DATE}. At 1:10 a.m., the yard camera shows {D} back a truck up to the rack and load the items. The contractor counted the missing equipment at 6 a.m. The loss came to $1,050. {D} says the equipment was dumped in a ditch and {D.he} was clearing it.",
        state: [E(.video, 3, "Yard Camera", "{D} loads nine barricades and an arrow board at 1:10 a.m."), E(.document, 3, "Equipment List", "Nine barricades and one arrow board listed with serial tags."), E(.physical, 2, "Recovered Barricades", "Six barricades found in {D}'s yard with serial tags intact."), E(.statement, 2, "Site Foreman", "The items were locked behind a fence.")],
        defense: [E(.statement, 1, "Cleaning a Ditch", "{DL} says the items were dumped in a ditch and {D.he} was cleaning it up."), E(.document, 1, "Roadside Photo", "A photo of barricades near a ditch two miles away.")],
        role: "Site foreman",
        exam: [.direct("What was missing at 6 a.m.?", "\"Nine barricades and an arrow board. The equipment list shows serial tags on each. The loss came to $1,050.\""), .direct("How were the items stored?", "\"Locked behind a fence in our equipment yard. Someone had cut the fence lock.\""), .direct("What did you find at 6 a.m.?", "\"The rack empty and the gate chain cut. Nine barricades and the flashing arrow board were gone. I called deputies and pulled the camera.\""), .direct("What does the yard camera show?", "\"At 1:10 a.m. {D} backs a truck to the rack and loads the barricades and the arrow board in about fifteen minutes. {D} drives out.\""), .direct("What was recovered?", "\"Six barricades with serial tags in {D}'s yard. The arrow board and three barricades are still missing.\""), .direct("What did you do after you found the rack empty at 6 a.m.?", "\"I counted the missing items against the equipment list and called the sheriff's office. I also pulled the yard camera and found the loading at 1:10 a.m.\""), .cross("{D} says the equipment was dumped in a ditch, doesn't {D.he}?", "\"Some items do end up in ditches after wind. That is fair.\""), .cross("Did {D} hide what was loaded?", "\"The camera shows {D} loading in the open, at night.\""), .cross("Did you inspect barricades near a ditch?", "\"A photo shows barricades near a ditch two miles away. I could not tell if they were ours.\""), .cross("Was the fence lock cut?", "\"Yes. It lay on the ground beside the gate. I cannot say who cut it.\""), .cross("The recovered barricades still had your serial tags, didn't they?", "\"Yes, all six. The tags are riveted on, and I matched each number to our list before the deputies took them as evidence.\"")],
        defenseRole: "Roadside worker",
        defenseExam: [.direct("Do barricades end up in ditches?", "\"All the time, after wind or when a truck clips one. They get knocked down and sit there for weeks.\""), .direct("Were any of those barricades in a ditch?", "\"Some. I have seen several near ditches on those roads, and nobody picks them up.\""), .direct("Does anyone pick up the strays?", "\"Neighbors do, sometimes. A neighbor might take a barricade home and use it for a driveway.\""), .direct("What do you do for the highway department?", "\"I set and retrieve barricades and cones on roadside jobs.\""), .direct("How often do barricades end up in ditches?", "\"Every week or two. Wind knocks them over and drivers hit them. Crews often have to collect strays.\""), .direct("What do people do with strays?", "\"Some call the contractor. Some pick them up and bring them to the yard. Others leave them.\""), .cross("Were any behind a fence?", "\"Some. The ones in the yard were behind a fence. Those are different from ones in a ditch.\""), .cross("Would you load barricades from a locked yard at 1 a.m.?", "\"No. I would call the contractor first.\""), .cross("Did you see {D} at the yard that night?", "\"No. I only know about barricades in general.\""), .cross("Did {D} work for the contractor?", "\"No. {D} is not on our crew.\""), .cross("Would you take equipment from a locked yard?", "\"No. I would call the foreman first and get permission.\"")],
        theory: ("{D} took a contractor's equipment at night.", "{D} was clearing roadside equipment."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} cut the fence lock with bolt cutters before loading.", "A few barricades really were near a ditch and {DL} picked those up too."),
        defendant: [.direct("Did you take the barricades and the arrow board?", "\"I took some, and I thought they were abandoned in a ditch. I believed I was clearing them away.\""), .direct("Why did you load them at 1 a.m.?", "\"I was working late that night. I did not realize they belonged to a contractor's yard until later.\""), .direct("Where did you take the equipment you loaded?", "\"To my own yard. I planned to ask around about who they belonged to, and then return them.\""), .direct("What do you do for work?", "\"I haul equipment and do roadside cleanup. I get called at all hours for debris and strays.\""), .direct("What did you see that night?", "\"Several barricades in a ditch along the road, and others by a fence. It looked like a dumping area.\""), .direct("Why were you at the contractor's yard?", "\"I saw more stacked there and thought they had been abandoned. I loaded them to take them out of the weather.\""), .cross("The fence at the equipment yard had a cut lock, didn't it?", "\"I do not know about the lock. I did not cut it, and I did not see it was cut.\""), .cross("Serial tags were on every barricade you loaded. Didn't you see them?", "\"I did not look closely at the tags. I should have, and I am sorry that I did not.\""), .cross("Six barricades were found in your yard, weren't they?", "\"Yes. I kept them there. I did not think about returning them quickly enough.\""), .cross("The yard was behind a fence. How is that abandoned?", "\"I did not see the fence as locked. The gate was open and I loaded quickly.\""), .cross("Serial tags are on every barricade. Why did you ignore them?", "\"I did not read them. I should have seen they were somebody's property.\"")],
        openings: ("At 1:10 a.m., a yard camera shows {D} back a truck up to a rack and load nine barricades and a flashing arrow board worth $1,050 from a contractor's locked equipment yard.", "By the end of this trial, the proof will show that some barricades really were near a ditch, that {D} believed they were abandoned, and that {D} loaded openly."),
        closings: ("Nine barricades and an arrow board, serial tags on each, taken from behind a fence at 1 a.m. Six were found in {D}'s yard.", "A person who thought the barricades were abandoned and who loaded openly in front of a camera. The State must prove {D} knew they belonged to the contractor."),
        timeline: [(0, "1:10 a.m.: {D} loads the rack."), (0, "6 a.m.: the foreman counts the missing equipment."), (1, "The foreman reviews the yard camera."), (3, "Deputies find six barricades in {D}'s yard.")],
        identified: "The yard camera identifies {D}.",
        notDone: ["The ditch photo's location was never verified.", "The fence lock was never examined for a cut."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let ebayBrickV1 = SmallCases.make(
        key: "story.ebayBrick",
        category: .whiteCollar,
        headlines: ["Buyer Opens Box From Console Seller and Finds Floor Tiles", "Online Seller Ships Wrong Item Three Times in a Row"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $640, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} $640 on {DATE} for a game console listed online. The box arrived four days later holding six ceramic floor tiles. {D} told {V} the shipment was a warehouse error and promised a replacement that never came. The shipping label lists {D}'s address. {D} says a friend packed the box.",
        state: [E(.physical, 3, "Shipping Box", "A box labeled with {D}'s return address holding six ceramic tiles."), E(.digital, 3, "Payment Record", "$640 sent to {D}'s payment account on {DATE}."), E(.document, 2, "Listing", "A listing for a game console with a photo and a $640 price."), E(.digital, 2, "Messages", "{D} promises a replacement within a week and then stops replying.")],
        defense: [E(.statement, 1, "Friend Packed It", "{DL} says a friend packed the box while {D.he} was at work."), E(.document, 1, "Work Schedule", "{DL} was at work from 7 a.m. to 3 p.m. the day it shipped.")],
        role: "Buyer",
        exam: [.direct("What did you buy on {DATE}?", "\"A game console I found in an online listing. I paid {D} $640 that day.\""), .direct("What did {DL} tell you?", "\"That the shipment was a warehouse error, with a replacement promised within a week. After that, {D} stopped replying.\""), .direct("How did you find the listing?", "\"An online marketplace, with a photo of a console in its box and a price of $640 including shipping. I sent the money through a payment app.\""), .direct("What arrived and what did you do?", "\"A box four days later with six heavy ceramic tiles inside. I messaged {D} and asked what happened.\""), .direct("What did {D} say?", "\"That it was a warehouse error and that a replacement would ship within a week. After that, {D} stopped answering.\""), .direct("What did you do when the tiles arrived instead of the console?", "\"I took photos of the box and the label and messaged {D} right away. {D} promised a replacement within a week and then stopped answering.\""), .cross("{DL} says a friend packed the box, doesn't {D.he}?", "\"I can't say who packed it. The label has {D}'s return address.\""), .cross("Did you ever get a refund?", "\"No. I'm still out $640. I've tried repeatedly.\""), .cross("Did the listing show the console?", "\"Yes. A photo and a $640 price. I trusted it.\""), .cross("Did the label show who sent it?", "\"Yes. {D}'s name and return address were on it. I do not know who actually packed the box.\""), .cross("Did you try to recover your money through the payment app?", "\"Yes. The dispute is still open. I have not received a refund.\"")],
        defenseRole: "Friend who packed the box",
        defenseExam: [.direct("Did you pack {DL}'s box?", "\"Yes. {D} asked me to ship a console while {D} was at work.\""), .direct("What did you put in the box?", "\"I thought it was the console. I grabbed a box from the garage and packed it.\""), .direct("Did {DL} check it?", "\"No. {D} was at work from 7 to 3. I did it alone.\""), .direct("How do you know {D}?", "\"We have been friends since high school. I help with errands and packing when {D} works long shifts.\""), .direct("What did you ship for {D}?", "\"A box I thought held a console. I grabbed it from the garage, taped it, and put on the label {D} gave me.\""), .direct("What was in the box?", "\"I assumed it was the console. I did not open it. I now think I grabbed the box of tiles by mistake.\""), .cross("What was in the box you packed?", "\"Tiles, apparently. I'm not sure how. I picked the wrong box.\""), .cross("Did you see the console?", "\"I saw one. I may have grabbed the wrong box. I'm not sure.\""), .cross("Did you tell {DL}?", "\"Not at once. I felt bad about it later.\""), .cross("Did you check the weight?", "\"I noticed it was heavy. I thought it was the console and its accessories.\""), .cross("When did you realize the mistake?", "\"When {D} told me the buyer got tiles. I felt awful and did not say how it happened until later.\"")],
        theory: ("{D} took $640 and shipped tiles.", "A friend packed the wrong box."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} listed two other consoles that week and shipped none.", "The tiles were left over from {DL}'s own home project."),
        defendant: [.direct("Did you sell {V} a console?", "\"I listed one and took the payment. I meant to ship it. A friend packed the box while I was at work.\""), .direct("Why did tiles arrive?", "\"I don't know. My friend packed the wrong box or something got mixed up. I was at work that day.\""), .direct("Why did you promise a replacement?", "\"I thought it was a warehouse mix-up. I didn't have it in me to fix it. I stopped replying out of embarrassment.\""), .direct("How did you set up the sale?", "\"I listed the console online, took the payment, and asked a friend to ship it since I was working long hours that week.\""), .direct("What did you do when the buyer complained?", "\"I told the buyer I would look into it. I checked with my friend and then felt too embarrassed to keep answering.\""), .direct("What happened to the console you listed for sale?", "\"I never had it in my hands. I advertised it hoping to get one from a supplier, and the supplier never delivered.\""), .cross("Your return address was on the box, wasn't it?", "\"Yes. My friend used my label. I didn't check.\""), .cross("You took $640, didn't you?", "\"Yes. I haven't returned it. In hindsight, yes.\""), .cross("You stopped replying to {V}, didn't you?", "\"Yes. I was ashamed. I should have kept in touch.\""), .cross("You took $640 and never delivered a console. Isn't that theft?", "\"I never meant to steal. I failed to deliver, and I should have refunded the money right away.\""), .cross("You listed two other consoles that week. Did any ship?", "\"I had listings up, yes. I fell behind on shipping and I should not have kept listing.\"")],
        openings: ("{V} paid {D} $640 for a game console, and four days later a box arrived holding six ceramic floor tiles, with {D}'s return address on the label. {D} promised a replacement and stopped replying. The State will show the box and the payment.", "The defense will point you to a friend who packed the box while {D} was at work, a mix-up in the garage, and a seller who was embarrassed, not scheming."),
        closings: ("$640 paid by a buyer, a box of tiles with {D}'s own return address on it, and a promise of a replacement that never came. {D} took the money and delivered nothing.", "A friend packed the wrong box while {D} was at work. The State has not proved {D} meant to deceive the buyer rather than failing to ship the right item."),
        timeline: [(0, "{V} pays $640."), (1, "The box ships from {D}'s address."), (4, "The box arrives holding tiles."), (8, "{V} stops hearing from {D}.")],
        identified: "The payment record and the shipping label identify {D}.",
        notDone: ["The friend who packed the box was never interviewed.", "The shipping scale weight was never compared with a console's weight."],
