        state: [E(.video, 3, "Mirror Camera", "{D} puts the jacket on over a coat in the fitting room and walks out at 4:25 p.m."), E(.physical, 3, "Tags", "Price tags tucked inside the sleeve of the jacket when it was recovered."), E(.document, 2, "Price List", "The leather jacket priced at $310."), E(.statement, 2, "Store Manager", "Noticed the empty hanger in the fitting room.")],
        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot the jacket was on."), E(.document, 1, "Receipt Left at Home", "A receipt for a different jacket from another store that week.")],
        role: "Store manager",
        exam: [.direct("What did you see at your boutique at 4 p.m. on {DATE}?", "\"{D} took a leather jacket into a fitting room. At 4:25, {D} walked out wearing it over a coat.\""), .direct("What does the mirror camera show?", "\"{D} putting the jacket on over a coat in the fitting room and walking past the register without stopping.\""), .direct("What was found when the jacket was recovered?", "\"Price tags tucked inside the sleeve. The jacket is priced at $310, and I found the empty hanger in the fitting room.\""), .direct("How did you notice something was wrong?", "\"An empty hanger was left on the fitting room hook, and the leather jacket was missing from the rack. I checked the mirror camera.\""), .direct("What does the camera show in the fitting room?", "\"{D} puts the jacket on over a coat, zips it, and walks out toward the register. {D} passes the counter without stopping.\""), .direct("How were the tags placed?", "\"Tucked inside the sleeve out of sight. When the jacket was recovered, the tag was still there with the price visible.\""), .cross("{DL} says {D.he} forgot the jacket was on, doesn't {D.he}?", "\"It's possible. But tags tucked in a sleeve doesn't look like forgetting.\""), .cross("Did {DL} try to run?", "\"No. {D} walked out normally. There was no rush.\""), .cross("Did you stop {DL} at the door?", "\"No. I saw the hanger later and checked the camera.\""), .cross("Did {D} seem hurried?", "\"No. {D} walked at a normal pace and made no attempt to hide anything.\""), .cross("Did you speak to {D} before {D} left?", "\"No. I was at the back of the store. I did not see {D} leave.\"")],
        defenseRole: "Friend waiting outside",
        defenseExam: [.direct("Were you with {DL}?", "\"I was waiting outside the boutique. I saw {D} come out.\""), .direct("How did {DL} come out?", "\"Chatting, unhurried, like any shopper. {D} didn't rush or look around.\""), .direct("Did {DL} seem to hide anything?", "\"No. Nothing stood out. {D} walked out normally.\""), .direct("What were you doing outside the boutique?", "\"Waiting on the sidewalk for {D}. We had planned to get lunch afterward.\""), .direct("Did {D} act nervous?", "\"No. {D} was relaxed and talking about something else. Nothing about the way {D} walked looked sneaky.\""), .direct("What did you see {DL} carry when {DL} came out of the boutique?", "\"{DL} had a coat on and, over it, a jacket I had not seen before. I did not think about it until deputies came.\""), .cross("Did {DL} mention it?", "\"No. We left together. Nothing was said.\""), .cross("Did you see {DL} in the fitting room?", "\"No. I was outside. I can't say what happened inside.\""), .cross("Did you know about the jacket?", "\"No. I did not notice it at the time. I was looking at my own phone.\""), .cross("Did {D} mention the jacket later?", "\"Only after the store manager called. {D} was shocked and said it must have been left on.\""), .cross("You did not see what happened inside the fitting room, did you?", "\"No. I was waiting outside. I know what I saw when {DL} came out, and I cannot tell you what was said or done in there.\"")],
        theory: ("{D} wore a jacket out without paying.", "{D} forgot the jacket was on."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had tucked the tags into the sleeve on purpose.", "{DL} was on the phone and distracted."),
        defendant: [.direct("Why were you wearing the jacket?", "\"I put it on in the fitting room and forgot to take it off. I put my coat over it, and I walked out.\""), .direct("Did you mean to steal the jacket?", "\"No. If I'd wanted to steal, I wouldn't have been so careless. I was distracted.\""), .direct("Why did you try on the jacket?", "\"I liked it and wanted to see how it fit. It was a cold day, so I put it over my coat to see if it was warm.\""), .direct("What happened after you tried it on?", "\"My phone rang and I started talking. I buttoned the jacket and walked toward the exit without thinking.\""), .direct("Why were the tags tucked into the sleeve?", "\"I tucked them in so they would not dangle while I tried it on. I forgot they were there.\""), .direct("What did you intend to do after you tried the jacket on?", "\"I planned to ask about the price and then decide. I got a call, walked out of the fitting room, and just kept moving.\""), .cross("You walked past the register, didn't you?", "\"Yes. I wasn't thinking. I didn't realize.\""), .cross("You had it over your own coat, didn't you?", "\"Yes. It was a cold day. I layered it.\""), .cross("A $310 jacket is hard to forget, isn't it?", "\"I know how it sounds. It happened. I was distracted.\""), .cross("You walked past a register while wearing an unpaid jacket. Doesn't that look intentional?", "\"It looks that way from the video. I did not realize I still had it on.\""), .cross("You had a receipt for a different jacket that week. Why mention it?", "\"It shows I buy things. I do not steal.\"")],
        openings: ("At 4 p.m. {D} took a $310 leather jacket into a boutique fitting room and at 4:25 walked out wearing it over a coat, with the tags tucked in the sleeve and without stopping at the register. The mirror camera shows it. The State will show the video and the tags.", "The defense will present a customer who layered a jacket in a fitting room, forgot it was on, and walked out unhurried in front of a friend."),
        closings: ("A leather jacket worn out over a coat, the price tags tucked inside the sleeve, and a walk past the register without paying. Those are the actions of someone who planned to leave with it.", "A distracted shopper on a phone call, an unhurried walk, and a friend waiting outside who saw nothing hidden. The State has not proved {D} meant to take the jacket without paying."),
        timeline: [(0, "4 p.m.: {D} enters the fitting room."), (0, "4:25 p.m.: {D} leaves wearing the jacket."), (0, "4:30 p.m.: the manager finds the empty hanger."), (1, "The store sends its mirror camera video.")],
        identified: "The mirror camera identifies {D}.",
        notDone: ["The phone call's start time was never checked.", "The boutique's fitting room policy was never read."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let gateArmV1 = SmallCases.make(
        key: "story.gateArm",
        category: .traffic,
        headlines: ["Driver Snaps Hospital Garage Arm After Ticket Machine Rejects Payment", "Ticket Rejection Ends With Broken Arm and Missing Plate"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a parking operator, causing damage of $520, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 3 p.m. on {DATE}, {D} reached the exit of a hospital garage and the ticket machine rejected {D}'s card twice. A car waited behind. {D} drove forward and snapped the gate arm. The camera recorded the plate and the exit at 3:08 p.m. The arm cost $520 to replace. {D} says the arm was stuck down.",
        state: [E(.video, 3, "Exit Camera", "{D} drives into the gate arm at 3:08 p.m. and it snaps."), E(.document, 2, "Machine Log", "Two declined card attempts at 3:05 and 3:06 p.m."), E(.document, 2, "Replacement Invoice", "$520 for a new arm and motor."), E(.statement, 2, "Garage Manager", "The arm raised normally for the previous car.")],
        defense: [E(.statement, 1, "Arm Stuck", "{DL} says the arm was stuck and a car was behind {D.him}."), E(.document, 1, "Maintenance Log", "A service call for the exit arm two weeks before.")],
        role: "Garage manager",
        exam: [.direct("What happened at your hospital garage exit at 3 p.m. on {DATE}?", "\"{D}'s card was rejected twice, at 3:05 and 3:06. {D} drove forward at 3:08 and snapped the gate arm.\""), .direct("What does the exit camera show?", "\"{D} driving into the gate arm and it snapping. A car waited behind.\""), .direct("What did it cost?", "\"$520 for a new arm and motor. The arm raised normally for the previous car.\""), .direct("How does your exit work?", "\"Drivers insert a ticket or card at the machine, the system takes payment, and the arm raises. A decline leaves the arm down.\""), .direct("What did the log show for {D}?", "\"Two declined card attempts at 3:05 and 3:06. No successful payment was recorded.\""), .direct("What happened at 3:08?", "\"{D} drove into the arm and snapped it off. A car was waiting behind. {D} then left through the gap.\""), .cross("{DL} says the arm was stuck, doesn't {D.he}?", "\"It raises normally. The machine log shows the card was declined, which is why it stayed down.\""), .cross("Was the exit serviced recently?", "\"There was a service call two weeks before. I can't say it was perfect.\""), .cross("Did {DL} stop and report it?", "\"No. I saw it on the camera afterward.\""), .cross("Did the arm raise for the previous car?", "\"Yes. It lifted normally for the car ahead, then dropped as usual.\""), .cross("Was there a recent repair?", "\"A service call two weeks earlier for sluggishness. The motor was replaced.\"")],
        defenseRole: "Hospital security guard",
        defenseExam: [.direct("Do you work at the hospital garage?", "\"Yes. I'm a security guard. I'm in the garage often.\""), .direct("Has the exit arm had trouble?", "\"Yes. A service call two weeks before. It's been sluggish.\""), .direct("Have you seen it stick?", "\"Sometimes. It can be slow to raise.\""), .direct("What do you do at the hospital?", "\"I am a security guard. I walk the garage all shift and respond to calls from drivers who have trouble at the exits.\""), .direct("What problems has that arm had?", "\"It sometimes comes down slowly and stays down if the payment system lags. We had it serviced about two weeks before that day.\""), .direct("Have you seen drivers hit it?", "\"Yes, a couple of times a year, usually when it lags and a driver loses patience with a line of cars behind.\""), .cross("Was it stuck that afternoon?", "\"I wasn't there. I don't know.\""), .cross("Did the machine decline {DL}'s card?", "\"I'm told so. I didn't see it.\""), .cross("Could the arm raise after a decline?", "\"No. It raises after payment. A decline leaves it down.\""), .cross("Were you at the exit that afternoon?", "\"No. I was working on another level of the garage and only learned about the broken arm from the manager afterward.\""), .cross("Does a declined card raise the arm?", "\"No. It only lifts after a successful payment goes through, so a declined card leaves the arm down until someone opens it.\"")],
        theory: ("{D} drove through a gate over a declined card.", "The arm was stuck and a car was behind {D}."),
        allocution: "\"I put people in danger and I'm sorry.\"",
        truths: ("{DL} had no other way to pay and drove through on purpose.", "The arm was sluggish and had been repaired recently."),
        defendant: [.direct("Why did you drive through the gate arm?", "\"My card was declined twice, and the arm was stuck down. A car was behind me, and I panicked.\""), .direct("Did you try to pay?", "\"Yes, twice. The machine rejected my card. I didn't have another way to pay on the spot.\""), .direct("Did you mean to break it?", "\"No. I thought it would lift or give way. I never meant to damage it.\""), .direct("Why were you at the hospital?", "\"I was visiting a family member who had surgery. I stayed longer than planned and was upset.\""), .direct("What happened at the exit?", "\"My card was declined twice. A car was behind me, and the arm did not lift. I did not want to hold up the line.\""), .direct("What did you do?", "\"I pressed the help button and nobody answered. I eased forward thinking the arm would give way.\""), .cross("The arm snapped when you drove into it, didn't it?", "\"Yes. I am truly sorry. I didn't think it would break.\""), .cross("Your card was declined, wasn't it?", "\"Yes. I couldn't pay. I should have asked for help.\""), .cross("The arm raised for the previous car, didn't it?", "\"I didn't see that. It stayed down for me.\""), .cross("You drove into the arm on purpose. Isn't that damage by choice?", "\"I did not choose to break it. I was stressed and thought it would tip up.\""), .cross("Why not back up and call for help?", "\"A car was behind me and I panicked. In hindsight, I should have waited.\"")],
        openings: ("At a hospital garage exit, the machine declined {D}'s card twice, and at 3:08 {D} drove forward and snapped the gate arm, a $520 replacement. The exit camera shows it. The State will show the video and the machine log.", "Jurors will also see an arm that had been sluggish and serviced two weeks earlier, a card that was declined, and a driver who panicked with a car behind."),
        closings: ("Two declined cards, a car driven into a gate arm, and $520 in damage. {D} chose to drive through rather than pay.", "A declined card, a stuck arm, and a driver who panicked. The State has not proved {D} meant to break the gate."),
        timeline: [(0, "3:05 p.m.: the first card decline."), (0, "3:08 p.m.: the arm snaps."), (0, "3:15 p.m.: the manager reports it."), (2, "The operator prices the repair.")],
        identified: "The exit camera and the plate identify {D}.",
        notDone: ["The gate arm's motor was never tested after the break.", "The previous driver's passage was never reviewed for lag."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let wifiBorrowV1 = SmallCases.make(
        key: "story.wifiBorrow",
        category: .cyber,
        headlines: ["Fired Employee's Login Still Works, Customer List Copied After Termination", "Audit Log Shows Download From Home Address Two Days After Layoff"],
        law: "accessingComputers",
        spec: "Accessed a computer network of {V}, a former employer, without authority and copied customer files, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} was laid off from a small distribution company on a Friday and told to return the laptop. On {DATE}, two days later, a login under {D}'s name opened the company's shared drive from {D}'s home address and copied a customer list and price file. The company had not yet disabled the account. {D} says the login still worked and {D.he} wanted personal files.",
        state: [E(.digital, 3, "Audit Log", "A login under {D}'s name from {D}'s home address at 9:40 p.m. two days after the layoff."), E(.digital, 3, "Download Record", "A customer list and a price file copied to a personal drive."), E(.document, 2, "Termination Letter", "A letter ending {D}'s access on Friday."), E(.statement, 2, "IT Manager", "The account was scheduled for deactivation on Monday.")],
        defense: [E(.statement, 1, "Login Worked", "{DL} says the login still worked and {D.he} only wanted personal files."), E(.document, 1, "Personal File List", "A list of family photos stored in a folder on the drive.")],
        role: "Company IT manager",
        exam: [.direct("What did your audit log show?", "\"A login under {D}'s name from {D}'s home address at 9:40 p.m., two days after the layoff. It opened the company's shared drive.\""), .direct("What was copied?", "\"A customer list and a price file, copied to a personal drive. The download record shows both.\""), .direct("Why was the account still working?", "\"It was scheduled for deactivation on Monday. {D} was laid off Friday, and the termination letter ended {D}'s access that day, but the system lagged.\""), .direct("What was the status of the account?", "\"Scheduled for deactivation Monday. A termination letter on Friday ended {D}'s access in writing.\""), .direct("How did you find out someone had logged in after the layoff?", "\"The nightly report flagged an unusual login from a home address. I checked the time and the user name, and it was {D}'s account at 9:40 p.m.\""), .direct("What did you do after you saw the files had been copied?", "\"I disabled the account at once, saved the logs, and told the owner. We then checked what else had been opened from that session.\""), .cross("{D} says the login still worked and {D.he} wanted personal files, doesn't {D.he}?", "\"Yes. The login did work. And personal photos were on the shared drive, which I will agree with.\""), .cross("Did {D} copy anything beyond the customer list and price file?", "\"The record shows those two files. I do not know about others.\""), .cross("Did anyone tell {D} not to log in?", "\"The letter ended access. It did not say anything about what would happen on the weekend.\""), .cross("Did {D} copy anything beyond those files?", "\"The record shows those two. I did not see anything else.\""), .cross("Was the login still working?", "\"Yes. We had not turned it off. That was our oversight.\"")],
        defenseRole: "Former coworker",
        defenseExam: [.direct("Was your account still active after your layoff?", "\"Mine worked for a week. It was the same for others who left, so {D}'s still working was not unusual.\""), .direct("Did you copy any files from the drive after you left?", "\"No. I did not copy anything. I logged in once to get my own photos and then left it alone.\""), .direct("Did {D} need personal photos from the shared drive?", "\"They were on the shared drive. Many of us stored personal photos there because it was easy.\""), .direct("How long did you work with {D}?", "\"Four years. We both stored personal files on the shared drive because it was handy.\""), .direct("Was your own login active after you left?", "\"Mine worked for a week. That is how our system handled departures.\""), .direct("What kind of person is {D}?", "\"Quiet and hardworking. I never saw {D} take anything that was not {D}'s.\""), .cross("Did you see {D} copy the customer list?", "\"No. I did not see that. I was not with {D} when any copying took place.\""), .cross("Would a person copying personal photos also copy a customer list?", "\"Not on purpose. But a bulk copy can pick up a folder by accident.\""), .cross("Did {D} talk about a competitor?", "\"I heard {D} had talked to one after the layoff. I do not know details.\""), .cross("You never watched {D} copy any files, did you?", "\"No. I was not there. I only know the account still worked after the layoff, because mine did too.\""), .cross("You do not know what {D} meant to copy, do you?", "\"I know {D} wanted personal photos. I cannot tell you what else was copied or why the customer list went along with them.\"")],
        theory: ("{D} copied company files after being cut off.", "{D} used a working login for personal files."),
        allocution: "\"I'm sorry, and I'll stay away from it.\"",
        truths: ("{DL} had told a competitor the customer list was 'coming.'", "The photos were real and the customer list was copied by accident."),
        defendant: [.direct("Did you copy the customer list and price file?", "\"I copied files from the shared drive, and that included them, but I only meant to get my personal files.\""), .direct("Why did you log in from home?", "\"I was laid off and wanted my photos and personal documents. The login still worked, and I did not think it was wrong.\""), .direct("How did the customer list get copied?", "\"By accident. I copied a whole folder, and the list and the price file were in it.\""), .direct("Why did you log in after the layoff?", "\"I wanted family photos stored on the shared drive. I had no other copy and was afraid they would be deleted.\""), .direct("How did you copy the files?", "\"I highlighted a whole folder and dragged it to my drive. I did not look at what was inside.\""), .direct("What did you do when you noticed?", "\"I saw the customer list in the folder later and was alarmed. I meant to delete it but did not.\""), .cross("You told a competitor the customer list was 'coming,' didn't you?", "\"I said something like that in a text. It was careless. I did not follow through.\""), .cross("Your access was supposed to end Friday, wasn't it?", "\"Yes, by the letter. I knew. But the login still worked.\""), .cross("Why copy the files at 9:40 p.m. on a weekend?", "\"Because I was home and had the time. I did not think about the hour.\""), .cross("You wrote to a competitor that the list was 'coming.' What did you mean?", "\"It was a bad joke in a text. I had not planned to send it.\""), .cross("You knew your access had ended. Why log in anyway?", "\"The login still worked, and I told myself the photos were mine. I should have asked.\"")],
        openings: ("{D} was laid off on a Friday and told that access had ended. Two days later at 9:40 p.m., a login under {D}'s name from {D}'s home opened the company's shared drive and copied a customer list and a price file.", "The defense case is that the login still worked, that personal photos were on the drive, and that the customer list was copied by accident with a folder."),
        closings: ("A layoff letter ending access, a login from {D}'s home two days later, and a customer list and price file on a personal drive. {D} had told a competitor the list was coming.", "The account still worked, and {D} went in for personal photos. A folder copied by accident is not a theft of trade secrets, and the State must prove intent."),
        timeline: [(0, "Friday: {D} is laid off."), (2, "9:40 p.m.: the login and download."), (3, "Monday: the account is disabled."), (4, "The company reviews the log.")],
        identified: "The audit log identifies {D}.",
        notDone: ["The IT manager never disabled the account at termination.", "The downloaded files were never shown to have been used."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let curbCouchV1 = SmallCases.make(
        key: "story.curbCouch",
        category: .property,
        headlines: ["Patio Set Priced for Sale on Front Lawn Loaded Into Truck", "Doorbell Camera Shows Two People Carry Away Listed Furniture"],
        law: "misdLarceny",
        spec: "Stole property of {V}, valued at $350, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} set a patio table and four chairs by the road on {DATE} with a sign saying 'Sold, pickup 5 p.m.' A buyer was due at five. At 3:45 p.m. {D} and a friend loaded the set into a pickup and left. {V}'s doorbell camera recorded the plate. {D} says furniture at the curb is free.",
        state: [E(.video, 3, "Doorbell Camera", "Two people load a patio table and four chairs into a pickup at 3:45 p.m."), E(.document, 2, "Marketplace Listing", "The set listed at $350 and marked sold."), E(.statement, 2, "Buyer", "Arrived at 5 p.m. to find the set gone."), E(.physical, 1, "Sign", "A 'Sold, pickup 5 p.m.' sign lying face-down in the grass.")],
        defense: [E(.statement, 1, "Curb Rules", "{DL} says furniture left by the road is free."), E(.document, 1, "City Code", "A city page about bulk pickup by the curb.")],
        role: "Homeowner",
        exam: [.direct("What did you set out on {DATE}?", "\"A patio table and four chairs, with a sign saying 'Sold, pickup 5 p.m.' I'd listed them for $350 and marked them sold.\""), .direct("What happened at 3:45?", "\"Two people loaded the set into a pickup and left. My doorbell camera recorded it, along with the plate.\""), .direct("What happened with the buyer?", "\"The buyer arrived at 5 and found the set gone. The sign was lying face-down in the grass.\""), .direct("Why did you put the set by the road?", "\"Because the buyer was coming from out of town and wanted to load it without disturbing the house. I listed it at $350 and marked it sold.\""), .direct("What did the sign say and where did you put it?", "\"'Sold, pickup 5 p.m.' I leaned it against the table. Later I found it lying face-down in the grass.\""), .direct("What did the doorbell camera show?", "\"At 3:45 two people loading the table and chairs into a pickup. The camera caught the plate as the truck pulled away.\""), .cross("{DL} says furniture left by the road is free, doesn't {D.he}?", "\"Many people think so. But mine was sold, with a sign.\""), .cross("Was the sign easy to see?", "\"I put it up. It was on the ground by the time. I can't say how it looked from the street.\""), .cross("Did you tell anyone not to take it?", "\"The sign did. I didn't speak to {D}. I was inside.\""), .cross("Could the sign have fallen before {D} arrived?", "\"It might have. It was windy that day. I cannot say when it went down.\""), .cross("Did you ever tell {D} the set was sold?", "\"No. I never spoke to {D}. The first I knew was when I checked the camera.\"")],
        defenseRole: "Friend who helped load",
        defenseExam: [.direct("Did you help {DL} load the set?", "\"Yes. We saw it by the curb and loaded it into the pickup.\""), .direct("Did you see a sign?", "\"No. I didn't see one. It was just a set at the curb.\""), .direct("What did {DL} say?", "\"That it looked free. Curb furniture usually is. I agreed.\""), .direct("How do you know {D}?", "\"We are friends and I help with moving. {D} called me that afternoon about some free patio furniture.\""), .direct("What did the curb look like?", "\"A table and four chairs side by side, only a few feet from the road, with nobody around to ask about them.\""), .direct("Did you see any note on the set?", "\"No. If a sign was there, I did not see it, and we would not have taken the set if we had read one.\""), .cross("Did you look around for a sign?", "\"Not really. We saw the furniture and acted.\""), .cross("Did you know it was listed?", "\"No. I'd have walked away if I had.\""), .cross("Did you take anything else?", "\"No. Just the table and chairs.\""), .cross("Did you walk around the property?", "\"No. We went straight to the curb and loaded up. Looking back, we should have looked around more carefully first.\""), .cross("Did you hear {D} say the set was listed?", "\"No. {D} never mentioned a listing.\"")],
        theory: ("{D} took a priced set from a lawn.", "{D} thought it was curb furniture."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had seen the listing on the marketplace before driving by.", "The sign blew over in the wind that morning."),
        defendant: [.direct("Why did you take the patio set?", "\"It was at the curb, and I thought it was free. I loaded it with a friend. I didn't see any sign.\""), .direct("Did you read a sign?", "\"No. I never saw one. If I had, I'd have left it.\""), .direct("Did you try to hide?", "\"No. I drove up in a pickup in broad daylight. My friend helped load it.\""), .direct("How did you come across the furniture?", "\"I was driving home and saw a patio set at the curb. It looked clean and I know people put free things out that way.\""), .direct("What did you do?", "\"I called a friend and we pulled over, loaded the pickup, and drove off. It took about ten minutes.\""), .direct("What happened when you learned it was sold?", "\"I felt terrible. I offered to bring it back and pay for any trouble.\""), .cross("The set was listed at $350, wasn't it?", "\"I didn't know. I thought it was a giveaway.\""), .cross("The sign was in the grass, wasn't it?", "\"I've heard so. I didn't see it.\""), .cross("The doorbell camera caught your plate, didn't it?", "\"Yes. I wasn't hiding. I'd never have driven my own truck if I thought it was theft.\""), .cross("You never knocked or looked for an owner. Why?", "\"Because furniture at a curb is usually free. I did not think anyone had sold it.\""), .cross("You saw the listing online before driving by, didn't you?", "\"I had browsed the marketplace, but I did not connect that set to the curb. I did not see a sign.\"")],
