        state: [E(.physical, 3, "Altered Vouchers", "Four vouchers with printed amounts changed from $5 to $100 over the original ink."), E(.digital, 3, "Kiosk Log", "Four redemptions between 9:30 and 9:34 p.m. and $400 dispensed."), E(.video, 2, "Cage Camera", "{D} feeds the vouchers one at a time into the kiosk."), E(.statement, 2, "Casino Auditor", "The audit found the system value of each voucher was $5.")],
        defense: [E(.statement, 1, "From a Machine", "{DL} says the vouchers came from a slot machine and were already marked."), E(.document, 1, "Slot Payout Log", "A machine payout of $20 at 8:50 p.m. to a player's card.")],
        role: "Casino auditor",
        exam: [.direct("What did your audit find on {DATE}?", "\"Four vouchers redeemed at a kiosk between 9:30 and 9:34 for $400. The printed amounts had been changed from $5 to $100 over the original ink.\""), .direct("What did the system show?", "\"The system value of each voucher was $5. The barcodes matched real tickets, but the printed amounts were altered.\""), .direct("How did the audit find the problem?", "\"Four redemptions in four minutes totaling $400 triggered a review. The system value of each voucher was $5, not $100.\""), .direct("What did the vouchers look like?", "\"The printed amounts showed $100 written over the original $5 with different ink and thicker strokes. The barcodes matched real tickets.\""), .direct("What does the cage camera show?", "\"{D} feeding the vouchers into the kiosk one at a time between 9:30 and 9:34 and collecting $400.\""), .direct("How did you confirm the voucher amounts were not what the system showed?", "\"I printed the system values for each barcode and laid the vouchers beside them. The printed amounts were $100, but each one was $5 in the system.\""), .cross("{DL} says the vouchers came from a machine, doesn't {D.he}?", "\"A machine payout log shows $20 at 8:50 to a player's card. That's not four vouchers.\""), .cross("Did {DL} alter the vouchers?", "\"I don't have a witness to that. I have the altered vouchers and the camera.\""), .cross("Could a machine print them already marked?", "\"I don't think so. A machine wouldn't print $100 over $5 ink.\""), .cross("Did a machine print one of the vouchers incorrectly that night?", "\"A payout log shows a $20 payout around 8:50. I do not see a misprint with those amounts.\""), .cross("Can you say who altered the vouchers?", "\"No. I only know the amounts were changed from the system value.\"")],
        defenseRole: "Slot machine technician",
        defenseExam: [.direct("Do you service the slot machines?", "\"Yes. I'm a technician. I know how they print vouchers.\""), .direct("Did a machine pay out at 8:50?", "\"Yes. A $20 payout to a player's card. It's in the log.\""), .direct("Can machines print vouchers wrong?", "\"Sometimes. A printer can misalign or smudge. It happens.\""), .direct("What do you do at the casino?", "\"I am a slot technician. I repair voucher printers and bill acceptors on the casino floor every day.\""), .direct("What kinds of problems do the voucher printers have?", "\"Smudging and misalignment are the common ones. A printer can print a faint or doubled number.\""), .direct("Do printers ever print a different amount than the system value?", "\"No. The printer prints the system's value. If the number is wrong, it is not from the machine.\""), .cross("Can a machine print $100 over $5 ink?", "\"No. That would not be a machine error. Someone would have to write over it.\""), .cross("Can you say where {DL} got them?", "\"No. I only know the machine log.\""), .cross("Did you inspect these vouchers?", "\"Yes. The amounts looked changed, with fresh ink drawn over the original printed numbers.\""), .cross("Could a machine make four such errors in a row?", "\"No. That would be nearly impossible, and I have never seen a printer repeat that kind of mistake four times.\""), .cross("A machine would not print a voucher in a different ink over a lower amount, would it?", "\"No. A printer prints one amount in one ink. A change over the original number would not come from the machine.\"")],
        theory: ("{D} altered vouchers and cashed them.", "{D} cashed vouchers from a machine."),
