        theory: ("{D} had controlled pills labeled for someone else.", "{D} was picking up pills for a relative."),
        allocution: "\"I have a problem and I need help.\"",
        truths: ("{DL} had taken some of the tablets that week.", "The relative's text was real and the pills were meant for the relative."),
        defendant: [.direct("Why did you have someone else's prescription?", "\"A relative asked me to pick them up to be delivered. I had not delivered them yet.\""), .direct("Whose pills were they?", "\"My relative's. The prescription was filled three days earlier, and I was holding them to deliver.\""), .direct("Did you take any of the tablets?", "\"I took a couple for a sore back. I should not have. It was foolish.\""), .direct("Explain to the jury how you came to pick up the prescription.", "\"My relative texted that a clinic visit left no time to get to the pharmacy. I agreed to pick it up on my way.\""), .direct("What did you do with the pills after that?", "\"I put the bottle in my console and meant to deliver it that evening. Then work ran long, and a few days went by.\""), .direct("Why did you take some of the tablets?", "\"I had a sore back and thought one or two would not matter. I know it was wrong.\""), .cross("Fourteen hydrocodone tablets in your console with another person's name. Why not deliver them sooner?", "\"I was busy. I told myself I would do it later.\""), .cross("You took some of the tablets, didn't you?", "\"Yes. I did. I regret it deeply.\""), .cross("You do not have a prescription for hydrocodone, do you?", "\"No. I do not. I know I should not have taken any.\""), .cross("You do not have a prescription for hydrocodone. Why take them?", "\"Because I was in pain and made a bad call. I should have taken my own medicine.\""), .cross("Fourteen tablets in your console three days after pickup. Why not deliver at once?", "\"I kept putting it off. I should have driven straight over.\"")],
        openings: ("A deputy stopped {D}'s pickup in a clinic lot after a tailgating complaint and found a prescription bottle labeled for someone else, with fourteen hydrocodone tablets, in the console. The prescription had been filled three days earlier.", "Weigh the defense proof, which will show that a relative asked {D} to pick up the pills, that the relative confirms it, and that {D} told the deputy right away."),
        closings: ("Fourteen hydrocodone tablets in a bottle labeled for someone else, in {D}'s console, three days after the prescription was filled. {D} had taken some.", "A relative's text, a relative's prescription, and a driver who was honest with a deputy. The State must prove knowing possession, and a favor for a relative is not that."),
        timeline: [(-3, "The pharmacy fills the prescription."), (0, "4:30 p.m.: the deputy stops {D}."), (0, "4:42 p.m.: the bottle is found."), (14, "The lab reports hydrocodone.")],
