        summary: "{D} tried on a pair of hiking boots at an outdoor store at 11 a.m. on {DATE} and left a pair of old sandals on the fitting bench. At 11:25 a.m., {D} walked out through the garden center door still wearing the boots. The boots cost $240. {D} says {D.he} meant to pay and forgot to take the sandals out of the box.",
        state: [E(.video, 3, "Rear Exit Camera", "{D} walks out the garden door in the new boots at 11:25 a.m."), E(.physical, 2, "Left Sandals", "A worn pair of sandals left on the fitting bench with no receipt."), E(.document, 2, "Price Tag", "A $240 tag on the display boot."), E(.statement, 2, "Store Clerk", "Saw {D} try on the boots and lost sight of {D.him}.")],
        defense: [E(.statement, 1, "Forgot to Pay", "{DL} says {D.he} meant to pay and forgot."), E(.document, 1, "Card Statement", "A $240 pending charge at a store down the street that evening.")],
        role: "Store clerk",
        exam: [.direct("What happened at 11:25?", "\"{D} walked out through the garden center door still wearing the boots. I had lost sight of {D}.\""), .direct("What were the boots worth?", "\"$240. The tag was on the display boot.\""), .direct("What did you see at the boot display?", "\"{D} picked a pair of hiking boots, sat on the fitting bench, and put them on. I helped with sizes and moved to another customer.\""), .direct("What did {D} leave behind?", "\"A worn pair of sandals on the bench with no receipt. I assumed {D} was still shopping.\""), .direct("How did you realize the boots were gone?", "\"The garden door alarm chirped at 11:25. The camera showed {D} walking out in the new boots through the garden center.\""), .direct("What did you do when you saw {D} head toward the garden door?", "\"I called out that the boots were not paid for, but {D} was already through the door and heading to the lot.\""), .cross("{D} says {D.he} meant to pay and forgot, doesn't {D.he}?", "\"Yes. {D} came back the next day with the money, I understand.\""), .cross("Did {D} go to a register?", "\"No. {D} went straight out the garden door.\""), .cross("Were the price tags cut?", "\"I heard the tags were removed in the fitting room. I did not see that.\""), .cross("Did {D} try to run?", "\"No. {D} walked out at a normal pace and did not look around.\""), .cross("Did you stop {D} at the door?", "\"No. I was at the front. I saw the camera later.\"")],
        defenseRole: "Companion shopper",
        defenseExam: [.direct("Did {D} plan to pay for the boots?", "\"Yes. {D} said so in the aisle, and said we would head to the register after trying them.\""), .direct("Why did {D} go out the garden door?", "\"It was nearest to the car. {D} was in a hurry, and I think {D} was thinking about the car.\""), .direct("Did {D} cut the tags?", "\"I did not see that. I was looking at other items.\""), .direct("How long have you known {D}?", "\"Several years. We often shop together, and I was with {D} that morning.\""), .direct("What did {D} say about the boots?", "\"That they would be perfect for the trip and that {D} planned to pay at the register.\""), .direct("What happened when the call came?", "\"{D} stepped toward the garden door to hear better. I stayed to look at jackets.\""), .cross("Did {D} go to the register at any point?", "\"No. {D} did not. {D} walked out with the boots on.\""), .cross("Did you tell {D} to stop?", "\"No. I did not know until later. I thought we were still shopping.\""), .cross("Did {D} come back to the store?", "\"Yes. {D} came back the next day with the money.\""), .cross("Did you see {D} leave the building?", "\"No. I was inside looking at jackets.\""), .cross("Did {D} ever mention the boots again?", "\"Only that evening, when {D} called in a panic about going back to pay.\"")],
        theory: ("{D} walked out in new boots.", "{D} forgot to pay."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had taken off the price tags in the fitting room.", "{DL} came back the next day with the money."),
        defendant: [.direct("Did you walk out wearing the store's boots?", "\"Yes. I meant to pay and forgot. I was distracted, and I walked out the garden door.\""), .direct("Why did you leave your old sandals?", "\"I left them on the bench when I tried on the boots. I forgot to take them.\""), .direct("Did you come back?", "\"Yes. I came back the next day with the money. I felt terrible.\""), .direct("Why did you try on the boots?", "\"I needed a pair for a hike that weekend. I liked these and wore them around the store for a few minutes.\""), .direct("What happened then?", "\"My phone rang and I walked outside to take the call. I forgot I was still wearing them.\""), .direct("How did you realize?", "\"At home that evening when I took off my socks. I felt sick and decided to pay the next day.\""), .cross("You took off the price tags in the fitting room, didn't you?", "\"I did. I wanted to see how they looked. I did not mean to hide anything.\""), .cross("You walked past registers, didn't you?", "\"The garden door was closer. I was not thinking.\""), .cross("The clerk lost sight of you. Isn't that because you left?", "\"I did leave. I did not try to dodge anyone.\""), .cross("The price tags were off before you left the fitting room. Why?", "\"I took them off to see how they fit. I should have left them on.\""), .cross("You walked out a back door instead of past a register. Why?", "\"It was closest to my car. I was on the phone and did not think about it.\"")],
        openings: ("{D} tried on hiking boots worth $240 and left old sandals on the fitting bench. At 11:25, {D} walked out the garden center door still wearing the boots, past the registers.", "Jurors will hear that {D} meant to pay and forgot, left the old sandals behind, and returned the next day with the money."),
        closings: ("Boots worn out the garden door, tags removed, and no stop at a register. The sandals left behind do not pay for $240 of boots.", "A forgetful shopper who came back the next day with the money. The State must prove {D} meant to leave without paying, and a return is strong evidence against that."),
        timeline: [(0, "11 a.m.: {D} tries on the boots."), (0, "11:25 a.m.: {D} leaves by the garden door."), (0, "11:30 a.m.: the clerk finds the sandals."), (1, "The store sends the camera video.")],
        identified: "The rear exit camera identifies {D}.",
        notDone: ["The store's tag cutter was never checked for who used it.", "{DL}'s next-day return was never confirmed by staff."],
