        state: [E(.physical, 3, "Sticker", "A photocopy with faint halftone dots and an altered month."), E(.document, 3, "Inspection Record", "The number was issued to a different vehicle in another county."), E(.video, 2, "Dash Camera", "The trooper scrapes at the sticker and it peels off a clear sleeve."), E(.document, 2, "Stop Report", "Notes the sticker was held in a clear plastic sleeve.")],
        defense: [E(.statement, 1, "Car Wash", "{DL} says {D.he} bought the sticker from an attendant at a car wash for $20."), E(.document, 1, "Car Wash Receipt", "A $20 receipt from a car wash dated the week before.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("Why did you stop {DL} at 8:15 a.m. on {DATE}?", "\"The inspection sticker on the windshield looked flat and had faint dots at the edge. I scraped at it on my dash camera and it peeled off a clear plastic sleeve.\""), .direct("What was the sticker?", "\"A photocopy of a real sticker with the month altered. The faint halftone dots are what you see in a copy.\""), .direct("What did the number show?", "\"It was issued to a different vehicle in another county. That's in the inspection record.\""), .direct("What did you notice about the sticker?", "\"It looked flat and had faint dots around the edge, which a real sticker does not. I stopped the car and checked it.\""), .direct("How did you confirm it was fake?", "\"I peeled at the edge and the sticker came away from a clear plastic sleeve. It was a photocopy with the month changed.\""), .direct("What did the inspection record show?", "\"The number was issued to a different car in another county. This car had no valid inspection.\""), .cross("{DL} says {D.he} bought it from a car wash attendant, doesn't {D.he}?", "\"There's a $20 car wash receipt from the week before. It doesn't mention a sticker.\""), .cross("Could a driver see it was a copy?", "\"It looked real at a glance. I noticed it because it was flat. Most drivers wouldn't notice.\""), .cross("Did you find a copier in {D}'s car?", "\"No. I found only the sticker and the sleeve. I did not search for printing equipment.\""), .cross("Did {D} explain where the sticker came from?", "\"Yes. {D} said an attendant at a car wash sold it for $20. A $20 receipt from a car wash the week before supports a visit.\""), .cross("The sticker looked real from a distance, didn't it?", "\"From a few feet, yes. Up close, the dots and the sleeve gave it away, and that is how I found it.\"")],
        defenseRole: "Car wash attendant",
        defenseExam: [.direct("Do you work at the car wash?", "\"Yes. I'm an attendant. I handle customers' cars and payments.\""), .direct("Did {DL} come in the week before?", "\"Yes. {D} paid $20 for a wash. I have the receipt.\""), .direct("Did you sell {DL} a sticker?", "\"I don't remember anything like that. We do washes.\""), .direct("What is your job at the car wash?", "\"I wash and dry cars, take payments, and keep an eye on the lot. I have worked there for about two years now.\""), .direct("What do you recall about {D}?", "\"{D} came in the week before for a wash, paid $20, and left in a hurry. I do not remember anything else about the visit.\""), .direct("Does the car wash handle stickers?", "\"No. We are not an inspection station, and we have never advertised anything of the kind to customers.\""), .cross("Does the car wash sell inspection stickers?", "\"Not officially. We aren't an inspection station.\""), .cross("Did you hand {DL} anything else?", "\"I'd have to check. I give out receipts and air fresheners.\""), .cross("Could someone have sold {DL} one on the side?", "\"I can't say. I'm not going to guess.\""), .cross("Did you ever sell stickers on the side?", "\"I would rather not say. All I can tell you for certain is that our job is washing cars.\""), .cross("Could another employee have sold one?", "\"I cannot rule it out. Other attendants come and go all day, and I do not watch what each one does.\"")],
        theory: ("{D} displayed a copied sticker.", "{D} bought a sticker from a car wash."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} had a color copier at home.", "The car wash attendant really did sell stickers on the side."),
        defendant: [.direct("Where did you get the sticker?", "\"From a car wash attendant. I paid $20 and the attendant said it was an inspection sticker I could put on my car.\""), .direct("Did you copy a sticker?", "\"No. I never made one. I bought what was handed to me. I thought it was real.\""), .direct("Why was it in a plastic sleeve?", "\"That's how it was sold. I stuck the sleeve to the glass. I didn't think much about it.\""), .direct("Why did you need a sticker?", "\"My inspection was overdue and I had not had time to get the car checked. The wash attendant said a sticker could be arranged.\""), .direct("What did you pay?", "\"$20 in cash to an attendant. I got a sticker in a clear sleeve and put it on the windshield.\""), .direct("What did you think when the trooper stopped you?", "\"I thought it was a routine stop. I was shocked when the trooper said the sticker was fake.\""), .cross("The number was issued to a different car, wasn't it?", "\"That's what they say. I didn't check the number.\""), .cross("$20 for an inspection sticker is cheap, isn't it?", "\"Yes. I thought it was a bargain. I should have gone to a station.\""), .cross("You never had the car inspected, did you?", "\"No. I didn't. That is on me.\""), .cross("You skipped a real inspection for a $20 sticker. Why?", "\"I thought it was a shortcut that was legitimate. I should have gone to a station.\""), .cross("You did not check the number on the sticker. Did that not bother you?", "\"No. I did not look. I trusted what I was given.\"")],
        openings: ("A trooper stopped {D} because the inspection sticker looked flat with faint dots at the edge. It was a photocopy with an altered month, and its number belongs to a different car in another county. The State will show the sticker and the record.", "Jurors will also see a driver who paid $20 to a car wash attendant for what {D} believed was a real sticker, and who never copied anything."),
        closings: ("A photocopied sticker in a plastic sleeve, an altered month, and a number from another car. The trooper saw it was not real.", "{D} paid $20 at a car wash and trusted what was sold. The State has not proved {D} knew the sticker was a copy."),
        timeline: [(0, "8:15 a.m.: the trooper stops {D}."), (0, "8:25 a.m.: the sticker peels off the sleeve."), (0, "8:30 a.m.: the number check returns."), (2, "The inspection office confirms the number was issued elsewhere.")],
        identified: "The trooper found the sticker on {D}'s car.",
        notDone: ["The car wash attendant was never identified.", "The copy machine at the car wash was never checked."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

