        role: "Resident",
        exam: [.direct("What happened with your packages on {DATE}?", "\"Two packages addressed to me arrived at the front desk. At 2:10 p.m., {D} told the clerk {D.he} was my roommate and signed for them.\""), .direct("Do you have a roommate?", "\"No. I live alone. I have never had a roommate named {D}.\""), .direct("What was in the packages?", "\"$450 in goods across two orders. The desk log shows a signature that does not match mine.\""), .direct("What did you expect that afternoon?", "\"Two packages of clothes and kitchen gear I had ordered. The tracking said they were delivered to the front desk at 1:30.\""), .direct("What happened when you went to pick them up?", "\"The desk clerk said they had been signed for at 2:10. The signature was not mine.\""), .direct("How did you find out who took them?", "\"The lobby camera shows {D} signing and carrying two boxes to the elevator. {D} told the clerk {D} was my roommate.\""), .cross("{DL} says you asked {D.him} to pick them up, doesn't {D.he}?", "\"I never asked. I don't know {D} well.\""), .cross("Did you ever text {DL} about a package?", "\"Two weeks before, I may have texted about a different package. I don't recall the details.\""), .cross("Did you see {DL} take them?", "\"No. I saw it on the lobby camera later. I wasn't home.\""), .cross("Do you know {D}?", "\"Only as a neighbor in the building. We have said hello but never been close.\""), .cross("You never told {D} to sign for anything, did you?", "\"No. I have no roommate and I never asked anyone to pick up a package. If I had, I would have told the front desk.\"")],
        defenseRole: "Relief desk clerk",
