        defenseRole: "Gas station attendant",
        defenseExam: [.direct("Do you work at the gas station?", "\"Yes. I'm an attendant. I was there that morning.\""), .direct("Did you see {DL}?", "\"I saw {D} at the pump after another customer left. {D} picked something up.\""), .direct("Did {DL} say anything?", "\"Not to me. I saw {D} write on a receipt.\""), .direct("What is your job?", "\"I work the counter and pumps at a gas station. I see a lot of customers come and go.\""), .direct("What do you remember about that morning?", "\"A customer filled at the pump and left. Right after, another person pulled in and picked something up from the ground.\""), .direct("What did the second person do?", "\"Wrote something on a slip of paper and put it in a pocket. I did not see what happened next.\""), .cross("Did you see what {DL} picked up?", "\"I assumed a card. I can't say for sure.\""), .cross("Did you see {DL} use it?", "\"No. The convenience store is separate. I didn't go there.\""), .cross("Did {DL} turn it in?", "\"Not to me. I don't recall that.\""), .cross("Did you see the card?", "\"I assumed it was a card. I did not see it up close.\""), .cross("Did {D} come inside?", "\"No. {D} drove off. I did not hear from {D}.\"")],
