    static let coopChickensV1 = SmallCases.make(
        key: "story.coopChickens",
        category: .property,
        headlines: ["Four Show Hens and a Rooster Taken From 4-H Barn", "Leg Bands Match Birds Found in Truck Bed"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a 4-H member, valued at $420, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} kept four show hens and a rooster in a barn for a county fair on {DATE}. The barn door was latched at 8 p.m. and found open at 6 a.m., and the birds were gone. A trail camera shows a pickup at the gate at 2:15 a.m. Deputies found the birds in {D}'s truck bed two days later with their leg bands. {D} says {D.he} bought them at an auction.",
        state: [E(.physical, 3, "Leg Bands", "Five birds with leg bands registered to {V} in {D}'s possession."), E(.video, 2, "Trail Camera", "A pickup at the barn gate at 2:15 a.m. with the plate partly visible."), E(.document, 2, "Show Registry", "Band numbers registered to {V} for the fair."), E(.statement, 2, "{V}", "Latched the barn and found it open at 6 a.m.")],
        defense: [E(.statement, 1, "Auction Buy", "{DL} says the birds were bought at a poultry auction on the weekend."), E(.document, 1, "Auction Flyer", "A flyer for a poultry auction two counties away.")],
        role: "4-H member",
        exam: [.direct("What did you keep in the barn?", "\"Four show hens and a rooster, for the county fair. I latched the barn door at 8 p.m. on {DATE}.\""), .direct("What did you find in the morning?", "\"The door open at 6 a.m. and the birds gone. My trail camera shows a pickup at the barn gate at 2:15, with the plate partly visible.\""), .direct("How were your birds found?", "\"Deputies found five birds with leg bands registered to me in {D}'s truck bed two days later. The show registry lists those band numbers.\""), .direct("How did you prepare the birds for the fair?", "\"I raised them from chicks, washed and groomed them, and registered each with a numbered leg band. I kept them in the barn.\""), .direct("How do you know which hens in the truck bed were yours?", "\"Each band has a number registered to me at the fair. I read the numbers off the legs and they matched my entry list.\""), .direct("What had you done to prepare the birds for the fair?", "\"I had washed, trimmed and fed them for weeks, and I had them ready for judging. They were my best hens in years.\""), .cross("{DL} says {D.he} bought the birds at an auction, doesn't {D.he}?", "\"There was a poultry auction two counties away. But my birds' bands are on file.\""), .cross("Could the bands have been copied?", "\"I don't think so. Each band is a registered number. They matched mine.\""), .cross("Can you identify the pickup's driver?", "\"No. The camera shows a pickup and a partial plate. It doesn't show a face.\""), .cross("How do you know the bands are yours?", "\"Each has a number recorded in the show registry for me. The numbers match the birds found.\""), .cross("Could someone have bought them legitimately?", "\"I did not sell them. If someone bought them, it was from a thief.\"")],
        defenseRole: "Poultry auction seller",
        defenseExam: [.direct("Do you sell at poultry auctions?", "\"Yes. I sell birds at a weekend auction two counties away.\""), .direct("Did {DL} buy birds?", "\"Yes. {D} bought some at my auction. I remember {D} bidding.\""), .direct("Did the birds have bands?", "\"Some did. Auction birds often do.\""), .direct("What do you do at the auction?", "\"I sell poultry from my own flock and handle consignments from others. I have run sales at the county fairgrounds for fifteen years.\""), .direct("What did {D} buy at your auction?", "\"A few hens and a rooster. {D} paid cash and loaded them in a pickup, as many buyers do.\""), .direct("Do birds at your auction wear leg bands?", "\"Some of them do. Consignors put on bands for shows, and we list the band numbers on the sheet.\""), .cross("Do you check bands against a registry?", "\"No. We list them but don't verify them.\""), .cross("Whose birds were they?", "\"They came from consignors. I can't say whose.\""), .cross("Can you say {DL}'s birds were not {V}'s?", "\"No. I can't. I don't know their history.\""), .cross("Do you verify who owns each band?", "\"No. We list what is on the leg and take the consignor's word. We do not check registries.\""), .cross("Can you rule out that {V}'s birds were sold at your auction?", "\"No. I cannot say where each bird came from. I do not know their history.\"")],
        theory: ("{D} took the birds in the night.", "{D} bought the birds at an auction."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had cut a bird's band the day before and used a marker to hide it.", "The auction listed bands but never checked them."),
        defendant: [.direct("Where did you get the birds?", "\"At a poultry auction over the weekend. I bought five birds, and I had them in my truck.\""), .direct("Did you take birds from {V}'s barn?", "\"No. I've never been to that barn. I wouldn't take someone's show birds.\""), .direct("Did you notice the leg bands?", "\"The birds had bands, but I didn't read the numbers. Many auction birds have bands.\""), .direct("What do you raise?", "\"A few chickens and ducks on my land. I go to poultry auctions to buy new birds and trade.\""), .direct("How did you get these birds?", "\"At a weekend auction in the next county. I bid on a crate of hens and a rooster and paid cash.\""), .direct("What happened when deputies stopped you?", "\"They found the birds in my truck bed and said they were stolen. I told them I bought them at auction and showed the flyer.\""), .cross("The bands are registered to {V}, aren't they?", "\"So I'm told. I didn't know. I trusted the auction.\""), .cross("A pickup like yours was at the barn gate, wasn't it?", "\"It's a common pickup. I wasn't there.\""), .cross("You can't show a receipt, can you?", "\"I have a flyer. I paid cash. I know that isn't much.\""), .cross("The bands are registered to another person. Why not check them?", "\"I saw bands but did not read the numbers. That is common at auctions.\""), .cross("A pickup like yours was at the barn gate. How do you explain it?", "\"It is a common color and model. I was not at the gate.\"")],
        openings: ("Four show hens and a rooster vanished from {V}'s barn before a county fair, and a trail camera shows a pickup at the gate at 2:15 a.m. Five birds with {V}'s registered leg bands were found in {D}'s truck bed two days later. The State will show the bands and the registry.", "The defense will present a poultry auction, a seller who confirms {D} bought birds there, and a pickup too common to identify. Listen closely to the witnesses."),
        closings: ("A barn latched at 8, open at 6, a pickup at 2:15, and {V}'s banded birds in {D}'s truck two days later. The band numbers don't lie.", "An auction sells birds that nobody verifies. {D} bought openly, and the camera shows no face. The State has not proved {D} took them."),
        timeline: [(0, "8 p.m.: {V} latches the barn."), (0, "2:15 a.m.: the pickup is at the gate."), (0, "6 a.m.: {V} finds the barn open."), (2, "Deputies find the birds in {D}'s truck bed.")],
        identified: "The leg bands tie the birds to {V}, and the birds were in {D}'s truck.",
        notDone: ["The auction's sale records were never subpoenaed.", "The bird counts were never compared with the auction's lot sheets."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let weddingDjNoShowV1 = SmallCases.make(
        key: "story.weddingDjNoShow",
