        ages: 18...60,
        victim: true,
        summary: "{V} booked {D}'s party band for a retirement dinner on {DATE} and paid a $1,200 deposit three weeks earlier. The day before the event, {D} cancelled by text and said a drummer was sick. {V} later learned the band played a paid show elsewhere that same night. {D} kept the deposit. {D} says the cancellation was unavoidable.",
        state: [E(.document, 3, "Booking Contract", "A signed $1,200 deposit contract for {DATE}."), E(.digital, 3, "Cancellation Text", "A text a day before saying a drummer was sick."), E(.digital, 2, "Event Listing", "The band listed at another venue the same night."), E(.statement, 2, "Venue Manager", "Booked the band and paid in full for the same night.")],
        defense: [E(.statement, 1, "Sick Drummer", "{DL} says the drummer got sick and the band could not play."), E(.document, 1, "Drummer Note", "A note from the drummer for an upset stomach.")],
        role: "Event host",
        exam: [.direct("What did you book with {D}'s band?", "\"A party band for a retirement dinner. I paid a $1,200 deposit three weeks earlier, under a signed contract.\""), .direct("What happened the day before the event?", "\"{D} cancelled by text and said a drummer was sick. I had to scramble for a replacement.\""), .direct("What did you later learn?", "\"The band played a paid show at another venue the same night. The venue manager confirmed booking and paying in full.\""), .direct("What did you pay for and when?", "\"A $1,200 deposit three weeks earlier for a four-hour set at my retirement dinner. The contract named the date and the band.\""), .direct("What happened the day before the dinner?", "\"A text from {D} said the drummer was sick and the band could not play. There was no offer of a substitute.\""), .direct("How did you scramble?", "\"I called a few other bands and a DJ. Everyone was booked. I ended up with a playlist and a friend running speakers.\""), .cross("{D} says the cancellation was unavoidable, doesn't {D.he}?", "\"Yes. A drummer was sick, as I understand. I will agree that it can happen.\""), .cross("Did {D} offer a substitute?", "\"I do not recall that. I was told only that the band could not come.\""), .cross("Did {D} keep the deposit?", "\"Yes. {D} never refunded it.\""), .cross("Did you ask for your deposit back?", "\"Yes, twice. {D} said it was non-refundable and did not respond after that.\""), .cross("How did you learn about the other show?", "\"A guest saw the band's listing at another venue that night. It was a paid show.\"")],
        defenseRole: "Drummer in the band",
        defenseExam: [.direct("Were you sick that week?", "\"A stomach illness for two days. I could not get out of bed, and I could not play.\""), .direct("Could another drummer cover for you?", "\"We called three. None was free that night, so we could not find a substitute for the dinner.\""), .direct("Did you tell the client about the cancellation?", "\"{D} did, by text. I was too sick to do anything, and I trusted {D} to handle it.\""), .direct("What do you play in the band?", "\"Drums. I have been with {D}'s band for six years.\""), .direct("How sick were you?", "\"I had a stomach virus for two days and could barely get out of bed. I could not play.\""), .direct("What did you do about the show?", "\"I told {D}. We called other drummers, and none was free.\""), .cross("Did the band play that night at a different show?", "\"Yes. A different show. We played without me, with a substitute who was available for that one.\""), .cross("Why was a substitute available for the other show but not for the dinner?", "\"The other show was a different arrangement. I do not know why.\""), .cross("Did {D} decide which show to play?", "\"Yes. {D} handled the bookings. I was not part of that decision.\""), .cross("What happened at the other show that night?", "\"The band played without me, with a drummer the venue supplied. I stayed home.\""), .cross("Who decided to take the other booking?", "\"{D} handled the bookings. I was not part of that.\"")],
        theory: ("{D} took a deposit and played elsewhere.", "A drummer's illness forced the cancellation."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} cancelled to take a better paying show.", "The drummer was sick and a substitute could not be found."),
        defendant: [.direct("Why did you cancel the retirement dinner?", "\"Our drummer was sick, and we could not find a substitute. I had no choice but to cancel.\""), .direct("Did the band play another show that night?", "\"Yes. A paid show at another venue. That was already booked, and I did not want to cancel two.\""), .direct("How long has your band played?", "\"Eight years. We do weddings and dinners around the region and rely on booking calendars.\""), .direct("What happened with your drummer?", "\"The drummer got a stomach illness two days before. We called three subs and none was free.\""), .direct("Why did you keep the deposit?", "\"I had turned down other work for that night and had expenses. I told myself it was fair, and now I do not think so.\""), .direct("What did you do to try to find a substitute drummer before you cancelled?", "\"I called three drummers I know and left messages. Two were booked and one never called back. I should have told {V} sooner.\""), .cross("You cancelled to take a better paying show, didn't you?", "\"The other show paid more. I will not deny that.\""), .cross("You told {V} a drummer was sick. Was that the whole reason?", "\"It was part of it. I should have been honest.\""), .cross("Will you refund the $1,200?", "\"I should. I would like to repay it.\""), .cross("The band played at another venue that night. How can you say you could not play for {V}?", "\"We played with a stand-in that the venue arranged. It was a different kind of show.\""), .cross("Why not offer {V} the same stand-in?", "\"The idea never crossed my mind in the rush. I should have tried it.\"")],
        openings: ("{V} booked {D}'s band for a retirement dinner and paid a $1,200 deposit. The day before, {D} cancelled by text, saying a drummer was sick, but the band played a paid show elsewhere that night and kept the deposit.", "The defense evidence will establish that the drummer was truly sick for two days and that the band could not find a substitute for the retirement dinner."),
        closings: ("A signed contract, a deposit, a text the day before, and a paid show at another venue that same night. {D} kept the money and chose the better gig.", "A sick drummer and three calls for a replacement. The State must prove {D} lied about the reason and meant to deceive, and a cancelled show is a contract dispute."),
