    static let shovelSpotV1 = SmallCases.make(
        key: "story.shovelSpot",
        category: .violent,
        headlines: ["Lawn Chair Saving Cleared Spot Swung at Neighbor After Parking Dispute", "Street Camera Shows Chair Raised at Parked Car"],
        law: "simpleAssault",
        spec: "Assaulted {V} by striking {V.him} with a lawn chair, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After a snowstorm on {DATE}, {D} cleared a parking space on a public street and set a lawn chair in it. At 12:30 p.m. {V} moved the chair and parked. {D} came out and struck {V} with the chair across the arm. {V} bruised the forearm and swelled at the elbow. {D} says {V} lunged first.",
        state: [E(.video, 3, "Street Camera", "{D} swings a lawn chair at {V} at 12:34 p.m."), E(.document, 2, "Medical Note", "A bruised forearm and a swollen elbow."), E(.physical, 2, "Lawn Chair", "A bent aluminum chair with a snapped leg."), E(.statement, 2, "Neighbor Witness", "Saw {D} swing the chair after a shouted argument.")],
        defense: [E(.statement, 1, "Lunged First", "{DL} says {V} lunged at {D.him} and the chair was a shield."), E(.document, 1, "City Snow Rule", "A page about parking in cleared spaces during a snow emergency.")],
        role: "Neighbor",
        exam: [.direct("What happened over the parking space after the snowstorm?", "\"{D} had cleared a space and set a lawn chair in it. At 12:30, I moved the chair and parked.\""), .direct("What did {D} do?", "\"{D} came out and swung the chair at me, striking my arm. The camera shows the swing at 12:34.\""), .direct("What was your injury?", "\"A bruised forearm and a swollen elbow. A medical note records it. The chair had a snapped leg.\""), .direct("What was the snow like that morning?", "\"Deep after a big storm, with plows leaving walls of snow along the curb. Parking was scarce, and neighbors had shoveled out spots.\""), .direct("What did you see at the space?", "\"A lawn chair sat in a cleared space. I moved it and parked. A few minutes later {D} came out shouting.\""), .direct("What did {D} do?", "\"{D} grabbed the chair and swung it at my arm. It bent and a leg snapped. I went to urgent care that afternoon.\""), .cross("{D} says you lunged first, doesn't {D.he}?", "\"I stepped forward after moving the chair. I did not lunge or touch {D}.\""), .cross("Did you shout at {D}?", "\"We shouted at each other. I will not deny that.\""), .cross("Who cleared the space?", "\"{D}. {D} shoveled for an hour. I know that.\""), .cross("Did you step toward {D} before the swing?", "\"I took a step forward when {D} shouted. I did not touch {D}.\""), .cross("Do you know the city's snow rule?", "\"It says spots are public in an emergency. I did not think about it before parking.\"")],
        defenseRole: "Neighbor across the street",
        defenseExam: [.direct("Who cleared the space on the street?", "\"{D}, with a shovel, for about an hour. I watched from my window as it was done.\""), .direct("Did {V} lunge at {D}?", "\"A step forward after moving the chair. It was not a lunge, but it was toward {D}.\""), .direct("Did you see the swing?", "\"Yes. I saw {D} swing the chair after a shouted argument. It was fast.\""), .direct("How long have you lived across the street?", "\"Six years. I see the whole block from my front window.\""), .direct("What did you see of the shoveling?", "\"{D} worked for about an hour, clearing a wide spot and stacking snow. Then {D} put out a chair.\""), .direct("What happened next?", "\"{V} moved the chair and parked. {D} stormed out shouting, and {V} stepped forward.\""), .cross("Was the street public?", "\"Yes. No one owns a space on it.\""), .cross("Did {V} touch {D}?", "\"I do not think so. I saw {V} step, but I did not see a hand land.\""), .cross("How many times did {D} swing?", "\"Twice, I think. I saw one clearly and the other more quickly.\""), .cross("You did not see what {V} did when moving the chair, did you?", "\"Not closely. I saw {V} lift the chair and set it on the curb. I looked away for a second and then heard the argument.\""), .cross("You cannot say how many times the chair was swung, can you?", "\"I saw it swing at least once and I think twice, but things were moving fast. I would not swear to a number.\"")],
        theory: ("{D} struck a neighbor over a parking space.", "{V} lunged first."),
        allocution: "\"I let it get out of hand. I'm ashamed.\"",
        truths: ("{DL} swung the chair twice without being touched.", "{V} did step forward after moving the chair."),
        defendant: [.direct("Did you swing the chair at {V}?", "\"Yes, I did. I had shoveled the space for an hour, and {V} moved my chair and parked.\""), .direct("Why did you swing?", "\"{V} stepped toward me after moving the chair. I was angry and I felt threatened.\""), .direct("Who cleared the space?", "\"I did, with a shovel, for an hour. I felt it was mine.\""), .direct("How long did it take to shovel the space?", "\"About an hour. I dug out the car and cleared a wide spot so I could park after work.\""), .direct("Why did you put a chair in the space?", "\"It is a habit on our street. Most neighbors do it, and it saves your spot.\""), .direct("What happened when {V} parked?", "\"I came out and saw my chair on the sidewalk. We shouted, and {V} stepped toward me. I swung the chair.\""), .cross("The street is public, isn't it?", "\"Yes. Nobody owns a space. I know that.\""), .cross("{V} did not touch you, did {V.he}?", "\"No. {V} did not touch me. I swung first.\""), .cross("You swung the chair twice, didn't you?", "\"I did. I am ashamed. I should have walked away.\""), .cross("You know a public street space belongs to no one. Why swing a chair at a neighbor?", "\"I was angry about an hour of work. It did not justify what I did.\""), .cross("How many swings did you take?", "\"Two. I regret that.\"")],
        openings: ("After a snowstorm, {D} cleared a parking space on a public street and set a lawn chair in it. {V} moved the chair and parked, and {D} struck {V} across the arm with the chair, leaving a bruise and a swollen elbow.", "By the end of this trial, the proof will show that {D} shoveled the space for an hour, that {V} stepped toward {D} after moving the chair, and that {D} reacted in anger."),
        closings: ("A public street, a lawn chair swung twice, and a bruised arm. A shoveled space is not a license to strike a neighbor.", "An hour of shoveling, a moved chair, and a step forward that frightened {D}. The State must prove {D} was not reacting to a perceived threat."),
        timeline: [(0, "12:30 p.m.: {V} moves the chair."), (0, "12:34 p.m.: {D} swings the chair."), (0, "12:45 p.m.: a witness calls deputies."), (1, "{V} gets the medical note.")],
        identified: "The street camera identifies {D}.",
        notDone: ["The city's snow parking rule was never explained to either neighbor.", "The chair's leg was never checked against the force of the hit."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let refundCheatV1 = SmallCases.make(
        key: "story.refundCheat",
        category: .whiteCollar,
        headlines: ["Online Shopper Files Twelve Damaged-Goods Claims With Reused Photos", "Retailer Finds Same Stain in Twelve Refund Photos"],
