        summary: "Over a month on {DATE}, {D} filed twelve damaged-goods claims with an online retailer and received $1,100 in refunds. Each claim included a photo of a cracked item with the same coffee stain on the box. Warehouse weights showed the returned boxes were lighter than the items shipped. {D} says the items arrived broken and that the boxes were reused by the shipper.",
        state: [E(.digital, 3, "Claim Photos", "Twelve photos of a cracked item with the same coffee stain on the box lid."), E(.document, 3, "Warehouse Weights", "Returned boxes weighed three to five pounds less than shipped."), E(.document, 2, "Refund Ledger", "$1,100 refunded across twelve claims in thirty days."), E(.digital, 2, "Account Records", "All twelve claims came from {D}'s account and phone.")],
        defense: [E(.statement, 1, "Arrived Broken", "{DL} says the items really arrived broken."), E(.document, 1, "Shipper Complaint", "A notice from the shipper about crushed packages that month.")],
        role: "Retailer investigator",
        exam: [.direct("What did you notice about {D}'s claims?", "\"Twelve damaged-goods claims in a month, with $1,100 refunded. Each claim included a photo of a cracked item with the same coffee stain on the box.\""), .direct("What did the warehouse weights show?", "\"The returned boxes weighed three to five pounds less than the items shipped. Something was missing from them.\""), .direct("How were the claims filed?", "\"All twelve came from {D}'s account and phone. The refund ledger shows the total.\""), .direct("How did the pattern appear?", "\"Twelve claims in thirty days, each with a damaged-item photo. The same coffee stain appeared on the box lid in all twelve.\""), .direct("How did the weights compare?", "\"Returned boxes weighed three to five pounds less than what we shipped. That suggests the item was not inside.\""), .direct("What was the total paid out?", "\"$1,100 in refunds across twelve claims. All claims were filed from {D}'s account and phone.\""), .cross("{D} says the items arrived broken and the shipper reused boxes, doesn't {D.he}?", "\"Yes. A shipping clerk says boxes get reused and stains show up on different ones.\""), .cross("Did one item really arrive cracked?", "\"I understand one did. That does not explain twelve photos with the same stain.\""), .cross("Can you tell a reused box from a new one by sight?", "\"Not easily. That is a fair point.\""), .cross("Can a box be reused by the shipper?", "\"It is possible. Some carriers reuse boxes, but not with the same stain on twelve different boxes.\""), .cross("Did one item really arrive broken?", "\"A damage report exists for one. We accepted that claim as valid.\"")],
        defenseRole: "Shipping clerk",
        defenseExam: [.direct("Do boxes get crushed in shipping?", "\"Often, especially the corners. A box can look badly damaged while the item inside is fine.\""), .direct("Can the same stain show up on different boxes?", "\"If the warehouse reuses boxes, yes. A stain can travel from one shipment to the next.\""), .direct("Did some of {D}'s items arrive broken?", "\"Two did, as I recall. We saw damage reports on two shipments to {D}.\""), .direct("What do you do at the shipper?", "\"I pack and load boxes. I see crushed corners and damaged goods every day.\""), .direct("Do boxes ever carry the same stain?", "\"If a box gets reused, the stain goes with it. We sometimes recycle clean boxes.\""), .direct("Did you ship {D}'s items?", "\"Some of them. Two arrived with damage reports that I remember.\""), .cross("Can you tell which boxes were reused?", "\"Not by sight. I would have to check the records.\""), .cross("Do returned boxes usually weigh less than shipped?", "\"Not by three to five pounds. That would mean items were removed.\""), .cross("Would twelve photos with the same stain be normal?", "\"No. That would be unusual. I would want to look at them.\""), .cross("You cannot say which boxes were crushed in transit and which were reused, can you?", "\"Not without opening each one. Boxes get dented in any shipment, but I cannot tell you from a photo whether one was reused.\""), .cross("You did not handle any of {D}'s twelve shipments yourself, did you?", "\"I handle a lot of packages and cannot say I remember any of these. I am speaking from general experience with shipping.\"")],
        theory: ("{D} reused photos to collect refunds.", "{D} received broken items."),
        allocution: "\"I should have told the truth the first time.\"",
        truths: ("{DL} kept the items and sent back empty boxes.", "One item really did arrive cracked and {DL} reused the photo."),
        defendant: [.direct("Did you file false damage claims?", "\"No. The items arrived broken, and I filed claims with photos of what I received.\""), .direct("Why is the same coffee stain in every photo?", "\"The shipper reused boxes. I think the stain was already on the boxes when they arrived.\""), .direct("Why were the returned boxes lighter?", "\"I do not know. I sent back what I received. Something may have been lost in transit.\""), .direct("What did you order?", "\"Small kitchen items and home goods, mostly glass and ceramic. I buy a lot online because I live far from stores.\""), .direct("What happened with the items?", "\"Several arrived cracked, in boxes that looked used. I photographed them and filed claims.\""), .direct("Why do the photos show the same stain?", "\"The boxes came from the same warehouse and may have been reused. The stain looked like the same mark each time.\""), .cross("You kept the items and sent back empty boxes, didn't you?", "\"No. I sent back what arrived. I do not know why the weights were off.\""), .cross("One item really did arrive cracked, and you reused that photo, didn't you?", "\"I may have used one photo more than once. I was sloppy.\""), .cross("Twelve claims in thirty days is a lot of broken goods, isn't it?", "\"It is. I ordered a lot, and a lot arrived damaged.\""), .cross("The returned boxes were three to five pounds light. What did you send back?", "\"What I received. I did not remove anything.\""), .cross("Twelve claims in thirty days with the same stain looks like one photo reused. Is that wrong?", "\"It may be that I used a photo more than once. I do not recall.\"")],
        openings: ("Over a month, {D} filed twelve damaged-goods claims and received $1,100 in refunds. Each claim photo shows a cracked item with the same coffee stain on the box, and the returned boxes weighed three to five pounds less than shipped.", "The defense will present evidence that the shipper reuses boxes, that two items really arrived broken, and that {D} sent back what arrived."),
        closings: ("Twelve claims, the same coffee stain in every photo, boxes returned lighter than shipped, and $1,100 refunded. The pattern is not an accident.", "A shipper who reuses boxes and items that really did arrive broken. The State must prove {D} faked the damage, and a repeated stain is as likely a reused box."),
        timeline: [(0, "{D} files the first claim."), (15, "{D} files the sixth claim."), (30, "The retailer sees the repeated stain."), (40, "The retailer reports the claims.")],
        identified: "The account records identify {D}.",
        notDone: ["The shipper's damage log was never reviewed.", "The returned boxes' tape was never compared."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let mallGrabRunV1 = SmallCases.make(
        key: "story.mallGrabRun",
        category: .property,
        headlines: ["Customer Grabs Two Display Tablets From Mall Kiosk and Runs Down Corridor", "Security Corners Shopper at Parking Deck With Two Tablets"],
        law: "larcenyMerchant",
        spec: "Took merchandise valued at $620 from {V}, an electronics kiosk, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} asked a mall kiosk clerk to demonstrate a tablet at 2 p.m. on {DATE}, then grabbed two display tablets and ran. Mall security chased {D} through a corridor and cornered {D} on the parking deck at 2:08 p.m. The tablets were worth $620 together. {D} says {D.he} thought the display models were free to try outside.",
        state: [E(.video, 3, "Mall Camera", "{D} grabs the two tablets and runs through the corridor at 2:02 p.m."), E(.physical, 2, "Tablets", "Two display tablets recovered from a bag on the parking deck."), E(.document, 2, "Inventory Sheet", "Two tablets and their serial numbers listed on the kiosk."), E(.statement, 2, "Mall Security", "Chased {D} for six minutes and detained {D.him} at the deck.")],
        defense: [E(.statement, 1, "Free to Try", "{DL} says {D.he} thought the display models could be tried outside."), E(.document, 1, "Kiosk Sign", "A sign that says 'Try me!' on the display stand.")],
        role: "Kiosk clerk",
        exam: [.direct("What happened at your kiosk at 2 p.m.?", "\"{D} asked me to demonstrate a tablet, then grabbed two display tablets and ran through the corridor at about 2:02.\""), .direct("What does the mall camera show?", "\"{D} grabbing the two tablets and running. The inventory sheet lists both, with serial numbers.\""), .direct("How was {D} caught?", "\"Mall security chased {D} for six minutes and cornered {D} on the parking deck at 2:08. The tablets were in a bag.\""), .direct("How do you display the tablets?", "\"On a stand with a sign that says 'Try me!' and a short tether cable. The sign is for customers to try them at the kiosk.\""), .direct("What did {D} ask you?", "\"To demonstrate a tablet. I stepped to the screen to show a feature. While I talked, {D} picked up two tablets and ran.\""), .direct("What happened next?", "\"I shouted and called mall security. {D} ran through the corridor and was cornered on the parking deck at 2:08.\""), .cross("{D} says the display models were free to try, doesn't {D.he}?", "\"The sign did say 'Try me!' I agree with that.\""), .cross("Were the tablets tethered?", "\"By a thin cable. The cables were found loose when we looked.\""), .cross("Did the sign say you could take a tablet out of the kiosk?", "\"No. It said try. It did not say take.\""), .cross("Were the cables cut?", "\"They were loose when I checked. I cannot say whether they were cut or pulled.\""), .cross("The tablets were tethered with cables when {D} grabbed them, weren't they?", "\"Yes, each tablet had a thin cable to the stand. When I looked after {D} ran, the cables were cut and hanging.\"")],
        defenseRole: "Shopper near the kiosk",
        defenseExam: [.direct("Did the kiosk sign say to try the tablets?", "\"Yes, 'Try me!' in big letters. It invited shoppers to pick up and play with the display models.\""), .direct("Were the tablets tethered to the display?", "\"By a thin cable, which would not stop anyone who tugged hard. Those cables come loose a lot.\""), .direct("Did you see the cables come loose?", "\"I saw them come loose when {D} picked up the tablets. I did not see any tool used.\""), .direct("What were you doing near the kiosk?", "\"Browsing the mall with a bag. I was a few feet away and watched the demonstration.\""), .direct("What did the sign say?", "\"'Try me!' in large letters. It invited shoppers to touch and use the tablets.\""), .direct("What did you see {D} do?", "\"{D} picked up two tablets and the cables came loose from the stand. Then {D} ran.\""), .cross("Did {D} run from the kiosk?", "\"Yes. {D} ran. I saw that clearly from where I stood by the pretzel stand.\""), .cross("Why run if the tablets were meant to be tried?", "\"I do not know. I only saw what happened. It looked strange to me.\""), .cross("Did anyone tell {D} to put them back?", "\"Not before {D} ran. The clerk shouted after.\""), .cross("Did {D} ask permission?", "\"I did not hear that. The clerk was speaking to {D} when it happened.\""), .cross("Why would someone run if the tablets were for trying?", "\"I cannot say. I saw only the run.\"")],
        theory: ("{D} took two tablets and ran.", "{D} thought the display models could be taken to try."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} cut the cables with a small tool.", "The cables were already loose."),
        defendant: [.direct("Did you take the two tablets?", "\"Yes, I took them. The sign said 'Try me!' and I thought I could try them outside the store.\""), .direct("Did you cut the cables?", "\"No. The cables were already loose. I did not use any tool.\""), .direct("Why did you stop at the kiosk?", "\"I wanted to compare tablets. The clerk showed me a few and the sign said 'Try me!'\""), .direct("What did you do with the tablets?", "\"I picked up two to try them while walking around. I did not realize I was supposed to stay at the kiosk.\""), .direct("Why did you run?", "\"The clerk shouted and security came. I panicked and ran toward the parking deck.\""), .direct("What did you intend to do with the tablets when you picked them up?", "\"I thought I could try them outside and bring them back. I did not think about what it would look like to leave.\""), .cross("You had a small tool in your pocket, didn't you?", "\"I carry one. I did not use it on the cables.\""), .cross("You ran for six minutes through a mall. Isn't that guilty behavior?", "\"It looks that way. I was scared. I should have stopped.\""), .cross("You were cornered on the parking deck, weren't you?", "\"Yes. I gave up there. I did not fight.\""), .cross("You carried two tablets away from a kiosk. Why not ask first?", "\"I own that. I thought they were fine to try outside.\""), .cross("You carry a small tool. Isn't that how you freed the cables?", "\"I carry one for my work. I did not use it on the cables.\"")],
        openings: ("{D} asked a kiosk clerk to demonstrate a tablet at 2 p.m., then grabbed two display tablets worth $620 and ran through a mall corridor. Security chased {D} for six minutes and cornered {D} on the parking deck.", "The defense witnesses will explain that the sign said 'Try me!', that the tethers were already loose, and that {D} panicked and ran when shouted at."),
        closings: ("Two tablets grabbed and a run through a mall, a six-minute chase, and a bag on the parking deck. Display models are for trying in the store.", "A sign inviting shoppers to try the tablets and loose cables. The State must prove {D} meant to steal, and a frightened run is not intent."),
        timeline: [(0, "2 p.m.: {D} asks for a demo."), (0, "2:02 p.m.: {D} grabs the tablets."), (0, "2:08 p.m.: security corners {D}."), (0, "2:20 p.m.: deputies take the report.")],
        identified: "The mall camera and security identify {D}.",
        notDone: ["The tethers' condition was never inspected.", "The kiosk clerk was never asked whether customers could take tablets away from the stand."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let busSpitV1 = SmallCases.make(
        key: "story.busSpit",
        category: .violent,
        headlines: ["Fare Inspector Spat On at Rail Platform After Ticket Check", "Platform Camera Shows Rider Spit at Inspector"],
