        state: [E(.video, 3, "Platform Camera", "{D} turns and spits at the inspector's face at 4:43 p.m."), E(.statement, 3, "Fare Inspector", "Wiped saliva from the face and reported it."), E(.document, 2, "Citation", "A fare citation written to {D} that minute."), E(.document, 2, "Police Report", "Officers took the report at 4:55 p.m.")],
        defense: [E(.statement, 1, "Coughing", "{DL} says {D.he} had a cough and the spit was not aimed."), E(.document, 1, "Clinic Note", "A walk-in clinic visit the day before for a cough.")],
        role: "Fare inspector",
        exam: [.direct("What happened on the rail platform at 4:40 p.m. on {DATE}?", "\"I asked {D} for a ticket. {D} had none, and I handed {D} a citation. As I wrote it, {D} spit in my face.\""), .direct("What does the platform camera show?", "\"{D} turning and spitting at my face at 4:43. I wiped it off and called police at 4:44.\""), .direct("What happened afterward?", "\"Officers took my report at 4:55. The citation was written that minute.\""), .direct("What is your job on the platform?", "\"I check tickets and issue citations. I stand on the platform during rush hour and ask riders to show fares.\""), .direct("What did {D} do?", "\"{D} turned toward me and spit in my face. I felt it hit my cheek and mouth and called police at 4:44.\""), .direct("What did you do right after {D} spat at you?", "\"I stepped back, wiped my face, and told {D} to stay put. I radioed for the police and kept my distance until they arrived.\""), .cross("{DL} says {D.he} was coughing, doesn't {D.he}?", "\"I saw the spit go toward my face. I can't say whether {D} had a cough.\""), .cross("Did {DL} say anything?", "\"Some words. I don't recall them. It was fast.\""), .cross("Were you hurt?", "\"No. It's disgusting and unsafe, but no physical injury.\""), .cross("Did {D} cough before?", "\"I heard {D} cough a couple of times. The spit looked aimed to me.\""), .cross("Did {D} say anything when spitting?", "\"I do not remember words. {D} was irritated about the citation.\"")],
        defenseRole: "Platform rider",
        defenseExam: [.direct("Were you on the platform?", "\"Yes. I was waiting for a train near {D}.\""), .direct("Did you see {DL} cough?", "\"Yes. {D} coughed a few times earlier. It sounded real.\""), .direct("Did you see the spit?", "\"I saw it. It happened fast. I couldn't tell if it was aimed.\""), .direct("Where were you on the platform?", "\"About ten feet away, waiting for a train. I could see and hear the whole conversation between them.\""), .direct("What did {D} do before the spit?", "\"Coughed a few times and covered {D.his} mouth once. {D} seemed irritated about being cited by the inspector.\""), .direct("What did you see?", "\"{D} turned toward the inspector and then there was spit. It happened fast, and I could not tell if it was intentional or a cough.\""), .cross("Did {DL} turn toward the inspector?", "\"Yes. {D} turned toward the inspector. Then the spit.\""), .cross("Did {D} look angry?", "\"A little annoyed about the citation. {D} did not shout or threaten the inspector in any way.\""), .cross("Did you speak to {D}?", "\"No. I only watched from where I stood. I did not know either of them before that afternoon.\""), .cross("You did not hear what {D} said before the spit, did you?", "\"No. The platform was loud with a train coming in. I saw {D} turn toward the inspector, and then I heard a shout.\""), .cross("You cannot say whether the cough and the spit were the same motion, can you?", "\"I saw a cough earlier. I am not able to say the spit was the same one, and I cannot tell you what {D} was thinking.\"")],
        theory: ("{D} spat at a fare inspector.", "{D} was coughing."),
        allocution: "\"I'm not proud of it, Your Honor.\"",
        truths: ("{DL} said afterward that it felt good to spit at an inspector.", "The cough was real and {DL} covered {D.his} mouth earlier."),
        defendant: [.direct("Why did you spit?", "\"I had a cough, and I turned away to cough. Some spit came out. I didn't aim it.\""), .direct("Had you been sick?", "\"Yes. I'd been to a walk-in clinic the day before for a cough.\""), .direct("Did you mean to spit at the inspector?", "\"No. I was angry about the citation, but I never meant to spit. I'm embarrassed.\""), .direct("Why did you not have a ticket?", "\"I ran late and the machine was out of service at my stop. I got on thinking I could pay on arrival.\""), .direct("How did you feel when handed a citation?", "\"Frustrated and annoyed. I had been coughing all day.\""), .direct("What exactly happened?", "\"I turned my head to cough and some spit came out. I did not mean to hit the inspector.\""), .cross("The camera shows you turning and spitting, doesn't it?", "\"It looks like that. I was coughing. I didn't plan it.\""), .cross("You were angry about the citation, weren't you?", "\"Yes. I didn't have a ticket. I was irritated.\""), .cross("The spit hit the inspector's face, didn't it?", "\"I've been told so. I'm so sorry.\""), .cross("The camera shows you turning toward the inspector. Why not turn away?", "\"I turned the wrong way. I was irritated and not thinking.\""), .cross("You were angry about the citation. Isn't that why you spit?", "\"I was angry, but I did not aim to spit on anyone.\"")],
        openings: ("A fare inspector asked {D} for a ticket on a rail platform and handed over a citation. As it was written, {D} spit in the inspector's face. The platform camera recorded it at 4:43 p.m. The State will show the video and the report.", "Jurors will also see a person with a documented cough, a rider who heard it, and a spit that was not aimed. Listen closely to the witnesses."),
        closings: ("A citation being written, a turn, and a spit in the inspector's face on camera. Public servants should not be treated that way.", "{D} had a cough, as a clinic note and a rider confirm. The State has not proved {D} meant to spit at the inspector."),
        timeline: [(0, "4:40 p.m.: the fare check begins."), (0, "4:43 p.m.: the spit."), (0, "4:44 p.m.: the inspector calls police."), (0, "4:55 p.m.: officers take the report.")],
        identified: "The platform camera and the citation identify {D}.",
