    static let lostDogRewardV1 = SmallCases.make(
        key: "story.lostDogReward",
        category: .whiteCollar,
        headlines: ["Man Claims He Found Cat and Demands $250 Vet Fee Before Returning It", "Vet Says No Visit Was Ever Made for Missing Cat"],
