        state: [E(.document, 3, "Clinic Check", "The named clinic has no visit for a cat matching the description."), E(.digital, 3, "Messages", "{D} writes that the cat needed stitches and the fee was due before return."), E(.statement, 2, "{V}", "Paid $250 cash and received a healthy cat."), E(.physical, 2, "Cat Exam", "A later exam found no stitches and no injury.")],
        defense: [E(.statement, 1, "After-Hours Clinic", "{DL} says the visit was at an after-hours clinic that does not keep records."), E(.document, 1, "Gas Receipt", "A receipt placing {D} near a clinic that evening.")],
        role: "Cat owner",
        exam: [.direct("What happened to your cat?", "\"My cat went missing. The next day {D} called and said {D.he} had found the cat injured and paid for a vet visit.\""), .direct("What did {D} ask for?", "\"$250 before returning the cat. {D}'s messages say the cat needed stitches and the fee was due first.\""), .direct("What did you find afterward?", "\"I paid $250 in cash in a parking lot and got my cat back healthy. A later exam found no stitches and no injury.\""), .direct("When did your cat go missing and what did you do?", "\"On the morning of {DATE} the cat was not at the door. I searched the yard, called neighbors, and posted flyers.\""), .direct("How did {D} contact you?", "\"A call the next day. {D} said the cat was hurt, had been treated at a clinic, and needed $250 before it could be returned.\""), .direct("What did you do?", "\"I agreed to meet in a parking lot and paid $250 in cash. {D} handed over the cat in a carrier. The cat looked fine.\""), .cross("{D} says the visit was at an after-hours clinic, doesn't {D.he}?", "\"Yes. The clinic {D} named has no record of a visit.\""), .cross("Did {D} say where the cat was found?", "\"Wandering, {D} said. I believe the cat was taken from my yard.\""), .cross("Did you pay willingly?", "\"I paid because I wanted my cat back. I did not argue.\""), .cross("Did you check the cat's health afterward?", "\"Yes. My vet found no injury and no stitches. That is why I checked the clinic {D} named.\""), .cross("Did {D} show you any vet paperwork?", "\"No. {D} only mentioned a clinic and a fee. I never saw a bill.\"")],
        defenseRole: "Neighbor of the defendant",
        defenseExam: [.direct("Did you see a cat at {D}'s house?", "\"A stray gray cat on the porch. It sat there for a day or two, and {D} fed it.\""), .direct("Does {D} feed strays?", "\"Often. {D} puts out food for neighborhood cats, and I have seen many on the porch.\""), .direct("Did {D} mention a vet?", "\"Yes. {D} said the cat needed a vet, and that {D} would take it. I did not see where.\""), .direct("How long have you lived next to {D}?", "\"Five years. I see {D}'s porch and yard most days and know the pets in the neighborhood.\""), .direct("What did you see at {D}'s house that week?", "\"A gray cat on the porch eating from a bowl. {D} said it was a stray.\""), .direct("What did {D} say about the cat?", "\"That it had been limping and needed a vet. {D} said {D.he} would find the owner.\""), .cross("Did you see {D} take the cat from a yard?", "\"I do not know. I only saw the cat on the porch.\""), .cross("Did you see {D} take the cat to a vet?", "\"No. I did not. I only heard {D} mention one.\""), .cross("Did {D} ask the owner for money?", "\"I did not hear that. I only know about the cat.\""), .cross("Did you see where the cat came from?", "\"No. I only saw it on the porch. I did not see how it got there.\""), .cross("Did you hear about the $250 fee?", "\"No. I only heard about the vet idea. I did not hear about money.\"")],
        theory: ("{D} invented a vet bill.", "{D} paid for care at a clinic with no records."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} took the cat from {V}'s yard and kept it overnight.", "{DL} did find the cat wandering and fed it."),
        defendant: [.direct("Did you take {V}'s cat?", "\"No. I found the cat wandering and fed it. I called the owner as soon as I could.\""), .direct("Why did you ask for $250?", "\"I thought the cat needed a vet and I had paid. I believed I was owed that money.\""), .direct("Where is the vet?", "\"An after-hours clinic. I do not remember the name, and I paid cash.\""), .direct("How did you come across the cat?", "\"It was wandering near my porch, thin and meowing. I put out food and brought it inside overnight.\""), .direct("Why did you think it needed a vet?", "\"It seemed to limp and favor a leg. I took it to a clinic that evening, and they looked at it.\""), .direct("What did you do when you found the owner?", "\"I called the number on a flyer and explained. I asked for the clinic fee so I would not be out of pocket.\""), .cross("The clinic you named has no record, does it?", "\"So I am told. I may have given the wrong name.\""), .cross("The cat had no stitches and no injury, did it?", "\"It looked hurt to me. I may have been wrong.\""), .cross("You kept the cat overnight, didn't you?", "\"Yes. I fed it. I wanted to keep it safe.\""), .cross("The clinic has no record of the visit. Why?", "\"I think it was an after-hours clinic that does not keep records. I do not remember its name.\""), .cross("You kept someone's cat overnight and demanded cash. Does that sound like a rescue?", "\"It sounds bad when you put it that way. I thought I was owed for the care.\"")],
        openings: ("{V}'s cat went missing, and the next day {D} called, claiming the cat was injured and needed stitches, and asked for $250 before returning it. The named clinic has no record, and a later exam found no injury.", "Weigh the defense proof, which will show that {D} found the cat wandering, fed it on the porch, and honestly believed it needed a vet before it could go home."),
        closings: ("A missing cat, a phone call, $250 in cash in a parking lot, a clinic with no record, and a healthy cat with no stitches. {D} used the cat to get money.", "A stray cat on a porch, a neighbor who feeds strays, and a belief that a vet bill was owed. The State must prove {D} lied to get the money."),
        timeline: [(0, "{V}'s cat goes missing."), (1, "{D} calls {V} demanding $250."), (1, "{V} pays and gets the cat back."), (3, "The clinic reports no record of a visit.")],
        identified: "The messages identify {D}.",
        notDone: ["The cat's microchip was never read.", "The clinic named by {DL} was never visited."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let siphonedDieselV1 = SmallCases.make(
        key: "story.siphonedDiesel",
        category: .property,
        headlines: ["Gas Cans Drained From Lawn Crew's Trailer Overnight", "Gas Station Receipts Show Neighbor Filling Same Cans"],
