        state: [E(.video, 3, "Driveway Camera", "{D} siphons four cans into a bucket at 2:10 a.m."), E(.physical, 2, "Empty Cans", "Four cans with fresh siphon marks and a hose smell."), E(.document, 2, "Fuel Receipt", "$180 in gasoline bought for the cans the afternoon before."), E(.statement, 2, "{V}", "The cans were full at 8 p.m. and never offered.")],
        defense: [E(.statement, 1, "Offered", "{DL} says one of {V}'s crew said {D.he} could take the extra fuel."), E(.document, 1, "Text Message", "A text from a crew member the week before that says 'help yourself to spare gas.'")],
        role: "Lawn crew owner",
        exam: [.direct("What did you leave in your driveway overnight?", "\"Four gas cans on a trailer. They were full at 8 p.m., and I had bought $180 of gasoline for them that afternoon.\""), .direct("What does your driveway camera show?", "\"{D}, from next door, siphoning the four cans into a bucket at about 2:10 a.m. and carrying them across the lawn.\""), .direct("What was left at 6 a.m.?", "\"Four empty cans with fresh siphon marks and a hose smell. {D} filled a lawn mower at 7.\""), .direct("What was on your trailer that night?", "\"Four five-gallon gas cans filled that afternoon for the next day's mowing jobs. I had a receipt for $180 in fuel.\""), .direct("What did you see on the camera?", "\"At about 2:10 a.m. {D} came across the lawn with a bucket and a hose and siphoned each can one by one. Then {D} carried the fuel back.\""), .direct("What did you find at 6?", "\"Four empty cans and a smell of gasoline on the trailer. We had to run to the station to get fuel before our first job.\""), .cross("{D} says your crew offered the fuel, doesn't {D.he}?", "\"A crew member texted {D} a week earlier about spare gas. These were not spare cans.\""), .cross("Did you tell {D} it was fine to take them?", "\"No. I never offered anything. I did not know about the text.\""), .cross("Did {D} hide what was happening?", "\"It was 2 a.m., but {D} did it in plain view of the camera.\""), .cross("Did a crew member text {D} about spare gas?", "\"One of my crew texted something about spare fuel a week earlier, and that was news to me when I learned of it afterward.\""), .cross("Did {D} use the fuel?", "\"The camera shows {D} putting some in a mower at about 7 a.m.\"")],
        defenseRole: "Crew member",
        defenseExam: [.direct("Did you text {D} about spare gas?", "\"Yes, a week ago. I said we sometimes had spare gas if {D} ever needed some.\""), .direct("Were these cans spare?", "\"No. They were full for the next day's jobs. They were not the spare gas I meant.\""), .direct("Does {D} help on jobs?", "\"Sometimes. {D} helps out when we are short-handed, and we have paid {D} before.\""), .direct("What is your role on the crew?", "\"I am one of the mowers. I load trailers and help on jobs most weekdays.\""), .direct("What did you text {D}?", "\"That we sometimes had spare fuel and {D} could ask me. I did not name a day or a can.\""), .direct("Were those cans spare?", "\"No. They were full and set aside for the next morning's jobs.\""), .cross("Did you tell {D} which cans were spare?", "\"No. I did not. I just said spare gas.\""), .cross("Did you tell {V} about the text?", "\"Not yet. I should have mentioned it when the cans went missing.\""), .cross("Would you take fuel from a trailer at that hour?", "\"No. I would ask in daylight. That is how I would handle it.\""), .cross("You never told {D} which cans were spare, did you?", "\"No. I said there was extra fuel around. I did not point to any cans or give any time to come get it.\""), .cross("You would not expect anyone to take fuel at 2 a.m. without asking, would you?", "\"No. If someone needed fuel, I would expect a call first. I did not expect anyone to come over at night.\"")],
        theory: ("{D} drained gas cans overnight.", "{D} used fuel offered by a crew member."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had no mower of {D.his} own; the fuel went to a resale.", "The text offered spare fuel and {DL} thought the cans were spare."),
        defendant: [.direct("Did you siphon the fuel from {V}'s cans?", "\"Yes, I did. I thought the crew had offered spare gas, and I took the cans from the trailer.\""), .direct("Why did you fill a lawn mower?", "\"I had a lawn to cut in the morning. I filled it at 7 a.m.\""), .direct("What did you understand about the offer?", "\"A crew member texted that there was spare gas I could use sometime. I took that to mean the cans on the trailer.\""), .direct("Why did you go at 2 a.m.?", "\"I was up late with a mowing job in the morning and my own gas was low. I did not want to wake anyone.\""), .direct("What did you do with the fuel?", "\"I put some in my mower and kept the rest in my garage. I did not hide that.\""), .direct("How did you come to believe the gas was spare?", "\"I got a text from a crew member about spare fuel in the driveway. I figured the full cans were the extras, and I did not check with {V}.\""), .cross("You do not have a mower of your own, do you?", "\"I have one. I also had a resale to make with some fuel.\""), .cross("The crew's text said spare gas. These cans were full, weren't they?", "\"Yes. I did not check. I took all four.\""), .cross("You did not ask {V} before taking four cans, did you?", "\"No. I own that. I am so sorry.\""), .cross("You took all four cans without asking. Why?", "\"I assumed they were spare. I should have knocked and asked first.\""), .cross("What happened to the rest of the fuel after your mower?", "\"It went into my garage cans for later use. I should not have taken it, and I will pay what I took.\"")],
        openings: ("{V}'s lawn crew kept four full gas cans on a trailer overnight. At 2:10 a.m., the driveway camera shows {D}, from next door, siphon all four into a bucket, and the cans were empty by 6.", "Jurors will hear that a crew member texted {D} about spare gas a week earlier and that {D} believed the cans were spare."),
        closings: ("Four full cans at 8 p.m., a siphon on camera at 2 a.m., and empty cans by 6. {D} took $180 of fuel while the owner slept.", "A crew member's offer of spare gas and a neighbor who took the wrong cans. The State must prove {D} knew the fuel was not offered."),
        timeline: [(0, "8 p.m.: the cans are full."), (0, "2:10 a.m.: {D} siphons the cans."), (0, "6 a.m.: the crew finds them empty."), (1, "{V} sends the camera video.")],
        identified: "The driveway camera identifies {D}.",
        notDone: ["The crew member's text was never read in full.", "The cans' fill levels were never recorded."],
