        role: "Dog owner",
        exam: [.direct("What did you pay {DL} for on {DATE}?", "\"$360 for a month of weekday dog walks, through a payment app.\""), .direct("What happened?", "\"{D} walked the dog twice and then stopped answering. I sent fourteen messages over twelve days and got no reply.\""), .direct("What did you find when you came home?", "\"The dog was found in distress on day thirteen, with a full bladder and an empty water bowl. The doorbell camera shows two visits and none after day three.\""), .direct("What did the arrangement include?", "\"Weekday dog walks for a month, at $360, paid by app. {D} was to come at noon each day to walk and feed my dog.\""), .direct("What did the doorbell camera show?", "\"Two visits the first week. Nothing after the third day. I texted fourteen times and got no replies.\""), .direct("How was the dog when you returned from your trip?", "\"On day thirteen the dog was whining at the door with an empty water bowl and a full bladder. The floor had a puddle.\""), .cross("{DL} says a car accident kept {D.him} away, doesn't {D.he}?", "\"A minor collision report exists for day four. I'd have wanted a message.\""), .cross("Did {DL} ever contact you?", "\"No. Not once after the first week. I'd have been understanding if I'd been told.\""), .cross("Did you arrange anyone else?", "\"I was on a work trip. I assumed the walks were happening.\""), .cross("Did {D} offer any explanation?", "\"Only later. {D} mentioned a minor car accident on day four.\""), .cross("Have you been refunded?", "\"No. I have not received any of the $360 back.\"")],
        defenseRole: "Neighbor of the defendant",
        defenseExam: [.direct("Do you live near {DL}?", "\"Yes. I'm next door.\""), .direct("Did {DL} have a car accident?", "\"Yes. On day four, in a parking lot. {D} was shaken.\""), .direct("How was {DL} afterward?", "\"Unwell for days. {D} didn't go out much.\""), .direct("How long have you lived next to {D}?", "\"Four years. I wave to {D} most days and I see when {D} comes and goes from the house.\""), .direct("What do you know about {D}'s car accident?", "\"It happened on the fourth day in a parking lot, nothing serious by itself, but {D} was visibly rattled afterward.\""), .direct("How did {D} seem in the days after?", "\"Unwell and unsteady for a while. {D} stayed in and did not go out much for several days afterward.\""), .cross("Did {DL} tell {V}?", "\"I don't know. I didn't talk to {V}.\""), .cross("Did {DL} walk the dog after?", "\"Not that I saw. I wasn't watching.\""), .cross("Was it a serious accident?", "\"Minor. But {D} seemed rattled.\""), .cross("Did {D} tell {V} about the accident?", "\"I cannot say whether {D} did. I never spoke to {V} about it, and I never saw any messages.\""), .cross("Did {D} walk the dog after day four?", "\"Not that I saw. But I was not watching the street all day, so I cannot say it never happened.\"")],
