        defense: [E(.statement, 1, "Helping Out", "{DL} says {D.he} was moving them to the backyard because the wind was blowing them over."), E(.document, 1, "Weather Note", "A wind advisory was in effect that night.")],
        role: "Neighbor",
        exam: [.direct("What happened to your decorations on {DATE}?", "\"I had six inflatable holiday decorations plugged in on the lawn. At 7 a.m. I found bare stakes.\""), .direct("What does your doorbell camera show?", "\"{D}, who lives across the street, unplugging them, deflating them, and carrying them across the street in two trash bags at 3:05 a.m.\""), .direct("Where were they found?", "\"Six deflated inflatables in a closet at {D}'s house. I bought them for about $260 total.\""), .direct("What did you have on the lawn?", "\"Six inflatable decorations, plugged into a timer and staked down. I bought them over several years for $260 total.\""), .direct("What did you find in the morning?", "\"Bare stakes and cords on the grass. I checked the camera and then looked across the street and saw a bag in {D}'s window.\""), .direct("What did you do after you saw the doorbell video?", "\"I walked across the street and knocked. {D} did not answer, so I called the sheriff's office and told them where the decorations probably were.\""), .cross("{DL} says {D.he} was moving them to the backyard, doesn't {D.he}?", "\"It was windy that night. But the decorations ended up across the street, not in my backyard.\""), .cross("Was there a wind advisory?", "\"I understand so. I slept through the wind.\""), .cross("Did you ask {DL} to move them?", "\"No. I never gave permission to anyone.\""), .cross("Was it windy that night?", "\"I slept through it. I heard there was a wind advisory.\""), .cross("Did you and {D} have any problems?", "\"We have had small disagreements about lights and the neighborhood association. Nothing serious.\"")],
        defenseRole: "Neighbor down the street",
