    static let fakeCharityDoorV1 = SmallCases.make(
        key: "story.fakeCharityDoor",
        category: .property,
        headlines: ["Door Knocker Sells Fundraiser Magazine Subscriptions for a School That Has No Fundraiser", "Principal Says Candy-Bar and Magazine Drive Was Never Held"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $80, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "On {DATE} at 4:30 p.m., {D} knocked at {V}'s door with an order form for magazine subscriptions to benefit an elementary school fundraiser. {V} paid $80 cash and received a carbon slip. When {V} called the school the next day, the principal said no fundraiser was under way and no student sells door to door. {D} says {D.he} was working for a vendor.",
        state: [E(.document, 3, "Order Form", "A form with the school's name and a handwritten $80 entry signed by {D}."), E(.statement, 3, "Principal", "The school holds no door-to-door fundraiser."), E(.document, 2, "Receipt Slip", "A carbon slip for $80 with no vendor name."), E(.statement, 2, "Neighbors", "Two neighbors say {D} knocked and gave the same pitch.")],
        defense: [E(.statement, 1, "Vendor Job", "{DL} says {D.he} worked for a vendor and was paid by commission."), E(.document, 1, "Vendor Text", "A text from a number offering 'door-to-door sales' work.")],
        role: "Homeowner",
        exam: [.direct("What happened at your door on {DATE} at 4:30 p.m.?", "\"{D} knocked with an order form for magazine subscriptions to benefit an elementary school fundraiser. I paid $80 cash and got a carbon slip.\""), .direct("What did you learn?", "\"The principal told me the school has no door-to-door fundraiser and no student sells that way.\""), .direct("What do the form and slip show?", "\"A form with the school's name and a handwritten $80 entry signed by {D}. The slip has no vendor name.\""), .direct("How did {D} approach you?", "\"Friendly and prepared. {D} had an order form with the school's name and said subscriptions would help the school fundraiser.\""), .direct("What did you pay and what did you get?", "\"$80 in cash for a three-year subscription. {D} wrote $80 on the form and gave me a carbon slip with no company name.\""), .direct("How did you find out?", "\"The next day I called the school. The principal said no door-to-door fundraiser existed and no student was selling.\""), .cross("{DL} says {D.he} worked for a vendor, doesn't {D.he}?", "\"There's a text offering door-to-door sales work. I can't verify any vendor.\""), .cross("Did {DL} say anything false?", "\"{D} said it benefited the school. That's what I relied on.\""), .cross("Did you check before paying?", "\"No. I should have, yes. It was a pleasant pitch and I wanted to help.\""), .cross("Did {D} use a badge or ID?", "\"No. {D} wore a polo shirt and carried a clipboard.\""), .cross("Did you ever receive any magazines?", "\"No. Nothing has come in the mail.\"")],
        defenseRole: "Another vendor salesperson",
        defenseExam: [.direct("Do you sell for the same vendor?", "\"Yes. I got the same text and took the commission job.\""), .direct("What were you told to say?", "\"That subscriptions benefit a local cause. I used whatever pitch I was given.\""), .direct("How do you know {D}?", "\"I sell for the same vendor. We never worked together, but we got the same text offer.\""), .direct("What did the vendor tell you?", "\"That we should say subscriptions helped a local cause and that using the school's name would help sales. I did not check it.\""), .direct("How were you paid?", "\"On commission, a percentage of each sale. The vendor sent me a check every two weeks.\""), .direct("What did the vendor tell you to say at the door?", "\"To say it was for a school fundraiser, because people respond to that. I was told the form was a standard form from the vendor.\""), .cross("Did the vendor say it was a school fundraiser?", "\"Something like that. I don't remember the exact words.\""), .cross("Was it real?", "\"I thought so. I'm not so sure now.\""), .cross("Did {DL} work with you?", "\"Not together. We got the same offer.\""), .cross("Did you ever find out whether it was real?", "\"I thought it was. I am not so sure now that I have heard about the principal.\""), .cross("You never checked whether the school had agreed to it, did you?", "\"No. I trusted the vendor. I should have called the school, and I regret that I did not.\"")],
        theory: ("{D} used a school's name to take $80.", "{D} worked for a vendor."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had made up the order form at home.", "The vendor was real and told {DL} to use the school's name."),
        defendant: [.direct("Who did you work for?", "\"A vendor that sold magazine subscriptions door to door on commission. I got a text offering the work.\""), .direct("Did you say it benefited the school?", "\"I used the school's name because that's how the pitch went. I thought the vendor had an arrangement.\""), .direct("Did you keep the $80?", "\"I kept my commission and passed on the rest. I didn't make up the fundraiser.\""), .direct("How did you get the job?", "\"A vendor texted me offering commission for door-to-door sales. They gave me order forms and a pitch to use.\""), .direct("What were you told to say?", "\"That subscriptions supported a local cause and a school. The vendor said using the school's name would help sales.\""), .direct("How did you handle the money?", "\"I kept my commission and turned the rest in to the vendor. I did not keep any of it for myself.\""), .cross("The principal says there's no fundraiser, doesn't the principal?", "\"That's what I hear. I didn't know.\""), .cross("The slip has no vendor name, does it?", "\"No. It was a basic carbon slip. I didn't think about that.\""), .cross("Neighbors say you gave the same pitch, don't they?", "\"Yes. It was the script I was given.\""), .cross("You used the school's name though it was not running a fundraiser. Isn't that a lie?", "\"I did not know it was untrue. I was following a script I was given.\""), .cross("You had the form made at home, didn't you?", "\"The vendor gave me the forms. I filled in the amounts and names by hand.\"")],
        openings: ("{D} knocked at {V}'s door with an order form for magazines to benefit an elementary school fundraiser, collected $80 cash, and gave a carbon slip. The principal says no such fundraiser exists. The State will show the form, the slip, and the neighbors.", "The defense will point you to a commission salesperson who followed a script from a vendor, another salesperson with the same offer, and no intent to defraud."),
        closings: ("An $80 payment at the door, a school's name on a form, and a principal who says no fundraiser existed. {D} took money from a homeowner on the strength of a school that was never involved.", "{D} followed a script from a vendor and was paid by commission, believing the pitch was real. The State has not proved that {D} knew the school's name was being used without permission."),
        timeline: [(0, "4:30 p.m.: {D} knocks at {V}'s door."), (0, "4:40 p.m.: {V} pays $80."), (1, "{V} calls the school and learns of no fundraiser."), (3, "{V} reports the sale to the Sheriff's Office.")],
        identified: "The signed order form and two neighbors identify {D}.",
        notDone: ["The vendor was never located or interviewed.", "The training sheet was never obtained."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let bridgeRailTagV1 = SmallCases.make(
        key: "story.bridgeRailTag",
        category: .property,
        headlines: ["Stenciled Tag Appears on Underpass Wall Overnight", "County Road Crew Spends Two Days Cleaning Paint From Concrete"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a county, with graffiti, causing damage of $900, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A large stenciled tag appeared on a county underpass wall overnight on {DATE}. The wall had been cleaned a month earlier. The road crew spent two days removing the paint at a cost of $900. A sketchbook found in {D}'s backpack during an unrelated stop shows the same stencil design. {D} says it is a drawing exercise, not the wall.",
        state: [E(.physical, 3, "Stencil", "A cardboard stencil in {D}'s backpack with paint matching the tag."), E(.video, 2, "Underpass Camera", "Two figures with a stencil and spray cans at 1:40 a.m."), E(.document, 2, "Cleanup Invoice", "$900 for two days of pressure washing and paint remover."), E(.document, 2, "Sketchbook", "Drawings of the same stencil with the tag number written in the corner.")],
        defense: [E(.statement, 1, "Drawing Only", "{DL} says the sketches are practice and the stencil was made for a poster."), E(.statement, 1, "Other Artist", "{DL} says several local artists use the same stencil design.")],
        role: "County road supervisor",
        exam: [.direct("What appeared on your underpass wall on {DATE}?", "\"A large stenciled tag appeared overnight. The wall had been cleaned a month earlier. It took two days and $900 to remove.\""), .direct("How was {DL} connected?", "\"A cardboard stencil in {D}'s backpack carries paint matching the tag, and a sketchbook shows the same design with the tag number in the corner.\""), .direct("How did you discover the tag?", "\"A crew member reported it at 7 a.m. The wall had been cleaned a month earlier, and there was a fresh stenciled tag three feet across.\""), .direct("What did the underpass camera capture?", "\"At 1:40 a.m. two figures with a stencil and spray cans. They worked for about ten minutes and left.\""), .direct("What did cleanup involve?", "\"Two days of pressure washing and paint remover. The invoice was $900.\""), .direct("What did the crew do to remove the tag?", "\"We pressure-washed the wall and then used paint remover on the red paint. It took two days and about $900 in materials and labor.\""), .cross("{DL} says the sketches are practice, doesn't {D.he}?", "\"Artists draw stencils. But the paint on the stencil matches.\""), .cross("Do other artists use the same design?", "\"I'm told several do. The design may be shared, which I can't rule out.\""), .cross("Can you identify the two figures?", "\"No. The camera shows two figures only.\""), .cross("Can you see the faces of the two figures?", "\"No. The camera shows silhouettes. I cannot identify either one.\""), .cross("How did you connect {D}?", "\"During an unrelated stop, deputies found a cardboard stencil and a sketchbook in {D}'s backpack.\"")],
        defenseRole: "Local artist",
        defenseExam: [.direct("Are you an artist?", "\"Yes. I'm a local artist. I make posters and stencils.\""), .direct("Do artists share designs?", "\"Often. A good stencil gets copied. Several of us use similar ones.\""), .direct("Do you know {DL}'s work?", "\"Yes. {D} draws and stencils for posters.\""), .direct("What kind of work do you do?", "\"I am a local artist. I make posters, murals, and stencil prints for events and shops.\""), .direct("How common is the design in the sketchbook?", "\"Common among stencil artists in this region. Several of us have copied the same poster that circulated here last year.\""), .direct("How do you know {D}'s work?", "\"{D} draws and stencils for posters, usually on paper and cardboard. I have seen the sketchbooks.\""), .cross("Did you tag the underpass?", "\"No. I wouldn't. I use paper.\""), .cross("Is the design unique to {DL}?", "\"No. It's shared. I've seen it around.\""), .cross("Did you see {DL} that night?", "\"No. I wasn't there. I only know {D}'s art.\""), .cross("Did you see {D} at the underpass?", "\"No. I was at home that night and know nothing about the underpass. I only know {D}'s art.\""), .cross("Would {D} tag a wall?", "\"I have never seen {D} do it. I work on paper, and I do not tag walls myself either, so I cannot speak to it.\"")],
        theory: ("{D} stenciled the wall and kept the stencil.", "{D} drew a design that others also used."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("The red paint on the stencil matches the paint on the wall.", "The design is a copy of a poster that other people stenciled."),
        defendant: [.direct("Why did you have a stencil in your backpack?", "\"I made it for a poster project. It's a design I practice. I carry my art supplies.\""), .direct("Did you tag the underpass?", "\"No. I've never tagged a wall. I do art on paper and posters.\""), .direct("What about the paint on the stencil?", "\"I use spray paint on my posters. Many people use the same color.\""), .direct("What do you do with a stencil and spray paint?", "\"I make posters and wheatpaste art. I use cardboard stencils and aerosol paint for the designs.\""), .direct("Why was the tag number in your sketchbook?", "\"It was a doodle of a design I liked. I wrote a number in the corner the way I label sketches.\""), .direct("Where were you at 1:40 a.m.?", "\"Asleep at home. I did not go near that underpass.\""), .cross("Your sketchbook has the tag number written in the corner, doesn't it?", "\"Yes. It's my doodle. I'm told it matches. I don't know how.\""), .cross("The paint matches the wall, doesn't it?", "\"That's what they say. It's a common color.\""), .cross("You carry a stencil and spray cans, don't you?", "\"Sometimes. For my art. That doesn't make me a vandal.\""), .cross("Your stencil matches the tag. How is that not you?", "\"The design is copied by many local artists. A matching stencil is not unique.\""), .cross("The paint on the stencil matches the wall. Another coincidence?", "\"I use a common color. Many people use the same can.\"")],
        openings: ("A large stenciled tag appeared overnight on a county underpass wall, costing $900 to remove. A stencil with matching paint was in {D}'s backpack, and {D}'s sketchbook shows the same design. The State will show the stencil, the camera, and the invoice.", "The defense will present an artist who draws stencils for posters, a design shared among local artists, and a camera that cannot identify anyone. Listen closely to the witnesses."),
        closings: ("A stencil with matching paint in {D}'s backpack, the same design in {D}'s sketchbook, and two figures on camera at 1:40 a.m.", "A shared stencil design and a sketchbook. The State has not proved {D} was one of the two figures at the wall."),
        timeline: [(0, "1:40 a.m.: two figures use the stencil on the wall."), (0, "7 a.m.: the road crew finds the tag."), (2, "The cleanup is finished and invoiced."), (12, "Deputies find the stencil in {D}'s backpack during an unrelated stop.")],
        identified: "The stencil and the sketchbook found in {D}'s backpack identify {D}.",
        notDone: ["The other walls with the same stencil were never checked.", "No one asked who else owned a copy of the stencil."],
                mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let trainCarTagV1 = SmallCases.make(
        key: "story.trainCarTag",
        category: .property,
        headlines: ["Boxcar Tagged With Stenciled Name and Posted Online", "Rail Yard Camera and Social Post Match Paint Job"],
        law: "injuryPersonalProperty",
        spec: "Willfully defaced property of {V}, a railroad, with graffiti, causing damage of $1,100, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A boxcar parked in a fenced rail yard was covered in a large tag on {DATE}. The yard camera shows {D} with a stencil and spray cans at 1:30 a.m. A photo of the tag appeared on {D}'s social media account at 6 a.m. The railroad paid $1,100 for cleanup. {D} says the yard's side wall is a legal graffiti spot and {D.he} thought the boxcar sat against it.",
        state: [E(.video, 3, "Rail Yard Camera", "{D} paints a stenciled tag across a boxcar at 1:30 a.m."), E(.digital, 3, "Social Media Post", "A photo of the tag posted at 6 a.m. from {D}'s account."), E(.document, 2, "Cleanup Invoice", "$1,100 for solvent washing and repainting."), E(.physical, 2, "Spray Cans", "Six cans in {D}'s car with paint matching the tag.")],
        defense: [E(.statement, 1, "Legal Wall", "{DL} says the side wall is a legal graffiti spot and {D.he} was confused."), E(.document, 1, "City Mural Program", "A page listing the yard's side wall as an approved mural wall.")],
        role: "Rail agent",
        exam: [.direct("What did you find in the rail yard?", "\"A boxcar covered in a large tag. The yard camera shows {D} painting it with a stencil at 1:30 a.m.\""), .direct("What was posted afterward?", "\"A photo of the tag posted at 6 a.m. from {D}'s social media account.\""), .direct("What did the cleanup cost?", "\"$1,100 for solvent washing and repainting. Six spray cans in {D}'s car had matching paint.\""), .direct("How did you learn of the tag?", "\"A crew reported a boxcar sprayed across the side at about 5 a.m. The yard camera showed the painting at 1:30.\""), .direct("What does the camera show?", "\"{D} climbing the fence, pulling out a stencil and six cans, and painting a large tag across a boxcar for about twenty minutes.\""), .direct("What happened afterward?", "\"A photo of the tag appeared on {D}'s social media account at 6 a.m. The railroad paid $1,100 to clean it.\""), .cross("{D} says the side wall is a legal graffiti spot, doesn't {D.he}?", "\"The side wall outside the fence is on the city's mural list. That is fair.\""), .cross("How far was the boxcar from that wall?", "\"About forty feet. The boxcar is inside the fence.\""), .cross("Did {D} climb the fence?", "\"I understand so. The approved wall is outside it.\""), .cross("Where is the approved wall?", "\"On the side wall outside the fence. It is a sanctioned mural spot.\""), .cross("Did {D} ever contact the railroad?", "\"No. We have no record of any request or permission.\"")],
        defenseRole: "Local mural artist",
        defenseExam: [.direct("Is the side wall an approved spot for murals?", "\"Yes. It is on the city's mural list. Artists use it with permission.\""), .direct("Where is the boxcar parked in relation to that wall?", "\"Forty feet from the wall. It sits inside the rail yard fence.\""), .direct("Is the boxcar inside the fence?", "\"Yes. The boxcar is inside the fence. The wall is just outside it.\""), .direct("What do you do with the city mural program?", "\"I am a local mural artist. I work with the city to approve walls and review designs.\""), .direct("Where is the approved wall?", "\"On the side wall of a building next to the rail yard fence. It is outside the fence.\""), .direct("How close is the boxcar?", "\"About forty feet inside the fence. At night it can look like it is against the wall.\""), .cross("Did you see {D} paint the boxcar?", "\"No. I did not see it. I only know about the wall.\""), .cross("Would an artist paint a boxcar inside a fenced yard?", "\"Not with permission. That is not part of the approved spot.\""), .cross("Is the boxcar next to the wall?", "\"Close, in a line of sight. A person could be confused in the dark.\""), .cross("Would an artist climb a fence to paint a boxcar?", "\"Not with permission. That is not part of what the city approves.\""), .cross("You were not at the rail yard that night, were you?", "\"No. I only know the approved wall and the layout of the area. I cannot tell you what happened on the boxcar.\"")],
        theory: ("{D} painted a boxcar inside a fenced yard.", "{D} was at an approved graffiti wall."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had climbed the fence and the approved wall is outside it.", "The approved wall is next to the boxcar and {DL} was confused."),
        defendant: [.direct("Did you paint the tag on the boxcar?", "\"Yes. I thought the boxcar sat against the legal wall. It was dark, and I was confused.\""), .direct("Did you climb the fence?", "\"Yes. I climbed over to reach what I thought was the legal spot.\""), .direct("What was your plan that night?", "\"To paint a mural at a legal graffiti spot I knew about. I went at night so I would not bother anyone.\""), .direct("How did you end up on the boxcar?", "\"In the dark it looked like the boxcar sat against the legal wall. I climbed the fence to get closer and began painting.\""), .direct("Why did you post a photo?", "\"I was proud of the piece. I did not think about the location until the next day.\""), .direct("What did you do right after you finished the tag?", "\"I took a photo and went home. I posted it before I went to bed, and I did not think about what it would mean to put it online.\""), .cross("The approved wall is outside the fence, isn't it?", "\"Yes. I did not understand that at night. I thought the wall was inside.\""), .cross("The boxcar was forty feet from the wall. How could you confuse them?", "\"It was dark. I misjudged the distance.\""), .cross("You posted a photo at 6 a.m. Isn't that bragging?", "\"It was pride. I regret it deeply.\""), .cross("The approved wall is outside the fence. Why climb a fence?", "\"I misjudged the layout. I should have checked in daylight.\""), .cross("You carried six cans and a stencil. Isn't that a plan to tag?", "\"It is a plan to paint. I thought it was legal.\"")],
        openings: ("At 1:30 a.m., a rail yard camera shows {D} painting a stenciled tag across a boxcar inside a fenced yard. {D} posted a photo at 6 a.m., and the cleanup cost $1,100.", "Listen for the defense evidence, which will show that an approved graffiti wall sits next to the yard and that {D} was confused about where it ended."),
        closings: ("A fenced yard, a boxcar tagged on camera, six matching cans in {D}'s car, and a photo posted at dawn. The legal wall is outside the fence.", "A legal wall near the yard, a dark night, and a confused artist. The State must prove {D} knew the boxcar was off limits."),
        timeline: [(0, "1:30 a.m.: {D} paints the boxcar."), (0, "6 a.m.: {D} posts the photo."), (0, "8 a.m.: a rail agent finds the tag."), (1, "The railroad prices the cleanup.")],
        identified: "The yard camera and the social media post identify {D}.",
        notDone: ["The yard's fence line was never measured against the mural wall.", "The boxcar's position on the day was never recorded."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let carHoodDentV1 = SmallCases.make(
        key: "story.carHoodDent",
        category: .property,
        headlines: ["Driver Kicks Car Door in Drive-Through Line After Being Cut Off", "Door Camera Shows Kick That Dented Passenger Door"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, causing damage of $750, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} was waiting in a drive-through line at 12:40 p.m. on {DATE} when {V}'s car cut in ahead of {D}. At the pickup window {D} got out and kicked the passenger door of {V}'s car, leaving a dent. The window camera recorded it. The repair estimate was $750. {D} says {V}'s car had braked and nearly hit {D.him}.",
        state: [E(.video, 3, "Window Camera", "{D} steps out at the pickup window and kicks {V}'s passenger door."), E(.physical, 2, "Dent", "A shoe-sized dent in the passenger door with a scuff of rubber."), E(.document, 2, "Repair Estimate", "$750 to repair and repaint the door."), E(.document, 2, "Order Receipt", "Both cars at the window within a minute at 12:41 p.m.")],
        defense: [E(.statement, 1, "Near Miss", "{DL} says {V}'s car braked suddenly and almost hit {D.him}."), E(.statement, 1, "Cut In Line", "{DL} says {V} cut the line.")],
        role: "Car owner",
        exam: [.direct("What happened at the drive-through window at 12:41 p.m. on {DATE}?", "\"{D}, in line, got out at the pickup window and kicked the passenger door of my car, leaving a dent.\""), .direct("What does the window camera show?", "\"{D} stepping out and kicking my passenger door. Both cars were at the window within a minute.\""), .direct("What did the damage cost?", "\"$750 to repair and repaint the door. There's a shoe-sized dent with a scuff of rubber.\""), .direct("What were you doing at 12:40?", "\"In a drive-through line for lunch. I had just pulled in ahead of {D} where there was a gap.\""), .direct("What happened at the pickup window?", "\"{D} got out of the car behind me and kicked my passenger door. The door dented and left a scuff.\""), .direct("What damage did the door have?", "\"A shoe-sized dent in the panel and a rubber scuff. Repair and repaint were estimated at $750.\""), .cross("{DL} says your car braked suddenly and nearly hit {D.him}, doesn't {D.he}?", "\"I pulled in ahead of {D}. I didn't hit anyone.\""), .cross("Did you cut the line?", "\"I pulled in where I saw a gap. {D} may have thought I cut in. I didn't mean to.\""), .cross("Did you speak to {DL}?", "\"Not before the kick. I was at the window.\""), .cross("Did you brake suddenly in front of {D}?", "\"I slowed to merge. I did not hit {D}'s car.\""), .cross("Did you hear {D} say anything?", "\"No. I was at the window and saw the kick in the mirror.\"")],
        defenseRole: "Customer behind both cars",
        defenseExam: [.direct("Were you in the line?", "\"Yes. I was behind both cars.\""), .direct("What did you see?", "\"{V}'s car pulled in ahead of {D}. {D} looked annoyed.\""), .direct("Did the car brake hard?", "\"I saw it pull in. I can't say how hard it braked.\""), .direct("Where were you in the line?", "\"Behind both cars, close enough to see the window and both drivers clearly. I was waiting for my own order.\""), .direct("What did you see {V}'s car do?", "\"It pulled in ahead of {D} where there was a small gap. {D} looked upset right away.\""), .direct("What happened at the window?", "\"{D} got out and walked to the other car, then kicked the passenger door. It was a quick, hard kick.\""), .cross("Did you see the kick?", "\"Yes. {D} got out and kicked the door.\""), .cross("Did you see a near miss?", "\"No. I did not see a collision or a sudden stop. The cars were close, but I did not see contact.\""), .cross("Did {V} cut the line?", "\"It looked like {V} pulled in where there was not much room. I would call it pushy.\""), .cross("You did not see {D} kick the door, did you?", "\"I saw {D} get out of the car. I was looking at my own order and turned back when I heard the thump.\""), .cross("You cannot say whether the cars touched, can you?", "\"I saw the brake lights come on. I did not see a bump, but I was a few cars back and could not see the bumpers.\"")],
        theory: ("{D} kicked a car door over a line dispute.", "{V} cut the line and nearly caused a crash."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} kicked the door twice.", "{V}'s car did stop short and touch {D}'s bumper."),
        defendant: [.direct("What happened in the line?", "\"{V}'s car cut in ahead of me and braked hard. I thought it would hit me. I was shaken.\""), .direct("Why did you kick the car?", "\"I was angry and scared. I got out at the window and kicked the door. I regret it.\""), .direct("Did you mean to dent the car?", "\"No. I just kicked. I didn't think it would dent.\""), .direct("What did {V}'s car do in the line?", "\"It cut in ahead of me, stopped short, and nearly hit my bumper. I had to jam the brakes.\""), .direct("How did you feel?", "\"Scared and angry. My heart was pounding, and I felt disrespected after waiting in line for ten minutes.\""), .direct("What did you do at the window?", "\"I got out and kicked the door once or twice. I was too angry to think.\""), .cross("The camera shows you kicking the passenger door, doesn't it?", "\"Yes. That's me. I won't deny it.\""), .cross("The dent is shoe-sized, isn't it?", "\"I guess so. I'll pay for it.\""), .cross("You could have honked or called, couldn't you?", "\"Yes. I let my temper win.\""), .cross("Did {V} hit your car?", "\"I think {V} touched my bumper when stopping. I did not check for damage.\""), .cross("Why not honk or call a manager instead?", "\"I know I should have. I let my temper win and I made it worse.\"")],
        openings: ("At a drive-through window, {D} got out and kicked the passenger door of {V}'s car, leaving a dent that cost $750 to repair. The window camera recorded it.", "The defense evidence includes a driver who was cut off in line, who says the other car nearly hit {D.him}, and a customer who saw the cut-in."),
        closings: ("A kick on camera and a shoe-sized dent. Being cut off in line does not give anyone the right to damage a car.", "A cut-in and a near miss pushed {D} to a momentary reaction. The State has not proved {D} meant more than a flash of anger."),
