    static let tireDeflateV1 = SmallCases.make(
        key: "story.tireDeflate",
        category: .property,
        headlines: ["Two Tires Slashed on Neighbor's Work Van After Noise Dispute", "Porch Camera Shows Neighbor With Knife at Van Wheel"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, two tires on a work van, causing damage of $380, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} had argued with {D} the evening before {DATE} about a loud generator running at night. At 2:10 a.m., {D} knelt at the rear wheels of {V}'s work van and slashed two tires with a knife. {V} found the van flat at 6 a.m. The tires cost $380 to replace. {D} says {D.he} was checking the tires and that a nail caused the damage.",
        state: [E(.video, 3, "Porch Camera", "{D} slashes two tires with a knife at 2:10 a.m."), E(.physical, 2, "Tires", "Two tires with clean four-inch cuts in the sidewall."), E(.document, 2, "Replacement Receipt", "$380 for two commercial tires."), E(.statement, 2, "{V}", "Had argued with {D} about the generator the night before.")],
        defense: [E(.statement, 1, "Nail", "{DL} says a nail caused the damage and {D.he} was checking the tires."), E(.document, 1, "Tire Shop Note", "A shop note about a nail found in the tread.")],
        role: "Neighbor",
        exam: [.direct("What can you tell us about your work van and how you use it?", "\"It's a work van I use for my plumbing business. I park it in front of my house every night, and it carries about $3,000 in tools.\""), .direct("What happened the evening before?", "\"{D} and I argued about a loud generator running at night. At 2:10 a.m., the camera shows {D} slashing two tires on my work van.\""), .direct("What did you find at 6 a.m.?", "\"The van was flat, with two tires showing clean four-inch cuts in the sidewall. They cost $380 to replace.\""), .direct("What does the camera show?", "\"{D} kneeling at the rear wheels with a knife.\""), .direct("How did the argument with {D} begin?", "\"{D} runs a loud generator in the evening, and I asked {D} to turn it off at ten. {D} said I had no right to tell {D.him} what to do.\""), .direct("What did you see when you looked at the tires?", "\"The two rear tires were flat to the rims, with clean cuts about four inches long in the sidewalls. Nothing in the tread.\""), .cross("{D} says a nail caused the damage, doesn't {D.he}?", "\"A nail was in one tire's tread. But the cuts are in the sidewall.\""), .cross("Could the cuts have been old?", "\"I cannot say. The tire shop mechanic could not say.\""), .cross("Did {D} threaten you?", "\"No. We argued. That is all.\""), .cross("Did you see {D} touch the van?", "\"Only on the porch camera. It shows {D} kneeling at the rear wheels at about 2:10.\""), .cross("Was the nail the mechanic found in the same tire as a cut?", "\"One tire had a nail in the tread. The cuts were on a different part of the tire.\"")],
        defenseRole: "Tire shop mechanic",
        defenseExam: [.direct("Describe what you do and why you looked at the tires.", "\"I'm a tire shop mechanic. {V} brought the van in that morning, and I inspected both tires and wrote up a note.\""), .direct("Was there a nail in one of the tires?", "\"In one tire, yes. It was in the tread, right where a nail normally goes when a van runs over one.\""), .direct("Can a nail cause a flat on a tire like that?", "\"Yes, in the tread. It would cause a slow leak over time, not a sudden flat like this one.\""), .direct("Were the sidewall cuts caused by that nail?", "\"No. A nail does not make a clean four-inch cut in a sidewall. That kind of cut is made with a blade.\""), .direct("What did you find in the first tire?", "\"A nail in the tread near the center. It would cause a slow leak but not a sudden flat.\""), .direct("What did you find in the sidewall?", "\"A clean cut about four inches long on each tire. They were straight and shallow.\""), .cross("Could the sidewall cuts be old damage?", "\"I cannot say. I would need to know how long the tires were on the van before I could say.\""), .cross("Can a cut like that be made with a utility knife?", "\"Yes. It looks like a clean cut that a knife would make, though I cannot say whose knife.\""), .cross("Do you know who cut the tires?", "\"No. I only know the tires and what the cuts look like. I was not there that night.\""), .cross("Could a nail make those sidewall cuts?", "\"No. A nail leaves a puncture, not a slice.\""), .cross("Could you tell when the cuts were made?", "\"Not exactly. I could say they weren't fresh enough to see debris, but I can't give a date.\"")],
        theory: ("{D} slashed tires after a dispute.", "A nail caused the flats."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} keeps a utility knife in {D.his} pocket.", "A nail was in the tread and the cuts were old."),
        defendant: [.direct("Did you slash {V}'s tires?", "\"No. I was only checking the tires. A nail in the tread caused the damage, and I was looking at the leak.\""), .direct("Why were you kneeling at the wheels at 2 a.m.?", "\"I thought I heard a leak coming from the van. I got down to look at the tires with my knife in hand.\""), .direct("Do you normally carry a knife?", "\"A utility knife, in my pocket. I use it for work every day, and I had it on me that night.\""), .direct("Tell us what you were doing at 2 a.m.", "\"I was walking home from a late shift when I heard a hiss near my neighbor's van. I knelt to see if a tire was leaking.\""), .direct("How did you feel about the argument the night before?", "\"I was irritated, but it was a small disagreement. I'd never damage someone's van over a generator.\""), .direct("Why did you have your knife in your hand?", "\"I keep a utility knife in my pocket for work. I took it out to cut a plastic tie that was caught on the wheel.\""), .cross("The cuts are in the sidewall, not in the tread, aren't they?", "\"So the mechanic says. I believe the cuts may have been old, and I did not make them.\""), .cross("You had argued with {V} the night before, hadn't you?", "\"Yes, about the generator. I was upset about it, but I would never slash anyone's tires over that.\""), .cross("The camera shows you with a knife at the tires. How is that checking?", "\"I was using the knife to look closely. I know how it looks on camera, and I am sorry for that.\""), .cross("Clean four-inch cuts in the sidewall look like a knife, don't they?", "\"They do. I didn't make them, and I believe they were already there.\""), .cross("You were kneeling at the wheels at 2 a.m., after an argument. Isn't that a coincidence?", "\"It's a coincidence. I was checking the sound, and I should have knocked on the door.\"")],
        openings: ("After an argument over a loud generator, {D} knelt at the rear wheels of {V}'s work van at 2:10 a.m. and slashed two tires with a knife. The tires cost $380 to replace.", "Weigh the defense proof, which will show that a nail was in one tire, that the cuts may have been old, and that {D} was only checking the tires."),
        closings: ("An argument the night before, a knife at the tires on camera at 2:10, and two sidewall cuts that a nail does not make. {D} slashed the tires.", "A nail in the tread and cuts that could be old. The State must prove {D} cut those tires, and a camera at night is not clear on what was happening."),
        timeline: [(-1, "{D} and {V} argue about the generator."), (0, "2:10 a.m.: {D} cuts the tires."), (0, "6 a.m.: {V} finds the van flat."), (1, "The tire shop writes its note.")],
        identified: "The porch camera identifies {D}.",
        notDone: ["The knife was never compared with the cuts.", "The generator argument was never put to the other neighbors."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let windowEggV1 = SmallCases.make(
        key: "story.windowEgg",
        category: .property,
        headlines: ["Golf Balls Hit Neighbor's Sunroom Glass Three Times in an Afternoon", "Neighbor Camera Shows Chip Shots Over the Fence"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, glass panels in a sunroom, causing damage of $780, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 4 p.m. on {DATE}, {D} hit golf balls from a back lawn toward a wooden fence. Three shots cleared the fence and cracked three panels of {V}'s sunroom glass. {V}'s camera recorded the shots. The panels cost $780 to replace. {D} says the shots were stray and unintended.",
        state: [E(.video, 3, "Neighbor Camera", "Three balls clear the fence and strike the sunroom glass between 4:02 and 4:18 p.m."), E(.physical, 2, "Golf Balls", "Three balls with {D}'s initials found in the sunroom."), E(.document, 2, "Replacement Estimate", "$780 for three glass panels."), E(.statement, 2, "{V}", "Heard three bangs and found cracked panels.")],
        defense: [E(.statement, 1, "Stray Shots", "{DL} says the shots were stray and {D.he} did not know where they went."), E(.document, 1, "Practice Plan", "A note about chip shot practice at home.")],
        role: "Neighbor",
        exam: [.direct("Please tell us about your sunroom.", "\"It's a glass sunroom on the back of my house. I use it as an office, and the fence runs about twenty feet from the glass.\""), .direct("What happened to your sunroom?", "\"Three glass panels cracked between 4:02 and 4:18 p.m. I heard three bangs and found cracked panels.\""), .direct("What does your camera show?", "\"Three golf balls clearing the fence from {D}'s lawn and striking the glass.\""), .direct("What was found in the sunroom?", "\"Three balls with {D}'s initials. The panels cost $780 to replace.\""), .direct("What did you hear that afternoon?", "\"Three loud bangs, about eight minutes apart. I found three cracked panels and a golf ball on the floor each time.\""), .direct("How did you identify the balls?", "\"They had initials in marker. A deputy matched them to {D}, who lives behind the fence.\""), .cross("{D} says the shots were stray, doesn't {D.he}?", "\"I know that is what {D} says. Balls do clear that fence with a chip shot.\""), .cross("Can {D} see your sunroom from the lawn?", "\"Not from the lawn. It is behind the fence.\""), .cross("Did {D} stop after the first ball?", "\"No. {D} kept hitting after the first ball broke the glass.\""), .cross("Did you speak to {D} after the first ball?", "\"No. I didn't know who was hitting them. I called after the third.\""), .cross("How high is the fence?", "\"About six feet. A chip shot would have to clear it by a good margin.\"")],
        defenseRole: "Neighbor who golfs",
        defenseExam: [.direct("Tell us how you know {D}.", "\"I'm a neighbor and also a golfer. {D} and I have chipped in each other's yards before.\""), .direct("Do golf balls clear that fence?", "\"Sometimes, with a chip shot. I have found balls in my own yard that came from that direction.\""), .direct("Is the sunroom visible from {D}'s back lawn?", "\"Not from the lawn. The fence blocks the view, so a golfer could not see the glass from there.\""), .direct("Did you hear glass break that afternoon?", "\"Yes. I heard it from my porch, a sharp crack, and then I heard a couple more bangs after it.\""), .direct("How easily do balls clear the fence?", "\"With a chip shot, they clear it often. I've hit balls over it myself.\""), .direct("Can you see the sunroom from {D}'s lawn?", "\"No. A tall fence and a tree block it, and you'd have to walk to the corner.\""), .cross("Did {D} stop after the first ball hit the glass?", "\"I do not know. I did not see {D} that afternoon, and I could not tell what {D} heard.\""), .cross("Would a careful golfer check where balls land before hitting more?", "\"A careful one would, yes. That is basic courtesy when you are hitting toward a fence near houses.\""), .cross("Do you play golf with {D} at all?", "\"No. I golf too, but not with {D}. I only know the layout of the yards back there.\""), .cross("Would you check where a ball landed before hitting another?", "\"I would, and I'd check after the first one. {D} didn't.\""), .cross("Did you see {D} hit the three balls?", "\"No. I heard the glass from my porch, but I didn't see {D}.\"")],
        theory: ("{D} kept hitting balls toward a neighbor's house.", "{D} hit stray shots."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} kept hitting after the first ball broke the glass.", "{DL} could not see the sunroom behind the fence."),
        defendant: [.direct("Did you hit golf balls over the fence?", "\"Yes, three. I was practicing chip shots toward a fence. I did not know the sunroom was behind it.\""), .direct("Could you see the sunroom?", "\"No. The fence blocked it. I did not know there was glass behind it.\""), .direct("Did you stop after the first ball?", "\"I did not know it broke anything. I kept hitting. I regret that.\""), .direct("Describe what you were doing.", "\"Practicing chip shots into a net, and sometimes aiming at a spot on the fence. I do it most afternoons.\""), .direct("Why didn't you know the balls were hitting the sunroom?", "\"The fence blocks the view. I only knew they cleared it and landed somewhere in the yard behind.\""), .direct("What did you do when the neighbor called?", "\"I apologized and offered to pay. I'd had no idea the glass broke.\""), .cross("You kept hitting after the first ball broke the glass, didn't you?", "\"I did not hear glass. I heard a bang I thought was the fence.\""), .cross("Your initials are on the balls, aren't they?", "\"Yes. They are my balls.\""), .cross("You hit three balls into a neighbor's sunroom. Was that careless?", "\"Yes. I should have been more careful about where I aimed.\""), .cross("Three balls, each followed by a crack. Didn't you wonder?", "\"I heard bangs but I thought they hit the fence. I should have stopped.\""), .cross("You kept hitting after the first ball. Isn't that careless?", "\"It was. I should have checked.\"")],
        openings: ("At 4 p.m., {D} hit golf balls from a back lawn toward a wooden fence. Three shots cleared the fence and cracked three panels of {V}'s sunroom glass, and a camera recorded each one.", "Jurors will hear that {D} could not see the sunroom behind the fence and that the shots were stray, with no intent to damage anything."),
        closings: ("Three balls over a fence, three cracked panels, balls with {D}'s initials found in the sunroom, and $780 in damage. {D} kept hitting.", "A chip shot practice, a fence that blocked the view, and a stray ball. The State must prove {D} meant to hit the sunroom."),
        timeline: [(0, "4:02 p.m.: the first ball hits the glass."), (0, "4:10 p.m.: the second."), (0, "4:18 p.m.: the third."), (1, "{V} gets the replacement estimate.")],
        identified: "The balls carry {D}'s initials.",
        notDone: ["The fence height was never measured.", "The ball flight angles were never reconstructed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let doorKickV1 = SmallCases.make(
        key: "story.doorKick",
        category: .property,
        headlines: ["Upstairs Resident Kicks Neighbor's Door and Breaks Deadbolt at 2 a.m.", "Apartment Door Splinters After Noise Complaint Argument"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a door and deadbolt, causing damage of $450, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} banged on a neighbor's door at 2 a.m. on {DATE} to complain about music. When {V} did not answer, {D} kicked the door twice and broke the deadbolt plate. {V} called the manager. The repair of the door and deadbolt cost $450. {D} says {D.he} heard a shout inside and thought someone was hurt.",
        state: [E(.video, 3, "Hallway Camera", "{D} kicks the door twice at 2:08 a.m. and the frame splinters."), E(.physical, 2, "Door and Deadbolt", "A split frame and a bent deadbolt plate."), E(.document, 2, "Repair Estimate", "$450 to replace the frame and deadbolt."), E(.statement, 2, "{V}", "Was home and did not shout.")],
        defense: [E(.statement, 1, "Heard a Shout", "{DL} says {D.he} heard a shout and thought someone needed help."), E(.document, 1, "Noise Complaint", "A complaint from {D} to the manager about music two days earlier.")],
        role: "Neighbor",
        exam: [.direct("Describe your apartment and how it's laid out for the jury.", "\"I live in a second-floor apartment. The hallway camera covers my door, and I keep a television in the living room.\""), .direct("What happened at your door at 2 a.m. on {DATE}?", "\"{D}, a neighbor, banged on my door to complain about music. When I did not answer, {D} kicked the door twice and broke the deadbolt plate.\""), .direct("What does the hallway camera show?", "\"{D} kicking the door at 2:08 a.m. and the frame splintering. I was home and I did not shout.\""), .direct("What did it cost to repair?", "\"$450 to replace the frame and deadbolt. I called the manager right after.\""), .direct("What did {D} say when {D.he} knocked?", "\"{D} shouted that the music was too loud and asked me to turn it down. I hadn't heard any music, and I stayed quiet.\""), .direct("What happened next?", "\"{D} kicked the door twice. The frame splintered and the deadbolt plate bent, and I called the manager.\""), .cross("{DL} says {D.he} heard a shout and thought someone needed help, doesn't {D.he}?", "\"I didn't shout. If someone heard a noise, it wasn't me.\""), .cross("Did {DL} complain about your music before?", "\"Yes, there was a complaint to the manager two days earlier. I didn't think it was serious.\""), .cross("Was anything playing inside?", "\"I may have had the television on. I can't say what was on at that hour.\""), .cross("Was music playing that night?", "\"A movie may have been on, but not loudly. I didn't hear anything shouting.\""), .cross("Had {D} complained about noise before?", "\"Yes, twice, and left a note. I didn't get a chance to respond.\"")],
        defenseRole: "Third-floor neighbor",
        defenseExam: [.direct("Walk us through what you heard from the third floor.", "\"I live above {V}. At about two I heard banging on the door and then a loud crack.\""), .direct("Do you live above {V}?", "\"Yes, on the third floor. I hear most of what goes on in this hallway.\""), .direct("What did you hear that night?", "\"Banging and then a loud crack. I looked out and saw {D} at {V}'s door.\""), .direct("Was music playing?", "\"Some, earlier. By then it was quiet. I heard voices, maybe a television.\""), .direct("Was there music at that hour?", "\"It had quieted by then. I heard a television, not music.\""), .direct("Did you see {D}?", "\"I looked out and saw {D} at the door. {D} looked upset and was knocking.\""), .cross("Did you see the kicks?", "\"I heard them. I saw the door afterward.\""), .cross("Did you hear a shout from inside?", "\"I heard something that could have been from a television. I couldn't tell.\""), .cross("Did you call anyone?", "\"No. I thought it would stop, and it didn't.\""), .cross("You did not hear a shout from inside {V}'s apartment, did you?", "\"No. I heard music and then banging. If someone had shouted for help, I would have remembered, and I did not hear that.\""), .cross("You did not see {D} kick the door, did you?", "\"No. I was on the third floor and only heard thumps. I looked out when I heard the manager and saw the broken frame.\"")],
        theory: ("{D} kicked in a door over noise.", "{D} heard a shout and acted."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had complained twice before and left a note on the door.", "A television inside was playing a movie with shouting."),
        defendant: [.direct("Why did you go to {V}'s door at 2 a.m.?", "\"I was bothered by the music, but when I got there I heard a shout inside. I thought someone was hurt.\""), .direct("Did you mean to damage the door?", "\"No. I wanted to get in to check. I'm sorry about the frame.\""), .direct("Tell us what you heard.", "\"I was in bed when I heard what sounded like a shout from {V}'s apartment. I got up and went to the door.\""), .direct("Why did you kick the door?", "\"I knocked and no one answered. I thought someone was hurt and I wanted to get in.\""), .direct("What did you do when {V} called the manager?", "\"I told the manager what I'd heard and offered to pay. I was embarrassed.\""), .direct("How long were you awake before you went to the door?", "\"About two hours. I tried earplugs and a pillow, and then I decided I had to say something before I lost the night's sleep.\""), .cross("The complaint you made was about music, wasn't it?", "\"Yes. Two days earlier. That's why I went there. But I heard a shout.\""), .cross("{V} says there was no shout, doesn't {V.he}?", "\"That's what {V} says. It sounded real to me. It may have been a movie.\""), .cross("You could have called the manager or deputies, couldn't you?", "\"Yes. I know I should have. I reacted without thinking.\""), .cross("You'd complained about music two days earlier. Isn't that why you went?", "\"It's why I was awake. When I heard the shout, I thought it was serious.\""), .cross("You could have called 911. Why kick?", "\"I panicked. I should have called.\"")],
        openings: ("At 2 a.m., {D} banged on {V}'s door about music, and when {V} did not answer, kicked it twice, splitting the frame and bending the deadbolt plate, a $450 repair. The hallway camera shows it.", "Jurors will also see a neighbor who heard a shout from inside, thought someone was hurt, and kicked the door out of alarm. Listen closely to the witnesses."),
        closings: ("Two kicks at 2:08 a.m., a split frame, a bent deadbolt, and a $450 repair. {V} was home and did not shout. The camera shows what {D} did.", "A shout, a television, and a late-night worry. The State has not proved {D} meant to damage the door rather than help."),
        timeline: [(0, "2:05 a.m.: {D} knocks on the door."), (0, "2:08 a.m.: {D} kicks the door."), (0, "2:15 a.m.: {V} calls the manager."), (1, "The manager sends the hallway video.")],
        identified: "The hallway camera identifies {D}.",
        notDone: ["The television and its volume were never checked.", "No one asked other neighbors about the shouting before the kick."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let shutterTearV1 = SmallCases.make(
        key: "story.shutterTear",
        category: .property,
        headlines: ["Trellis and Window Boxes Pulled From Neighbor's Wall After Boundary Survey", "Porch Camera Shows Neighbor Tearing Out Wall Fixtures"],
