        summary: "A surveyor marked the boundary between {D}'s and {V}'s houses at 9 a.m. on {DATE}. At 3 p.m., {D} pulled a trellis and two window boxes off {V}'s wall, saying they crossed the line. {V}'s camera recorded the work. The trellis and boxes cost $450 to replace. {D} says the survey line proved the fixtures were on {D.his} side.",
        state: [E(.video, 3, "Porch Camera", "{D} pulls the trellis and two window boxes off the wall at 3 p.m."), E(.document, 3, "Survey Plat", "The wall and the fixtures lie 14 inches inside {V}'s line."), E(.document, 2, "Replacement Receipt", "$450 for a trellis and two window boxes."), E(.statement, 2, "{V}", "Never agreed to move the fixtures.")],
        defense: [E(.statement, 1, "Survey Line", "{DL} says the survey line showed the fixtures were on {D.his} side."), E(.document, 1, "Surveyor Sketch", "A field sketch with a stake on the wall.")],
        role: "Neighbor",
        exam: [.direct("Tell the jury about the trellis and window boxes.", "\"I built the trellis and window boxes six years ago. They're attached to my wall and I planted climbing roses.\""), .direct("What did a surveyor do on that date?", "\"Marked the boundary between my house and {D}'s at 9 a.m. The plat shows the wall and fixtures 14 inches inside my line.\""), .direct("What did {D} do at 3 p.m.?", "\"{D} pulled a trellis and two window boxes off my wall, saying they crossed the line. My porch camera recorded it.\""), .direct("What did the replacements cost?", "\"$450 for a trellis and two window boxes. I never agreed to move the fixtures.\""), .direct("What did the survey show?", "\"The line runs fourteen inches inside my property from the wall. The fixtures are on my side.\""), .direct("What did {D} do at 3 p.m.?", "\"{D} came onto my wall with a pry bar and pulled off the trellis and both boxes. I watched it on my porch camera.\""), .cross("{D} says the survey line proved the fixtures were on {D.his} side, doesn't {D.he}?", "\"The surveyor's stake was set on the wall, not on the line. That may have caused confusion.\""), .cross("Did {D} get a copy of the plat?", "\"No. It was delivered to me.\""), .cross("Were you told the fixtures could stay?", "\"I think {D} was told the fixtures could stay. {D} tore them out anyway.\""), .cross("Did {D} ask you before removing them?", "\"No. I wasn't home, and {D} didn't call.\""), .cross("Did you tell {D} the fixtures could stay?", "\"I said so a year earlier. {D} didn't object.\"")],
        defenseRole: "Surveyor's helper",
        defenseExam: [.direct("Tell the jury what you do for the surveyor.", "\"I'm the surveyor's helper. I set stakes and hold the rod while the surveyor shoots the line.\""), .direct("Where did the surveyor's stake go on that wall?", "\"On the wall. It was set at the wall, not at the actual property line, which was 14 inches farther in.\""), .direct("What did the plat show about the property line?", "\"Fourteen inches in from the wall. The fixtures sit inside {V}'s line, and the plat shows that clearly.\""), .direct("Did {D} receive a copy of the plat that morning?", "\"No, {D} did not. The plat went to {V}, and nobody handed {D} a copy at the site.\""), .direct("Where did you put the stake that morning?", "\"On the wall of {V}'s house, as a reference point. It marked a corner, not the boundary.\""), .direct("How was the line marked?", "\"With flags fourteen inches in from the wall. The stake itself wasn't the line.\""), .cross("Did you explain the meaning of the stake to {D}?", "\"No. I did not explain it. I should have, because a stake on a wall looks like the line.\""), .cross("Could {D} have misread the stake as the boundary line?", "\"Yes, easily. A stake set on a wall looks just like a boundary marker to anyone who has not seen the plat.\""), .cross("Did anyone tell {D} the fixtures could stay for now?", "\"I think someone said they could stay for now. I do not recall exactly who said it, or when.\""), .cross("Did you explain the stake to {D}?", "\"No. I assumed it was understood, and I own that.\""), .cross("Could {D} have thought the stake was the line?", "\"I suppose so. A stake on a wall looks official.\"")],
        theory: ("{D} tore down fixtures despite a plat.", "{D} acted on a survey stake."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had been told the fixtures could stay and tore them out anyway.", "The surveyor's stake was set on the wall, not the line."),
        defendant: [.direct("Did you pull the trellis and window boxes off {V}'s wall?", "\"Yes, I did. I believed they crossed onto my side, based on the surveyor's stake that I saw on the wall.\""), .direct("Why did you believe the fixtures were on your side?", "\"The stake was on the wall, and I thought that stake was the property line. I did not see the plat.\""), .direct("Did you ever receive a copy of the survey plat?", "\"No. I never saw it. All I saw was the stake and the paint, and I acted on that alone.\""), .direct("Tell the jury about the survey.", "\"A surveyor marked the line that morning and put a stake on the wall. I took that to mean the line ran there.\""), .direct("What did you believe about the fixtures?", "\"That they crossed onto my side. I thought the stake proved it.\""), .direct("What did you do with them?", "\"I pulled them off and put them in my yard. I didn't throw them away.\""), .cross("You were told the fixtures could stay, weren't you?", "\"I was told something like that. I did not trust it, because I believed the line said otherwise.\""), .cross("The plat puts the line 14 inches inside {V}'s side, doesn't it?", "\"I know that now. I did not know it then, and I regret acting before I understood.\""), .cross("You tore them out the same day the surveyor marked the line, didn't you?", "\"Yes. I was angry and in a hurry. I should have waited and asked someone to explain it to me.\""), .cross("You never saw the plat. Why act on a stake?", "\"It was the only mark I saw. I should have asked.\""), .cross("You were told they could stay. Why remove them?", "\"I didn't think that applied after the survey.\"")],
        openings: ("A surveyor marked the boundary between {D}'s and {V}'s houses at 9 a.m., and at 3 p.m. {D} pulled a trellis and two window boxes off {V}'s wall, saying they crossed the line. The plat puts them 14 inches inside {V}'s side.", "By the end of this trial, the proof will show that the surveyor's stake was set on the wall and not the line and that {D} never received the plat."),
        closings: ("A survey that morning, a trellis and window boxes torn off that afternoon, and a plat that puts them on {V}'s side. {D} acted before asking.", "A stake set on the wall, a plat {D} never saw, and a good-faith belief. The State must prove {D} knew the fixtures were {V}'s."),
        timeline: [(0, "9 a.m.: the surveyor sets stakes."), (0, "3 p.m.: {D} pulls the trellis and boxes."), (0, "5 p.m.: {V} finds the damage."), (2, "{V} gets the replacement quote.")],
        identified: "The porch camera identifies {D}.",
        notDone: ["The plat was never delivered to {DL}.", "The stake's position was never rechecked after the dispute."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fenceFlattenV1 = SmallCases.make(
        key: "story.fenceFlatten",
        category: .property,
        headlines: ["Pickup Reverses Through Backyard Fence at Dawn and Keeps Going", "Trail of Paint and Splinters Leads to Neighbor Down the Road"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a fence and gate, causing damage of $1,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 5:30 a.m. on {DATE}, a pickup backed out of {V}'s alley, caught the corner of the backyard fence and kept going, snapping eight panels and a gate. The doorbell camera recorded the truck's taillights and a partial plate. Paint on the splintered boards matched {D}'s truck at a house four blocks away. {D} says {D.he} never felt a bump.",
        state: [E(.video, 3, "Doorbell Camera", "A pickup with a partial plate reverses through the fence at 5:30 a.m."), E(.physical, 3, "Paint Transfer", "Blue paint on the boards matches the damage on {D}'s truck bumper."), E(.document, 2, "Repair Estimate", "$1,200 for eight panels and a gate."), E(.statement, 2, "{V}", "Found the fence flat at 6 a.m.")],
        defense: [E(.statement, 1, "Felt Nothing", "{DL} says {D.he} felt nothing and was listening to the radio."), E(.document, 1, "Work Schedule", "{DL} starts work at 6 a.m. and leaves home before dawn.")],
        role: "Homeowner",
        exam: [.direct("What can you tell us about your fence and where it is?", "\"It's a six-foot wood privacy fence along my alley. The alley is narrow and trucks sometimes brush it.\""), .direct("What did you find at 6 a.m. on {DATE}?", "\"My backyard fence flat, with eight panels and a gate broken. The repair estimate is $1,200.\""), .direct("What does your doorbell camera show?", "\"A pickup with a partial plate reversing through the fence at 5:30 a.m. and driving on.\""), .direct("How was {DL} connected?", "\"Blue paint on the splintered boards matches damage on the bumper of {D}'s truck at a house four blocks away.\""), .direct("What did your doorbell camera record?", "\"A pickup reversing at about 5:30 a.m. through the corner of the fence. The taillights glow and the plate is partly visible.\""), .direct("What did deputies find?", "\"Blue paint on the broken boards and on a truck bumper four blocks away. It matched {D}'s truck.\""), .cross("{DL} says {D.he} never felt a bump, doesn't {D.he}?", "\"A truck going through eight panels makes noise, but I can't say what's felt in the cab.\""), .cross("Is the alley tight?", "\"Yes. It's narrow. Trucks brush fences sometimes.\""), .cross("Can you see the driver on the camera?", "\"No. I see taillights and a partial plate.\""), .cross("Could someone brush a fence without feeling it?", "\"Maybe, but this was eight panels and a gate. It was a lot of noise.\""), .cross("How did the truck behave after it hit the fence?", "\"It paused for a moment and then drove forward. It didn't stop.\"")],
        defenseRole: "Neighbor on the same alley",
        defenseExam: [.direct("Tell us how you know {D}.", "\"I live on the same alley. I see {D}'s truck leave most mornings before dawn, and we've talked about how tight the alley is.\""), .direct("Do you live on the same alley?", "\"Yes. I know how tight it is, because I drive it every morning and I've scraped my own mirrors on that fence.\""), .direct("Did you hear anything that morning?", "\"No. I was asleep until {V} knocked on my door and told me about the fence.\""), .direct("Can a truck really brush a fence in that alley?", "\"Yes, easily. I've done it with my own car and not noticed until later.\""), .direct("What did you hear that morning?", "\"Nothing. I was asleep, and I only learned about the fence from {V}.\""), .direct("How wide is the alley behind {V}'s house?", "\"Barely wider than a truck. Mirrors brush the fences, and I have scraped my own fender on that corner more than once.\""), .cross("Did you see {DL}'s truck?", "\"I see it most mornings leaving before dawn.\""), .cross("Did {DL} work early?", "\"Yes. {D} leaves before six most mornings, and I've seen the truck pull out in the dark.\""), .cross("Would a driver miss eight panels?", "\"I'd think it would be noticeable. I can't say what {D} felt.\""), .cross("Do you know if {D} noticed the fence and kept going?", "\"No. I wasn't there, and {D} never told me.\""), .cross("You did not see the truck hit the fence, did you?", "\"No. I was asleep. I only know the alley and the morning noise, and I cannot say what happened at 5:30.\"")],
        theory: ("{D} backed through a fence and left.", "{D} felt nothing and drove on."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} noticed the fence and kept going to avoid being late.", "The alley is so tight that a truck can brush a fence without a bump."),
        defendant: [.direct("Were you backing out of that alley?", "\"I back out of my alley every morning for work. I leave before dawn, and I was listening to the radio.\""), .direct("Did you feel the fence?", "\"No. I felt nothing. If I'd felt it, I would have stopped.\""), .direct("Did you know about the damage?", "\"Not until deputies came. I was shocked.\""), .direct("What can you tell us about your morning routine?", "\"I leave before dawn for a six o'clock shift. I back out of my alley, and the radio is usually on.\""), .direct("Did you hear or feel anything that morning?", "\"No. I didn't hear a crash or feel a bump. I'd have stopped.\""), .direct("What did you do when deputies came?", "\"I told them I hadn't noticed. I offered to pay for the fence.\""), .cross("The blue paint on the boards matches your bumper, doesn't it?", "\"That's what they say. It's a common color. I'm not sure how it got there.\""), .cross("You start work at 6 a.m., don't you?", "\"Yes. I was in a hurry that morning, as always.\""), .cross("Your truck has damage on the bumper, doesn't it?", "\"Yes. I didn't notice when it happened. I thought it was an old dent.\""), .cross("The paint on your bumper matches. How does that happen?", "\"I don't know. The alley is tight, and I may have brushed it without feeling it.\""), .cross("You were in a hurry. Isn't that why you didn't check?", "\"I was in a hurry. I didn't know there was anything to check.\"")],
        openings: ("At 5:30 a.m., a pickup backed out of an alley, caught {V}'s fence, and snapped eight panels and a gate, a $1,200 repair. Blue paint on the boards matches the bumper of {D}'s truck. The State will show the camera and the paint.", "The defense will point you to a narrow alley where trucks brush fences, a driver who felt nothing with the radio on, and a neighbor who confirms how tight it is."),
        closings: ("A truck through a fence, a partial plate on camera, and blue paint on the boards that matches {D}'s bumper. {D} drove on and left {V} with the repair.", "A tight alley, a radio, and a bump no one felt. The State has not proved {D} knew the fence was hit."),
        timeline: [(0, "5:30 a.m.: the pickup backs through the fence."), (0, "6 a.m.: {V} finds the fence flat."), (1, "Deputies match the paint to {D}'s truck."), (3, "{V} gets the repair estimate.")],
        identified: "The paint ties the fence to {D}'s truck.",
        notDone: ["No one measured the alley or the truck's turning path.", "The truck's bumper was never examined for fence paint."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let drunkPorchBellV1 = SmallCases.make(
        key: "story.drunkPorchBell",
        category: .publicOrder,
        headlines: ["Neighbor Throws Gravel at Bedroom Window and Shouts at 1 a.m.", "Doorbell Camera Catches Drunk Neighbor Looking for Dog"],
        law: "disorderly",
        spec: "Disturbed the peace of {V}, at {V.his} home, by shouting and throwing gravel at a window, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 1 a.m. on {DATE}, {D} stood in {V}'s front yard shouting and threw gravel at the bedroom window. The doorbell camera recorded {D} for twenty minutes. {V} called deputies at 1:20 a.m. {D}, who lives next door, says {D.he} was looking for a lost dog and was not drunk.",
        state: [E(.video, 3, "Doorbell Camera", "{D} shouts in the front yard and throws gravel at the window from 1:02 to 1:20 a.m."), E(.statement, 2, "{V}", "Woke to gravel against the window and shouting."), E(.document, 2, "Deputy's Report", "Smelled alcohol on {D}'s breath and took the report at 1:35 a.m."), E(.physical, 1, "Gravel", "Handfuls of gravel on the flower bed and window sill.")],
        defense: [E(.statement, 1, "Lost Dog", "{DL} says {D.he} was looking for a lost dog and thought the dog was in the yard."), E(.document, 1, "Lost Dog Post", "A neighborhood post about a missing dog the same night.")],
        role: "Neighbor",
        exam: [.direct("What woke you up in the early hours of {DATE}?", "\"A sharp rattling on my bedroom window, like hail, and then a voice shouting out in the front yard. I looked at the clock and it was just after one in the morning.\""), .direct("Who did you see when you looked outside?", "\"I stayed back from the glass, but the porch light was on and I recognized {D}, who lives in the house next to mine. {D} was standing in the flower bed with a fistful of gravel.\""), .direct("What was being shouted?", "\"I couldn't make out words through the glass. It was loud and slurred and went on and on, and every minute or two another handful of gravel hit the window.\""), .direct("How long did this go on before you called anyone?", "\"I watched my doorbell camera on my phone for a while, hoping it would stop. When it hadn't after about eighteen minutes, I called the Sheriff's Office at 1:20.\""), .direct("What did the deputy do when the deputy arrived?", "\"The deputy talked to {D} on the sidewalk and then came to my door at about 1:35 to take my statement. The deputy photographed the gravel on my windowsill and in the flower bed.\""), .direct("What did the doorbell footage show?", "\"It shows {D} come into the yard at 1:02, shout toward the house, and throw gravel in handfuls until I called at 1:20. I sent the clip to the deputy the next day.\""), .cross("{DL} says {D.he} was looking for a lost dog. Did you know that night that a dog was missing?", "\"No. Nobody told me anything until the next morning, when I saw a post about a missing dog on the neighborhood page. I did not see a dog in my yard on the video.\""), .cross("Did {DL} threaten you or say anything about harming you?", "\"Not that I could understand. I heard a lot of volume and no clear sentence. I was frightened because of the hour and the gravel, not because of a specific threat.\""), .cross("Did any of the gravel break your window?", "\"No, the glass held. It rattled and left a few tiny scuffs I could see in daylight, but nothing cracked, and nothing was damaged inside the house.\""), .cross("Did {DL} ever ring your doorbell or knock on your door?", "\"Not that the camera shows. The doorbell is right by the front door and {D} never walked up to it. {D} stayed out in the yard near the bedroom side.\""), .cross("You and {DL} have lived next door to each other for years. Have you ever had trouble before?", "\"We aren't close, but there has never been any trouble. I would wave and that was all. Nothing like this had happened before that night.\"")],
        defenseRole: "Friend from the cookout",
        defenseExam: [.direct("How do you know {D}?", "\"We have been friends for years. I was at the same cookout the evening of {DATE}, and we stood in the same circle of lawn chairs for most of it.\""), .direct("Did {D} mention a dog that night?", "\"Yes. {D} talked about the dog a couple of times, saying {D.he} had left the dog in the back yard and hoped the gate was latched. {D.He} seemed a little worried about it.\""), .direct("When did {D} leave the cookout?", "\"Around midnight. {D} said goodnight to the host and walked off down the street toward home, which was only a few minutes away on foot.\""), .direct("Did you see anything about a missing dog afterward?", "\"The next morning I saw a post on the neighborhood page with a photo of {D}'s dog and a plea to call if anyone had seen it. A few people commented.\""), .direct("What kind of dog is it?", "\"A mid-sized brown mutt with a gray muzzle, maybe twelve years old. It follows {D} everywhere, so it is very unlike that dog to be missing.\""), .direct("How did {D} seem when you spoke with {D.him} afterward?", "\"Embarrassed. {D.He} told me what had happened with the gravel and said it was a dumb way to ask for help. {D.He} wasn't bragging about it at all.\""), .cross("You were at the cookout. Was {D} drinking?", "\"We all were. I saw {D} with a few beers over the course of the evening. I did not count them, and I won't claim to know exactly how many {D.he} had.\""), .cross("You didn't see what {D} did after leaving, did you?", "\"No. I stayed at the cookout another hour or so. Everything I know about the yard and the gravel comes from {D} and from what I later saw posted.\""), .cross("Did you see the dog at the cookout?", "\"No, the dog stayed home. I only know that the dog was gone from what {D} told me and from the neighborhood post the next day.\""), .cross("Did you help {D} look for the dog that night?", "\"No. I went home to bed. I did not know anything was wrong until the next morning, so I can't say what the search looked like.\""), .cross("Isn't it true you would not want to see a friend convicted?", "\"I'd be sorry for anyone in that position. But I'm here to say what I saw and heard, and I have kept it to that. I did not see the yard.\"")],
        theory: ("{D} shouted and threw gravel at a home.", "{D} was looking for a lost dog."),
        allocution: "\"It was childish, and I know it.\"",
        truths: ("{DL} had been drinking at a cookout that evening.", "{DL}'s dog really was missing."),
        defendant: [.direct("Why were you in {V}'s front yard at one in the morning?", "\"My dog had gotten out of the back yard sometime that evening and I couldn't find {D.him} anywhere. I thought {D.he} might have run into the next yard, so I went over looking.\""), .direct("What were you shouting?", "\"I was calling the dog's name over and over, and I was also hollering to wake {V} so I could ask whether {V.he} had seen {D.him}. I know how it must have sounded.\""), .direct("Why did you throw gravel at the window?", "\"I didn't have my phone and I didn't want to pound on the front door at that hour. I thought a little gravel would get {V}'s attention. It was a stupid idea, and I regret it a lot.\""), .direct("Where had you been earlier that evening?", "\"At a cookout a few streets over. I came home around midnight, went to let the dog out one last time, and found the back gate swinging open and the dog gone.\""), .direct("Had you been drinking?", "\"I'd had a couple of beers over the evening. I was not falling down drunk. Mostly I was scared, because the dog is old and has never run off before.\""), .direct("What did you do when you saw the deputy?", "\"I stopped right away and told the deputy about the dog. I apologized and I walked home when I was told to. I have not bothered {V} since.\""), .cross("You were in that yard for about twenty minutes, weren't you?", "\"If the video says eighteen or twenty, I will not argue. I kept circling the bushes and calling. I wasn't watching a clock, but I know it was a long time.\""), .cross("You could have rung the bell, couldn't you?", "\"Yes. Looking back, that is what a sensible person does. I was panicking about the dog and not thinking in a straight line, and I picked the worst possible way.\""), .cross("The deputy smelled alcohol on your breath, didn't the deputy?", "\"I expect so, because I'd been drinking earlier. But I answered every question, I stood still, and I wasn't staggering. Having a drink isn't the same as being out of control.\""), .cross("You never found the dog in {V}'s yard, did you?", "\"No, the dog wasn't there. I was wrong about where to look. I did find the dog later, but I don't want to say more than I actually know about when.\""), .cross("Handfuls of gravel are not exactly a gentle way to get attention, are they?", "\"No, they are not. I threw it low and light, but I understand that, at one in the morning, any gravel on a bedroom window is frightening.\"")],
        openings: ("At one in the morning, {D} stood in {V}'s front yard shouting and throwing handfuls of gravel at a bedroom window. The doorbell camera recorded it for eighteen minutes, and the responding deputy smelled alcohol. You will see the video and hear from {V}, who woke up frightened.", "A very old dog had slipped out of a back yard, and a worried owner went looking in the next yard. The way {D} tried to get {V}'s attention was foolish, but nothing on that camera shows an intent to frighten anyone. You will hear about the neighborhood post that appeared the same night."),
        closings: ("Gravel against a bedroom window and shouting for eighteen minutes after one in the morning is not a neighborly request for help. The video shows {D} never went near the doorbell. {V} was awakened and alarmed, and the deputy smelled alcohol on {D}.", "A lost dog explains why {D} was in that yard at all, and the neighborhood post fits the story. {D} stopped the moment a deputy arrived and apologized. A bad idea at midnight is not the same as an intent to disturb, and the State has the burden."),
        timeline: [(0, "1:02 a.m.: {D} starts shouting in the yard."), (0, "1:20 a.m.: {V} calls deputies."), (0, "1:35 a.m.: deputies take the report."), (1, "{V} sends the doorbell video.")],
        identified: "The doorbell camera identifies {D}.",
        notDone: ["The missing-dog post was never checked for its time.", "No one asked whether the dog was ever found."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let callbackPrankV1 = SmallCases.make(
        key: "story.callbackPrank",
        category: .publicOrder,
        headlines: ["Twelve Pizzas Delivered to Neighbor's Door in Two Hours", "Delivery App Records Show Prank Orders Placed From Neighbor's Phone"],
        law: "disorderly",
        spec: "Disturbed the peace of {V}, a neighbor, by repeated unwanted deliveries and calls, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Between 6 p.m. and 8 p.m. on {DATE}, twelve pizza and wing deliveries arrived at {V}'s door, each ordered in {V}'s name and paid in cash on delivery. {V} refused and apologized to each driver. Delivery app records show the orders were placed from an account tied to {D}'s phone. {D} says friends used the phone.",
        state: [E(.digital, 3, "Delivery App Records", "Twelve orders to {V}'s address placed from an account tied to {D}'s phone."), E(.video, 2, "Doorbell Camera", "Drivers arrive at 6:05, 6:12, 6:20 and every few minutes through 8 p.m."), E(.statement, 2, "Delivery Drivers", "Two drivers say the customer on the phone asked for the door on the left."), E(.document, 2, "Warning Text", "A text from {V} to {D} at 6:30 p.m. asking {D.him} to stop.")],
        defense: [E(.statement, 1, "Friends", "{DL} says friends borrowed the phone that evening."), E(.document, 1, "Party Invite", "An invite to a party at {D}'s house starting at 6 p.m.")],
        role: "Neighbor",
        exam: [.direct("What happened at your front door on the evening of {DATE}?", "\"Pizza and wing deliveries started showing up a little after six. One driver after another, each saying there was an order in my name and I owed cash on delivery. I hadn't ordered any of it.\""), .direct("How many deliveries did you receive?", "\"Twelve, all told, between about six and eight. Some of the drivers were carrying several bags. Some orders came from different restaurants, so I kept answering the door to a fresh face.\""), .direct("What did you do each time a driver came?", "\"I said I hadn't ordered anything, apologized for the mix-up, and sent them away. A couple of them looked frustrated, and a few asked me who might want to do this to me.\""), .direct("Did you try to find out who was behind it?", "\"Yes. Around 6:30 I texted {D}, who lives down the street, because the drivers told me the order phone number looked familiar to a number I had. I asked {D.him} to stop.\""), .direct("What did the drivers tell you about the orders?", "\"Two of them said the person on the phone asked them to come to the door on the left side of the house, which is the side door I almost never use.\""), .direct("What did you do after the last delivery arrived?", "\"I sent my doorbell footage to the Sheriff's Office the next day, and I gave a deputy the delivery app screenshots that showed which account placed the orders.\""), .cross("Did you personally see {DL} place any of these orders?", "\"No. I never saw anyone use a phone. What I know comes from the drivers, my doorbell, and the delivery app's records the deputy showed me.\""), .cross("Did {DL} reply to your 6:30 text?", "\"I did not get a reply that evening. I saw the message marked as delivered. Whether the phone was in {D}'s hand at that moment, I can't tell you.\""), .cross("Was there a party at {D}'s house that evening?", "\"I could hear music from that direction and saw cars parked along the street. I didn't go over, so I do not know who was inside.\""), .cross("Did any of the drivers say it was {D} on the phone?", "\"No. The drivers said they only spoke to a customer on the line who sounded young. None of them could tell me a name.\""), .cross("Did the delivery app tell you which phone placed the orders?", "\"It listed an account linked to {D}'s phone number, but I don't know how many people could have used that phone at the time. The deputy said the same.\"")],
        defenseRole: "Party guest",
        defenseExam: [.direct("How do you know {D}?", "\"We have been friends since middle school. I was invited to the birthday party at {D}'s house on {DATE}, and I arrived around six with a bag of chips.\""), .direct("What was the party like?", "\"Crowded and noisy. There were about a dozen of us, music from a speaker, burgers on the grill, and everyone was drifting in and out of the kitchen and the back yard.\""), .direct("Where was {D}'s phone during the party?", "\"On the kitchen counter next to the snacks. It was unlocked half the time because people kept using it to change the music, and nobody treated it as private.\""), .direct("Did you see {D} on the phone ordering food?", "\"No. {D} was at the grill most of the evening and busy greeting people. I never saw {D.him} order anything.\""), .direct("How did you learn about the deliveries?", "\"Around seven someone said food kept showing up at the neighbor's house. We thought it was funny for a minute, and then {D} looked embarrassed and told everyone to stop.\""), .direct("What did {D} do when {D.he} understood what was happening?", "\"{D.He} took the phone back from whoever had it and put it in {D.his} pocket. {D.He} seemed annoyed and told us the neighbor was not someone to mess with.\""), .cross("Did you see who actually placed the orders?", "\"No. I did not see anyone place an order. I only know the phone was lying around and that several people handled it.\""), .cross("How many of the guests handled that phone?", "\"I can think of at least four or five who used it for music. I cannot say who tapped the delivery app, if anyone did.\""), .cross("Were you using the phone yourself?", "\"I picked it up once, for a song request. I put it down after a minute. I did not open any food apps.\""), .cross("You and {D} are friends, aren't you?", "\"Yes, good friends. But I'm describing what I saw at the party, not what I hope happened. I did not see the orders placed.\""), .cross("Did anyone at the party admit placing the orders?", "\"Nobody told me directly. People laughed about it in the group chat that night, but I did not hear anyone say that they did it.\"")],
        theory: ("{D} sent a flood of pranks to a neighbor.", "Friends used {D}'s phone at a party."),
        allocution: "\"I'm sorry for the trouble I caused.\"",
        truths: ("{DL} laughed about it in a group chat that night.", "A guest at the party used the phone for the orders."),
        defendant: [.direct("Whose phone is linked to the delivery app account?", "\"Mine. I set up that account months ago for ordering food when I'm studying late, and it stays signed in on my phone.\""), .direct("What was going on at your house the evening of {DATE}?", "\"I was throwing a birthday get-together that started at six. A dozen friends came by, there was music in the back, and people were wandering in and out of the kitchen.\""), .direct("Did you place any of the twelve orders?", "\"No, I did not. I was grilling and greeting people. I'd put my phone on the counter by the chips, and it was unlocked for most of the evening.\""), .direct("What did you do when you got the text from {V}?", "\"I saw it a little before seven. I was confused, because I didn't know what {V} meant. I wrote back that I'd look into it but got pulled away by the party.\""), .direct("How did you find out about the orders?", "\"One of my guests came and told me a few cars had been stopping at {V}'s house, and then everyone was laughing about it. I told them to knock it off.\""), .direct("What did you do afterward?", "\"I locked my phone, took the delivery app off my home screen, and apologized to {V} the next day. I did not want any trouble with a neighbor.\""), .cross("You posted in a group chat about the deliveries that night, didn't you?", "\"I wrote something in the chat that I'm not proud of. I made a joke about it, which I should not have done. That doesn't mean I ordered anything.\""), .cross("Your phone was the one logged in, wasn't it?", "\"Yes, my account, my phone number. I'm not saying the records are wrong. I'm saying more than one person was holding that phone during the party.\""), .cross("You saw {V}'s text at about 7, and eight more deliveries still arrived after that, didn't they?", "\"Yes, they did. I should have shut it down the moment I understood. I was slow, and that's on me.\""), .cross("Can you name the guest who used your phone?", "\"I have a good idea who it was, but I did not see it happen, and I don't want to accuse somebody without being sure. That is the honest answer.\""), .cross("You never checked the phone's order history that night, did you?", "\"Not that night. It didn't cross my mind until the next day, after {V} sent the footage and a deputy came by. I should have looked right then.\"")],
        openings: ("Twelve pizza and wing deliveries arrived at {V}'s door in two hours, each ordered in {V}'s name and paid in cash on delivery. The delivery app ties every order to an account on {D}'s phone, and {V} texted {D} to stop. You will see the records, the doorbell video, and the text.", "{D} was hosting a birthday party with a dozen guests, and {D}'s phone sat unlocked on a kitchen counter all evening. The records point to a phone, not to a person. You will hear who was in that house and how many hands held the phone."),
        closings: ("Twelve orders, one account, and a text from {V} at 6:30 that did nothing to stop the next eight deliveries. The records come from {D}'s own phone, and {D} joked about it in a group chat. A neighbor was harassed for two hours.", "A phone sat unlocked on a counter in a crowded party, and the delivery records cannot say whose finger touched the screen. No one saw {D} place an order, and {D} apologized the next day. The State must prove {D} did this, not merely that {D}'s phone did."),
        timeline: [(0, "6:00 p.m.: the first order is placed."), (0, "6:30 p.m.: {V} texts {D}."), (0, "8:00 p.m.: the twelfth delivery arrives."), (1, "{V} sends the doorbell video to the Sheriff's Office.")],
        identified: "The delivery app account is tied to {D}'s phone.",
        notDone: ["The party's guest list was never obtained.", "The delivery app's device log was never checked for a second phone."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fakeRobberyReportV1 = SmallCases.make(
        key: "story.fakeRobberyReport",
        category: .publicOrder,
        headlines: ["Parking Garage Abduction Report Falls Apart on Camera Review", "Woman Told Deputies She Was Grabbed and Robbed, Video Shows Otherwise"],
        law: "falseReport",
        spec: "Gave a false report of a crime to a law enforcement officer, claiming to have been grabbed and robbed in a parking garage, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 6:20 p.m. on {DATE}, {D} flagged down a deputy and said two people had grabbed {D.him} in a parking garage and taken a purse and a phone at knifepoint. Deputies spent three hours searching the garage. Camera footage showed {D} walking to the stairwell alone, leaving the purse on a bench and driving off in {D.his} own car. {D} says {D.he} was confused and frightened.",
        state: [E(.video, 3, "Garage Camera", "{D} walks to the stairwell alone and leaves the purse on a bench at 5:50 p.m."), E(.document, 2, "Incident Report", "The statement {D} gave the deputy, including the knife and two attackers."), E(.physical, 2, "Purse", "Found on the stairwell bench with the phone inside."), E(.statement, 2, "Deputy", "Spent three hours searching and found no sign of anyone else.")],
        defense: [E(.statement, 1, "Confused", "{DL} says {D.he} was confused and shaken after a panic attack."), E(.document, 1, "Clinic Note", "A walk-in clinic note for anxiety from the previous week.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you doing at about 6:20 p.m. on {DATE}?", "\"I was on patrol when {D} flagged me down on the street near the garage, visibly upset, and said two people had grabbed {D.him} inside and taken a purse and a phone.\""), .direct("What did {D} tell you the attackers did?", "\"{D} said two people came out of the stairwell, held a knife to {D.him}, and took the purse and the phone, then ran toward the exit. {D} gave only vague descriptions.\""), .direct("What did you and the other deputies do in response?", "\"We secured the garage and searched every level, the stairwells, and the exits for about three hours. We looked for the knife, for people matching the description, and for any other victims.\""), .direct("What did you find during the search?", "\"We found no sign of anyone else, no knife, and no witnesses. The purse turned up on a bench in the stairwell with the phone still sitting inside it.\""), .direct("What did the garage camera show when you reviewed it?", "\"It showed {D} walking alone toward the stairwell at 5:50, setting the purse down on the bench, and then driving off in {D.his} own car. Nobody else is on screen with {D}.\""), .direct("What did you do after reviewing the footage?", "\"I went back through the report with {D}, pointed out what the video showed, and {D} could not explain the difference. That is when I wrote up the false report.\""), .cross("Were you able to see all the cameras in the garage?", "\"No, I only saw the camera at the stairwell entrance. There are others on the other levels that we did not review during that evening.\""), .cross("Did {D} seem frightened when you first met?", "\"{D} was shaking and talking fast. I wouldn't say it was calm. Whether that was fear of an attack or fear of what would come next, I couldn't tell.\""), .cross("Did {D} ask for medical help or mention a panic attack?", "\"Not to me at the scene. A panic attack was mentioned later by {D}, in the interview. I did not see any medical records.\""), .cross("Did {D} hold on to the story during the whole three hours?", "\"{D} repeated the main points, a knife and two people, but some of the details changed. The garage level shifted in different tellings.\""), .cross("Isn't it possible the attackers were off camera?", "\"It's possible in theory, but the footage showed {D} walking in alone and walking out alone. There was no gap that fit a robbery in the minutes that mattered.\"")],
        defenseRole: "Friend who got a call from {DL}",
        defenseExam: [.direct("How do you know {D}?", "\"We have been close friends for about six years. I am the person {D} called that afternoon from the garage after the episode.\""), .direct("What time did {D} call you?", "\"Right around five fifty, maybe a few minutes after. {D} was breathing hard and talking so fast I could barely follow what was being said.\""), .direct("What did {D} say on the call?", "\"{D} said something terrible had happened, that {D.he} could not breathe and could not think straight. {D.He} didn't give me a clear story at all.\""), .direct("Had you seen {D} like this before?", "\"Once, about a week earlier. {D} had gone to a walk-in clinic for anxiety after nearly fainting at work. It was scary to watch.\""), .direct("What did you tell {D} to do?", "\"I told {D} to sit down, drink water, and call someone for help. I told {D} to call the police if {D.he} felt unsafe. I think that is why {D.he} flagged the deputy.\""), .direct("What did {D} say about the report afterward?", "\"{D} told me that {D.he} felt horrible, that none of it made sense when {D.he} saw the video, and that {D.he} hadn't meant to waste the deputies' time.\""), .cross("Were you with {D} in the garage?", "\"No. I was at home when {D} called. Everything I know about that afternoon comes from the phone call and later conversations.\""), .cross("Did {D} mention a robbery on the phone?", "\"{D} said something about someone grabbing {D.him}, but it came out in pieces. I did not get a clear account of a robbery or a weapon.\""), .cross("Did you know {D} had missed work that day?", "\"I found out later. {D} did not mention it on the call. I'm not sure what pressure {D.he} was under, but {D} did seem rattled.\""), .cross("You can't tell us what happened in that stairwell, can you?", "\"No. I only know what {D} told me and how {D.he} sounded. I cannot say what {D.he} saw or did.\""), .cross("You told {D} to call the police if unsafe. Did {D} call?", "\"Not that I know of. {D} flagged down a deputy rather than call 911, and I had no part in that decision.\"")],
        theory: ("{D} invented an abduction.", "{D} was confused after a panic attack."),
        allocution: "\"I'm sorry for the trouble I caused.\"",
        truths: ("{DL} had missed work that day and wanted an excuse.", "{DL} did have a panic attack that afternoon."),
        defendant: [.direct("Why did you stop the deputy on the street that evening?", "\"I was shaking and I felt like I could not breathe. I wanted help, and I told the deputy the first thing I could put into words, that someone had grabbed me.\""), .direct("What do you remember about the garage that afternoon?", "\"I remember walking toward the stairwell and feeling my chest close up. The next thing I recall clearly is standing outside the garage and feeling that something terrible had happened.\""), .direct("Had you had anything like that before?", "\"Yes. I had been to a walk-in clinic the week before for anxiety and had a similar episode. I hadn't gotten any further treatment yet.\""), .direct("Why did you say there was a knife?", "\"In the moment, it felt like that was true. I wasn't sure what was real. I didn't think I was lying. I truly believed something had happened to me.\""), .direct("What were you doing at work that day?", "\"I had missed work that afternoon, and I was worried about what my supervisor would say. I wasn't thinking clearly the whole day.\""), .direct("What did you say when the deputy showed you the video?", "\"I told the deputy I was confused, that I didn't remember the walk the way the video showed it, and that I was sorry for the three hours the deputies spent.\""), .cross("The video shows you walking alone, doesn't it?", "\"Yes, it does. I can see that now. I'm not going to argue with my own video, but I did not understand it in the moment.\""), .cross("You left the purse on the bench on purpose, didn't you?", "\"I don't remember setting it down. I can't tell you whether it was on purpose. I know it was there when the deputies looked.\""), .cross("You drove away in your own car after supposedly being robbed, didn't you?", "\"I did drive, yes. I only remember walking out to the street afterward. I don't know why I came back and flagged the deputy down rather than call 911.\""), .cross("You told the deputy about a knife and two attackers. Was any of that true?", "\"I believed it when I said it, but I cannot point to a specific person. I can't describe either of them, because there was no one.\""), .cross("You had missed work that day, hadn't you?", "\"I had, and I was dreading having to explain it. I'm not saying that did not weigh on me. But the panic was real, and I wasn't planning it.\"")],
        openings: ("At 6:20 p.m., {D} told a deputy that two people had held a knife on {D.him} in a parking garage and taken a purse and phone. The garage camera shows {D} walking alone, leaving the purse on a bench, and driving away. Deputies spent three hours searching for attackers who were never there.", "{D} had a panic attack in a parking garage and, in a confused state, told a deputy something that was not what the camera shows. A clinic note and a friend's phone call from that afternoon show an anxious person, not a schemer. You will hear how the confusion unfolded."),
        closings: ("The video shows one person in that stairwell, and it is {D}. There was no knife, no second person, and no one who ever fit the description. Three hours of deputies' time went to a story that {D} was not able to support.", "A frightened person with a documented anxiety history and a friend's phone call from that afternoon is not a person who deliberately invented a crime. The garage's other cameras were never reviewed. The State must prove {D} knew the report was false."),
        timeline: [(0, "5:50 p.m.: {D} leaves the purse on the bench."), (0, "6:20 p.m.: {D} reports the robbery."), (0, "9:30 p.m.: the search ends."), (1, "Deputies review the garage camera.")],
        identified: "The garage camera identifies {D}.",
        notDone: ["The garage's other cameras were never reviewed.", "The clinic's anxiety note was never matched to the day of the report."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let overdoseHoaxV1 = SmallCases.make(
        key: "story.overdoseHoax",
        category: .publicOrder,
        headlines: ["Caller Reports Person Trapped in Mall Elevator, Fire Crews Find Empty Car", "Elevator Rescue Call at 8 p.m. Traced to Prank"],
        law: "falseReport",
        spec: "Gave a false report of an emergency to a public safety agency, claiming a person was trapped in an elevator, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 8:05 p.m. on {DATE}, {D} called 911 and said a person was trapped in a mall elevator and screaming for help. Fire crews and two deputies arrived at 8:18 p.m., and engineers shut down both elevators for twenty minutes. The cab was empty and had run normally all day. {D}'s phone placed the call from a parking lot across the street. {D} says {D.he} heard shouting.",
        state: [E(.digital, 3, "911 Recording", "{D} reports a person trapped and screaming in the east elevator."), E(.document, 3, "Elevator Log", "The elevator ran normally all day with no stops or alarms."), E(.document, 2, "Fire Dispatch Log", "Two engines and a ladder were sent at 8:08 p.m. and cleared at 8:45 p.m."), E(.digital, 2, "Phone Records", "The call came from {D}'s phone from the lot across from the mall.")],
        defense: [E(.statement, 1, "Heard Shouting", "{DL} says {D.he} heard shouting from the building and thought it was an elevator."), E(.document, 1, "Mall Event Notice", "A notice of a dance team performance in the atrium at 8 p.m.")],
        role: "911 dispatcher",
        exam: [.direct("Describe your job and how you took the call for the jury.", "\"I'm a 911 dispatcher. At 8:05 a caller reported a person trapped in the mall's east elevator, screaming for help. I sent fire and deputies right away.\""), .direct("What did the caller tell you at 8:05 p.m.?", "\"A person was trapped in the east mall elevator, screaming for help. I dispatched fire crews and deputies.\""), .direct("What did the response find?", "\"Fire crews and two deputies arrived at 8:18. The cab was empty, and engineers shut down both elevators for twenty minutes.\""), .direct("What did the elevator log show?", "\"It ran normally all day with no stops or alarms. The dispatch log shows two engines and a ladder cleared at 8:45.\""), .direct("What did the caller sound like?", "\"Excited and out of breath. {D} said the person was banging and shouting for help, and then said {D.he} had to go.\""), .direct("How did the responding crews react?", "\"Two engines and a ladder were dispatched at 8:08, and the mall's engineers shut down both elevators for twenty minutes.\""), .cross("{D} says {D.he} heard shouting, doesn't {D.he}?", "\"Yes. {D} called from a parking lot across the street. There was a performance in the atrium.\""), .cross("Could shouting from the lot be a cheer?", "\"It could. There was loud cheering at eight.\""), .cross("Did anyone else report an elevator problem?", "\"No. I did not receive other reports.\""), .cross("Did the caller give a name or number you could trace?", "\"The number traced to {D}'s phone. {D} gave no name on the call.\""), .cross("Did the caller stay on the line?", "\"No. The caller hung up before I could ask about the person.\"")],
        defenseRole: "Dance team coach",
        defenseExam: [.direct("Please tell us about your dance team's performance.", "\"We performed in the mall atrium at eight. The crowd cheered loudly and our music was on speakers.\""), .direct("Was there a performance in the atrium that evening?", "\"At eight, with loud cheering. My dance team was performing, and the crowd cheered at the end of each number.\""), .direct("Could someone in the parking lot hear shouting from the mall?", "\"Yes, through the open doors. The sound carried across the street, especially the cheering and clapping.\""), .direct("Did you see {D} anywhere at the mall that evening?", "\"No. I did not see {D}. I was busy with my dancers backstage for most of the time.\""), .direct("Could the sound carry outside?", "\"Yes. The doors were open, and the sound carried across the street.\""), .direct("What did the cheering sound like?", "\"Like a crowd shouting. Someone outside could easily mistake it for people calling for help.\""), .cross("Did anyone report an elevator problem to you that night?", "\"Not to me. I only know about the performance and the noise it made, nothing about elevators.\""), .cross("Could cheering sound like screaming from far away?", "\"It could, from a distance. The crowd was loud, and some of the shouting was high pitched.\""), .cross("Did you hear anyone scream for help from an elevator?", "\"No. I did not hear anything like that. I only heard the crowd cheering for the team.\""), .cross("Did you see {D} at the mall?", "\"No. I was on the floor with my team.\""), .cross("You do not know who called 911 from the parking lot, do you?", "\"No. I was in the atrium. I only know our cheering was loud, and I cannot say who was outside or who heard it.\"")],
        theory: ("{D} made up an elevator emergency.", "{D} heard shouting and acted in good faith."),
        allocution: "\"I let things get out of hand.\"",
        truths: ("{DL} laughed afterward and posted about it.", "The shouting was from the dance team and {DL} did believe it."),
        defendant: [.direct("Did you call 911 about the elevator?", "\"Yes, I did. I heard shouting coming from the mall, and I honestly believed someone was trapped and in trouble.\""), .direct("Where were you standing when you made the call?", "\"In a parking lot across the street. I heard the shouting through the open doors of the mall.\""), .direct("Did you believe the call was true when you made it?", "\"Yes. I believed it. I did not mean to waste anyone's time or send fire crews to an empty elevator.\""), .direct("Tell us what you were doing across the street.", "\"I was in a parking lot waiting for a friend. The mall's front doors were open and I heard a lot of shouting.\""), .direct("What did you think you heard?", "\"A person yelling for help, over and over. It sounded urgent, so I called 911.\""), .direct("What did you do after the call?", "\"I stayed and watched the engines arrive. When I saw an empty elevator and cheering, I felt foolish.\""), .cross("You posted about it afterward and laughed, didn't you?", "\"Yes, I did. It was foolish. I laughed out of nerves when I found out the cab was empty.\""), .cross("The elevator ran normally all day, didn't it?", "\"So I am told. I did not know that at the time, and I just reacted to what I heard.\""), .cross("Two engines and a ladder responded to your call. Do you understand that?", "\"Yes. I feel terrible about it. I did not think it would turn into such a big response.\""), .cross("You posted about it afterward. Why?", "\"That was a foolish post to make. I was embarrassed and I tried to laugh it off.\""), .cross("The elevator ran normally all day. Doesn't that tell you nothing happened?", "\"Yes. I know now that I heard a dance team, not a trapped person.\"")],
        openings: ("At 8:05 p.m., {D} called 911 and said a person was trapped in a mall elevator, screaming. Fire crews and deputies responded, engineers shut down both elevators for twenty minutes, and the cab was empty.", "Weigh the defense proof, which will show that a dance team performed at eight with loud cheering and that {D} honestly believed someone was in trouble."),
        closings: ("A call about a trapped person, two engines and a ladder dispatched, elevators shut down, and an empty cab. {D} laughed and posted about it afterward.", "Cheering from a dance team, a caller in a parking lot, and an honest mistake. The State must prove {D} knew the call was false."),
        timeline: [(0, "8:05 p.m.: {D} calls 911."), (0, "8:18 p.m.: crews arrive."), (0, "8:45 p.m.: crews clear the mall."), (1, "The dispatcher sends the recording.")],
        identified: "The phone records and the recording identify {D}.",
        notDone: ["No one tested whether shouting from the atrium carries to the lot.", "The elevator was never checked for a service call at that hour."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fakeStolenCarV1 = SmallCases.make(
        key: "story.fakeStolenCar",
        category: .publicOrder,
        headlines: ["Man Reports Boat Trailer Stolen After Selling It", "Pawnshop Record Shows Trailer Sold Before the Theft Report"],
        law: "falseReport",
        spec: "Gave a false report of a crime to a law enforcement officer, claiming a boat trailer was stolen, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} reported a boat trailer stolen from {D.his} driveway on {DATE} at 9 a.m. and told deputies the thieves had cut the hitch lock. A dealer's bill of sale shows {D} sold the trailer for $900 five days earlier. Deputies found the trailer on the dealer's lot that afternoon. {D} says the buyer picked it up without telling {D.him}.",
        state: [E(.document, 3, "Bill of Sale", "The trailer sold by {D} to a dealer for $900 five days earlier, signed by {D}."), E(.physical, 2, "Trailer", "Found on the dealer's lot with {D}'s hitch lock still attached."), E(.document, 2, "Incident Report", "The theft report {D} gave at 9 a.m. with the hitch lock claim."), E(.statement, 2, "Dealer", "Bought the trailer and paid {D} in cash.")],
        defense: [E(.statement, 1, "Buyer Took It", "{DL} says the buyer picked up the trailer without telling {D.him}."), E(.document, 1, "Text From Buyer", "A text from the buyer on the day of the sale asking where to pick it up.")],
        role: "Sheriff's deputy",
        exam: [.direct("What report were you called to take on the morning of {DATE}?", "\"{D} called at about nine in the morning saying a boat trailer had been stolen out of the driveway overnight. I took the report at the house.\""), .direct("What did {D} tell you about how the trailer was taken?", "\"{D} said the thieves must have cut the lock on the hitch, because the lock was missing, and the trailer was gone. {D} wanted a report for insurance.\""), .direct("How did the trailer turn up?", "\"That same afternoon, around three, we found it parked on a local dealer's lot with the hitch lock still clamped to the tongue, not cut. Seeing that lock made me suspicious right away.\""), .direct("What did the dealer tell you?", "\"The dealer said {D} sold the trailer five days earlier for $900, cash, and showed me a bill of sale with {D}'s signature on it.\""), .direct("What did the bill of sale show?", "\"It listed {D} as the seller, a price of $900, the trailer's serial number, and a date five days before the theft report. It matched the trailer on the lot.\""), .direct("What did you do after you saw the bill of sale?", "\"I went back to {D} and asked about it. {D} said the buyer must have come and taken it without notice, and could not explain the signature or the date.\""), .cross("Did the dealer's lot have cameras you checked?", "\"I did not pull the lot camera. I relied on the bill of sale and the dealer's statement. A video of the day it arrived could still exist.\""), .cross("Did you read the whole text thread between {D} and the buyer?", "\"I saw a text from the buyer asking where to pick it up, but I did not read the rest of the thread in detail that day.\""), .cross("Was the hitch lock cut?", "\"No. It was intact and attached to the trailer when we found it. That is why the claim about thieves cutting the lock did not hold up.\""), .cross("Is it possible {D} forgot about the sale?", "\"Anything is possible, but a signed bill of sale five days earlier and a cash payment of $900 is hard to forget, in my experience.\""), .cross("Did {D} ask you to drop the report once the trailer was found?", "\"{D} said they wanted the report corrected. I told {D} that a false report had already been made and I had to document it.\"")],
        defenseRole: "Dealer's lot worker",
        defenseExam: [.direct("What do you do at the dealer's lot?", "\"I work the yard, moving trailers, boats and equipment, and I handle the paperwork when the owner isn't around. I was on the lot the day {D} brought the trailer in.\""), .direct("Do you remember the trailer coming in?", "\"I remember a boat trailer with a lock on the hitch, hooked to a pickup. The owner of the truck dropped it and left with an envelope of cash from the dealer.\""), .direct("Did you speak to the person who sold it?", "\"Briefly. {D} told me the buyer would be getting in touch about the pickup. I thought it was routine, and I wrote it down on the paperwork.\""), .direct("Was there a text from a buyer?", "\"I saw {D}'s phone show a message from the buyer asking where to pick it up. {D} replied to it right there at the counter.\""), .direct("How did {D} seem that day?", "\"In a hurry. {D} signed what I put in front of {D.him}, took the cash, and headed out. {D.He} didn't seem upset about the sale.\""), .direct("What happened when deputies came?", "\"They looked at the trailer and the bill of sale. I told them everything I knew, and I gave them a copy of the paperwork.\""), .cross("Did you personally see {D} sign the bill of sale?", "\"I handed {D} the form at the counter and {D} signed it. I did not stand over {D} but I was right there.\""), .cross("Did you hear {D} say anything about reporting it stolen?", "\"No. Nothing like that was said to me. I only learned about a report when the deputies arrived.\""), .cross("Did {D} take the lock off the hitch?", "\"The lock was left on. I assumed it came with the trailer. Nobody asked me to remove it.\""), .cross("Was the buyer's pickup arrangement something the dealer made?", "\"I do not know. I just saw a text. I do not know who the buyer was, or whether any pickup was actually planned.\""), .cross("Does the lot have cameras?", "\"We have one on the gate, but I did not pull the footage for the deputies, and I don't know whether it was kept.\"")],
        theory: ("{D} sold a trailer and reported it stolen.", "{D} thought the buyer took it without notice."),
        allocution: "\"I should have walked away, and I'm sorry.\"",
        truths: ("{DL} owed money on the trailer to a lender.", "The text from the buyer shows a pickup arrangement that {DL} forgot."),
        defendant: [.direct("Did you sell the boat trailer?", "\"Yes, I sold it to the dealer for $900 about five days before I called the Sheriff. I remember the sale, I remember the signature, and I remember the cash.\""), .direct("Why did you call in a theft?", "\"I had arranged for a buyer to pick it up the following weekend, and when I walked out that morning the trailer was gone. I panicked and assumed it had been stolen.\""), .direct("Did you mention the dealer sale to the deputy?", "\"No, and I wish I had. When I saw the empty driveway my mind went straight to theft, and I didn't connect it to the sale I had made.\""), .direct("Why did you say the hitch lock was cut?", "\"I saw the lock was missing and assumed it had been cut. I did not look closely. I was upset, and I was guessing at what had happened.\""), .direct("Did you owe money on the trailer?", "\"Yes, I owed the lender a balance on it. That was part of why I sold it. I was behind and needed the cash.\""), .direct("What did the buyer text you?", "\"The buyer texted me on the day of the sale to ask where to pick it up. I had forgotten that we set that up, and it explains why it was gone.\""), .cross("You signed the bill of sale, didn't you?", "\"Yes, that is my signature. I'm not disputing that I sold it. I'm saying I did not think of it that morning.\""), .cross("You told the deputy thieves cut the lock, didn't you?", "\"I told the deputy the lock was gone and I assumed it was cut. I did not know that for certain, and I said it more strongly than I should have, yes.\""), .cross("You took $900 cash five days before. Isn't that easy to remember?", "\"Normally, yes. I had a lot going on that week, and I kept thinking the sale was set for the weekend. I realize how that sounds.\""), .cross("You had a lender wanting payment, hadn't you?", "\"Yes. I was behind on the balance, and I knew that if the trailer had been sold, the lender would want it. But I never intended to lie.\""), .cross("You didn't call the deputy back when you remembered the sale, did you?", "\"No. I was waiting until I had time to look at the text, and then the deputy called me. I should have called right away.\"")],
        openings: ("{D} signed a bill of sale for a boat trailer on one day and, five days later, reported it stolen with a story about cut locks. Deputies found the trailer on a dealer's lot with the hitch lock still on. You will see the bill of sale and the report side by side.", "{D} had arranged for someone to pick up the trailer, saw an empty driveway, and called it in without remembering the earlier arrangement. There is a text from a buyer about picking up the trailer. A forgetful report is not a lie."),
        closings: ("A signature on a $900 bill of sale, a lock that was never cut, and a trailer on a dealer's lot. {D} reported a theft that never happened, and the facts prove it. A cash sale five days earlier is not something people forget.", "{D} did sell the trailer, and nobody disputes that. A text from the buyer shows a pickup arrangement that {D} had lost track of. Honest forgetting is not the intent to deceive that this charge requires."),
        timeline: [(-5, "{D} sells the trailer to a dealer."), (0, "9 a.m.: {D} reports the trailer stolen."), (0, "3 p.m.: deputies find the trailer on the dealer's lot."), (1, "The dealer provides the bill of sale.")],
        identified: "The bill of sale and the report both carry {D}'s name.",
        notDone: ["The buyer's pickup text was never read in full.", "The dealer's lot camera was never checked for the date the trailer arrived."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let givenFalseDOBV1 = SmallCases.make(
        key: "story.givenFalseDOB",
        category: .publicOrder,
        headlines: ["Driver Gives Cousin's Name at Traffic Stop to Avoid Warrant", "Fingerprint Check Shows Name and Birth Date Were a Relative's"],
        law: "obstruction",
        spec: "Gave a false name and date of birth to a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A deputy stopped {D} at 10:20 p.m. on {DATE} for a missing taillight. {D} gave the name and birth date of a cousin. The records check showed the cousin was in another state, and a fingerprint scan at the jail matched {D}, who had an open warrant. {D} says {D.he} panicked and meant to correct it.",
        state: [E(.video, 3, "Body Camera", "{D} gives the cousin's name and birth date at 10:22 p.m."), E(.document, 3, "Records Check", "The cousin's record does not match {D}'s description or photo."), E(.document, 2, "Fingerprint Report", "The jail scan matches {D}, with an open warrant."), E(.statement, 2, "Deputy", "Noticed the photo did not match and called for a second check.")],
        defense: [E(.statement, 1, "Panic", "{DL} says {D.he} panicked and meant to give the real name."), E(.document, 1, "Warrant Notice", "A warrant for a missed court date that {D} says {D.he} forgot.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did you come to meet {D} on {DATE}?", "\"At about 10:20 at night I stopped {D}'s car for a missing taillight on a county road. It was a routine traffic stop and I was alone in my cruiser.\""), .direct("What did you ask {D} for?", "\"A license and a name. {D} said {D.he} didn't have a license on {D.him} and gave me a full name and date of birth. I wrote them down and ran them.\""), .direct("What did the body camera capture?", "\"It shows {D} giving that name and a birth date at 10:22, calmly and without hesitation, and nothing in the exchange suggested that the name was borrowed.\""), .direct("What did the records check show?", "\"A name that matched a person older than {D} looked, and the photo on the record did not match the person in the car. I asked dispatch to double check it.\""), .direct("What did you do when the photo did not match?", "\"I called for backup and asked {D} to confirm the date of birth and the address. The answers were slow and did not line up with the record.\""), .direct("How did you find out who {D} really was?", "\"At the jail, a fingerprint scan came back to {D}, and it showed an open warrant for a missed court date. That was about 11:30.\""), .cross("How long between giving the cousin's name and the correct one?", "\"The correct name came only after the fingerprint scan. I do not recall {D} volunteering the real name before then.\""), .cross("Did {D} resist or run?", "\"No. {D} stayed in the car, kept hands where I could see them, and did not argue when I put {D.him} in handcuffs.\""), .cross("Did you ask {D} for the name more than once?", "\"Twice. I asked at the car window and again after the photo did not match. Both times {D} gave the same cousin's name.\""), .cross("Did {D} say anything about a mistake?", "\"At the jail, {D} said {D.he} panicked. I did not hear that on the roadside, and I could not tell you the moment {D} started to say it.\""), .cross("Did you contact the cousin?", "\"The records check showed the cousin was out of state. I did not speak with the cousin myself, and I do not know what the cousin knew.\"")],
        defenseRole: "Cousin whose name was used",
        defenseExam: [.direct("How are you related to {D}?", "\"We are cousins and grew up in the same town. We talk regularly and I've known {D} my entire life.\""), .direct("Where were you the night of {DATE}?", "\"Out of state, about six hours away, at work on a night shift. I wasn't anywhere near the stop.\""), .direct("How did you learn that your name had been used?", "\"A deputy called me the next day and asked about my birth date and whether I was in the county. I told the deputy I was working out of state.\""), .direct("Did {D} tell you about it?", "\"Yes, {D} called me that weekend. {D} was ashamed and said {D.he} had panicked and used my name without thinking. {D.He} apologized.\""), .direct("Has {D} ever used your name before?", "\"Not that I know. I have never had any problem with my record or my identification, and nothing else has turned up.\""), .direct("What did {D} say about the warrant?", "\"{D} told me it was a missed court date, and that {D.he} had forgotten about it. {D.He} said {D.he} was scared of being arrested.\""), .cross("Do you know what happened on the roadside?", "\"No. I was out of state. I only know what {D} told me afterward and what the deputy said when calling me.\""), .cross("Did {D} say {D.he} planned to use your name?", "\"No. {D} told me it was a panic, that it just came out. I can't verify that, but that is what I was told.\""), .cross("Does {D} know your birth date by heart?", "\"Probably. We are family and have celebrated each other's birthdays for years. It is easy for either of us to recite the other's.\""), .cross("Did you give {D} permission to use your name?", "\"Absolutely not. I never gave anyone permission to use my name with law enforcement.\""), .cross("Are you angry with {D}?", "\"I was surprised, not angry. I am here to tell you the truth, and I haven't tried to hide anything about our relationship.\"")],
        theory: ("{D} gave a false identity to dodge a warrant.", "{D} panicked and was about to correct it."),
        allocution: "\"I understand why people were afraid. I'm sorry.\"",
        truths: ("{DL} had memorized the cousin's birth date for this purpose.", "{DL} did give the correct name before being fingerprinted."),
        defendant: [.direct("Why did you give a different name to the deputy?", "\"I panicked. I knew there was a warrant out for a missed court date, and my mind jumped to my cousin's name before I thought about what I was doing.\""), .direct("What did you do about the warrant?", "\"I forgot about the court date. When the notice came, I thought I had handled it. I did not know it was still open until that night.\""), .direct("Did you mean to give the cousin's name for long?", "\"No. I intended to correct it as soon as I steadied myself. I had my mouth open to say the real name when the deputy asked the second time.\""), .direct("How do you know your cousin's birth date?", "\"We are close and I have known it for years. It came to me automatically, and that is why it came out so smoothly. It was not rehearsed.\""), .direct("How were you treated when the deputy stopped you?", "\"Politely. The deputy explained the taillight and asked for my information. I did not feel threatened, which makes me feel worse about what I did.\""), .direct("What happened at the jail?", "\"They took my fingerprints, and it matched me. I told them my real name before the print came back, but I understand the timing looks bad.\""), .cross("You looked at the deputy and gave a false name with a date of birth, didn't you?", "\"Yes. I gave my cousin's name and date of birth. I'm not pretending otherwise. I did it in a moment of fear.\""), .cross("You repeated it a second time when asked, didn't you?", "\"I did, and that is the hardest part to explain. Once it was out, I felt I couldn't take it back without making things worse.\""), .cross("You did not tell the deputy the truth before the fingerprint came back, did you?", "\"I started to at the jail, I believe, but I can't swear to the exact minute. The print was already being run.\""), .cross("You knew your cousin was out of state, didn't you?", "\"Yes. I knew the cousin lived far away. I wasn't thinking about whether it would be checked. I was only thinking about the warrant.\""), .cross("The cousin's name was one you could recall instantly, wasn't it?", "\"Yes, because it is a name I hear and say all the time. That does not mean I planned it.\"")],
        openings: ("{D} was stopped for a missing taillight and, with a warrant waiting, gave a cousin's name and date of birth, twice. Only a fingerprint scan at the jail revealed who {D} really was. The body camera captured the false name at 10:22.", "{D} was stopped at night, afraid of a warrant that had slipped {D.his} mind, and a name tumbled out in a panic. {D} never ran, never argued, and told the truth at the jail. A moment of fear is not a plan."),
        closings: ("A deputy asked twice, and twice {D} gave the cousin's name and birth date, calmly, on camera. The truth came only when the fingerprint scan left no choice. That is a false identity given to dodge an open warrant.", "{D} stayed in the car, kept hands in view, and answered politely. A panic over a forgotten court date does not turn a muddled moment into a calculated lie. The State has not shown {D} meant to deceive rather than flinch."),
        timeline: [(0, "10:20 p.m.: the stop."), (0, "10:22 p.m.: {D} gives the cousin's name."), (0, "10:40 p.m.: the records check fails to match."), (0, "11:30 p.m.: the fingerprint match at the jail.")],
        identified: "The fingerprints identify {D}.",
        notDone: ["The cousin was never asked whether {DL} had used the name before.", "The body camera was never matched with the time of the fingerprint scan."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let hidesInBushesV1 = SmallCases.make(
        key: "story.hidesInBushes",
        category: .publicOrder,
        headlines: ["Man Crawls Under Porch During Welfare Check and Stays Forty Minutes", "Deputies Plead With Man Beneath Deck Before Flashlight Finds Him"],
        law: "resisting",
        spec: "Resisted, delayed, or obstructed a public officer in the discharge of duty by hiding under a porch and refusing to come out, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies were sent to check on a neighbor's report of a person looking into windows at 10 p.m. on {DATE}. {D} crawled under a nearby porch when the cruiser arrived. For forty minutes deputies called out, then brought a flashlight and a canine. {D} came out at 10:45 p.m. {D} says {D.he} was afraid of the dog.",
        state: [E(.video, 3, "Body Camera", "Deputies call out four times and shine a flashlight under the porch for forty minutes."), E(.document, 2, "Dispatch Log", "The check began at 10:05 p.m. and ended at 10:45 p.m."), E(.statement, 2, "Deputy", "Called out the same commands four times and got no answer."), E(.physical, 1, "Porch Space", "A crawl space about eighteen inches high with a flattened patch of dirt.")],
        defense: [E(.statement, 1, "Afraid of the Dog", "{DL} says {D.he} was afraid of the dog and the dark."), E(.document, 1, "Dog Bite Record", "A bite from a dog in {D}'s childhood on a medical record.")],
        role: "Sheriff's deputy",
        exam: [.direct("What call were you responding to at 10 p.m. on {DATE}?", "\"A neighbor had called to report a person looking into windows on a quiet street. Dispatch sent me and a second deputy, and we arrived at about 10:05.\""), .direct("What did you see when you arrived?", "\"As our cruiser pulled up I saw a person near the side of a house, and then that person dropped to the ground and crawled under the front porch.\""), .direct("What did you do when {D} went under the porch?", "\"I identified myself as a deputy and called out four times for {D} to come out and show hands. I used the same words each time.\""), .direct("How did {D} respond?", "\"There was no answer. I shined a flashlight under the porch and could see a person flat against the dirt, but nothing came back verbally.\""), .direct("How long did you wait?", "\"About forty minutes in total. We tried calling, lighting the space, and finally asked for a canine unit to help, which arrived around 10:40.\""), .direct("What happened when the canine unit arrived?", "\"As soon as I told {D} a dog was on scene and would be sent in, {D} came out at 10:45 on {D.his} own and was taken into custody.\""), .cross("How high is the crawl space under that porch?", "\"About eighteen inches. It is tight. A person in there is flat on their stomach, and it would be hard to turn around.\""), .cross("Did you tell {D} you were going to send a dog in before the canine arrived?", "\"I announced that a canine would be used if {D} did not come out. I believe it was said once, close to 10:40.\""), .cross("Did {D} ever say a word under the porch?", "\"I did not hear any words. If {D} spoke, it was low enough that neither of us picked it up.\""), .cross("Did you ever find out whether anyone was looking into windows?", "\"No. We never confirmed the caller's report. I did not find any evidence of a window incident, and I could not tie {D} to it.\""), .cross("Did you consider that {D} might have been frightened?", "\"Of course. Frightened people hide. I was patient for a long time, but my duty was to resolve the call, and I could not walk away from it.\"")],
        defenseRole: "Resident whose porch it was",
        defenseExam: [.direct("Whose porch was it?", "\"Mine. I live in that house and I was inside when the deputies came. I heard shouting outside and came to the door.\""), .direct("What did you see when you looked out?", "\"I saw two deputies in the yard with flashlights, shining them under my porch. I could not see exactly who or what was under there.\""), .direct("Did you speak with the deputies?", "\"Yes. I told them the crawl space is tight and that nobody should go in there. I asked whether they wanted me to turn on more lights.\""), .direct("How long was it before the person came out?", "\"It felt like forever. I looked at the clock at one point and it was well past ten thirty. It was about forty minutes, as I recall.\""), .direct("What happened when the person emerged?", "\"The person crawled out covered in dirt, looked terrified, and was handcuffed by the deputies. The person kept saying they were afraid of dogs.\""), .direct("Did you know the person?", "\"I did not recognize the person at all. It was only later that I learned the name.\""), .cross("Did you see the person go under the porch?", "\"No. I was inside. I only saw the deputies' lights and heard them calling out.\""), .cross("Did you hear the commands the deputies gave?", "\"I heard them calling something like come out with your hands up. I couldn't tell you how many times or in what words.\""), .cross("Did you see anyone looking in your windows that night?", "\"No. I did not see anyone at my windows, and I did not make the call about a prowler.\""), .cross("Could the person under your porch hear the deputies?", "\"I believe so. The crawl space is open at the front, and I could hear them clearly from inside the house.\""), .cross("Did you think the person was hiding from the deputies?", "\"I assumed so. I didn't think about whether it was fear. I was mostly worried about my porch and my dog.\"")],
        theory: ("{D} hid for forty minutes and delayed deputies.", "{D} was afraid and did not understand."),
        allocution: "\"I was angry and I made it everyone else's problem.\"",
        truths: ("{DL} heard the commands and stayed quiet to avoid being found.", "{DL} was afraid of dogs and had a panic response."),
        defendant: [.direct("Why did you crawl under the porch?", "\"The cruiser lights came on, I was walking near the house, and I got scared. I did not think. I dropped and went under the nearest dark space.\""), .direct("Were you looking into windows?", "\"No. I was walking home along that street and cutting across a side yard. I was not looking in anyone's windows.\""), .direct("Did you hear the deputies call to you?", "\"I heard shouting and bright lights, but with the panic I could not make sense of it. I kept thinking I needed to stay still and wait for it to pass.\""), .direct("Why were you afraid?", "\"I was bitten by a dog as a kid and have been afraid of them since. When I heard there might be a dog, I locked up even more.\""), .direct("What happened when you came out?", "\"I came out because I realized how long it had been and that I could not stay under there. I was shaking, my knees were scraped, and the deputy handcuffed me.\""), .direct("How did you feel while you were under the porch?", "\"Terrified. My heart was pounding and I couldn't get my breath. I know it looks like I was ignoring them, but I wasn't thinking at all.\""), .cross("You heard the deputies identify themselves, didn't you?", "\"I heard that people were calling out, and I understood they were deputies. I just couldn't make myself move, and I did not know what to say.\""), .cross("They asked you four times to come out, didn't they?", "\"I think so. It might have been more. I lost track. I knew each time that I should answer, and I did not.\""), .cross("You were under there about forty minutes, weren't you?", "\"If the records say so, I accept that. It felt both very long and very short. I just remember staying frozen.\""), .cross("You stayed hidden until you heard about the dog, didn't you?", "\"I stayed until it dawned on me that they were going to send a dog in. At that point I could not stay silent any longer.\""), .cross("You were nearby a house where someone reported a prowler, weren't you?", "\"I was on that street, yes. I did not know about any report. I was simply on my way home.\"")],
        openings: ("Deputies were sent to check on a report of a prowler. When they arrived, {D} crawled under a porch and stayed there for forty minutes, ignoring four commands to come out. The body camera and dispatch log show every minute.", "{D} was walking home, saw the cruiser lights, and froze in a panic because of a childhood dog bite. {D} never fought or ran, and came out the moment the canine was mentioned. You will hear a resident confirm how tight and dark that space was."),
        closings: ("Four commands, a flashlight, and forty minutes of silence while two deputies waited in the dark. {D} could hear them and stayed hidden. That delay is exactly what the statute calls obstruction.", "The State never confirmed that anyone was peering into windows, and {D} never touched a deputy. An old fear of dogs froze {D} under a cramped porch. Fear and silence do not equal an intent to obstruct."),
        timeline: [(0, "10:05 p.m.: deputies arrive."), (0, "10:10 p.m.: {D} crawls under the porch."), (0, "10:40 p.m.: the canine unit arrives."), (0, "10:45 p.m.: {D} comes out.")],
        identified: "The body camera identifies {D}.",
        notDone: ["The canine unit's presence was never explained to {DL} on the record.", "The caller's report about looking in windows was never confirmed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let needlesCarV1 = SmallCases.make(
        key: "story.needlesCar",
        category: .drugs,
        headlines: ["Syringes and Residue Found in Tackle Box During Traffic Stop", "Driver Says Needles Are for Insulin, Lab Finds Residue"],
