        state: [E(.physical, 3, "Syringes", "Six syringes in a tackle box, three with residue."), E(.document, 3, "Lab Report", "Methamphetamine residue in three syringes."), E(.video, 2, "Body Camera", "The deputy opens the tackle box and finds the syringes at 3:12 p.m."), E(.document, 2, "Stop Report", "The car is registered to {D} and {D} was the only occupant.")],
        defense: [E(.statement, 1, "Insulin", "{DL} says {D.he} is diabetic and carries syringes for insulin."), E(.document, 1, "Prescription", "A pharmacy label for insulin with {DL}'s name.")],
        role: "Sheriff's deputy",
        exam: [.direct("Tell the jury what led to the stop.", "\"I saw a car with a broken brake light at about three in the afternoon and stopped it. I smelled smoke when I walked up to the window.\""), .direct("Why did you stop {D}?", "\"For a broken brake light at 3 p.m. I smelled smoke and asked to look in the car.\""), .direct("What did you find?", "\"A tackle box on the passenger seat with six syringes. Three had residue. My body camera shows it at 3:12.\""), .direct("What did the lab find?", "\"Methamphetamine residue in three of the syringes. The car is registered to {D}, who was the only occupant.\""), .direct("How did you come to look in the tackle box?", "\"I asked to look in the car and {D} agreed. The tackle box was on the passenger seat.\""), .direct("What did you find inside?", "\"Six syringes. Three had residue in them, and I sent them to the lab.\""), .cross("{D} says the syringes were for insulin, doesn't {D.he}?", "\"Yes. {D} is diabetic with insulin pens, and kept insulin syringes in a separate case.\""), .cross("Did the tackle box belong to {D}?", "\"I do not know. A passenger from last week may have left it.\""), .cross("Were the three with residue the only ones tested?", "\"Yes. The other three were clean.\""), .cross("Whose car was it, and who was in it?", "\"The car is registered to {D}, and {D} was the only person in it that day.\""), .cross("Did {D} say anything about the box?", "\"{D} said it wasn't {D.his} and that it had been left by a passenger.\"")],
        defenseRole: "Passenger from last week",
        defenseExam: [.direct("Tell the jury how you know {D}.", "\"I'm a friend. I rode with {D} a few times last week.\""), .direct("Did you ride in {D}'s car last week?", "\"Sometimes. I rode with {D} a few times last week, usually to and from work.\""), .direct("Did you leave a tackle box in the car?", "\"A friend did, not me. A friend who rode with us left a tackle box on the passenger seat.\""), .direct("Is {D} diabetic, as far as you know?", "\"Yes, with insulin pens. I have seen {D} use them, and {D} keeps the supplies in a separate case.\""), .direct("Is {D} diabetic?", "\"Yes. I've seen {D} use insulin pens.\""), .direct("What did the tackle box look like when you left it in the car?", "\"A green plastic box with a latch, with fishing lures in the top tray. I did not open the lower part and did not know what was inside.\""), .cross("Did you ever see {D} use drugs in the car?", "\"No. I never saw that in all the times I rode with {D}. I only saw the insulin pens.\""), .cross("Did you see syringes inside the tackle box?", "\"No. I did not open it, and I never looked inside. It was not mine, so I left it alone.\""), .cross("Do you know the full name of the friend who left the box?", "\"Only a first name, and I do not know how to reach that person now. I wish I did.\""), .cross("Did you open the tackle box?", "\"No. I never looked inside.\""), .cross("You never saw what was in the lower tray, did you?", "\"No. I never looked. I only know it was mine for fishing, and I am surprised anything else was in it.\"")],
        theory: ("{D} had syringes with drug residue.", "{D} is diabetic and carries syringes."),
        allocution: "\"I have a problem and I need help.\"",
        truths: ("{DL} had used the three syringes with residue that week.", "{DL}'s insulin syringes were in a separate case and the tackle box belonged to a passenger."),
        defendant: [.direct("Were the syringes yours?", "\"The insulin syringes were mine, in a separate case. The tackle box belonged to a passenger.\""), .direct("Do you have diabetes?", "\"Yes. I use insulin pens, and I keep supplies in a case.\""), .direct("Did you know about the tackle box?", "\"I knew it was in the car. I did not open it.\""), .direct("Tell us about your insulin.", "\"I've been diabetic for years. I use insulin pens and keep syringes in a small case in my glove compartment.\""), .direct("Where did the tackle box come from?", "\"A passenger rode with me last week and left it. I hadn't opened it, and I'd forgotten it was there.\""), .direct("What did you tell the deputy?", "\"That I'm diabetic and the tackle box wasn't mine. I showed the deputy my insulin case.\""), .cross("Methamphetamine residue was in three syringes in your car, wasn't it?", "\"Yes. I do not know how it got there. I did not use them.\""), .cross("You were the only one in the car, weren't you?", "\"That day, yes. But the box was left earlier by someone else.\""), .cross("You drive that car every day. How do you not know what is in it?", "\"I do not look in boxes that are not mine.\""), .cross("Methamphetamine residue was in three syringes. Whose?", "\"I don't know. I never touched them.\""), .cross("You were the only one in the car. Isn't it yours to account for?", "\"It's my car, but I didn't know what was in the box.\"")],
        openings: ("A deputy stopped {D} for a broken brake light, smelled smoke, and found a tackle box with six syringes on the passenger seat. A lab found methamphetamine residue in three of them.", "The defense will present evidence that {D} is diabetic, kept insulin syringes in a separate case, and that the tackle box belonged to a passenger."),
        closings: ("Six syringes in a tackle box in {D}'s car, methamphetamine residue in three, and {D} alone at the wheel. A driver answers for what is in the car.", "A diabetic's insulin case, a passenger's tackle box, and no one who saw {D} use drugs. The State must prove {D} knew what was in the box."),
        timeline: [(0, "3 p.m.: the stop."), (0, "3:12 p.m.: the syringes are found."), (0, "3:30 p.m.: {D} is cited."), (14, "The lab reports the residue.")],
