        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let sleepingDriverV1 = SmallCases.make(
        key: "story.sleepingDriver",
        category: .traffic,
        headlines: ["Driver Asleep in Drive-Through Lane at 3 a.m. Blows .13", "Engine Running, Gear in Drive, Window Down at Drive-Through"],
        law: "dwi",
        spec: "Operated a motor vehicle while under the influence of an impairing substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 3:10 a.m. on {DATE}, a restaurant worker called deputies about a car stopped in the drive-through lane with the driver asleep. The deputy found {D} slumped at the wheel with the engine running, in drive with a foot on the brake. A breath test at 3:35 a.m. read .13. {D} says {D.he} was waiting for a ride.",
        state: [E(.document, 3, "Breath Result", "A breath alcohol concentration of .13 at 3:35 a.m."), E(.video, 2, "Body Camera", "The deputy finds {D} asleep with the engine running and the car in drive."), E(.statement, 2, "Restaurant Worker", "The car sat at the window for twenty minutes."), E(.document, 2, "Registration", "The car is registered to {D}.")],
        defense: [E(.statement, 1, "Waiting for a Ride", "{DL} says {D.he} was waiting for a ride and fell asleep."), E(.document, 1, "Ride App Screenshot", "A ride request at 2:50 a.m. cancelled at 3:05 a.m.")],
        role: "Sheriff's deputy",
        exam: [.direct("Explain to the jury how you came to the scene.", "\"At about 3:10 a.m., a restaurant worker called about a car stopped in the drive-through lane with the driver asleep.\""), .direct("What did you find at the drive-through?", "\"{D} slumped at the wheel with the engine running, the car in drive and a foot on the brake. A worker had called me about it.\""), .direct("How long had the car sat there?", "\"About twenty minutes at the window, according to the worker.\""), .direct("What did the breath test show?", "\"A .13 at 3:35 a.m. That is well over the legal limit of .08.\""), .direct("What did you find when you got to the car?", "\"The engine was running, the car was in drive, and {D} was slumped at the wheel with a foot on the brake.\""), .direct("How did you wake {D}?", "\"I knocked on the window several times. It took a while before {D} responded.\""), .cross("The car was not moving, was it?", "\"No. It was stopped with the brake on. It was not moving.\""), .cross("{D} says {D.he} was waiting for a ride, doesn't {D.he}?", "\"Yes. A ride was requested and cancelled.\""), .cross("Did {D} wake up easily?", "\"Slowly. It took a few tries.\""), .cross("Did {D} say anything about the ride?", "\"Yes, that {D} was waiting for a ride. A ride app request was made at 2:50 and cancelled at 3:05.\""), .cross("You did not see {D} drive the car to the window, did you?", "\"No. I arrived after the car was already there. The worker told me when it pulled in, and the camera showed the car sitting for twenty minutes.\"")],
        defenseRole: "Drive-through manager",
        defenseExam: [.direct("Tell us what you saw at the window.", "\"A car sat at the speaker for about twenty minutes without ordering. I leaned out and saw the driver asleep.\""), .direct("Did {D} order anything at your drive-through window?", "\"No. {D} never ordered anything. The car just sat there, and at first I thought {D} was deciding.\""), .direct("Was the car moving while it sat at your window?", "\"No. The brake was on and the engine was running. It sat at the window for about twenty minutes.\""), .direct("Did {D} wake up when you knocked on the window?", "\"Slowly. I knocked a few times, and it took a while before {D} stirred and rolled the window down.\""), .direct("Did the car move?", "\"No. It sat still with the brake lights on.\""), .direct("How did {D} wake?", "\"Slowly. I knocked a few times and the driver blinked and looked confused.\""), .cross("Did {D} seem sober to you when you spoke with {D}?", "\"I could not tell. {D} seemed confused and groggy, which can be from sleep as much as anything.\""), .cross("Did you smell alcohol on {D}'s breath at the window?", "\"I did not get close enough to say. I only spoke through the window and kept my distance.\""), .cross("Why did you decide to call deputies about the car?", "\"I was worried. A driver asleep at a window in drive is not normal, and I thought something might be wrong.\""), .cross("Did you smell alcohol?", "\"A little. I couldn't be sure.\""), .cross("Did {D} seem sober?", "\"No. {D} seemed groggy and out of it.\"")],
        theory: ("{D} was impaired in control of a running car.", "{D} was waiting for a ride."),
        allocution: "\"I wasn't thinking about anyone else on the road.\"",
        truths: ("{DL} had driven to the drive-through and fell asleep before ordering.", "The ride was requested and cancelled."),
        defendant: [.direct("Were you driving the car?", "\"I drove to the drive-through and fell asleep before ordering. I was waiting for a ride I had requested.\""), .direct("Why did you go to the drive-through?", "\"I meant to order, but I fell asleep. I was exhausted.\""), .direct("Had you been drinking?", "\"Yes. I had been drinking, and I decided to wait for a ride.\""), .direct("Describe your night for the jury.", "\"I'd had a few drinks at a friend's place. I decided to drive to a drive-through for food while I waited for a ride.\""), .direct("Why were you in drive?", "\"I was ready to move up. I fell asleep before I ordered.\""), .direct("What did you do when the deputy knocked?", "\"I woke up groggy and told the deputy I was waiting for a ride. I handed over my license.\""), .cross("You were in drive with a foot on the brake, weren't you?", "\"Yes. I was ready to go if the ride did not come. That was a mistake.\""), .cross("A .13 is well over the limit, isn't it?", "\"Yes. I know. I should not have been in the driver's seat.\""), .cross("You could have waited outside the car, couldn't you?", "\"Yes. I wish I had. I truly am sorry.\""), .cross("You drove to the drive-through after drinking. Isn't that driving impaired?", "\"I drove there, and I shouldn't have. I was trying to stay put until my ride came.\""), .cross("You cancelled the ride at 3:05. Why?", "\"I thought I could drive. I fell asleep before I did.\"")],
        openings: ("At 3:10 a.m., a restaurant worker called deputies about a car stopped in the drive-through lane with the driver asleep. The deputy found {D} slumped at the wheel with the engine running, in drive, and a breath test read .13.", "The defense witnesses will explain that {D} drove to the window, fell asleep before ordering, and was waiting for a ride that was later cancelled."),
        closings: ("A car in drive with the engine running, a driver asleep, and a .13 reading. {D} was in control of the car and impaired.", "A person who was waiting for a ride and fell asleep. The car was not moving, and the State must prove {D} was driving while impaired."),
        timeline: [(0, "2:50 a.m.: {D} requests a ride."), (0, "3:10 a.m.: the worker calls deputies."), (0, "3:35 a.m.: the breath test reads .13."), (0, "4 a.m.: {D} is cited.")],
        identified: "The registration and the deputy identify {D}.",
        notDone: ["The ride app's cancellation was never matched to the time.", "No one noted whether {DL} left the keys in the ignition out of habit."],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let cigarCaseSmashV1 = SmallCases.make(
        key: "story.cigarCaseSmash",
        category: .property,
        headlines: ["Customer Hurls Water Bottle Through Vape Shop Glass Counter After Refund Denied", "Shop Camera Shows Counter Shatter After Dispute Over Broken Device"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a vape shop, causing damage of $720, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} returned to a vape shop at 3:30 p.m. on {DATE} with a broken device and demanded a refund. The clerk refused because the warranty had expired. {D} hurled a metal water bottle at the glass counter, shattering the top. Deputies arrived at 3:45 p.m. and the counter cost $720 to replace. {D} says the bottle slipped.",
        state: [E(.video, 3, "Shop Camera", "{D} throws a metal water bottle overhand at the counter at 3:37 p.m."), E(.physical, 2, "Broken Glass", "A shattered glass top with the bottle's dent in the metal frame."), E(.document, 2, "Replacement Invoice", "$720 for a new glass top and frame repair."), E(.statement, 2, "Clerk", "Told {DL} the warranty had expired and refused the refund.")],
        defense: [E(.statement, 1, "Slipped", "{DL} says the bottle slipped from {D.his} hand during the argument."), E(.document, 1, "Warranty Page", "A page showing a 30-day warranty that had ended five days earlier.")],
        role: "Shop clerk",
        exam: [.direct("What do you do at the shop?", "\"I work the counter at a vape shop. On {DATE} I was working alone the afternoon {D} came in, a little after three thirty.\""), .direct("What did {D} want?", "\"A refund. {D} brought in a device that had stopped working and said it was defective. I checked the receipt and told {D} that the thirty-day warranty had ended five days before.\""), .direct("How did {D} react?", "\"{D} got louder and angrier, saying it was a ripoff and that I could not treat customers that way. I offered to look into a repair, but {D} wanted cash.\""), .direct("What happened to the counter?", "\"At 3:37, {D} threw a metal water bottle at the glass top of the counter and the glass shattered all over my display of products.\""), .direct("Was anything said when the bottle was thrown?", "\"I heard {D} say you'll regret this as the arm came forward. That is why I was sure it was intentional.\""), .direct("What did the damage cost?", "\"A new glass top and repairs to the metal frame came to $720. The invoice is in the exhibits, and that part is not in dispute.\""), .cross("Did you offer {D} a repair or replacement before the incident?", "\"I told {D} I could send it to the manufacturer, but it would take weeks and might not be covered. I did not offer a free fix.\""), .cross("Was the water bottle wet?", "\"It could have been. I know {D} had a drink in hand when {D} walked in. I did not touch the bottle, so I can't say how slick it was.\""), .cross("Did {D} aim at you?", "\"No. The bottle went toward the counter, not toward me. I was standing behind it, and the glass was between us.\""), .cross("How much space is between where {D} stood and the counter?", "\"Maybe three feet. It is a small shop, and {D} was right up against the glass when the argument got heated.\""), .cross("Did the warranty page say thirty days?", "\"Yes, thirty days. It was five days past. I explained that to {D} politely at the beginning.\"")],
        defenseRole: "Shop customer",
        defenseExam: [.direct("Where were you when this happened?", "\"I was a customer at the same shop, standing a few feet behind {D} at the counter, waiting my turn to buy a pack of cartridges.\""), .direct("What did you hear between {D} and the clerk?", "\"An argument about a refund. {D} got louder, the clerk stayed firm, and it kept going back and forth for several minutes.\""), .direct("What did you see {D} doing with the bottle?", "\"{D} had it in one hand and was gesturing with it while talking. It looked like it was wet, with drops running down the side.\""), .direct("What did you see when the bottle left {D}'s hand?", "\"{D} swung an arm out wide and the bottle just flew. It looked to me like it slipped, but it happened fast.\""), .direct("How did {D} react when the glass broke?", "\"{D} froze, put both hands to {D.his} head, and said sorry to the clerk right away. {D} did not run.\""), .direct("Did the clerk say anything to {D}?", "\"The clerk said a few sharp words and asked {D} to stay put until the deputies came. {D} agreed.\""), .cross("Did you hear {D} say anything as the bottle left?", "\"I heard something, but I couldn't make out the words over the noise in the shop.\""), .cross("How far were you from {D}?", "\"About four or five feet behind and to one side. I had a decent view of {D}'s arm but not of the hand.\""), .cross("Did you see whether {D} aimed at the counter?", "\"It went toward the counter, but I can't say if it was aimed. It was so quick I only saw it fly.\""), .cross("How well do you know {D}?", "\"Not well. I know {D} from around the neighborhood. I have no stake in this, and I am saying what I saw.\""), .cross("Were you angry at the clerk, too?", "\"No, though I could see why {D} was upset. I did not take part in the argument.\"")],
        theory: ("{D} threw a bottle through the counter over a refund.", "The bottle slipped during an argument."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had said 'you'll regret this' as the bottle left {D.his} hand.", "The water bottle was wet from a drink {DL} had just taken."),
        defendant: [.direct("Why did you come to the shop that afternoon?", "\"The device I bought stopped working, and I wanted my money back. I paid good money for it and was frustrated that it died so soon.\""), .direct("What did the clerk tell you?", "\"That the warranty had ended five days earlier and no refund was possible. I tried to argue, and I did get loud with the clerk.\""), .direct("What were you holding?", "\"A metal water bottle. I had just taken a drink on my way in, and my hand was still damp from the bottle.\""), .direct("What happened with the bottle?", "\"In the middle of arguing, I waved my arm and the bottle slipped out of my hand. It hit the counter and the glass top shattered.\""), .direct("Did you intend to break the counter?", "\"No. I was mad, but I never meant to hurt anyone or damage anything. I wanted a refund, not a broken counter.\""), .direct("What did you do after the glass broke?", "\"I stood there stunned, told the clerk I was sorry, and waited for the deputies. I did not leave or try to hide.\""), .cross("The camera shows an overhand throw, doesn't it?", "\"It shows my arm going up, and it looks hard. I'm not going to deny that. But the bottle was wet and it came out of my hand.\""), .cross("You were angry at the clerk, weren't you?", "\"Yes, I was. I raised my voice and used some unkind words. I am not proud of how I acted.\""), .cross("Did you say you'll regret this?", "\"I might have said something like that. I was upset. It was a figure of speech and not a threat against the counter.\""), .cross("You could have walked out when told no, couldn't you?", "\"Yes. I own that. I stayed to argue, and the argument got out of hand.\""), .cross("How hard did you swing your arm?", "\"Pretty hard. I was gesturing hard. I did not think of the bottle in my hand as a projectile until it flew.\"")],
        openings: ("{D} came to a vape shop demanding a refund on an expired warranty, was told no, and hurled a metal water bottle overhand at the glass counter at 3:37. The camera shows the throw and the shattered glass. The repair cost $720.", "{D} was arguing about a broken device with a wet water bottle in hand, and the bottle slipped as {D} gestured. Nobody was aimed at, and {D} apologized immediately and waited for deputies. You will hear a bystander who watched it happen."),
        closings: ("The camera shows an overhand throw, the clerk heard you'll regret this, and the glass was destroyed. {D} had been told no and answered with a bottle. The $720 repair is the price of that anger.", "A wet bottle, a wide gesture, and a slip in the middle of an argument. {D} stayed, apologized, and waited for deputies. Willful and wanton injury requires intent, and the State's own clerk cannot say how slick that bottle was."),
        timeline: [(0, "3:30 p.m.: {D} demands a refund."), (0, "3:37 p.m.: the bottle shatters the counter."), (0, "3:45 p.m.: deputies arrive."), (2, "The shop prices the repair.")],
        identified: "The shop camera identifies {D}.",
        notDone: ["The bottle's trajectory was never reconstructed.", "The shop never offered a repair in place of the refund."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let atmHammerV1 = SmallCases.make(
        key: "story.atmHammer",
        category: .property,
        headlines: ["Man Breaks Credit Union ATM With Tire Iron After Deposit Is Held", "Drive-Up ATM Screen Shattered by Customer With Tire Iron"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a credit union, causing damage of $2,100, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} made a $400 cash deposit at a credit union drive-up ATM at 6:50 p.m. on {DATE}, and the machine printed a slip showing the deposit as pending. {D} got a tire iron from the trunk and struck the screen three times. Deputies arrived at 7:10 p.m. and the machine was out of service for two weeks. The repair cost $2,100.",
        state: [E(.video, 3, "Drive-Up Camera", "{D} steps out with a tire iron and strikes the ATM screen three times."), E(.document, 2, "Repair Invoice", "$2,100 to replace the screen, bezel and card reader."), E(.physical, 2, "Tire Iron", "Recovered from {D}'s trunk with a fragment of the screen on the tip."), E(.document, 2, "Deposit Slip", "A $400 deposit marked pending at 6:50 p.m.")],
        defense: [E(.statement, 1, "Held Deposit", "{DL} says the machine kept the cash and printed a pending slip."), E(.document, 1, "Posted Hold Policy", "The ATM posts that deposits made after 5 p.m. post the next business day.")],
        role: "Credit union branch manager",
        exam: [.direct("What is your role at the credit union?", "\"I am the branch manager. I oversee the drive-up ATM and I was called in on the evening of {DATE} after the machine was struck.\""), .direct("What does the ATM record show for {D}'s deposit?", "\"A $400 cash deposit at 6:50 p.m., with a slip showing the deposit as pending. That is how every after-hours deposit is handled.\""), .direct("What did the drive-up camera show next?", "\"At about 6:53, {D} stepped out of the car with a tire iron and struck the screen three times, cracking the display and bending the bezel.\""), .direct("What did deputies recover?", "\"A tire iron from {D}'s trunk with a fragment of the screen stuck to the tip. They arrived at 7:10 and took photographs.\""), .direct("What was the effect on the branch?", "\"The machine was out of service for two weeks. Customers had to use another branch, and we had to bring in a technician to replace the screen, bezel and card reader.\""), .direct("What did the repair cost?", "\"$2,100 for parts and labor. The invoice is in evidence and includes the screen, the bezel and the card reader.\""), .cross("Does the ATM tell customers a deposit will post the next business day?", "\"There is a posted notice that deposits made after five p.m. post the next business day. It is a sticker on the machine.\""), .cross("Was the $400 credited?", "\"Yes. It was credited by nine the next morning. {D} did not lose the money.\""), .cross("How readable is that posted sticker at night?", "\"I have not tested it in the dark. It is small print. I cannot say whether {D} could read it at that hour.\""), .cross("Did the slip say pending?", "\"The slip did say pending. I didn't compare the slip's exact wording to the posted notice.\""), .cross("Did {D} try to talk to anyone before striking the screen?", "\"The camera does not show any call to the intercom. {D} went right from the deposit to the trunk.\"")],
        defenseRole: "Customer who used the same ATM",
        defenseExam: [.direct("How do you know {D}?", "\"I do not know {D} personally. I was a customer at the credit union's drive-up that same evening and used the same ATM earlier.\""), .direct("What happened when you used the ATM?", "\"I made a deposit and got a slip marked pending. I was not sure what that meant, so I looked at the machine for any posted notice.\""), .direct("Was there a notice on the machine?", "\"There was a sticker, but the print was small and the lighting at the drive-up was dim. I had to lean out of my car to read it.\""), .direct("Did you understand the slip?", "\"Not at first. The word pending is vague. I thought it might mean the machine had not accepted the cash, and I got a little worried.\""), .direct("Did you see {D} that evening?", "\"Only in passing. I saw a car pull up behind mine and a person standing at the machine looking frustrated.\""), .direct("What did you do about your own deposit?", "\"I drove home and checked my account the next morning. It had been credited, so there was no issue.\""), .cross("Did you see {D} strike the ATM?", "\"No. I had already left the drive-up. I only heard about the damage afterward.\""), .cross("How long have you used that ATM?", "\"For several years. I know the machine well, but I know the hold policy because I read it, not because anyone explained it.\""), .cross("Did you ever feel like destroying the machine?", "\"No. I would never do that. A pending slip made me nervous, but I handled it calmly.\""), .cross("Do you know whether {D} had read the sticker?", "\"I have no way of knowing. All I can say is that the sticker is small and the light is poor.\""), .cross("Is the drive-up lighting always dim?", "\"In the evening, yes. I have been there at that hour many times. It is not a brightly lit lane.\"")],
        theory: ("{D} smashed an ATM with a tire iron.", "A held deposit and an angry customer."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("The tire iron was taken from the trunk before {DL} made the deposit.", "The deposit was credited by 9 a.m. the next day."),
        defendant: [.direct("Why were you at the ATM?", "\"I needed to make a $400 deposit to cover a rent check that was about to bounce. I was worried and in a hurry that evening.\""), .direct("What did the machine do?", "\"It took my money and printed a slip that said pending. I thought that meant it had not accepted the cash and was holding it.\""), .direct("What were you worried about?", "\"That the rent check would bounce the next morning and I would get hit with fees and a late notice. I had very little cushion that week.\""), .direct("What did you do next?", "\"I got angry. I felt like the machine had taken my last four hundred dollars and not told me what happened. I got the tire iron out of the trunk.\""), .direct("How many times did you strike the screen?", "\"Three times. I wasn't thinking, I just wanted it to give me my money back. It was a terrible reaction.\""), .direct("What did you do when the deputies came?", "\"I waited, told them what I did, and apologized. I did not run. I gave them the tire iron when they asked.\""), .cross("You took a tire iron out of the trunk before you made the deposit, didn't you?", "\"I'm not going to say whether it was before or after. I do know I grabbed it after I got the slip.\""), .cross("The screen cost $2,100 to repair, didn't it?", "\"Yes, and I understand I'm responsible for that. I did not understand the cost when I swung.\""), .cross("You never pressed the help button, did you?", "\"No. I did not see an intercom, and I did not think to call. I was too upset.\""), .cross("You knew a deposit would be credited, didn't you?", "\"Not that night. I read the slip as meaning the cash was not accepted. Reading the sticker earlier might have prevented this.\""), .cross("Three swings of a tire iron isn't an accident, is it?", "\"No, it isn't. I did swing three times, and I meant to hit the screen. I thought the machine had my money.\"")],
        openings: ("At 6:50 p.m. {D} deposited $400 at a drive-up ATM and, three minutes later, struck the screen three times with a tire iron from the trunk. The camera caught it, deputies recovered the iron with a piece of the screen on it, and the repair cost $2,100. You will hear from the branch manager.", "{D} fed the last of a rent budget into a machine that printed a vague slip marked pending, then lost control. The posted hold policy was a small sticker in a dim lane. You will hear another customer describe the same confusing slip."),
        closings: ("Three blows with a tire iron to a screen, on camera, over a deposit that was credited by nine the next morning. {D} chose to destroy the machine rather than call or wait. The repair bill was $2,100.", "A pending slip and a hard-to-read sticker do not excuse the damage, but they explain what {D} thought was happening. {D} stayed, apologized, and handed over the tire iron. Consider what {D} believed about the money when you decide what {D} intended."),
        timeline: [(0, "6:50 p.m.: {D} deposits $400."), (0, "6:53 p.m.: {D} strikes the screen."), (0, "7:10 p.m.: deputies arrive."), (1, "The credit union credits the deposit and prices the repair.")],
        identified: "The drive-up camera and the deposit slip identify {D}.",
        notDone: ["The sticker's readability was never tested.", "The ATM's slip text was never compared with the posted hold policy."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let wrongWayRoadV1 = SmallCases.make(
        key: "story.wrongWayRoad",
        category: .traffic,
        headlines: ["Pickup Heads Wrong Way Up Divided Highway On-Ramp at 55 Miles Per Hour", "Drivers Swerve as Wrong-Way Truck Enters Highway"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, driving the wrong way on a divided highway ramp, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 11:50 p.m. on {DATE}, {D} drove a pickup up an exit ramp onto a divided highway at 55 miles per hour, heading against traffic. Three drivers swerved and one called 911 at 11:52 p.m. A deputy stopped {D} at 11:58 p.m. after {D} drove a mile in the wrong lane. {D} says {D.he} was following a navigation app.",
        state: [E(.digital, 3, "911 Recordings", "Three callers report a pickup going the wrong way."), E(.video, 3, "Dash Camera", "A driver's dash camera shows the pickup passing on the shoulder at 55 miles per hour."), E(.document, 2, "Ramp Photos", "'Wrong Way' and 'Do Not Enter' signs at the bottom of the exit ramp."), E(.document, 2, "Deputy's Report", "Stopped {D} at 11:58 p.m. a mile from the ramp.")],
        defense: [E(.statement, 1, "Navigation App", "{DL} says the app routed {D.him} up the ramp."), E(.document, 1, "Navigation Log", "A route that shows a turn at the exit ramp.")],
        role: "Sheriff's deputy",
        exam: [.direct("Walk us through how you came to stop {D}.", "\"At 11:52 p.m., dispatch said a pickup was going the wrong way on the highway. I found it a mile from the ramp at 11:58.\""), .direct("What did callers report at 11:50 p.m.?", "\"Three callers reported a pickup going the wrong way up an exit ramp onto a divided highway.\""), .direct("What does the driver's dash camera show?", "\"The pickup passing on the shoulder at 55 miles per hour, heading against traffic.\""), .direct("What signs are posted at the ramp?", "\"'Wrong Way' and 'Do Not Enter' signs at the bottom of the exit ramp. I stopped {D} at 11:58, a mile from the ramp.\""), .direct("What did you see?", "\"A pickup in the left lane, facing oncoming traffic, with its hazards off. {D} pulled over when I turned on my lights.\""), .direct("What did {D} say?", "\"That {D} was following a navigation app and didn't see the signs. I smelled alcohol and asked for a breath test.\""), .cross("{D} says {D.he} was following a navigation app, doesn't {D.he}?", "\"Yes. The app did show a turn at that exit. I agree with that.\""), .cross("Was it dark at the ramp?", "\"Yes. At 11:50 p.m. it was dark.\""), .cross("Was anyone hit?", "\"No. Three drivers swerved, but no one was struck.\""), .cross("Did the navigation app show a turn at that exit?", "\"The route log shows a turn near the ramp. It doesn't show an instruction to go the wrong way.\""), .cross("How dark was the ramp?", "\"It was dark. The signs are reflective, but they're low.\"")],
        defenseRole: "Passenger in the pickup",
        defenseExam: [.direct("Walk us through how you came to be in the pickup.", "\"I was a passenger. {D} offered me a ride home from the restaurant.\""), .direct("Did the navigation app tell the driver to turn at that exit?", "\"Yes. The app showed a turn at the exit, and the driver followed it up the ramp as the voice directed.\""), .direct("Were there signs on the ramp that you could see?", "\"Not that we saw in the dark. I did not notice any 'Wrong Way' signs, and I was looking out the window.\""), .direct("Did the driver see any signs before turning?", "\"I do not know. I did not see them myself, and the driver did not say anything about signs.\""), .direct("Did the app give an instruction at the exit?", "\"Yes. It said to turn right at the ramp. I saw the screen.\""), .direct("Could you see the signs?", "\"Not in the dark. I didn't notice any until cars started honking.\""), .cross("Did you warn the driver before getting onto the highway?", "\"Not in time. I said something once we were already on the highway, and by then it was too late.\""), .cross("Had the driver been drinking that evening at the restaurant?", "\"I smelled alcohol. I do not know how much the driver had, and I did not ask about it.\""), .cross("How long were you in the wrong lane before the stop?", "\"About a mile. It felt like forever, with horns and headlights coming at us from every direction.\""), .cross("Did you warn {D}?", "\"I said something once we were on the highway, but it was too late.\""), .cross("Had {D} been drinking?", "\"A couple of drinks. I thought {D} was fine to drive.\"")],
        theory: ("{D} drove against traffic for a mile.", "{D} followed a navigation app."),
        allocution: "\"I'm lucky no one was hurt, and I know it.\"",
        truths: ("{DL} had been drinking at a restaurant that evening.", "The app did show a turn at that exit."),
        defendant: [.direct("Did you drive up the exit ramp the wrong way?", "\"Yes, I did. My navigation app showed a turn at that exit, and I followed it up the ramp without question.\""), .direct("Did you see the 'Wrong Way' and 'Do Not Enter' signs?", "\"No. It was dark, and I did not see them. If I had, I would have stopped right there.\""), .direct("How far did you drive in the wrong lane before stopping?", "\"About a mile. I did not realize anything was wrong until cars began to swerve and honk at me.\""), .direct("Tell the jury what happened.", "\"I was following my phone's directions in a part of town I don't know. It told me to turn at an exit, and I turned.\""), .direct("Why didn't you see the signs?", "\"It was dark, and I was looking at my phone. I never saw 'Wrong Way.'\""), .direct("How long were you on the highway?", "\"About a mile. Cars swerved and honked, and I didn't understand why until I pulled over.\""), .cross("You had been drinking at a restaurant that evening, hadn't you?", "\"Yes. I had a couple of drinks at dinner. I did not think they affected my driving that night.\""), .cross("Three drivers swerved to avoid you, didn't they?", "\"Yes. I am very sorry about that. I did not mean to endanger anyone on that highway.\""), .cross("You drove at 55 miles an hour against traffic. Why did you not slow down?", "\"I did not understand what was happening. I panicked and kept going until a deputy stopped me.\""), .cross("You'd been drinking at dinner. Isn't that why you missed the signs?", "\"I'd had a couple of drinks. I believe I was following the phone.\""), .cross("Three drivers swerved. Weren't you aware?", "\"I was scared and confused. I apologize.\"")],
        openings: ("At 11:50 p.m., {D} drove a pickup up an exit ramp onto a divided highway, going 55 miles per hour against traffic for a mile. Three drivers swerved, and signs at the ramp warned 'Wrong Way.'", "Weigh the defense proof, which will show that a navigation app told {D} to turn at that exit, that the signs were hard to see in the dark, and that {D} did not realize."),
        closings: ("A wrong-way pickup at 55 miles per hour, three drivers swerving, signs at the ramp, and a driver who had been drinking. A mile in the wrong lane is no accident.", "A navigation app that showed a turn and a dark ramp with signs hard to see. The State must prove {D} knowingly drove the wrong way."),
        timeline: [(0, "11:50 p.m.: {D} enters the exit ramp."), (0, "11:52 p.m.: the first 911 call."), (0, "11:58 p.m.: the deputy stops {D}."), (1, "The caller sends the dash camera video.")],
        identified: "The deputy stopped {D} at the scene.",
        notDone: ["The app's route was never recreated.", "The ramp's lighting was never tested at night."],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let hotelLobbySleepV1 = SmallCases.make(
        key: "story.hotelLobbySleep",
        category: .publicOrder,
        headlines: ["Man Sleeps in Hospital Waiting Room After Visiting Hours and Ignores Security", "Hospital Security Gives Two Warnings Before Calling Deputies"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a hospital, after being notified not to, on {DATE}.",
        ages: 18...60,
